update public.stage_fields f set translations = '{"de":{"question":"Wie kommt diese Person heute mit dem Problem zurecht?","help":"Welche Produkte, Dienste, Abläufe, Umwege oder manuellen Lösungen nutzt sie? Wenn sie nichts tut — ist das auch eine Antwort."},"uk":{"question":"Як ця людина дає раду з проблемою сьогодні?","help":"Які продукти, послуги, процеси, обхідні шляхи чи ручні рішення вона використовує? Якщо нічого не робить — це теж відповідь."},"es":{"question":"¿Cómo se las arregla hoy esa persona con el problema?","help":"¿Qué productos, servicios, procesos, atajos o soluciones manuales usa? Si no hace nada, eso también es una respuesta."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
