update public.stage_fields f set translations = '{"de":{"question":"Nenne konkrete Probleme der heutigen Vorgehensweise.","help":"Zeitverlust, Kosten, Fehler, Frust, fehlender Komfort. Nenne Zahlen, wenn du eine Grundlage hast: „laut Gesprächspartner etwa eine Stunde pro Woche“."},"uk":{"question":"Вкажи конкретні проблеми теперішнього способу дій.","help":"Втрата часу, витрати, помилки, роздратування, незручність. Наводь цифри, коли маєш підставу: «за словами співрозмовника, приблизно година на тиждень»."},"es":{"question":"Señala problemas concretos de la forma actual de actuar.","help":"Pérdida de tiempo, costes, errores, frustración, incomodidad. Da cifras cuando tengas base: «según la persona entrevistada, una hora a la semana más o menos»."}}'::jsonb
