    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'zdefiniuj-problem'
    and s.key = 'gdzie-nie-dziala' and f.key = 'problemy';
update public.stage_fields f set translations = '{"de":{"question":"Welche Folgen hat das?","help":"Entgangene Einnahmen, Risiko, verschwendete Ressourcen, verpasste Chancen. Trenne das Hindernis selbst von seinen Folgen."},"uk":{"question":"Які це має наслідки?","help":"Втрачені доходи, ризик, змарновані ресурси, упущені можливості. Відокрем саму перешкоду від її наслідків."},"es":{"question":"¿Qué consecuencias tiene?","help":"Ingresos perdidos, riesgo, recursos desperdiciados, oportunidades perdidas. Separa el obstáculo en sí de sus consecuencias."}}'::jsonb
