update public.stage_subpoints s set translations = '{"de":{"title":"Endgültige Problemdefinition","description":"Fasse das Problem aus den bisherigen Antworten in einem Satz zusammen. Schreib über die Schwierigkeit, nicht über dein Produkt."},"uk":{"title":"Остаточне визначення проблеми","description":"Склади проблему в одне речення з попередніх відповідей. Пиши про труднощі, а не про свій продукт."},"es":{"title":"Definición final del problema","description":"Resume el problema en una frase a partir de las respuestas anteriores. Escribe sobre la dificultad, no sobre tu producto."}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
