update public.stage_fields f set translations = '{"de":{"question":"Schreib deine Hauptannahme auf.","help":"Diesen Satz wirst du in Gesprächen mit Menschen prüfen. Je konkreter, desto leichter lässt er sich widerlegen oder bestätigen.","config":{"template":"Ich nehme an, dass {kto} {czego} nutzen werden, um {po-co}.","slots":[{"key":"kto","label":"Wer? z. B. Shopinhaber","size":"md"},{"key":"czego","label":"Was?","size":"md"},{"key":"po-co","label":"Was erreichen?","size":"lg"}]}},"uk":{"question":"Запиши своє головне припущення.","help":"Це речення ти перевірятимеш у розмовах із людьми. Що конкретніше, то легше його спростувати чи підтвердити.","config":{"template":"Я припускаю, що {kto} скористаються {czego}, щоб {po-co}.","slots":[{"key":"kto","label":"Хто? напр. власники магазинів","size":"md"},{"key":"czego","label":"Чим?","size":"md"},{"key":"po-co","label":"Чого досягти?","size":"lg"}]}},"es":{"question":"Anota tu suposición principal.","help":"Esta frase la comprobarás en conversaciones con personas. Cuanto más concreta, más fácil será refutarla o confirmarla.","config":{"template":"Supongo que {kto} usarán {czego} para {po-co}.","slots":[{"key":"kto","label":"¿Quién? p. ej. dueños de tiendas","size":"md"},{"key":"czego","label":"¿Qué?","size":"md"},{"key":"po-co","label":"¿Para conseguir qué?","size":"lg"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'hipoteza-rozwiazania'
    and s.key = 'dlaczego-skorzysta' and f.key = 'zalozenie';
update public.stage_fields f set translations = '{"de":{"question":"Was muss zutreffen, damit deine Idee eine Chance hat zu funktionieren?","help":"Wähle Annahmen, deren Nichteintreffen dich zwingen würde, die Idee zu ändern. Der Rest ist nicht entscheidend."},"uk":{"question":"Що має справдитися, щоб твоя ідея мала шанс спрацювати?","help":"Обери такі припущення, неспрацювання яких змусить тебе змінити ідею. Решта не критична."},"es":{"question":"¿Qué tiene que cumplirse para que tu idea tenga opciones de funcionar?","help":"Elige las suposiciones que, si no se cumplen, te obligarían a cambiar la idea. El resto no es crítico."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
