update public.stage_subpoints s set translations = '{"de":{"title":"Prüfe, was Nutzer sagen"},"uk":{"title":"Перевір, що кажуть користувачі"},"es":{"title":"Comprueba qué dicen los usuarios"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
