update public.stage_fields f set translations = '{"de":{"question":"Ich habe Bewertungen, Kommentare oder Diskussionen über diese Lösungen gelesen.","help":"Bewertungen in App-Stores, Forenthreads, Kommentare auf Reddit und in Gruppen — dort sagen Leute die Wahrheit."},"uk":{"question":"Відгуки, коментарі чи обговорення цих рішень прочитано.","help":"Відгуки в магазинах, теми на форумах, коментарі на Reddit і в групах — там люди кажуть правду."},"es":{"question":"He leído opiniones, comentarios o debates sobre estas soluciones.","help":"Reseñas en tiendas, hilos de foros, comentarios en Reddit y en grupos: ahí la gente dice la verdad."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'konkurencja'
    and s.key = 'opinie-uzytkownikow' and f.key = 'przeczytane';
update public.stage_fields f set translations = '{"de":{"question":"Was loben die Nutzer?"},"uk":{"question":"Що хвалять користувачі?"},"es":{"question":"¿Qué elogian los usuarios?"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
