update public.stage_subpoints s set translations = '{"de":{"title":"Wenn du keine ähnlichen Lösungen findest","description":"Füll das nur aus, wenn sich wirklich nichts gefunden hat. Fehlende Konkurrenz bedeutet häufiger einen fehlenden Markt als ein freies Feld."},"uk":{"title":"Якщо не знаходиш схожих рішень","description":"Заповнюй лише тоді, коли справді нічого не знайшлося. Відсутність конкурентів частіше означає відсутність ринку, ніж вільну нішу."},"es":{"title":"Si no encuentras soluciones parecidas","description":"Rellénalo solo si de verdad no ha aparecido nada. La falta de competencia significa más a menudo falta de mercado que terreno libre."}}'::jsonb
