update public.stage_subpoints s set translations = '{"de":{"title":"Stelle die Idee und den Preis vor","description":"Sprich mit einigen Personen, die das Problem betrifft. Wenn jemand anderes als die Nutzerin oder der Nutzer zahlen soll, sprich auch mit dieser Person."},"uk":{"title":"Представ ідею і ціну","description":"Поговори з кількома людьми, яких стосується проблема. Якщо платити має хтось інший, ніж користувач, поговори і з ним."},"es":{"title":"Presenta la idea y el precio","description":"Habla con varias personas a las que afecta el problema. Si va a pagar alguien distinto del usuario, habla también con esa persona."}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'general' and p.key = 'zainteresowanie-i-cena' and s.key = 'przedstaw-pomysl';
update public.stage_fields f set translations = '{"de":{"question":"Wie haben die Gesprächspartner Idee und Preis bewertet? Was hat sie überzeugt und was abgeschreckt?"},"uk":{"question":"Як співрозмовники оцінили ідею і ціну? Що їх переконало, а що відштовхнуло?"},"es":{"question":"¿Cómo valoraron la idea y el precio las personas con las que hablaste? ¿Qué las convenció y qué las echó para atrás?"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'zainteresowanie-i-cena'
    and s.key = 'przedstaw-pomysl' and f.key = 'reakcje';
update public.stage_fields f set translations = '{"de":{"question":"Wie viele Personen haben die vorgeschlagene Handlung ausgeführt — gemessen an allen, denen die Idee vorgestellt wurde?","help":"Lob für die Idee, Anmeldung zu einem kostenlosen Test und die Aussage „ich würde zahlen“ bedeuten Verschiedenes. Nichts davon allein beweist, dass jemand kaufen wird."},"uk":{"question":"Скільки людей виконали запропоновану дію з усіх, кому представили ідею?","help":"Похвала ідеї, запис на безплатний тест і заява «я б заплатив» означають різне. Жодне з них саме по собі не доводить, що хтось купить."},"es":{"question":"¿Cuántas personas hicieron la acción propuesta, del total a quienes se presentó la idea?","help":"Elogiar la idea, apuntarse a una prueba gratuita y decir «pagaría» significan cosas distintas. Ninguna de ellas por sí sola demuestra que alguien vaya a comprar."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'zainteresowanie-i-cena'
    and s.key = 'przedstaw-pomysl' and f.key = 'wynik';
update public.stage_subpoints s set translations = '{"de":{"title":"Entscheide, wie es weitergeht"},"uk":{"title":"Виріши, що далі"},"es":{"title":"Decide qué sigue"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'general' and p.key = 'zainteresowanie-i-cena' and s.key = 'decyzja';
update public.stage_fields f set translations = '{"de":{"question":"Was behältst du, was änderst du und was musst du noch prüfen?","help":"Das ist die Zusammenfassung der ganzen Etappe. In einem Monat kommst du darauf zurück und prüfst, ob der Plan eingehalten wurde."},"uk":{"question":"Що залишиш, що зміниш і що ще маєш перевірити?","help":"Це підсумок усього етапу. За місяць ти повернешся до нього й перевіриш, чи план виконано."},"es":{"question":"¿Qué mantienes, qué cambias y qué tienes que comprobar todavía?","help":"Es el resumen de toda la etapa. Dentro de un mes volverás a él y comprobarás si se ha cumplido el plan."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'zainteresowanie-i-cena'
    and s.key = 'decyzja' and f.key = 'wnioski';
update public.stage_categories c set translations = '{"de":{"title":"SaaS","intro":"Ein Abo ist sinnvoll, wenn das Problem regelmäßig wiederkehrt — so oft, dass Kunden das Abonnement jeden Monat oder jedes Jahr verlängern. Prüfe, wie oft das Problem wiederkehrt, wie lange der Start dauert, was Kunden hält und was sie abschreckt."},"uk":{"title":"SaaS","intro":"Підписка має сенс, коли проблема регулярно повертається — так часто, що клієнт поновлює підписку щомісяця або щороку. Перевір, як часто проблема повертається, скільки триває старт, що втримає клієнта, а що його відштовхне."},"es":{"title":"SaaS","intro":"Una suscripción tiene sentido cuando el problema vuelve con regularidad, tan a menudo que el cliente la renueva cada mes o cada año. Comprueba cada cuánto vuelve el problema, cuánto tarda el arranque, qué retiene al cliente y qué lo desanima."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'idea' and t.version = 1 and c.key = 'saas';
update public.stage_points p set translations = '{"de":{"title":"Wofür Kunden während der Nutzung zahlen","description":"Nutze die Problembeschreibung und den Preisvorschlag aus der Allgemeinen Validierung. Hier prüfst du, ob die Art der Abrechnung dazu passt, wie das Programm genutzt wird.","guide_body":"Lege fest, was das Programm mit der Zeit leistet\nIm allgemeinen Teil ist der Hauptnutzen schon beschrieben. Überlege jetzt, was Kunden nach der ersten Nutzung bekommen und warum sie das Programm weiter brauchen.\nDas Programm kann weitere Aufgaben erledigen, Informationen speichern, Zusammenarbeit ermöglichen oder ständig im Hintergrund arbeiten. Ein Buchungswerkzeug nimmt zum Beispiel weitere Buchungen an, und ein Backup-Programm schützt neue Dateiversionen.\nWie oft das Programm geöffnet wird, zeigt nicht immer, wie nützlich es ist. Man kann selten in ein Werkzeug schauen, das ständig etwas für einen im Blick behält. Beschreibe also, was der Mensch tut und was das Programm zwischen seinen Besuchen leistet.\nKläre dann, wie lange Kunden diese Hilfe brauchen. Wer regelmäßig Kurse gibt, nutzt ein Buchungsprogramm vielleicht das ganze Jahr. Wer eine einzige Veranstaltung organisiert, braucht es vielleicht ein paar Monate. Wer Dateien umwandelt, kommt vielleicht nur bei bestimmten Aufgaben zurück.\nGeh zu den Beispielen aus früheren Gesprächen zurück. Prüfe, wann das Bedürfnis zuletzt auftrat, wie oft es wiederkam und wann es endete. Wenn du diese Informationen noch nicht hast, notiere eine Vermutung zum Prüfen.\nVermeide die Antwort „Kunden kommen dank Benachrichtigungen zurück“. Eine Benachrichtigung kann an eine Aufgabe erinnern, aber du musst noch erklären, warum diese Aufgabe nötig ist.\nPasse die Art der Abrechnung an\nWähle, wofür Kunden zahlen. Das kann ein Monat Zugang sein, die Zahl der Nutzer oder die Zahl erledigter Aufgaben. Passe die Abrechnung an die Nutzung des Programms an.\nErkläre bei einer Gebühr pro Nutzer, wen du zählst: jede Person mit Konto, jedes Teammitglied oder jede aktiv nutzende Person. Lege bei einer Gebühr pro Nutzung fest, was eine Nutzung ist, z. B. die Verarbeitung eines Dokuments.\nListe dann auf, was der im allgemeinen Teil genannte Preis enthält. Statt „12 € für das Programm“ kannst du schreiben: „12 € pro Monat für einen Buchungskalender für eine Person, bis zu 100 Buchungen im Monat.“ Das ist ein Beispiel für die Beschreibung eines Angebots, kein empfohlener Preis.\nNimm die wichtigsten Möglichkeiten des Programms und wesentliche Limits in die Liste auf. Wenn du ein Limit planst, erkläre, was passiert, wenn es überschritten wird. Kunden sollten verstehen, wie ihre Rechnung entsteht.\nDu musst jetzt keine mehreren Pakete erstellen. Ein klares Angebot reicht für die erste Prüfung.\nPrüfe die Reaktion auf die Abrechnungsart\nStelle deinem Gegenüber den Preis zusammen mit der Abrechnungsregel vor. Frag, was passt, was stört und wie diese Abrechnung zur eigenen Nutzung passen würde.\nDu kannst fragen:\n„Wie bezahlst du heute für ähnliche Werkzeuge?“\n„Schwankt die Zahl deiner Aufgaben stark von Monat zu Monat?“\n„Was wäre für dich an dieser Abrechnung unklar?“\n„Welches kostenpflichtige Programm hast du zuletzt gekündigt? Warum?“\nWenn jemand ein Abo ablehnt, prüfe den Grund. Es kann um den Preis gehen, um seltene Nutzung, die Vertragslaufzeit oder zu wenig Nutzen. Nimm nicht sofort an, dass eine Preissenkung genügt.\nFrag auch, wann dein Gegenüber deine Lösung nicht mehr bräuchte. Das Bedürfnis kann mit einem Projekt, einem Jobwechsel oder dem Umstieg auf ein anderes Werkzeug enden. Notiere diese Situationen als mögliche Kündigungsgründe.\nTrenne Erfahrungen von Vorhersagen. „Ich habe das Programm gekündigt, weil ich es nur für eine Veranstaltung brauchte“ beschreibt ein Ereignis. „Dein Programm würde ich das ganze Jahr nutzen“ bleibt eine Absichtserklärung.\nNach diesem Punkt hast du eine vorläufige Abrechnungsart, eine Beschreibung dessen, was der Preis umfasst, und die Anmerkungen deiner Gesprächspartner. Ob Zahlungen verlängert werden, prüfst du erst während der Nutzung des Produkts.","guide_sources":["Kevin Hale, How to Evaluate Startup Ideas. Das Bedürfnis und die Annahmen erkennen, von denen der Erfolg der Idee abhängt. Zusammenfassung und Aufzeichnung des Vortrags bei YC.","Eric Migicovsky, How to Talk to Users. Nach konkreten Erfahrungen und der heutigen Vorgehensweise fragen. Zusammenfassung und Aufzeichnung des Vortrags bei YC."]},"uk":{"title":"За що клієнт платитиме під час користування","description":"Скористайся описом проблеми й пропозицією ціни із Загальної валідації. Тут ти перевіриш, чи спосіб нарахування оплат відповідає тому, як користуються програмою.","guide_body":"Визнач, що програма дає з часом\nУ загальній частині вже описано головну користь. Тепер подумай, що клієнт отримуватиме після першого використання і чому програма й далі буде йому потрібна.\nПрограма може обробляти наступні завдання, зберігати інформацію, давати змогу співпрацювати або постійно працювати у фоні. Наприклад, інструмент для бронювань приймає нові записи, а програма резервного копіювання захищає нові версії файлів.\nЧастота відкривання програми не завжди показує її корисність. Користувач може рідко заглядати в інструмент, який увесь час пильнує щось за нього. Тож опиши, що робить людина і що програма забезпечує між її візитами.\nДалі з’ясуй, як довго клієнтові потрібна ця допомога. Людина, що регулярно проводить заняття, може користуватися програмою бронювань цілий рік. Організаторові однієї події вона може знадобитися на кілька місяців. Хтось, хто перетворює файли, може повертатися лише за конкретних завдань.\nПовернися до прикладів із попередніх розмов. Перевір, коли востаннє виникала потреба, як часто вона поверталася і коли закінчувалася. Якщо цієї інформації ще немає, запиши припущення для перевірки.\nУникай відповіді «клієнт повертатиметься завдяки сповіщенням». Сповіщення може нагадати про завдання, але ще треба пояснити, чому виконувати це завдання потрібно.\nДобери спосіб нарахування оплат\nОбери, за що клієнт платитиме. Це може бути місяць доступу, кількість користувачів або кількість виконаних завдань. Добери спосіб розрахунку до того, як користуються програмою.\nЗа оплати за користувача поясни, кого рахуєш: кожну людину з акаунтом, члена команди чи людину, що активно користується. За оплати за використання визнач, що таке одне використання, наприклад обробка одного документа.\nДалі випиши, що входить у ціну, названу в загальній частині. Замість «490 грн за програму» можна записати: «490 грн на місяць за календар бронювань для однієї людини, до 100 бронювань на місяць». Це приклад того, як описати пропозицію, а не рекомендована ціна.\nУ списку врахуй головні можливості програми й суттєві ліміти. Якщо передбачаєш ліміт, поясни, що станеться після його перевищення. Клієнт має розуміти, як утвориться його рахунок.\nЗараз не треба створювати кількох пакетів. Для першої перевірки досить однієї чіткої пропозиції.\nПеревір реакцію на спосіб розрахунку\nПредстав співрозмовникові ціну разом із правилом нарахування оплат. Запитай, що йому підходить, що заважає і як такий розрахунок пасував би до того, як він користується.\nМожеш запитати:\n«Як ти зараз платиш за схожі інструменти?»\n«Чи сильно змінюється кількість твоїх завдань від місяця до місяця?»\n«Що в такому нарахуванні оплат було б для тебе незрозумілим?»\n«Від якої платної програми ти нещодавно відмовився? Чому?»\nЯкщо хтось відкидає підписку, з’ясуй причину. Ідеться може про ціну, рідке користування, тривалість зобов’язання або недостатню користь. Не вважай одразу, що досить знизити суму.\nЗапитай також, коли співрозмовникові перестало б бути потрібне твоє рішення. Потреба може закінчитися разом із проєктом, зміною роботи або переходом на інший інструмент. Запиши ці ситуації як можливі причини відмови.\nВідокремлюй досвід від прогнозів. «Я відмовився від програми, бо вона була потрібна лише для однієї події» описує подію. «Твоєю програмою я користувався б цілий рік» лишається декларацією.\nПісля цього пункту в тебе є попередній спосіб нарахування оплат, опис того, що входить у ціну, і зауваження співрозмовників. Поновлення платежів ти перевіриш лише під час користування продуктом.","guide_sources":["Kevin Hale, How to Evaluate Startup Ideas. Розпізнавання потреби та припущень, від яких залежить успіх ідеї. Огляд і запис лекції в YC.","Eric Migicovsky, How to Talk to Users. Запитання про конкретний досвід і теперішній спосіб дій. Огляд і запис лекції в YC."]},"es":{"title":"Por qué pagará el cliente mientras lo use","description":"Usa la descripción del problema y la propuesta de precio de la Validación general. Aquí comprobarás si la forma de cobrar encaja con cómo se usa el programa.","guide_body":"Define qué aporta el programa con el tiempo\nEn la parte general ya está descrito el beneficio principal. Ahora piensa qué recibirá el cliente después del primer uso y por qué seguirá necesitando el programa.\nEl programa puede gestionar nuevas tareas, guardar información, permitir colaborar o trabajar continuamente en segundo plano. Por ejemplo, una herramienta de reservas recibe nuevas citas y un programa de copias de seguridad protege nuevas versiones de los archivos.\nLa frecuencia con la que se abre el programa no siempre muestra su utilidad. Alguien puede entrar pocas veces en una herramienta que vigila algo por él todo el tiempo. Describe, por tanto, qué hace la persona y qué aporta el programa entre una visita y otra.\nDespués determina durante cuánto tiempo necesita el cliente esa ayuda. Quien da clases con regularidad puede usar un programa de reservas todo el año. Quien organiza un único evento puede necesitarlo unos meses. Quien convierte archivos puede volver solo para tareas concretas.\nVuelve a los ejemplos de conversaciones anteriores. Comprueba cuándo surgió la necesidad por última vez, cada cuánto volvía y cuándo terminaba. Si aún no tienes esa información, anota una suposición por comprobar.\nEvita la respuesta «el cliente volverá gracias a las notificaciones». Una notificación puede recordar una tarea, pero aún hay que explicar por qué hace falta hacerla.\nAjusta la forma de cobrar\nElige por qué pagará el cliente. Puede ser un mes de acceso, el número de usuarios o el número de tareas realizadas. Ajusta el cobro a cómo se usa el programa.\nSi cobras por usuario, explica a quién cuentas: a cada persona con cuenta, a cada miembro del equipo o a quien lo use activamente. Si cobras por uso, define qué es un uso, por ejemplo procesar un documento.\nDespués enumera qué incluye el precio indicado en la parte general. En lugar de «12 € por el programa» puedes escribir: «12 € al mes por un calendario de reservas para una persona, hasta 100 reservas al mes». Es un ejemplo de cómo describir la oferta, no un precio recomendado.\nIncluye en la lista las principales funciones del programa y los límites importantes. Si prevés un límite, explica qué pasa al superarlo. El cliente debe entender cómo se forma su factura.\nNo tienes que crear ahora varios planes. Una propuesta clara basta para la primera comprobación.\nComprueba la reacción a la forma de cobro\nPresenta el precio junto con la regla de cobro. Pregunta qué le encaja, qué le molesta y cómo encajaría ese cobro con su forma de usarlo.\nPuedes preguntar:\n«¿Cómo pagas ahora herramientas parecidas?»\n«¿Cambia mucho de un mes a otro el número de tareas que haces?»\n«¿Qué te resultaría poco claro en esta forma de cobrar?»\n«¿Qué programa de pago dejaste hace poco? ¿Por qué?»\nSi alguien rechaza la suscripción, averigua el motivo. Puede ser el precio, el uso esporádico, la duración del compromiso o un beneficio insuficiente. No supongas de entrada que basta con bajar la cifra.\nPregunta también cuándo dejaría de necesitar tu solución. La necesidad puede acabar con un proyecto, un cambio de trabajo o el paso a otra herramienta. Anota esas situaciones como posibles motivos de baja.\nSepara experiencias de previsiones. «Dejé el programa porque solo lo necesitaba para un evento» describe un hecho. «Usaría tu programa todo el año» sigue siendo una declaración.\nTras este punto tienes una forma de cobro inicial, una descripción de lo que incluye el precio y los comentarios de tus interlocutores. Las renovaciones de pago solo las comprobarás durante el uso del producto.","guide_sources":["Kevin Hale, How to Evaluate Startup Ideas. Reconocer la necesidad y las suposiciones de las que depende el éxito de la idea. Resumen y grabación de la charla en YC.","Eric Migicovsky, How to Talk to Users. Preguntar por experiencias concretas y por la forma actual de actuar. Resumen y grabación de la charla en YC."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'saas' and p.key = 'za-co-placi';
update public.stage_subpoints s set translations = '{"de":{"title":"Lege fest, was das Programm mit der Zeit leistet"},"uk":{"title":"Визнач, що програма дає з часом"},"es":{"title":"Define qué aporta el programa con el tiempo"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'saas' and p.key = 'za-co-placi' and s.key = 'co-zapewnia-z-czasem';
update public.stage_fields f set translations = '{"de":{"question":"Was bekommen Kunden schon nach der ersten Nutzung?","help":"Z. B. Bearbeitung weiterer Bestellungen, Datenspeicherung, Teamarbeit oder ständige Überwachung."},"uk":{"question":"Що клієнт отримає вже після першого використання?","help":"Напр. обробку наступних замовлень, зберігання даних, командну роботу або постійний моніторинг."},"es":{"question":"¿Qué recibirá el cliente ya tras el primer uso?","help":"P. ej. gestión de nuevos pedidos, almacenamiento de datos, trabajo en equipo o supervisión continua."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'saas' and p.key = 'za-co-placi'
    and s.key = 'co-zapewnia-z-czasem' and f.key = 'po-pierwszym-uzyciu';
update public.stage_fields f set translations = '{"de":{"question":"Brauchen Kunden ständigen Zugang, Nutzung für eine bestimmte Zeit oder nur einzelne Aufgaben?","help":"Du kannst dich auf Beispiele aus den Gesprächen in der Allgemeinen Validierung stützen. Das entscheidet, ob ein Abo überhaupt Sinn ergibt."},"uk":{"question":"Чи потрібен клієнтові постійний доступ, користування протягом певного часу чи лише виконання окремих завдань?","help":"Можна спертися на приклади з розмов у Загальній валідації. Від цього залежить, чи підписка взагалі має сенс."},"es":{"question":"¿El cliente necesita acceso continuo, usarlo durante un tiempo determinado o solo hacer tareas sueltas?","help":"Puedes basarte en ejemplos de las conversaciones de la Validación general. De esto depende que una suscripción tenga sentido."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'saas' and p.key = 'za-co-placi'
    and s.key = 'co-zapewnia-z-czasem' and f.key = 'rodzaj-dostepu';
update public.stage_subpoints s set translations = '{"de":{"title":"Passe die Art der Abrechnung an"},"uk":{"title":"Добери спосіб нарахування оплат"},"es":{"title":"Ajusta la forma de cobrar"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'saas' and p.key = 'za-co-placi' and s.key = 'sposob-naliczania';
update public.stage_fields f set translations = '{"de":{"question":"Wofür willst du eine Gebühr berechnen?","help":"Z. B. einen Monat Zugang, die Zahl der Nutzer oder die Zahl erledigter Aufgaben."},"uk":{"question":"За що ти хочеш нараховувати оплату?","help":"Напр. місяць доступу, кількість користувачів або кількість виконаних завдань."},"es":{"question":"¿Por qué quieres cobrar?","help":"P. ej. un mes de acceso, el número de usuarios o el número de tareas realizadas."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
