update public.stage_fields f set translations = '{"de":{"question":"Was könnte Kunden davon abhalten, ein Online-Programm zu nutzen oder Daten darin zu speichern?"},"uk":{"question":"Що могло б утримати клієнта від користування онлайн-програмою або зберігання в ній даних?"},"es":{"question":"¿Qué podría frenar al cliente a la hora de usar un programa online o guardar datos en él?"}}'::jsonb
