update public.stage_fields f set translations = '{"de":{"question":"Schreib den Ablauf vom Auftreten des Problems bis zur Entscheidung auf, dann bis zur Nutzung und zur Vertragsverlängerung.","help":"Eine Zeile ist ein Schritt. Du siehst, wie viel passieren muss, bevor jemand zahlt."},"uk":{"question":"Розпиши процес від появи проблеми до рішення, а потім до користування й поновлення договору.","help":"Одна позиція — один крок. Побачиш, скільки всього має статися, перш ніж хтось заплатить."},"es":{"question":"Describe el proceso desde que aparece el problema hasta la decisión, y después hasta el uso y la renovación del contrato.","help":"Una línea es un paso. Verás cuántas cosas tienen que pasar antes de que alguien pague."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2b' and p.key = 'decyzja-o-zakupie'
    and s.key = 'sciezka-zakupowa' and f.key = 'kroki';
update public.stage_points p set translations = '{"de":{"title":"Untersuche Dauer und Bedingungen des Verkaufsprozesses","guide_body":"Prüfe, wie die Firma über einen Kauf entscheidet\nGeh zur Liste der Personen und Zustimmungen aus Punkt 1 zurück. Kläre jetzt, wann die Firma entscheiden und Geld für den Kauf bereitstellen kann.\nEin Budget ist Geld, das für bestimmte Ausgaben eingeplant ist. Die Firma hat vielleicht schon Mittel für einen ähnlichen Kauf oder muss ihn in künftigen Plänen berücksichtigen. Nimm nicht von vornherein an, dass sie bis zum nächsten Jahr warten muss.\nEine hilfreiche Frage lautet: „Wie lief der letzte ähnliche Kauf ab und wie viel Zeit verging von der Meldung des Bedarfs bis zur Bestellung?“ Die Frage nach einer konkreten Situation entspricht Migicovskys Ansatz für Gespräche mit Nutzern.\nWenn du selbst recherchierst, prüfe Informationen für Lieferanten, Angebotsanfragen und Ausschreibungen der gewählten Firma. Sie können Fristen oder Anforderungen enthalten. Fehlen solche Informationen, musst du sie auf anderem Weg herausfinden.\nNotiere eine ungefähre Dauer, wenn du sie belegen kannst. Du kannst auch angeben, wovon sie abhängt, z. B. „Der Inhaber genehmigt kleine Käufe sofort; größere Ausgaben bespricht er einmal im Monat.“\nFinde die größten Verzögerungen\nGeh den Kaufprozess durch und markiere Stellen, an denen die Firma auf den nächsten Schritt warten kann. Beispiele sind Vertragsprüfung, das Einholen mehrerer Angebote, das Ende einer bestehenden Zusammenarbeit oder Zeit für einen Test.\nBeschreibe konkret: „Der Kauf wartet auf den Vergleich von drei Angeboten.“ Nur „Verfahren“ erklärt nicht, was zu tun ist und wo die Verzögerung entsteht.\nFrag im Gespräch nach, was den letzten ähnlichen Kauf aufgehalten hat. Trenne ein Hindernis, das nur das Warten verlängert, von einer Bedingung, ohne die die Firma gar nicht kauft.\nNotiere zum Schluss, was das für deine Idee bedeutet. Wenn die gewählten Firmen mehrere Monate für eine Entscheidung brauchen, berücksichtige das im Plan für die ersten Kunden.","guide_sources":["Eric Migicovsky, How to Talk to Users, Regeln zum Sammeln von Informationen über frühere Ereignisse.","Gustaf Alströmer, How to Get Your First Customers, Material über die Anfänge des Verkaufs und die Kundengewinnung. Die detaillierten Fragen zu Fristen und Zustimmungen sind eine Anpassung an die Vairo-Aufgaben."]},"uk":{"title":"Досліди час і умови процесу продажу","guide_body":"Перевір, як компанія ухвалює рішення про покупку\nПовернися до списку людей і погоджень із пункту 1. Тепер з’ясуй, коли компанія може ухвалити рішення й виділити гроші на покупку.\nБюджет — це гроші, заплановані на певні витрати. Компанія може вже мати кошти на схожу покупку або мусить врахувати її в наступних планах. Не вважай наперед, що вона мусить чекати до наступного року.\nКорисне запитання: «Як виглядала остання схожа покупка і скільки часу минуло від заявки на потребу до замовлення?». Запитання про конкретну ситуацію відповідає підходу Migicovsky до розмов із користувачами.\nЯкщо шукаєш сам, перевір інформацію для постачальників, запити пропозицій і оголошення про закупівлі обраної компанії. Вони можуть містити терміни чи вимоги. Відсутність такої інформації означає, що її треба з’ясувати іншим шляхом.\nЗапиши приблизний час, якщо маєш на що спертися. Можна також вказати, від чого він залежить, наприклад: «власник затверджує дрібні покупки одразу; більші витрати обговорює раз на місяць».\nВизнач найбільші затримки\nПереглянь шлях покупки й познач місця, де компанія може чекати на наступний крок. Приклади: перевірка договору, збір кількох пропозицій, завершення теперішньої співпраці або пошук часу на тест.\nОписуй конкретно: «Покупка чекає на порівняння трьох пропозицій». Саме слово «процедури» не пояснює, що треба зробити і де виникає затримка.\nПід час розмови розпитай, що затримало попередню схожу покупку. Відокрем перешкоду, яка лише подовжує очікування, від умови, без якої компанія взагалі не купить.\nНасамкінець запиши, що це означає для твоєї ідеї. Якщо обраним компаніям потрібно кілька місяців на рішення, врахуй це в плані здобуття перших клієнтів.","guide_sources":["Eric Migicovsky, How to Talk to Users, правила збору інформації про попередні події.","Gustaf Alströmer, How to Get Your First Customers, матеріал про початки продажів і здобуття клієнтів. Детальні запитання про терміни й погодження — адаптація до завдань Vairo."]},"es":{"title":"Analiza el tiempo y las condiciones del proceso de venta","guide_body":"Comprueba cómo decide la empresa la compra\nVuelve a la lista de personas y aprobaciones del punto 1. Ahora averigua cuándo puede la empresa decidir y destinar dinero a la compra.\nUn presupuesto es dinero planificado para gastos concretos. La empresa puede tener ya fondos para una compra parecida o necesitar incluirla en próximos planes. No supongas de entrada que tenga que esperar al año siguiente.\nUna pregunta útil es: «¿Cómo fue la última compra parecida y cuánto tiempo pasó desde que se planteó la necesidad hasta el pedido?». Preguntar por una situación concreta sigue el enfoque de Migicovsky para hablar con usuarios.\nSi investigas por tu cuenta, revisa la información para proveedores, las solicitudes de oferta y los anuncios de compras de la empresa elegida. Pueden incluir plazos o requisitos. Si no hay esa información, tendrás que averiguarla por otra vía.\nAnota un tiempo aproximado si tienes en qué basarlo. También puedes indicar de qué depende, por ejemplo: «el dueño aprueba las compras pequeñas en el momento; los gastos mayores los trata una vez al mes».\nIdentifica los mayores retrasos\nRepasa el proceso de compra y marca los puntos en los que la empresa puede quedarse esperando el siguiente paso. Por ejemplo: revisar el contrato, reunir varias ofertas, terminar la colaboración actual o encontrar tiempo para una prueba.\nDescríbelo de forma concreta: «La compra espera a que se comparen tres ofertas». Decir solo «trámites» no explica qué hay que hacer ni dónde se produce el retraso.\nEn la conversación, pregunta qué frenó la última compra parecida. Separa un obstáculo que solo alarga la espera de una condición sin la cual la empresa no comprará.\nPor último, anota qué significa para tu idea. Si las empresas elegidas necesitan varios meses para decidir, tenlo en cuenta en el plan para conseguir los primeros clientes.","guide_sources":["Eric Migicovsky, How to Talk to Users, pautas para reunir información sobre hechos pasados.","Gustaf Alströmer, How to Get Your First Customers, material sobre los inicios de la venta y la captación de clientes. Las preguntas detalladas sobre plazos y aprobaciones son una adaptación a las tareas de Vairo."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'b2b' and p.key = 'czas-sprzedazy';
update public.stage_subpoints s set translations = '{"de":{"title":"Prüfe, wie die Firma entscheidet"},"uk":{"title":"Перевір, як компанія ухвалює рішення"},"es":{"title":"Comprueba cómo decide la empresa"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'b2b' and p.key = 'czas-sprzedazy' and s.key = 'jak-decyduje';
update public.stage_fields f set translations = '{"de":{"question":"Reicht die Entscheidung einer Person oder braucht es die Zustimmung mehrerer?"},"uk":{"question":"Чи досить рішення однієї людини, чи потрібна згода кількох?"},"es":{"question":"¿Basta con la decisión de una persona o hace falta el visto bueno de varias?"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
