update public.stage_fields f set translations = '{"de":{"question":"In welcher Situation erwägen Verbraucher den Kauf und warum ergibt die Ausgabe gerade dann Sinn?","help":"z. B. ein Elternteil sucht einen Kurs, wenn der Schüler Schwierigkeiten bei der Abiturvorbereitung bekommt"},"uk":{"question":"У якій ситуації споживач розгляне покупку і чому витрата має сенс саме тоді?","help":"напр. батьки шукають курс, коли учень починає мати труднощі з підготовкою до іспиту"},"es":{"question":"¿En qué situación se planteará el consumidor la compra y por qué tiene sentido el gasto justo entonces?","help":"p. ej. un progenitor busca un curso cuando el alumno empieza a tener dificultades para prepararse el examen"}}'::jsonb
