update public.stage_subpoints s set translations = '{"de":{"title":"Ordne die Ausgabe ins private Budget ein","description":"Lege fest, woher im privaten Budget das Geld kommen soll und ob der Kauf eine bisherige Ausgabe ersetzt."},"uk":{"title":"Впиши витрату в приватний бюджет","description":"Визнач, звідки в приватному бюджеті мають узятися гроші і чи покупка замінює дотеперішню витрату."},"es":{"title":"Sitúa el gasto en el presupuesto personal","description":"Indica de qué parte del presupuesto personal saldrá el dinero y si la compra sustituye un gasto actual."}}'::jsonb
