update public.stage_fields f set translations = '{"de":{"question":"Was hat es gekostet, diese Personen zu erreichen?","help":"Anzeigen, Materialien, Messetickets. Wenn es nichts gekostet hat, trag 0 ein.","config":{"unit":"€"}},"uk":{"question":"Скільки коштувало дістатися до цих людей?","help":"Реклама, матеріали, квитки на ярмарки. Якщо нічого не коштувало, впиши 0.","config":{"unit":"грн"}},"es":{"question":"¿Cuánto costó llegar a estas personas?","help":"Anuncios, materiales, entradas a ferias. Si no costó nada, escribe 0.","config":{"unit":"€"}}}'::jsonb
