update public.stage_fields f set translations = '{"de":{"question":"Was hat die Gewinnung einer interessierten Person gekostet?","help":"Das sind die Kosten für die Gewinnung eines Kunden (in der Branche: CAC). Trag den ausgegebenen Betrag und die Zahl der Interessierten ein — das Ergebnis wird automatisch berechnet.","config":{"unit":"€","calc":{"op":"quotient","inputs":[{"key":"wydane","label":"Ausgegebenes Geld","unit":"€"},{"key":"osoby","label":"Interessierte Personen"}]}}},"uk":{"question":"Скільки коштувало здобуття однієї зацікавленої людини?","help":"Це вартість здобуття одного клієнта (у галузі: CAC). Впиши витрачену суму й кількість зацікавлених людей — результат порахується сам.","config":{"unit":"грн","calc":{"op":"quotient","inputs":[{"key":"wydane","label":"Витрачені гроші","unit":"грн"},{"key":"osoby","label":"Зацікавлені люди"}]}}},"es":{"question":"¿Cuánto costó conseguir a una persona interesada?","help":"Es el coste de conseguir un cliente (en el sector: CAC). Escribe lo gastado y el número de personas interesadas: el resultado se calcula solo.","config":{"unit":"€","calc":{"op":"quotient","inputs":[{"key":"wydane","label":"Dinero gastado","unit":"€"},{"key":"osoby","label":"Personas interesadas"}]}}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
