update public.stage_subpoints s set translations = '{"de":{"title":"Wähle einen Hauptweg, um Kunden zu erreichen"},"uk":{"title":"Обери один головний спосіб охоплення"},"es":{"title":"Elige una forma principal de llegar a los clientes"}}'::jsonb
