    and t.key = 'idea' and t.version = 1 and c.key = 'hardware' and p.key = 'koszty-jednostkowe'
    and s.key = 'koszt-vs-cena' and f.key = 'marza';
update public.stage_points p set translations = '{"de":{"title":"Untersuche die Kaufabsicht","guide_body":"Parallel werden Kaufabsicht, Wertversprechen und ein früher Zielgruppensegment validiert. In Interviews wird die Preisakzeptanz für das gezeigte Modell oder die Skizze untersucht und eine Gruppe früher Nutzer (Early Adopters) ausgewählt, für die das Problem am drängendsten ist. Nachfrage wird nicht nur über Aussagen gemessen, sondern vor allem über Kennzahlen echten Marktengagements, etwa Einträge in eine Warteliste, Kaufabsicht auf einer Landingpage oder Vorbestellformulare."},"uk":{"title":"Досліди намір купити","guide_body":"Паралельно перевіряють намір купити, ціннісну пропозицію та ранній сегмент адресатів. Під час інтерв’ю досліджують сприйняття ціни показаного макета чи ескізу й відбирають групу ранніх користувачів (early adopters), для яких проблема найгостріша. Попит вимірюють не лише заявами, а передусім показниками ринкової залученості, як-от записи до списку очікування, намір купити на лендингу чи форми передпродажу."},"es":{"title":"Analiza la intención de compra","guide_body":"En paralelo se validan la intención de compra, la propuesta de valor y un segmento temprano de destinatarios. En las entrevistas se estudia la aceptación del precio de la maqueta o el boceto mostrados y se selecciona un grupo de primeros usuarios (early adopters) para quienes el problema es más agudo. La demanda no se mide solo con declaraciones, sino sobre todo con indicadores de interés real del mercado, como registros en una lista de espera, intención de compra en una landing page o formularios de preventa."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'hardware' and p.key = 'zamiar-zakupu';
update public.stage_subpoints s set translations = '{"de":{"title":"Prüfe die Preisakzeptanz"},"uk":{"title":"Перевір сприйняття ціни"},"es":{"title":"Comprueba la aceptación del precio"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'hardware' and p.key = 'zamiar-zakupu' and s.key = 'akceptacja-cenowa';
update public.stage_fields f set translations = '{"de":{"question":"Welche Preisspanne nennen potenzielle Nutzer?","help":"Frag beim Modell oder der Skizze, nicht losgelöst vom Produkt."},"uk":{"question":"Який діапазон цін називають потенційні користувачі?","help":"Запитуй при макеті чи ескізі, а не у відриві від продукту."},"es":{"question":"¿Qué rango de precios dan los posibles usuarios?","help":"Pregunta con la maqueta o el boceto delante, no desligado del producto."}}'::jsonb
