update public.stage_points p set translations = '{"de":{"title":"Umreiße die Regulierung und die Umsetzungsrisiken","guide_body":"Der letzte Bereich ist das Umreißen der Regulierung und der Umsetzungsrisiken. Lege die Produktkategorie fest (z. B. Unterhaltungselektronik, Medizinprodukt, Lebensmittelkontakt) und nenne die wichtigsten Zertifikate und Normen (z. B. CE, FCC, RoHS), die in den Zielmärkten gelten, samt ihren Einschränkungen. Zum Schluss werden gesammelte Nachfrage, Einschätzung der Ingenieurin oder des Ingenieurs, Kostenschätzungen und regulatorischer Rahmen zusammengeführt, um formell über den Übergang zur Preparation-Etappe und den Beginn einer detaillierten Spezifikation zu entscheiden."},"uk":{"title":"Окресли регуляторні рамки та ризики впровадження","guide_body":"Остання ділянка — окреслення регуляторних рамок і ризиків впровадження. Слід визначити категорію продукту (напр. побутова електроніка, медичне обладнання, контакт із харчами) і вказати ключові сертифікати й норми (напр. CE, FCC, RoHS), чинні на цільових ринках, разом із їхніми обмеженнями. Насамкінець треба зіставити зібраний попит, думку інженера, оцінки витрат і регуляторні рамки, щоб ухвалити формальне рішення про перехід до етапу Preparation і початок роботи над детальною специфікацією."},"es":{"title":"Esboza el marco normativo y los riesgos de implantación","guide_body":"La última área consiste en esbozar el marco normativo y los riesgos de implantación. Hay que definir la categoría del producto (p. ej. electrónica de consumo, producto sanitario, contacto con alimentos) y señalar los certificados y normas clave (p. ej. CE, FCC, RoHS) vigentes en los mercados objetivo, con sus limitaciones. Por último, se contrastan la demanda reunida, la opinión del ingeniero, las estimaciones de coste y el marco normativo para tomar la decisión formal de pasar a la etapa Preparation y empezar la especificación detallada."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'hardware' and p.key = 'regulacje';
