update public.stage_fields f set translations = '{"de":{"question":"Stelle gesammelte Nachfrage, Einschätzung der Ingenieurin oder des Ingenieurs und Kostenschätzungen nebeneinander. Rechtfertigt das Projekt den Übergang zur detaillierten Spezifikation?","help":"Das ist der Moment für eine ehrliche Antwort. Hardware verzeiht weniger als Software — ein Fehler in dieser Phase kostet Monate und Geld."},"uk":{"question":"Зістав зібраний попит, думку інженера й оцінки витрат. Чи виправдовує проєкт перехід до детальної специфікації?","help":"Це момент для чесної відповіді. Залізо пробачає менше, ніж програми, — помилка на цьому етапі коштує місяців і грошей."},"es":{"question":"Contrasta la demanda reunida, la opinión del ingeniero y las estimaciones de coste. ¿Justifica el proyecto pasar a la especificación detallada?","help":"Es el momento de una respuesta sincera. El hardware perdona menos que el software: un error en esta fase cuesta meses y dinero."}}'::jsonb
