    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'scope'
    and s.key = 'mode' and f.key = 'choice';
update public.stage_subpoints s set translations = '{"de":{"title":"Co-Founder-Profil"},"uk":{"title":"Профіль co-founder"},"es":{"title":"Perfil del cofundador"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'scope' and s.key = 'cofounder';
update public.stage_fields f set translations = '{"de":{"question":"Beschreibe, wen du als Co-Founder suchst.","help":"Eine Zeile ist eine Rolle. Du kannst ein eigenes Feld ergänzen, wenn im Profil etwas fehlt.","example":"Verantwortung: erste Version des Programms und Weiterentwicklung nach den Tests. Anteile: 15–25 % zur Verhandlung.","config":{"add_label":"Weitere Rolle hinzufügen","columns":[{"key":"responsibility","label":"Verantwortung","placeholder":"Wofür diese Person verantwortlich ist"},{"key":"equity","label":"Anteilsspanne zur Verhandlung","placeholder":"Z. B. 10–20 %"},{"key":"experience","label":"Erforderliche Erfahrung","placeholder":"Was sie vorweisen können sollte"},{"key":"approach","label":"Arbeitsweise","placeholder":"Welche Zusammenarbeit du erwartest"},{"key":"hours","label":"Freie Stunden und Engagement","placeholder":"Wie viel Zeit sie investieren kann"}]}},"uk":{"question":"Опиши, кого шукаєш як co-founder.","help":"Одна позиція — одна роль. Можеш дописати власне поле, якщо чогось бракує в профілі.","example":"Відповідальність: перша версія програми та її розвиток після тестів. Частки: 15–25% для обговорення.","config":{"add_label":"Додати ще одну роль","columns":[{"key":"responsibility","label":"Відповідальність","placeholder":"За що відповідає ця людина"},{"key":"equity","label":"Діапазон часток для обговорення","placeholder":"Напр. 10–20%"},{"key":"experience","label":"Потрібний досвід","placeholder":"Що вона має вміти показати"},{"key":"approach","label":"Підхід","placeholder":"Якої співпраці ти очікуєш"},{"key":"hours","label":"Вільні години й залученість","placeholder":"Скільки часу вона може приділити"}]}},"es":{"question":"Describe a quién buscas como cofundador.","help":"Una línea es un rol. Puedes añadir un campo propio si falta algo en el perfil.","example":"Responsabilidad: primera versión del programa y su desarrollo tras las pruebas. Participaciones: 15–25 % a negociar.","config":{"add_label":"Añadir otro rol","columns":[{"key":"responsibility","label":"Responsabilidad","placeholder":"De qué es responsable esta persona"},{"key":"equity","label":"Rango de participaciones a negociar","placeholder":"P. ej. 10–20 %"},{"key":"experience","label":"Experiencia requerida","placeholder":"Qué debería poder mostrar"},{"key":"approach","label":"Forma de trabajar","placeholder":"Qué colaboración esperas"},{"key":"hours","label":"Horas disponibles y compromiso","placeholder":"Cuánto tiempo puede dedicar"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'scope'
    and s.key = 'cofounder' and f.key = 'profile';
update public.stage_subpoints s set translations = '{"de":{"title":"Personen für eine konkrete Arbeit"},"uk":{"title":"Люди, потрібні для конкретної роботи"},"es":{"title":"Personas para un trabajo concreto"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'scope' and s.key = 'helpers';
update public.stage_fields f set translations = '{"de":{"question":"Aufgaben, die zu klein für einen Co-Founder sind, die du aber nicht allein erledigst.","help":"Schreib bei jeder Zeile die Fähigkeit dazu und ob du für die Arbeit zahlen kannst.","example":"Druckfertiger Verpackungsentwurf. Ich suche jemanden, der solche Dateien schon vorbereitet hat. Budget: 200 €.","config":{"add_label":"Person hinzufügen","columns":[{"key":"task","label":"Aufgabe","placeholder":"Was entstehen soll"},{"key":"skill","label":"Fähigkeit und Erfahrung","placeholder":"Was du suchst"},{"key":"pay","label":"Kannst du zahlen und wie viel","placeholder":"Z. B. 200 € oder kein Budget"}]}},"uk":{"question":"Завдання, замалі для co-founder, але яких ти не зробиш сам.","help":"Біля кожної позиції напиши вміння і чи можеш заплатити за цю роботу.","example":"Проєкт упаковки, готовий до друкарні. Шукаю когось, хто готував такі файли. Бюджет: 8000 грн.","config":{"add_label":"Додати людину","columns":[{"key":"task","label":"Завдання","placeholder":"Що має з’явитися"},{"key":"skill","label":"Уміння й досвід","placeholder":"Кого шукаєш"},{"key":"pay","label":"Чи можеш заплатити і скільки","placeholder":"Напр. 8000 грн або без бюджету"}]}},"es":{"question":"Tareas demasiado pequeñas para un cofundador que no harás tú solo.","help":"En cada línea indica la habilidad y si puedes pagar por el trabajo.","example":"Diseño de envase listo para imprenta. Busco a alguien que haya preparado archivos así. Presupuesto: 200 €.","config":{"add_label":"Añadir persona","columns":[{"key":"task","label":"Tarea","placeholder":"Qué hay que hacer"},{"key":"skill","label":"Habilidad y experiencia","placeholder":"Qué buscas"},{"key":"pay","label":"¿Puedes pagar y cuánto?","placeholder":"P. ej. 200 € o sin presupuesto"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'scope'
    and s.key = 'helpers' and f.key = 'roles';
update public.stage_points p set translations = '{"de":{"title":"Hol dir Hilfe und erste Kontakte","duration_hint":"Etwa 20 Minuten","guide_body":"Profil und Einladung\nNutze die Informationen aus Punkt 1, um dein Profil und das Projektprofil zu ergänzen. Wer das Profil ansieht, sollte schnell verstehen, was du baust, in welcher Phase du bist und wobei er helfen kann. Wenn du schon eine passende Beschreibung hast, verwende sie wieder.\nZeig, was du selbst einbringst: Kenntnis des Problems, Zugang zu Zielpersonen, eine fertige Skizze oder eine für den Bau nötige Fähigkeit. Ergänze, ob du eine Mitgründerin, jemanden für eine konkrete Aufgabe oder eine kurze Beratung suchst.\nBeispiel: „Ich baue eine Halterung, um Einkäufe mit dem Fahrrad zu transportieren. Ich habe eine Skizze und Erkenntnisse aus Gesprächen mit Radfahrern. Ich suche jemanden, der ein Modell der Befestigung vorbereitet.“\nWenn du schon mit passenden Personen arbeitest, lade sie ins Projekt ein. Weitere zu suchen ergibt Sinn, wenn ein konkreter Bedarf bleibt.\n§\nWen du fragst\nWähle Personen, deren Fähigkeiten zu den notierten Aufgaben passen. Sieh dir ein Beispiel ähnlicher Arbeit an oder bitte um eine kurze Beschreibung dessen, was die Person schon gemacht hat. Du kannst in Vairo, im Bekanntenkreis oder über Empfehlungen suchen.\nSchreib kurz, was du brauchst und welche Bedingungen du anbieten kannst. Beispiel: „Ich suche Hilfe beim Modell einer Fahrradhalterung. Ich habe dein Befestigungsprojekt gesehen. Darf ich dir die Skizze zeigen und nach einer möglichen Zusammenarbeit fragen?“\nErgänze nach der Antwort die Tabellenzeile. Etwas Konkretes reicht: „Hat geantwortet, hat Modelle ähnlicher Teile gemacht, wir haben einen gemeinsamen Test vereinbart.“ Wenn jemand noch nicht geantwortet hat, lass den Kontakt als wartend stehen.\nVergleiche Passung zur Aufgabe, Verfügbarkeit und vereinbarte Bedingungen. Füge Personen zur Zusammenarbeit hinzu, die ihre Teilnahme bestätigt haben. Im nächsten Punkt prüft ihr, wie gut ihr zusammenarbeitet.","guide_sources":["Michael Seibel, One Order of Operations for Starting a Startup (2018): mit Menschen mit ergänzenden Fähigkeiten bauen."]},"uk":{"title":"Здобудь допомогу й перші контакти","duration_hint":"Близько 20 хвилин","guide_body":"Профіль і запрошення\nСкористайся інформацією з пункту 1, щоб доповнити свій профіль і профіль проєкту. Людина, яка переглядає профіль, має швидко зрозуміти, що ти створюєш, на якому ти етапі і чим вона може допомогти. Якщо вже маєш відповідний опис, використай його знову.\nПокажи, що вносиш від себе: знання проблеми, доступ до адресатів, готовий ескіз або вміння, потрібне для створення. Допиши, чи шукаєш співзасновника, виконавця конкретного завдання чи коротку консультацію.\nПриклад: «Я створюю тримач для перевезення покупок велосипедом. Маю ескіз і висновки з розмов із велосипедистами. Шукаю людину, яка допоможе підготувати модель кріплення».\nЯкщо вже працюєш із відповідними людьми, запроси їх до проєкту. Шукати наступних має сенс тоді, коли залишається конкретна потреба.\n§\nКого питати\nОбирай людей, чиї вміння пасують до записаних завдань. Подивися на приклад схожої роботи або попроси короткий опис того, що людина робила раніше. Можеш шукати у Vairo, серед знайомих чи за рекомендацією.\nКоротко напиши, чого потребуєш і які умови можеш запропонувати. Приклад: «Шукаю допомоги з моделлю велосипедного тримача. Бачив(-ла) твій проєкт кріплення. Чи можу показати тобі ескіз і запитати про можливість співпраці?».\nПісля відповіді заповни рядок таблиці. Досить конкретики: «Відповіла, готувала моделі схожих деталей, домовилися про спільну спробу». Коли хтось ще не відповів, залиш контакт як очікуваний.\nПорівняй відповідність завданню, доступність і погоджені умови. До співпраці додавай людей, які підтвердили бажання взяти участь. У наступному пункті ви перевірите, як вам ідеться спільна робота.","guide_sources":["Michael Seibel, One Order of Operations for Starting a Startup (2018): створення разом із людьми з доповнювальними вміннями."]},"es":{"title":"Consigue ayuda y los primeros contactos","duration_hint":"Unos 20 minutos","guide_body":"Perfil e invitación\nUsa la información del punto 1 para completar tu perfil y el del proyecto. Quien vea el perfil debe entender rápido qué estás creando, en qué fase estás y en qué puede ayudar. Si ya tienes una descripción adecuada, reutilízala.\nMuestra lo que aportas: conocimiento del problema, acceso a los destinatarios, un boceto hecho o una habilidad necesaria para construir. Añade si buscas un cofundador, a alguien para una tarea concreta o una consulta breve.\nEjemplo: «Estoy creando un soporte para llevar la compra en bicicleta. Tengo un boceto y conclusiones de conversaciones con ciclistas. Busco a alguien que me ayude a preparar un modelo del anclaje».\nSi ya trabajas con las personas adecuadas, invítalas al proyecto. Buscar a más tiene sentido cuando queda una necesidad concreta.\n§\nA quién preguntar\nElige personas cuyas habilidades encajen con las tareas anotadas. Mira un ejemplo de trabajo parecido o pide una breve descripción de lo que ha hecho antes. Puedes buscar en Vairo, entre conocidos o por recomendación.\nEscribe brevemente qué necesitas y qué condiciones puedes ofrecer. Ejemplo: «Busco ayuda con el modelo de un soporte para bicicleta. He visto tu proyecto de anclaje. ¿Puedo enseñarte el boceto y preguntarte si te interesaría colaborar?».\nCuando te respondan, completa la fila de la tabla. Basta con algo concreto: «Respondió, ha hecho modelos de piezas parecidas, acordamos una prueba conjunta». Si alguien aún no ha respondido, deja el contacto como pendiente.\nCompara el encaje con la tarea, la disponibilidad y las condiciones acordadas. Añade a la colaboración a las personas que hayan confirmado que quieren participar. En el siguiente punto comprobaréis cómo os va trabajando juntos.","guide_sources":["Michael Seibel, One Order of Operations for Starting a Startup (2018): construir con personas de habilidades complementarias."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'find-help';
update public.stage_subpoints s set translations = '{"de":{"title":"Nutze den Social-Bereich"},"uk":{"title":"Скористайся шаром Social"},"es":{"title":"Usa la parte Social"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'find-help' and s.key = 'social';
update public.stage_fields f set translations = '{"de":{"question":"Vervollständige dein Profil und das deines Startups und suche dann Leute im Vairo-Netzwerk.","help":"Dieser Schritt öffnet Social. Hake ihn ab, wenn das Profil fertig ist und du weißt, wen du suchst.","config":{"confirm_label":"Profil ist fertig","label":"Social öffnen"}},"uk":{"question":"Доповни свій профіль і профіль стартапу, а потім шукай людей у мережі Vairo.","help":"Цей крок відкриває Social. Познач його, коли профіль готовий і ти знаєш, кого шукаєш.","config":{"confirm_label":"Профіль готовий","label":"Відкрити Social"}},"es":{"question":"Completa tu perfil y el de tu startup, y después busca gente en la red de Vairo.","help":"Este paso abre Social. Márcalo cuando el perfil esté listo y sepas a quién buscas.","config":{"confirm_label":"El perfil está listo","label":"Abrir Social"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'find-help'
    and s.key = 'social' and f.key = 'opened';
update public.stage_subpoints s set translations = '{"de":{"title":"Notiere, wen du um Hilfe bittest"},"uk":{"title":"Запиши, кого просиш про допомогу"},"es":{"title":"Anota a quién pides ayuda"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'find-help' and s.key = 'outreach';
update public.stage_fields f set translations = '{"de":{"question":"Kontakte: Person oder Firma, ob geantwortet wurde, welche Fähigkeiten sie hat und ob ihr zusammenarbeitet.","help":"Eine Zeile ist ein Gespräch. Wenn jemand noch nicht geantwortet hat, trag „wartet“ ein.","example":"Anna Schmidt. Hat geantwortet. Hat Modelle ähnlicher Teile gemacht. Wir vereinbaren einen gemeinsamen Test.","config":{"add_label":"Kontakt hinzufügen","columns":[{"key":"who","label":"Vor- und Nachname oder Firma"},{"key":"reply","label":"Hat geantwortet?"},{"key":"skills","label":"Fähigkeiten"},{"key":"together","label":"Arbeitet ihr zusammen?"}]}},"uk":{"question":"Контакти: людина чи компанія, чи відповіла, які має вміння і чи співпрацюватимете.","help":"Одна позиція — одна розмова. Коли хтось ще не відписав, впиши «чекає».","example":"Оля Коваленко. Відповіла. Робила моделі схожих деталей. Домовляємося про спільну спробу.","config":{"add_label":"Додати контакт","columns":[{"key":"who","label":"Ім’я та прізвище або компанія"},{"key":"reply","label":"Чи відповіла"},{"key":"skills","label":"Уміння"},{"key":"together","label":"Чи будете співпрацювати"}]}},"es":{"question":"Contactos: persona o empresa, si respondió, qué habilidades tiene y si vais a colaborar.","help":"Una línea es una conversación. Si alguien aún no ha respondido, escribe «pendiente».","example":"Lucía García. Respondió. Ha hecho modelos de piezas parecidas. Estamos acordando una prueba conjunta.","config":{"add_label":"Añadir contacto","columns":[{"key":"who","label":"Nombre y apellidos o empresa"},{"key":"reply","label":"¿Ha respondido?"},{"key":"skills","label":"Habilidades"},{"key":"together","label":"¿Vais a colaborar?"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'find-help'
    and s.key = 'outreach' and f.key = 'contacts';
update public.stage_subpoints s set translations = '{"de":{"title":"Wähle Personen von der Plattform"},"uk":{"title":"Обери людей із платформи"},"es":{"title":"Elige personas de la plataforma"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'find-help' and s.key = 'pick';
update public.stage_fields f set translations = '{"de":{"question":"Markiere die Personen, mit denen du weitermachen willst.","help":"Das sind echte Profile aus Vairo. Die Einladung ins Startup schickst du von der Karte der Person in Social. Das Markieren allein erzeugt keine Mitgliedschaft. Wenn du niemanden wählst, speichere eine leere Liste."},"uk":{"question":"Познач людей, з якими хочеш іти далі.","help":"Це справжні профілі з Vairo. Запрошення до стартапу надсилаєш із картки людини в Social. Сама позначка не створює членства. Якщо нікого не обираєш, збережи порожній список."},"es":{"question":"Marca a las personas con las que quieres seguir.","help":"Son perfiles reales de Vairo. La invitación a la startup la envías desde la tarjeta de la persona en Social. Marcarla no crea la membresía. Si no eliges a nadie, guarda una lista vacía."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'find-help'
    and s.key = 'pick' and f.key = 'people';
update public.stage_points p set translations = '{"de":{"title":"Prüft, ob ihr zusammenarbeiten könnt","duration_hint":"Ein paar Tage","guide_body":"Gemeinsame Aufgabe\nWählt aus Punkt 1 eine Arbeit, deren Ergebnis im Projekt nützlich ist und die sich in ein paar Tagen abschließen lässt. Das kann die Skizze eines Teils sein, ein einfaches Formular oder die Vorbereitung eines Teils des Dienstes, um ihn einer Zielperson zu zeigen.\nLegt vor dem Start fest, was fertig sein soll, wer welche Teile vorbereitet und wann ihr sie zusammenführt. Passt die Arbeit an die Fähigkeiten der Beteiligten an.\nBeispiel: „Anna bereitet das Modell der Befestigung vor, ich liefere die Maße und prüfe die Passung zum Korb. Am Freitag sehen wir uns das Ergebnis gemeinsam an.“\nNotiert nach der Aufgabe das Ergebnis. Beispiel: „Ein Modell der Befestigung ist entstanden. Es passt zum gewählten Korb, aber der Haken muss verbessert werden.“ So eine Notiz zeigt auch, was sich weiter nutzen lässt.\n§\nWie es mit diesem Team weitergeht\nBesprecht, ob das vereinbarte Ergebnis entstanden ist und ob jede Person ihren Teil erledigen konnte. Wenn etwas hängen geblieben ist, klärt den Grund: fehlende Fähigkeiten, Zeit oder nötige Informationen.\nBestätigt, ob ihr weitermachen wollt. Notiert nur die Änderung, die umgesetzt werden muss, zum Beispiel: „Wir machen weiter. Vor dem nächsten Modell übergebe ich zuerst alle Maße.“ Wenn alles passt, reicht „Wir machen in dieser Besetzung weiter“.\nTeambereitschaft bedeutet hier, dass ihr eine vereinbarte Besetzung habt und die weitere Arbeit aufnehmen könnt. Ein gelungener Test gibt erste Informationen über die Zusammenarbeit. Bei einer schwierigeren Aufgabe können weitere Themen auftauchen.","guide_sources":["Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): gemeinsames Probeprojekt.","Michael Seibel, The Scientific Method for Startups (2016): eine Annahme prüfen und aus dem Ergebnis schließen. Die Anwendung auf einen Zusammenarbeitstest ist eine Anpassung."]},"uk":{"title":"Перевірте, чи вмієте працювати разом","duration_hint":"Кілька днів","guide_body":"Спільне завдання\nОберіть із пункту 1 роботу, результат якої знадобиться в проєкті і яку можна завершити за кілька днів. Це може бути ескіз одного елемента, проста форма або підготовка частини послуги для показу адресатові.\nПеред початком домовтеся, що має бути готове, хто підготує окремі частини і коли ви їх поєднаєте. Підберіть роботу до вмінь людей, які беруть у ній участь.\nПриклад: «Оля підготує модель кріплення, а я надам розміри й перевірю сумісність із кошиком. У п’ятницю подивимося на результат разом».\nПісля завдання запишіть результат. Приклад: «Готова модель кріплення. Пасує до обраного кошика, але гачок треба виправити». Такий запис показує також, що можна використати далі.\n§\nЩо далі з цим складом\nОбговоріть, чи з’явився домовлений результат і чи кожна людина змогла виконати свою частину. Якщо щось застрягло, з’ясуйте причину: брак умінь, часу чи потрібної інформації.\nПідтвердьте, чи хочете продовжувати. Запишіть лише зміну, яку треба запровадити, наприклад: «Продовжуємо. Перед наступною моделлю спершу передаю повний набір розмірів». Якщо все пасує, досить «Продовжуємо в цьому складі».\nГотовність команди означає тут, що у вас є погоджений склад і ви можете взятися за подальшу роботу. Одна вдала спроба дає першу інформацію про співпрацю. За складнішого завдання можуть виникнути інші питання.","guide_sources":["Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): спільний пробний проєкт.","Michael Seibel, The Scientific Method for Startups (2016): перевірка припущення й висновок із результату. Застосування до спроби співпраці — адаптація."]},"es":{"title":"Comprobad si sabéis trabajar juntos","duration_hint":"Unos días","guide_body":"Tarea conjunta\nElegid del punto 1 un trabajo cuyo resultado sirva al proyecto y que pueda terminarse en unos días. Puede ser el boceto de una pieza, un formulario sencillo o preparar una parte del servicio para enseñársela a un destinatario.\nAntes de empezar, acordad qué tiene que estar listo, quién preparará cada parte y cuándo las juntaréis. Ajustad el trabajo a las habilidades de quienes participan.\nEjemplo: «Lucía preparará el modelo del anclaje y yo aportaré las medidas y comprobaré que encaja en la cesta. El viernes vemos juntos el resultado».\nTras la tarea, anotad el resultado. Ejemplo: «Tenemos el modelo del anclaje. Encaja en la cesta elegida, pero hay que mejorar el enganche». Una nota así muestra también qué se puede aprovechar después.\n§\nQué hacer con este equipo\nHablad de si se consiguió el resultado acordado y de si cada persona pudo hacer su parte. Si algo se atascó, averiguad el motivo: falta de habilidades, de tiempo o de información necesaria.\nConfirmad si queréis seguir. Anotad solo el cambio que hay que aplicar, por ejemplo: «Seguimos. Antes del próximo modelo, primero paso todas las medidas». Si todo encaja, basta con «Seguimos con este equipo».\nQue el equipo esté listo significa aquí que tenéis una composición acordada y podéis seguir trabajando. Una prueba que sale bien da la primera información sobre la colaboración. Con una tarea más difícil pueden surgir otras cuestiones.","guide_sources":["Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): proyecto conjunto de prueba.","Michael Seibel, The Scientific Method for Startups (2016): comprobar una suposición y sacar una conclusión del resultado. Aplicarlo a una prueba de colaboración es una adaptación."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'trial';
update public.stage_subpoints s set translations = '{"de":{"title":"Wählt eine gemeinsame Aufgabe"},"uk":{"title":"Оберіть спільне завдання"},"es":{"title":"Elegid una tarea conjunta"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'trial' and s.key = 'task';
update public.stage_fields f set translations = '{"de":{"question":"Welche kleine Aufgabe aus der Liste nehmt ihr als Test?","help":"Sie soll verschiedene Fähigkeiten nutzen und höchstens ein paar Tage dauern.","example":"Modell der Befestigung für eine Fahrradhalterung."},"uk":{"question":"Яке невелике завдання зі списку берете на спробу?","help":"Воно має задіяти різні вміння й зайняти щонайбільше кілька днів.","example":"Модель кріплення велосипедного тримача."},"es":{"question":"¿Qué tarea pequeña de la lista tomáis como prueba?","help":"Debe aprovechar habilidades distintas y llevar como mucho unos días.","example":"Modelo del anclaje del soporte para bicicleta."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'trial'
    and s.key = 'task' and f.key = 'which';
update public.stage_fields f set translations = '{"de":{"question":"Was soll entstehen, wer macht welchen Teil und wann seid ihr fertig?","help":"Ein Satz pro Person reicht.","example":"Anna bereitet das Modell vor, ich liefere die Maße. Am Freitag sehen wir uns das Ergebnis an."},"uk":{"question":"Що має з’явитися, хто робить яку частину і коли завершуєте?","help":"Досить одного речення на людину.","example":"Оля підготує модель, я надам розміри. У п’ятницю дивимося результат."},"es":{"question":"¿Qué hay que hacer, quién hace cada parte y cuándo terminais?","help":"Basta una frase por persona.","example":"Lucía prepara el modelo y yo aporto las medidas. El viernes vemos el resultado."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'trial'
    and s.key = 'task' and f.key = 'plan';
update public.stage_subpoints s set translations = '{"de":{"title":"Notiert das Ergebnis des Tests"},"uk":{"title":"Запишіть результат спроби"},"es":{"title":"Anotad el resultado de la prueba"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'trial' and s.key = 'result';
update public.stage_fields f set translations = '{"de":{"question":"Was ist entstanden und wofür könnt ihr es nutzen?","help":"Kurze Beschreibung oder Link. Das Ergebnis bleibt eine normale Antwort in dieser Etappe.","example":"Ein Modell der Befestigung ist entstanden. Es passt zum Korb, aber der Haken muss verbessert werden. Link: …"},"uk":{"question":"Що з’явилося і для чого можете це використати?","help":"Короткий опис або посилання. Результат залишається звичайною відповіддю в цьому етапі.","example":"Готова модель кріплення. Пасує до кошика, але гачок потребує виправлення. Посилання: …"},"es":{"question":"¿Qué ha salido y para qué podéis usarlo?","help":"Una breve descripción o un enlace. El resultado queda como una respuesta normal de esta etapa.","example":"Tenemos el modelo del anclaje. Encaja en la cesta, pero hay que mejorar el enganche. Enlace: …"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'trial'
    and s.key = 'result' and f.key = 'outcome';
update public.stage_fields f set translations = '{"de":{"question":"Wie geht es mit diesem Team weiter?","help":"Wenn ihr nichts ändert, reicht „Wir machen in dieser Besetzung weiter“. Sonst notiert nur die nötige Änderung.","example":"Wir machen weiter. Vor dem nächsten Modell übergebe ich zuerst alle Maße."},"uk":{"question":"Що далі з цим складом?","help":"Якщо нічого не змінюєте, досить «Продовжуємо в цьому складі». Інакше запишіть лише потрібну зміну.","example":"Продовжуємо. Перед наступною моделлю спершу передаю повний набір розмірів."},"es":{"question":"¿Qué hacéis con este equipo?","help":"Si no cambiáis nada, basta con «Seguimos con este equipo». Si no, anotad solo el cambio necesario.","example":"Seguimos. Antes del próximo modelo, primero paso todas las medidas."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'trial'
    and s.key = 'result' and f.key = 'decision';
update public.stage_fields f set translations = '{"de":{"question":"Das Team ist bereit für die weitere Arbeit.","help":"Hake es ab, wenn ihr eine vereinbarte Besetzung habt. Ein Test muss nicht alles lösen.","config":{"confirm_label":"Team bereit"}},"uk":{"question":"Команда готова до подальшої роботи.","help":"Познач, коли у вас є погоджений склад. Одна спроба не мусить розв’язати всього.","config":{"confirm_label":"Команда готова"}},"es":{"question":"El equipo está listo para seguir trabajando.","help":"Márcalo cuando tengáis una composición acordada. Una prueba no tiene que resolverlo todo.","config":{"confirm_label":"Equipo listo"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'trial'
    and s.key = 'result' and f.key = 'ready';
update public.stage_points p set translations = '{"de":{"title":"Richte einen Arbeitsort ein","duration_hint":"Etwa 10 Minuten","guide_body":"Sammle die Materialien\nSammle in den Dateien die aktuellen Materialien, die weiter gebraucht werden: Beschreibung der Idee, nützliche Erkenntnisse aus Gesprächen und Ergebnisse bisheriger Aufgaben. Wähle Dokumente, zu denen du oder das Team zurückkehren werdet.\nBenenne sie so, dass klar ist, was sie enthalten. Beispiele: „Beschreibung der Idee“, „Erkenntnisse aus Gesprächen“, „Modell der Befestigung“. Wenn es mehrere Versionen gibt, kennzeichne die, an der ihr gerade arbeitet.\nTeile die Materialien mit den nötigen Personen und prüfe, ob sie sie öffnen können. Den Unterpunkt kannst du abhaken, wenn die Dokumente gesammelt und für die Personen zugänglich sind, die sie nutzen werden.\n§\nRegeln der Zusammenarbeit\nVereinbart Verfügbarkeit, Kontaktweg, Entscheidungsfindung und Bedingungen der Beteiligung. Nutzt frühere Vereinbarungen, wenn sie noch gelten.\nNotiert kurze, akzeptierte Regeln. Beispiele: „Jede von uns investiert etwa fünf Stunden pro Woche ins Projekt.“ „Informationen zu Aufgaben schicken wir im gemeinsamen Chat.“ „Ausgaben genehmigen wir gemeinsam.“ „Anna erledigt die bezahlte Aufgabe aus dem vereinbarten Angebot.“\nWählt die Einträge, die zu eurer Situation passen. Wenn ein Punkt nicht geklärt ist, markiert ihn als offen. Wer allein arbeitet, überspringt diesen Unterpunkt.","guide_sources":["Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): Verfügbarkeit, Erwartungen und der Umgang mit Meinungsverschiedenheiten."]},"uk":{"title":"Запусти місце для роботи","duration_hint":"Близько 10 хвилин","guide_body":"Збери матеріали\nУ Файлах збери актуальні матеріали, потрібні далі: опис ідеї, корисні висновки з розмов і результати дотеперішніх завдань. Обери документи, до яких ти або команда повертатиметеся.\nНазви їх так, щоб було зрозуміло, що в них. Приклади: «Опис ідеї», «Висновки з розмов», «Модель кріплення». Коли є кілька версій, вкажи ту, над якою зараз працюєте.\nНадай матеріали потрібним людям і перевір, чи вони можуть їх відкрити. Підпункт можна зарахувати, коли документи зібрано й вони доступні людям, які ними користуватимуться.\n§\nПравила співпраці\nДомовтеся про доступність, спосіб контакту, ухвалення рішень і умови участі. Скористайтеся попередніми домовленостями, якщо вони й далі чинні.\nЗаписуйте короткі погоджені правила. Приклади: «Кожен із нас приділяє проєкту близько п’яти годин на тиждень». «Інформацію до завдання надсилаємо в спільному чаті». «Витрати затверджуємо разом». «Оля виконує платне завдання, описане в погодженій пропозиції».\nОберіть записи, що відповідають вашій ситуації. Якщо якесь питання лишається неузгодженим, позначте його як відкрите. При самостійній роботі пропусти цей підпункт.","guide_sources":["Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): доступність, очікування і спосіб розв’язання непорозумінь."]},"es":{"title":"Pon en marcha el espacio de trabajo","duration_hint":"Unos 10 minutos","guide_body":"Reúne los materiales\nReúne en Archivos los materiales actuales que harán falta: la descripción de la idea, las conclusiones útiles de las conversaciones y los resultados de las tareas hechas. Elige los documentos a los que tú o el equipo volveréis.\nNómbralos de forma que se sepa qué contienen. Ejemplos: «Descripción de la idea», «Conclusiones de las conversaciones», «Modelo del anclaje». Si hay varias versiones, señala la que estáis usando ahora.\nComparte los materiales con quien los necesite y comprueba que pueden abrirlos. Puedes dar por hecho el subpunto cuando los documentos estén reunidos y accesibles para quienes los usarán.\n§\nNormas de colaboración\nAcordad disponibilidad, forma de contacto, toma de decisiones y condiciones de participación. Aprovechad acuerdos anteriores si siguen vigentes.\nAnotad normas breves y aceptadas. Ejemplos: «Cada uno dedica unas cinco horas a la semana al proyecto». «La información de cada tarea la enviamos por el chat común». «Los gastos los aprobamos juntos». «Lucía hace la tarea remunerada descrita en la oferta acordada».\nElegid las que encajen con vuestra situación. Si algo queda sin acordar, marcadlo como abierto. Si trabajas en solitario, omite este subpunto.","guide_sources":["Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): disponibilidad, expectativas y forma de resolver desacuerdos."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'workspace';
update public.stage_subpoints s set translations = '{"de":{"title":"Sammle die Materialien in den Dateien"},"uk":{"title":"Збери матеріали у Файлах"},"es":{"title":"Reúne los materiales en Archivos"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'workspace' and s.key = 'files';
update public.stage_fields f set translations = '{"de":{"question":"Lade die aktuellen Projektmaterialien in den Bereich Dateien hoch und teile sie mit den Personen, die sie nutzen werden.","help":"Hake es ab, wenn die Dokumente an einem Ort sind und sich öffnen lassen.","config":{"confirm_label":"Materialien sind gesammelt","label":"Zu den Dateien"}},"uk":{"question":"Завантаж актуальні матеріали проєкту в розділ Файли й надай їх людям, які ними користуватимуться.","help":"Познач, коли документи в одному місці й відкриваються.","config":{"confirm_label":"Матеріали зібрано","label":"Перейти до Файлів"}},"es":{"question":"Sube los materiales actuales del proyecto a Archivos y compártelos con quienes los vayan a usar.","help":"Márcalo cuando los documentos estén en un solo sitio y se puedan abrir.","config":{"confirm_label":"Los materiales están reunidos","label":"Ir a Archivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'workspace'
    and s.key = 'files' and f.key = 'collected';
update public.stage_subpoints s set translations = '{"de":{"title":"Legt die Regeln der Zusammenarbeit fest"},"uk":{"title":"Домовтеся про правила співпраці"},"es":{"title":"Acordad las normas de colaboración"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'workspace' and s.key = 'rules';
update public.stage_fields f set translations = '{"de":{"question":"Akzeptierte Vereinbarungen, eine pro Eintrag.","help":"Verfügbarkeit, Kontaktweg, Entscheidungsfindung und Bedingungen der Beteiligung. Markiere einen ungeklärten Punkt als offen.","example":"Jede von uns investiert etwa fünf Stunden pro Woche ins Projekt.\nAusgaben genehmigen wir gemeinsam."},"uk":{"question":"Погоджені домовленості, по одній у кожному записі.","help":"Доступність, спосіб контакту, ухвалення рішень і умови участі. Неузгоджене питання познач як відкрите.","example":"Кожен із нас приділяє проєкту близько п’яти годин на тиждень.\nВитрати затверджуємо разом."},"es":{"question":"Acuerdos aceptados, uno por entrada.","help":"Disponibilidad, forma de contacto, toma de decisiones y condiciones de participación. Marca como abierto lo que no esté acordado.","example":"Cada uno dedica unas cinco horas a la semana al proyecto.\nLos gastos los aprobamos juntos."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'workspace'
    and s.key = 'rules' and f.key = 'agreements';
update public.stage_points p set translations = '{"de":{"title":"Sammle, was du für den Start brauchst","duration_hint":"Etwa 10 Minuten","guide_body":"Was zum Start fehlt\nSieh dir die ersten Aufgaben an und prüfe, ob dir etwas zu ihrer Erledigung fehlt. Füge nur hinzu, was du jetzt brauchst. Wenn du alles hast, um anzufangen, ergänze keine Einträge, nur um die Liste zu füllen.\nPrüfe bei einer fehlenden Sache, wie du sie bekommst. Du kannst Material kaufen, Ausrüstung leihen, eine Werkstatt nutzen oder ein Werkzeug verwenden, das jemand im Team schon hat. Trag eine konkrete Quelle ein, wenn du sie kennst.\nEs geht darum, die Dinge mit dem verfügbaren Budget zu bekommen. Kostenloser Zugang oder Leihen können die Startausgaben senken.\nBei den Kosten reicht ein ungefährer Betrag. Ergänze, ob du einmal, monatlich oder pro Nutzung zahlst. Einen unbekannten Preis trägst du als „zu prüfen“ ein. „Kostenlos“ schreibst du, wenn schon feststeht, dass keine Gebühr anfällt.\nBeispiel: Druck des ersten Befestigungsmodells. Werkstatt der Hochschule, nach Absprache über den Zugang. Etwa 15 € für das Material eines Drucks, Betrag noch zu bestätigen.","guide_sources":["Dominika Blackappl, Practical Design: MVP Spec (2016): die erste Version an Machbarkeit und Kosten anpassen.","Michael Seibel, How to Plan an MVP (Startup School, 2019): einfache Mittel für den Start."]},"uk":{"title":"Збери речі, потрібні на старт","duration_hint":"Близько 10 хвилин","guide_body":"Чого бракує на старт\nПоглянь на перші завдання й перевір, чи бракує чогось для їх виконання. Додавай лише те, що зараз потрібно. Якщо маєш усе, щоб почати, не дописуй позицій лише для заповнення списку.\nДля відсутньої речі перевір спосіб її здобути. Можна купити матеріал, позичити обладнання, скористатися майстернею або інструментом, який уже має хтось із команди. Впиши конкретне джерело, якщо його знаєш.\nІдеться про те, щоб здобути речі в межах доступного бюджету. Безплатний доступ або позика можуть зменшити витрати на старт.\nДля вартості досить орієнтовної суми. Допиши, чи платиш раз, щомісяця чи за використання. Невідому ціну впиши як «перевірити». «Безплатно» пиши тоді, коли вже відомо, що оплати не буде.\nПриклад: друк першої моделі кріплення. Майстерня університету, після погодження доступу. Близько 600 грн за матеріал на один друк, суму треба підтвердити.","guide_sources":["Dominika Blackappl, Practical Design: MVP Spec (2016): пристосування першої версії до можливостей виконання й витрат.","Michael Seibel, How to Plan an MVP (Startup School, 2019): прості засоби на старт."]},"es":{"title":"Reúne lo que necesitas para empezar","duration_hint":"Unos 10 minutos","guide_body":"Qué falta para empezar\nMira las primeras tareas y comprueba si te falta algo para hacerlas. Añade solo lo que necesites ahora. Si tienes todo lo necesario para empezar, no añadas elementos solo por rellenar la lista.\nEn cada cosa que falte, mira cómo conseguirla. Puedes comprar material, pedir prestado un equipo, usar un taller o una herramienta que ya tenga alguien del equipo. Escribe una fuente concreta si la conoces.\nSe trata de conseguir las cosas con el presupuesto disponible. El acceso gratuito o el préstamo pueden reducir el gasto inicial.\nPara el coste basta una cifra aproximada. Añade si pagas una vez, cada mes o por uso. Si no sabes el precio, escribe «por comprobar». Escribe «gratis» cuando ya se sepa que no habrá pago.\nEjemplo: impresión del primer modelo del anclaje. Taller de la universidad, tras acordar el acceso. Unos 15 € de material por impresión, cifra por confirmar.","guide_sources":["Dominika Blackappl, Practical Design: MVP Spec (2016): ajustar la primera versión a lo que se puede hacer y a los costes.","Michael Seibel, How to Plan an MVP (Startup School, 2019): medios sencillos para empezar."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'supplies';
update public.stage_subpoints s set translations = '{"de":{"title":"Was fehlt, um anzufangen?"},"uk":{"title":"Чого бракує, щоб почати?"},"es":{"title":"¿Qué falta para empezar?"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'supplies' and s.key = 'missing';
update public.stage_fields f set translations = '{"de":{"question":"Füge nur fehlende Dinge hinzu.","help":"Name, woher du es bekommst und ungefähre Kosten. Eine leere Liste bedeutet, dass du mit dem beginnen kannst, was du schon hast.","example":"Druck des ersten Modells. Werkstatt der Hochschule. Etwa 15 € für das Material.","config":{"add_label":"Ding hinzufügen","columns":[{"key":"thing","label":"Benötigtes Ding","placeholder":"Name, du kannst einen Link ergänzen"},{"key":"source","label":"Woher du es bekommst","placeholder":"Kaufe ich, leihe ich, haben wir im Team"},{"key":"cost","label":"Kosten","placeholder":"Z. B. 50 € einmalig oder kostenlos"}]}},"uk":{"question":"Додай лише те, чого бракує.","help":"Назва, звідки візьмеш і орієнтовна вартість. Порожній список означає, що можна почати з того, що вже є.","example":"Друк першої моделі. Майстерня університету. Близько 600 грн за матеріал.","config":{"add_label":"Додати річ","columns":[{"key":"thing","label":"Потрібна річ","placeholder":"Назва, можна додати посилання"},{"key":"source","label":"Звідки візьмеш","placeholder":"Куплю, позичу, є в команді"},{"key":"cost","label":"Вартість","placeholder":"Напр. 2000 грн одноразово або безплатно"}]}},"es":{"question":"Añade solo lo que falta.","help":"Nombre, de dónde lo sacarás y coste aproximado. Una lista vacía significa que puedes empezar con lo que ya tienes.","example":"Impresión del primer modelo. Taller de la universidad. Unos 15 € de material.","config":{"add_label":"Añadir elemento","columns":[{"key":"thing","label":"Lo que hace falta","placeholder":"Nombre; puedes añadir un enlace"},{"key":"source","label":"De dónde lo sacarás","placeholder":"Lo compro, lo pido prestado, lo tiene el equipo"},{"key":"cost","label":"Coste","placeholder":"P. ej. 50 € una vez o gratis"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'supplies'
    and s.key = 'missing' and f.key = 'items';
update public.stage_categories c set translations = '{"de":{"title":"SaaS","intro":"Ergänze die Zugriffsregeln, die Kosten der ersten Tests und — wenn die erste Version kostenpflichtig ist — was nach der Zahlung mit dem Konto passiert."},"uk":{"title":"SaaS","intro":"Допиши правила доступу, вартість перших тестів і — якщо перша версія платна — що відбувається з акаунтом після оплати."},"es":{"title":"SaaS","intro":"Añade las reglas de acceso, el coste de las primeras pruebas y, si la primera versión es de pago, qué pasa con la cuenta tras el pago."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'preparation' and t.version = 1 and c.key = 'saas';
update public.stage_points p set translations = '{"de":{"title":"Lege fest, wer worauf Zugriff hat","duration_hint":"Etwa 15 Minuten","guide_body":"Wem die Daten gehören\nStell dir vor, zwei verschiedene Kunden nutzen das Programm. Lege fest, welche Materialien jedem von ihnen gehören und ob sie etwas gemeinsam nutzen.\nIn einem Programm für private Notizen kann jede Person eigene Materialien haben. In einem Programm für Firmen können Beschäftigte einen gemeinsamen Bereich ihrer Firma nutzen. Jede Person kann sich dabei mit einem eigenen Konto anmelden.\nBeispiel: „Jede Firma hat einen eigenen Bereich mit Dokumenten. Ihre Beschäftigten nutzen individuelle Konten. Die Dokumente einer Firma sind für andere Firmen nicht zugänglich.“\n§\nWas jede Rolle darf\nLege fest, was die einzelnen Personen tun dürfen. Es reicht anzugeben, welche Materialien sie sehen, ändern und löschen dürfen und ob sie andere einladen können.\nBeispiel: Die Inhaberin des Bereichs kann die Dokumente der Firma sehen, ändern und löschen sowie Beschäftigte einladen und ihnen den Zugriff entziehen. Ein Mitarbeiter kann freigegebene Dokumente sehen und ändern, verwaltet aber nicht den Zugriff anderer.\nFüge nur die Nutzerarten hinzu, die du in der ersten Version brauchst. Wenn jede Person nur eigene Materialien nutzt und alle die gleichen Möglichkeiten haben, reicht ein Eintrag.\nBesprich die Notiz mit der Person, die das Programm baut. Ihr solltet die Frage beantworten können: „Darf diese Person dieses Dokument sehen oder ändern?“ Die Umsetzung dieser Regeln im Programm und die Prüfung der Sicherheit erfolgen beim Bau.","guide_sources":["Microsoft, Tenancy models for a multitenant solution: Aufteilung in Kunden, Nutzer und ihre Daten.","Alex Kracov, The First 90 Days of Building a SaaS Startup: die Funktionsweise des Produkts mit den Menschen abstimmen, die es bauen."]},"uk":{"title":"Визнач, хто має доступ до чого","duration_hint":"Близько 15 хвилин","guide_body":"Чиї дані\nУяви, що програмою користуються двоє різних клієнтів. Визнач, які матеріали належать кожному з них і чи мають вони щось спільне.\nУ програмі для приватних нотаток кожна людина може мати власні матеріали. У програмі для компаній працівники можуть користуватися спільним простором своєї компанії. Кожен працівник може при цьому входити через власний акаунт.\nПриклад: «Кожна компанія має власний простір із документами. Її працівники користуються індивідуальними акаунтами. Документи однієї компанії недоступні іншим компаніям».\n§\nЩо може кожна роль\nВизнач, що можуть робити окремі люди. Досить вказати, які матеріали вони можуть бачити, змінювати й видаляти і чи можуть запрошувати інших.\nПриклад: власник простору може бачити, змінювати й видаляти документи компанії, а також запрошувати працівників і забирати в них доступ. Співробітник може бачити й змінювати надані документи, але не керує доступом інших людей.\nДодавай лише ті типи користувачів, які потрібні в першій версії. Якщо кожен користується лише власними матеріалами і всі мають однакові можливості, досить одного запису.\nОбговори запис із людиною, яка створює програму. Ви маєте вміти відповісти на запитання: «Чи може ця людина побачити або змінити цей документ?». Запровадження цих правил у програмі й перевірка захисту відбудуться під час створення.","guide_sources":["Microsoft, Tenancy models for a multitenant solution: поділ на клієнтів, користувачів і їхні дані.","Alex Kracov, The First 90 Days of Building a SaaS Startup: узгодження того, як працює продукт, із людьми, які його створюють."]},"es":{"title":"Define quién tiene acceso a qué","duration_hint":"Unos 15 minutos","guide_body":"De quién son los datos\nImagina que dos clientes distintos usan el programa. Determina qué materiales pertenecen a cada uno y si deben compartir algo.\nEn un programa de notas personales, cada persona puede tener sus propios materiales. En un programa para empresas, los empleados pueden usar un espacio común de su empresa. Cada empleado puede entrar con su propia cuenta.\nEjemplo: «Cada empresa tiene su propio espacio con documentos. Sus empleados usan cuentas individuales. Los documentos de una empresa no son accesibles para las demás».\n§\nQué puede hacer cada rol\nDetermina qué puede hacer cada persona. Basta con indicar qué materiales pueden ver, cambiar y borrar y si pueden invitar a otros.\nEjemplo: el propietario del espacio puede ver, cambiar y borrar los documentos de la empresa, además de invitar a empleados y quitarles el acceso. Un colaborador puede ver y cambiar los documentos compartidos, pero no gestiona el acceso de otras personas.\nAñade solo los tipos de usuario que necesites en la primera versión. Si cada uno usa solo sus propios materiales y todos pueden hacer lo mismo, basta con una entrada.\nRevisa la nota con quien construye el programa. Deberíais poder responder a la pregunta: «¿Puede esta persona ver o cambiar este documento?». Aplicar estas reglas en el programa y comprobar la seguridad se hará durante la construcción.","guide_sources":["Microsoft, Tenancy models for a multitenant solution: división en clientes, usuarios y sus datos.","Alex Kracov, The First 90 Days of Building a SaaS Startup: acordar cómo funciona el producto con quienes lo construyen."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'access';
update public.stage_subpoints s set translations = '{"de":{"title":"Wem die Daten gehören"},"uk":{"title":"Чиї дані"},"es":{"title":"De quién son los datos"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'access' and s.key = 'space';
update public.stage_fields f set translations = '{"de":{"question":"Haben Nutzer eigene Daten oder teilen sie einen Bereich, etwa einer Firma oder eines Teams?","help":"Notiere die gewählte Variante in einem konkreten Satz.","example":"Jede Firma hat eigene Dokumente. Beschäftigte melden sich mit eigenen Konten an. Firma A sieht die Dokumente von Firma B nicht."},"uk":{"question":"Чи користувачі мають окремі дані, чи ділять простір, наприклад компанії або команди?","help":"Запиши обраний спосіб одним конкретним реченням.","example":"Кожна компанія має власні документи. Працівники входять через власні акаунти. Компанія A не бачить документів компанії B."},"es":{"question":"¿Los usuarios tienen datos separados o comparten un espacio, por ejemplo de una empresa o un equipo?","help":"Anota la opción elegida en una frase concreta.","example":"Cada empresa tiene sus documentos. Los empleados entran con sus propias cuentas. La empresa A no ve los documentos de la empresa B."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'access'
    and s.key = 'space' and f.key = 'model';
update public.stage_subpoints s set translations = '{"de":{"title":"Was jede Rolle darf"},"uk":{"title":"Що може кожна роль"},"es":{"title":"Qué puede hacer cada rol"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'access' and s.key = 'roles';
update public.stage_fields f set translations = '{"de":{"question":"Notiere die Berechtigungen jeder Nutzerart.","help":"Eine Zeile ist eine Rolle. Wenn alle das Gleiche dürfen, reicht ein Eintrag.","example":"Die Inhaberin sieht, ändert und löscht die Dokumente der Firma und lädt Leute ein. Ein Mitarbeiter sieht und ändert freigegebene Dokumente, verwaltet aber keinen Zugriff.","config":{"add_label":"Rolle hinzufügen","columns":[{"key":"role","label":"Rolle","placeholder":"Z. B. Inhaberin des Bereichs"},{"key":"see","label":"Was sie sehen darf","placeholder":"Z. B. Dokumente der eigenen Firma"},{"key":"change","label":"Was sie ändern oder löschen darf","placeholder":"Z. B. eigene Dokumente, keine fremden"},{"key":"invite","label":"Darf sie andere einladen","placeholder":"Ja, nein oder nur zum Lesen"}]}},"uk":{"question":"Запиши повноваження кожного типу користувача.","help":"Одна позиція — одна роль. Якщо всі можуть те саме, досить одного запису.","example":"Власник бачить, змінює й видаляє документи компанії та запрошує людей. Співробітник бачить і змінює надані документи, але не керує доступом.","config":{"add_label":"Додати роль","columns":[{"key":"role","label":"Роль","placeholder":"Напр. власник простору"},{"key":"see","label":"Що може бачити","placeholder":"Напр. документи своєї компанії"},{"key":"change","label":"Що може змінити чи видалити","placeholder":"Напр. власні документи, не чужі"},{"key":"invite","label":"Чи може запрошувати інших","placeholder":"Так, ні або лише для перегляду"}]}},"es":{"question":"Anota los permisos de cada tipo de usuario.","help":"Una línea es un rol. Si todos pueden lo mismo, basta con una entrada.","example":"El propietario ve, cambia y borra los documentos de la empresa e invita a gente. Un colaborador ve y cambia los documentos compartidos, pero no gestiona el acceso.","config":{"add_label":"Añadir rol","columns":[{"key":"role","label":"Rol","placeholder":"P. ej. propietario del espacio"},{"key":"see","label":"Qué puede ver","placeholder":"P. ej. documentos de su empresa"},{"key":"change","label":"Qué puede cambiar o borrar","placeholder":"P. ej. sus propios documentos, no los de otros"},{"key":"invite","label":"¿Puede invitar a otros?","placeholder":"Sí, no o solo de lectura"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'access'
    and s.key = 'roles' and f.key = 'permissions';
update public.stage_points p set translations = '{"de":{"title":"Prüfe, was die ersten Tests kosten","duration_hint":"Etwa 20 Minuten","guide_body":"Berechne die Kosten der Tests\nBeginne mit der Zahl der Personen, die du zu Tests einladen willst. Schätze auch, wie viel sie das Programm nutzen werden. Am Anfang ist das eine Näherung, die du nach den ersten Tests korrigierst.\nDie Zahl der Konten allein reicht womöglich nicht. In einem Programm, das Aufnahmen verarbeitet, zählt ihre Länge. In einem Programm, das Dateien speichert, zählt auch der belegte Speicherplatz.\nBeispiel: „Wir laden 10 Testpersonen ein. Jede verarbeitet etwa 5 Stunden Aufnahmen pro Monat. Zusammen sind das 50 Stunden, also 3000 Minuten Aufnahmen.“\nNutze die im allgemeinen Teil notierten Beträge und prüfe fehlende Preise. Die frühere Liste umfasste vielleicht nur Dinge für den Start. Hier interessieren dich die Kosten der Dienste, die das Programm während der Tests braucht.\nTrenne Fixgebühr und nutzungsabhängige Gebühr. Eine Fixgebühr ist ein fester Betrag pro Zeitraum, zum Beispiel ein Monat Serverbetrieb. Eine nutzungsabhängige Gebühr hängt von der genutzten Menge ab, zum Beispiel von Minuten Aufnahme oder Datenmenge. Ein Dienst kann beide Arten von Gebühren haben.\nBeispiel mit ausgedachten Beträgen: Server 15 € pro Monat, Verarbeitung von Aufnahmen 0,01 € pro Minute. Bei 3000 Minuten kostet die Verarbeitung 30 €. Zusammen etwa 45 € pro Monat.\nNotiere den Betrag und die Annahmen, aus denen er sich ergibt. Wenn du etwas noch nicht weißt, markiere es als „zu prüfen“. Unbekannte Kosten trägst du nicht als null ein.\n§\nLimit und Budget\nPrüfe, was der Anbieter bei Überschreitung eines Limits tut: Er berechnet einen Aufschlag, stoppt den Betrieb oder verlangt den Wechsel in ein teureres Paket. Achte darauf, ob das Limit für das ganze Programm oder pro Nutzer gilt.\nVergleiche die geschätzten Kosten mit dem Betrag, den du für Tests ausgeben kannst. Berücksichtige deine eigenen Tests des Programms und eine stärkere Nutzung als ursprünglich angenommen.\nWenn die Kosten zu hoch sind, begrenze, was sie erhöht: die Zahl der Testpersonen, die Länge der verarbeiteten Aufnahmen oder die Menge gespeicherter Dateien.\nBeispiel: „Für den Anfang laden wir 10 Personen ein. Jede kann bis zu 5 Stunden Aufnahmen pro Monat verarbeiten. Nach Ausschöpfen des Limits warten weitere Aufnahmen bis zum nächsten Monat.“\nStimme mit der Person, die das Programm baut, ab, wie dieses Limit funktionieren soll. Das bloße Notieren in Vairo stoppt die Abrechnung durch den Anbieter nicht.\nWenn eine zusätzliche Begrenzung unnötig ist, reicht eine kurze Begründung, zum Beispiel: „Das gewählte Paket hat einen Festpreis und blockiert Uploads, sobald der verfügbare Speicher belegt ist, ohne automatische Aufschläge.“","guide_sources":["Stripe, How to start a SaaS business: Kosten für Infrastruktur und Dienste.","Microsoft, Pricing models for a multitenant solution: Kosten an die Nutzung koppeln und die Bedeutung von Limits.","Userpilot, How to build a product launch plan for SaaS: Start mit einer begrenzten Gruppe und kleinem Umfang."]},"uk":{"title":"Перевір, скільки коштуватимуть перші тести","duration_hint":"Близько 20 хвилин","guide_body":"Порахуй вартість тестів\nПочни з кількості людей, яких хочеш запросити до тестів. Оціни також, скільки вони користуватимуться програмою. На початку це буде наближення, яке виправиш після перших тестів.\nСамої кількості акаунтів може не вистачити. У програмі, що обробляє записи, має значення їхня тривалість. У програмі, що зберігає файли, важить також зайняте місце.\nПриклад: «Запрошуємо 10 тестувальників. Кожен оброблятиме близько 5 годин записів на місяць. Разом це 50 годин, тобто 3000 хвилин записів».\nСкористайся сумами, записаними в загальній частині, і перевір відсутні ціни. Попередній список міг охоплювати лише речі на старт. Тут тебе цікавить вартість послуг, потрібних для роботи програми під час тестів.\nРозділи фіксовану оплату й оплату за використання. Фіксована оплата — це певна сума за період, наприклад місяць утримання програми на сервері. Оплата за використання залежить від використаного обсягу, наприклад хвилин запису чи обсягу даних. Одна послуга може мати обидва види оплат.\nПриклад із вигаданими сумами: сервер 600 грн на місяць, обробка записів 0,4 грн за хвилину. За 3000 хвилин обробка коштує 1200 грн. Разом близько 1800 грн на місяць.\nЗапиши суму й припущення, з яких вона випливає. Якщо чогось ще не знаєш, познач як «перевірити». Невідому вартість не вписуй як нуль.\n§\nЛіміт і бюджет\nПеревір, що зробить постачальник після перевищення ліміту: нарахує доплату, зупинить роботу чи вимагатиме переходу на дорожчий пакет. Зверни увагу, чи ліміт стосується всієї програми чи окремого користувача.\nПорівняй оцінену вартість із сумою, яку можеш виділити на тести. Врахуй власну перевірку програми й можливість більшого використання, ніж спершу припускаєш.\nЯкщо вартість зависока, обмеж те, що її збільшує: кількість тестувальників, тривалість оброблюваних записів або обсяг збережених файлів.\nПриклад: «На початок запрошуємо 10 людей. Кожна може обробити до 5 годин записів на місяць. Після вичерпання ліміту наступні записи чекають до наступного місяця».\nДомовся з людиною, яка створює програму, як працюватиме такий ліміт. Сам запис у Vairo не зупинить нарахування оплат постачальником.\nЯкщо додаткове обмеження зайве, досить короткого обґрунтування, наприклад: «Обраний пакет має фіксовану ціну і блокує завантаження файлів після вичерпання доступного місця, без автоматичних доплат».","guide_sources":["Stripe, How to start a SaaS business: витрати на інфраструктуру й послуги.","Microsoft, Pricing models for a multitenant solution: зв’язок витрат із використанням і значення лімітів.","Userpilot, How to build a product launch plan for SaaS: старт з обмеженої групи й невеликого обсягу."]},"es":{"title":"Comprueba cuánto costarán las primeras pruebas","duration_hint":"Unos 20 minutos","guide_body":"Calcula el coste de las pruebas\nEmpieza por el número de personas que quieres invitar a las pruebas. Estima también cuánto usarán el programa. Al principio será una aproximación que corregirás tras las primeras pruebas.\nEl número de cuentas puede no bastar. En un programa que procesa grabaciones importa su duración. En uno que guarda archivos cuenta también el espacio ocupado.\nEjemplo: «Invitamos a 10 testers. Cada uno procesará unas 5 horas de grabaciones al mes. En total, 50 horas, es decir, 3000 minutos de grabaciones».\nUsa las cifras anotadas en la parte general y comprueba los precios que faltan. La lista anterior quizá solo incluía lo necesario para empezar. Aquí te interesan los costes de los servicios necesarios para que el programa funcione durante las pruebas.\nSepara la tarifa fija de la tarifa por uso. La tarifa fija es una cantidad determinada por periodo, por ejemplo un mes de servidor. La tarifa por uso depende de la cantidad utilizada, por ejemplo minutos de grabación o volumen de datos. Un mismo servicio puede tener ambos tipos.\nEjemplo con cifras inventadas: servidor 15 € al mes, procesamiento de grabaciones 0,01 € por minuto. Con 3000 minutos, el procesamiento cuesta 30 €. En total, unos 45 € al mes.\nAnota la cifra y las suposiciones de las que sale. Si aún no sabes algo, márcalo como «por comprobar». No escribas cero en un coste desconocido.\n§\nLímite y presupuesto\nComprueba qué hará el proveedor al superar el límite: cobrar un recargo, detener el servicio o exigir pasar a un plan más caro. Fíjate en si el límite es para todo el programa o por usuario.\nCompara el coste estimado con la cantidad que puedes destinar a las pruebas. Ten en cuenta tus propias comprobaciones del programa y la posibilidad de un uso mayor del previsto.\nSi el coste es demasiado alto, limita lo que lo aumenta: el número de testers, la duración de las grabaciones procesadas o la cantidad de archivos guardados.\nEjemplo: «Para empezar invitamos a 10 personas. Cada una puede procesar hasta 5 horas de grabaciones al mes. Agotado el límite, las siguientes grabaciones esperan al mes siguiente».\nAcuerda con quien construye el programa cómo funcionará ese límite. Anotarlo en Vairo no detiene los cobros del proveedor.\nSi no hace falta un límite adicional, basta una justificación breve, por ejemplo: «El plan elegido tiene precio fijo y bloquea la subida de archivos al agotar el espacio, sin recargos automáticos».","guide_sources":["Stripe, How to start a SaaS business: costes de infraestructura y servicios.","Microsoft, Pricing models for a multitenant solution: vincular costes al uso e importancia de los límites.","Userpilot, How to build a product launch plan for SaaS: empezar con un grupo limitado y un alcance pequeño."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'test-cost';
update public.stage_subpoints s set translations = '{"de":{"title":"Wie viele Testpersonen und wie viel sie verbrauchen"},"uk":{"title":"Скільки тестувальників і скільки вони використають"},"es":{"title":"Cuántos testers y cuánto consumirán"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'test-cost' and s.key = 'usage';
update public.stage_fields f set translations = '{"de":{"question":"Wie viele Testpersonen lädst du ein und wie viel verbraucht jede?","help":"Nenne die Zahl der Personen und die Einheit, die wirklich Kosten verursacht: Zeit, Speicherplatz oder Zahl der Vorgänge.","example":"10 Personen, jede verarbeitet etwa 5 Stunden Aufnahmen pro Monat. Zusammen 50 Stunden."},"uk":{"question":"Скільки тестувальників запросиш і скільки кожен використає?","help":"Вкажи кількість людей і одиницю, яка справді породжує витрати: час, місце або кількість операцій.","example":"10 людей, кожна обробить близько 5 годин записів на місяць. Разом 50 годин."},"es":{"question":"¿Cuántos testers invitarás y cuánto consumirá cada uno?","help":"Indica el número de personas y la unidad que de verdad genera coste: tiempo, espacio o número de operaciones.","example":"10 personas; cada una procesará unas 5 horas de grabaciones al mes. En total, 50 horas."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'test-cost'
    and s.key = 'usage' and f.key = 'plan';
update public.stage_fields f set translations = '{"de":{"question":"Wie hoch sind die geschätzten monatlichen Kosten der Dienste für diese Gruppe?","help":"Geh von den Preisen aus der Fehlliste im Allgemeinen Teil aus. Rechne Fixgebühr und nutzungsabhängige Gebühr dazu. Bei unbekanntem Preis schreib „zu prüfen“, nicht null.","example":"Server 15 € pro Monat plus 0,01 € pro Minute Aufnahme. Bei 3000 Minuten ergibt das etwa 45 € pro Monat."},"uk":{"question":"Яка орієнтовна місячна вартість послуг для цієї групи?","help":"Відштовхуйся від цін зі списку прогалин у Загальному. Додай фіксовану оплату й оплату за використання. За невідомої ціни напиши «перевірити», а не нуль.","example":"Сервер 600 грн на місяць плюс 0,4 грн за хвилину запису. За 3000 хвилин виходить близько 1800 грн на місяць."},"es":{"question":"¿Cuál es el coste mensual estimado de los servicios para este grupo?","help":"Parte de los precios de la lista de pendientes de General. Suma la tarifa fija y la tarifa por uso. Si no conoces un precio, escribe «por comprobar», no cero.","example":"Servidor 15 € al mes más 0,01 € por minuto de grabación. Con 3000 minutos salen unos 45 € al mes."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'test-cost'
    and s.key = 'usage' and f.key = 'monthly';
update public.stage_subpoints s set translations = '{"de":{"title":"Was nach Überschreiten des Limits passiert"},"uk":{"title":"Що після перевищення ліміту"},"es":{"title":"Qué pasa al superar el límite"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'test-cost' and s.key = 'limits';
update public.stage_fields f set translations = '{"de":{"question":"Was passiert, wenn die Limits der gewählten Dienste überschritten werden?","help":"Schreib bei jedem Dienst: Aufschlag, Betriebsstopp oder nötiger Paketwechsel. Vermerke, ob das Limit für das ganze Programm oder pro Nutzer gilt.","example":"Ist der Speicher voll, blockiert der Anbieter neue Dateien und berechnet keinen Aufschlag.\nVerarbeitung von Aufnahmen über das Paket hinaus kostet mehr pro Minute."},"uk":{"question":"Що станеться після перевищення лімітів обраних послуг?","help":"Біля кожної послуги напиши: доплата, зупинка роботи або потреба змінити пакет. Познач, чи ліміт на всю програму, чи на одного користувача.","example":"Після вичерпання місця постачальник блокує нові файли й не нараховує доплати.\nОбробка записів понад пакет коштує дорожче за хвилину."},"es":{"question":"¿Qué pasará al superar los límites de los servicios elegidos?","help":"En cada servicio escribe: recargo, detención del servicio o cambio obligado de plan. Indica si el límite es para todo el programa o por usuario.","example":"Agotado el espacio, el proveedor bloquea nuevos archivos y no cobra recargo.\nProcesar grabaciones por encima del plan cuesta más por minuto."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'test-cost'
    and s.key = 'limits' and f.key = 'overage';
update public.stage_fields f set translations = '{"de":{"question":"Welches Limit legst du für die Tests fest, um im Budget zu bleiben?","help":"Zahl der Testpersonen, Stunden oder Speicherplatz. Wenn ein zusätzliches Limit unnötig ist, schreib kurz warum.","example":"10 Personen, bis zu 5 Stunden Aufnahmen pro Person und Monat. Nach dem Limit warten weitere Aufnahmen bis zum nächsten Monat."},"uk":{"question":"Який ліміт накладаєш на тести, щоб умістися в бюджет?","help":"Кількість тестувальників, години або місце. Якщо додатковий ліміт зайвий, коротко напиши чому.","example":"10 людей, до 5 годин записів на людину щомісяця. Після ліміту наступні записи чекають до наступного місяця."},"es":{"question":"¿Qué límite pones a las pruebas para no salirte del presupuesto?","help":"Número de testers, horas o espacio. Si no hace falta un límite adicional, explica brevemente por qué.","example":"10 personas, hasta 5 horas de grabaciones al mes por persona. Superado el límite, las siguientes esperan al mes siguiente."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'test-cost'
    and s.key = 'limits' and f.key = 'cap';
update public.stage_points p set translations = '{"de":{"title":"Lege die Regeln für den kostenpflichtigen Zugang fest","duration_hint":"Etwa 15 Minuten","guide_body":"Wie Kunden zahlen und Zugang bekommen\nNutze die in der Idea Stage gewählte Abrechnungsart. Lege fest, wie die erste Person zahlt und was passieren muss, damit sie die bezahlte Version nutzen kann.\nBei einem einfachen Angebot kannst du einen fertigen Zahlungslink verwenden. Wenn du anfangs nur wenige Personen betreust, kannst du den Zugang von Hand freischalten, nachdem du die Zahlung im Dashboard des Zahlungsanbieters geprüft hast.\nBeispiel: „Kunden zahlen über den Link zum gewählten Angebot. Nach Bestätigung der Zahlung im Dashboard des Zahlungsanbieters schalten wir das Konto frei und teilen mit, dass die Nutzung beginnen kann.“\nVereinbare bei manueller Abwicklung, wer Zahlungen prüft und wie lange Kunden auf den Zugang warten. Außerdem müssen Folgezahlungen und das Ende des bezahlten Zeitraums im Blick behalten werden.\nWenn der Zugang automatisch freigeschaltet werden soll, muss die Person, die das Programm baut, es mit den Informationen des Zahlungsanbieters verbinden. Ein Zahlungslink allein bedeutet nicht, dass das Konto automatisch freigeschaltet wird.\nBei nutzungsabhängiger Abrechnung legst du außerdem fest, woher ihr die Information über die genutzte Menge bekommt, etwa die Zahl erledigter Aufgaben.\n§\nWas in typischen Situationen passiert\nGeh die Situationen aus der Aufgabe durch. Notiere bei jeder, was Nutzer tun können und ab wann sich ihre Möglichkeiten ändern.\nBeginne mit einer erfolgreichen Zahlung. Lege fest, wann Kunden Zugang bekommen und für wie lange. Wenn du einen kostenlosen Test anbietest, entscheide, was nach seinem Ende passiert: welche Möglichkeiten bleiben und was Nutzer tun müssen, um weiterzumachen. Gibt es keinen solchen Test, trag „Entfällt“ ein.\nUnterscheide bei einer fehlgeschlagenen Zahlung zwischen Erstkauf und Verlängerung. Wer gerade ein Konto anlegt, ist in einer anderen Lage als jemand, der das Programm seit Monaten nutzt und plötzlich ein Problem mit der Karte hat. Lege fest, ob Bestandskunden zusätzliche Zeit bekommen und wann die Nutzung eingeschränkt wird.\nBetrachte die Kündigung der Verlängerung gesondert. Notiere, bis wann Kunden die bereits bezahlten Möglichkeiten nutzen können und wann keine weiteren Gebühren mehr abgebucht werden. Lege dann fest, was nach Ende des bezahlten Zeitraums passiert. Berücksichtige die Möglichkeit, gespeicherte Materialien anzusehen und herunterzuladen.\nBeispiel: „Nach der Kündigung der Verlängerung nutzt der Kunde das Programm bis zum Ende des bezahlten Zeitraums. Danach kann er gespeicherte Dokumente ansehen und herunterladen, aber keine neuen hinzufügen oder bestehende bearbeiten.“\nPasse die Regeln an dein Angebot an. Das Ende des bezahlten Zugangs, das Löschen des Kontos und das Löschen gespeicherter Materialien sind getrennte Entscheidungen.\nPrüfe zum Schluss mit der Person, die das Programm baut, ob die gewählte Zahlungsabwicklung eure Vereinbarungen umsetzen kann. Dieselben Regeln sollten den Kunden klar erklärt werden.","guide_sources":["Stripe, Create subscriptions: Abos über fertige Werkzeuge und Zahlungslinks abwickeln.","Stripe, Using webhooks with subscriptions: Zahlungsinformationen und Zugriffsverwaltung.","Stripe, Cancel subscriptions: Kündigung der Verlängerung und Ende nach dem bezahlten Zeitraum."]},"uk":{"title":"Визнач правила платного доступу","duration_hint":"Близько 15 хвилин","guide_body":"Як клієнт платить і отримує доступ\nСкористайся способом розрахунку, обраним в Idea Stage. Визнач, як заплатить перша людина і що має статися, щоб вона могла користуватися оплаченою версією.\nДля простої пропозиції можна скористатися готовим посиланням на оплату. Якщо спочатку обслуговуєш небагато людей, доступ можна надавати вручну після перевірки платежу в панелі платіжного оператора.\nПриклад: «Клієнт платить через посилання, прив’язане до обраної пропозиції. Після підтвердження оплати в панелі оператора ми розблоковуємо його акаунт і повідомляємо, що він може почати користуватися».\nЗа ручного обслуговування домовся, хто перевіряє платежі і скільки клієнт чекатиме на доступ. Також треба стежити за наступними платежами й кінцем оплаченого періоду.\nЯкщо доступ має вмикатися автоматично, людина, яка створює програму, мусить пов’язати її з інформацією від платіжного оператора. Саме посилання на оплату не означає, що акаунт автоматично розблокується.\nЗа оплати залежно від використання визнач також, звідки ви візьмете інформацію про використаний обсяг, наприклад про кількість виконаних завдань.\n§\nЩо відбувається в типових ситуаціях\nПройди ситуації із завдання. Для кожної запиши, що користувач може зробити і з якого моменту змінюються його можливості.\nПочни з успішної оплати. Визнач, коли клієнт отримує доступ і на який час. Якщо пропонуєш безплатний тест, виріши, що відбувається після його завершення: які можливості залишаються і що користувач має зробити, щоб користуватися далі. Якщо такого тесту немає, впиши «Не стосується».\nЗа невдалої оплати розрізняй першу покупку й поновлення. Людина, яка лише створює акаунт, у іншій ситуації, ніж клієнт, що кілька місяців користується програмою і раптом має проблему з карткою. Визнач, чи наявний клієнт отримує додатковий час і коли настане обмеження користування.\nОкремо розглянь відмову від поновлення. Запиши, до якого моменту клієнт може користуватися вже оплаченими можливостями і коли припиняється стягнення наступних оплат. Далі визнач, що відбувається після завершення оплаченого періоду. Врахуй можливість переглядати й завантажувати збережені матеріали.\nПриклад: «Після відмови від поновлення клієнт користується до кінця оплаченого періоду. Потім може переглядати й завантажувати збережені документи, але не може додавати нових чи редагувати наявні».\nДобери правила до своєї пропозиції. Завершення платного доступу, видалення акаунта й видалення збережених матеріалів — це окремі рішення.\nНасамкінець перевір із людиною, яка створює програму, чи обраний спосіб обробки платежів дає змогу застосувати ваші домовленості. Ті самі правила треба чітко пояснити клієнтові.","guide_sources":["Stripe, Create subscriptions: обслуговування підписок через готові інструменти й посилання на оплату.","Stripe, Using webhooks with subscriptions: інформація про платежі та керування доступом.","Stripe, Cancel subscriptions: відмова від поновлення й завершення після оплаченого періоду."]},"es":{"title":"Define las reglas del acceso de pago","duration_hint":"Unos 15 minutos","guide_body":"Cómo paga el cliente y obtiene acceso\nUsa la forma de cobro elegida en la Idea Stage. Determina cómo pagará la primera persona y qué tiene que pasar para que pueda usar la versión de pago.\nCon una oferta sencilla puedes usar un enlace de pago ya hecho. Si al principio atiendes a pocas personas, puedes dar acceso a mano tras comprobar el pago en el panel del proveedor de pagos.\nEjemplo: «El cliente paga con el enlace de la oferta elegida. Cuando el panel del proveedor confirma el pago, desbloqueamos su cuenta y le avisamos de que puede empezar».\nSi lo gestionas a mano, acuerda quién comprueba los pagos y cuánto esperará el cliente para tener acceso. También hay que vigilar los pagos siguientes y el fin del periodo pagado.\nSi el acceso debe activarse automáticamente, quien construye el programa tiene que conectarlo con la información del proveedor de pagos. Un enlace de pago, por sí solo, no desbloquea la cuenta automáticamente.\nSi cobras por uso, determina también de dónde sacaréis la cantidad utilizada, por ejemplo el número de tareas realizadas.\n§\nQué pasa en situaciones típicas\nRepasa las situaciones de la tarea. En cada una anota qué puede hacer el usuario y desde cuándo cambian sus posibilidades.\nEmpieza por un pago correcto. Determina cuándo obtiene acceso el cliente y por cuánto tiempo. Si ofreces una prueba gratuita, decide qué pasa al terminar: qué posibilidades se mantienen y qué tiene que hacer el usuario para seguir. Si no hay prueba, escribe «No aplica».\nSi falla un pago, distingue la primera compra de la renovación. Quien acaba de crear la cuenta está en otra situación que un cliente que lleva meses usando el programa y de repente tiene un problema con la tarjeta. Determina si el cliente actual tiene tiempo adicional y cuándo se limitará el uso.\nTrata aparte la cancelación de la renovación. Anota hasta cuándo puede usar el cliente lo ya pagado y cuándo dejan de cobrarse nuevos pagos. Después determina qué pasa al terminar el periodo pagado. Ten en cuenta la posibilidad de ver y descargar los materiales guardados.\nEjemplo: «Tras cancelar la renovación, el cliente lo usa hasta el final del periodo pagado. Después puede ver y descargar los documentos guardados, pero no añadir nuevos ni editar los existentes».\nAjusta las reglas a tu oferta. Terminar el acceso de pago, borrar la cuenta y borrar los materiales guardados son decisiones distintas.\nPor último, comprueba con quien construye el programa si la forma elegida de gestionar pagos permite aplicar lo acordado. Las mismas reglas deben explicarse con claridad al cliente.","guide_sources":["Stripe, Create subscriptions: gestionar suscripciones con herramientas ya hechas y enlaces de pago.","Stripe, Using webhooks with subscriptions: información de pagos y gestión del acceso.","Stripe, Cancel subscriptions: cancelar la renovación y finalizar tras el periodo pagado."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'paid';
update public.stage_subpoints s set translations = '{"de":{"title":"Ist die erste Version kostenpflichtig?"},"uk":{"title":"Чи перша версія платна?"},"es":{"title":"¿La primera versión es de pago?"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'paid' and s.key = 'choice';
update public.stage_fields f set translations = '{"de":{"question":"Wird in der ersten Version jemand für den Zugang zahlen?","help":"Wenn nicht, entfällt der Rest dieses Punkts. Du kommst darauf zurück, wenn du die Antwort änderst.","config":{"options":[{"value":"yes","label":"Ja, der Zugang wird kostenpflichtig"},{"value":"no","label":"Nein, die erste Version ist kostenlos"}]}},"uk":{"question":"Чи в першій версії хтось платитиме за доступ?","help":"Якщо ні, решта цього пункту відпадає. Повернешся до неї, коли зміниш відповідь.","config":{"options":[{"value":"yes","label":"Так, доступ буде платним"},{"value":"no","label":"Ні, перша версія безплатна"}]}},"es":{"question":"¿Alguien pagará por el acceso en la primera versión?","help":"Si no, el resto de este punto no aplica. Volverás a él si cambias la respuesta.","config":{"options":[{"value":"yes","label":"Sí, el acceso será de pago"},{"value":"no","label":"No, la primera versión es gratuita"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'paid'
    and s.key = 'choice' and f.key = 'answer';
update public.stage_subpoints s set translations = '{"de":{"title":"Wie Kunden zahlen und Zugang bekommen"},"uk":{"title":"Як клієнт платить і отримує доступ"},"es":{"title":"Cómo paga el cliente y obtiene acceso"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'paid' and s.key = 'how';
update public.stage_fields f set translations = '{"de":{"question":"Wie zahlen Kunden und wie bekommen sie Zugang?","help":"Schreib, wer die Zahlung prüft und ob das Konto von Hand oder automatisch freigeschaltet wird.","example":"Kunden zahlen über den Link zum Angebot. Nach Zahlungseingang im Dashboard des Zahlungsanbieters schalten wir das Konto von Hand frei und schreiben, dass es losgehen kann."},"uk":{"question":"Як клієнт заплатить і як отримає доступ?","help":"Напиши, хто перевіряє оплату і чи акаунт вмикається вручну, чи сам.","example":"Клієнт платить через посилання на пропозицію. Після оплати в панелі оператора вручну розблоковуємо акаунт і пишемо, що можна починати."},"es":{"question":"¿Cómo pagará el cliente y cómo obtendrá acceso?","help":"Escribe quién comprueba el pago y si la cuenta se activa a mano o sola.","example":"El cliente paga con el enlace de la oferta. Cuando llega el pago al panel del proveedor, desbloqueamos la cuenta a mano y le escribimos que ya puede empezar."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'paid'
    and s.key = 'how' and f.key = 'flow';
update public.stage_subpoints s set translations = '{"de":{"title":"Wann der Zugang beginnt und endet"},"uk":{"title":"Коли доступ починається і закінчується"},"es":{"title":"Cuándo empieza y termina el acceso"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'paid' and s.key = 'cases';
update public.stage_fields f set translations = '{"de":{"question":"Ein Kunde hat den Zugang bezahlt. Ab wann kann er ihn nutzen und wie lange?","help":"Ein Satz. Bei nutzungsabhängiger Abrechnung ergänze, woher ihr die Verbrauchsdaten bekommt.","example":"Der Zugang wird am selben Tag freigeschaltet und gilt bis zum Ende des bezahlten Monats."},"uk":{"question":"Клієнт оплатив доступ. З якого моменту може користуватися і як довго?","help":"Одне речення. За оплати за використання допиши, звідки берете інформацію про використання.","example":"Доступ вмикається того ж дня й триває до кінця оплаченого місяця."},"es":{"question":"Un cliente ha pagado el acceso. ¿Desde cuándo puede usarlo y durante cuánto tiempo?","help":"Una frase. Si cobras por uso, añade de dónde sacáis la información del consumo.","example":"El acceso se activa el mismo día y dura hasta el final del mes pagado."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'paid'
    and s.key = 'cases' and f.key = 'paid_ok';
update public.stage_fields f set translations = '{"de":{"question":"Der kostenlose Test ist zu Ende. Was bleibt und was erfordert eine Zahlung?","help":"Wenn es keinen kostenlosen Test gibt, schreib „Entfällt“.","example":"Nach 14 Tagen kann er gespeicherte Daten nur noch ansehen, bis er den Zugang bezahlt."},"uk":{"question":"Безплатний тест закінчився. Що залишається, а що вимагає оплати?","help":"Якщо безплатного тесту немає, напиши «Не стосується».","example":"Після 14 днів може лише переглядати збережені дані, доки не оплатить доступ."},"es":{"question":"Ha terminado la prueba gratuita. ¿Qué se mantiene y qué requiere pago?","help":"Si no hay prueba gratuita, escribe «No aplica».","example":"Pasados 14 días solo puede ver los datos guardados hasta que pague el acceso."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'paid'
    and s.key = 'cases' and f.key = 'trial';
update public.stage_fields f set translations = '{"de":{"question":"Die Zahlung ist fehlgeschlagen. Was passiert mit einem neuen Konto und was mit einem Kunden, der es schon nutzt?","help":"Trenne Erstkauf und Verlängerung. Schreib, ob Bestandskunden zusätzliche Tage bekommen.","example":"Ein neues Konto wird deaktiviert. Bestandskunden haben 7 Tage, um die Karte zu aktualisieren, danach wird das Hinzufügen neuer Inhalte gesperrt."},"uk":{"question":"Оплата не вдалася. Що з новим акаунтом, а що з клієнтом, який уже користується?","help":"Розрізняй першу покупку й поновлення. Напиши, чи наявний клієнт отримує додаткові дні.","example":"Новий акаунт вимикається. Наявний клієнт має 7 днів, щоб виправити картку, потім можливість додавати нове закривається."},"es":{"question":"El pago ha fallado. ¿Qué pasa con una cuenta nueva y qué con un cliente que ya lo usa?","help":"Separa la primera compra de la renovación. Escribe si el cliente actual tiene días adicionales.","example":"La cuenta nueva se desactiva. El cliente actual tiene 7 días para corregir la tarjeta; después se bloquea añadir cosas nuevas."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'paid'
    and s.key = 'cases' and f.key = 'failed';
update public.stage_fields f set translations = '{"de":{"question":"Ein Kunde hat die Verlängerung gekündigt, aber der bezahlte Zeitraum läuft noch. Bis wann nutzt er das Programm?","help":"Schreib, bis wann das bereits Bezahlte gilt und dass keine weitere Gebühr abgebucht wird.","example":"Er nutzt es bis zum Ende des bezahlten Monats. Die nächste Zahlung wird nicht abgebucht."},"uk":{"question":"Клієнт відмовився від поновлення, але оплачений період ще триває. До якого моменту він користується?","help":"Напиши, до якого моменту діє вже оплачене і що наступна оплата не стягується.","example":"Користується до кінця оплаченого місяця. Наступний платіж не списується."},"es":{"question":"Un cliente ha cancelado la renovación, pero el periodo pagado sigue en curso. ¿Hasta cuándo lo usa?","help":"Escribe hasta cuándo vale lo ya pagado y que no se cobra el siguiente pago.","example":"Lo usa hasta el final del mes pagado. No se cobra el siguiente pago."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'paid'
    and s.key = 'cases' and f.key = 'cancel';
update public.stage_fields f set translations = '{"de":{"question":"Der bezahlte Zeitraum ist vorbei. Kann er gespeicherte Materialien noch ansehen oder herunterladen?","help":"Ende des Zugangs, Löschen des Kontos und Löschen der Materialien sind getrennte Entscheidungen.","example":"Er kann gespeicherte Dokumente ansehen und herunterladen. Er kann keine neuen hinzufügen oder sie ändern."},"uk":{"question":"Оплачений період закінчився. Чи може він ще переглядати або завантажити збережені матеріали?","help":"Завершення доступу, видалення акаунта й видалення матеріалів — окремі рішення.","example":"Може переглядати й завантажувати збережені документи. Не може додавати нових чи їх змінювати."},"es":{"question":"Ha terminado el periodo pagado. ¿Puede todavía ver o descargar los materiales guardados?","help":"Terminar el acceso, borrar la cuenta y borrar los materiales son decisiones distintas.","example":"Puede ver y descargar los documentos guardados. No puede añadir nuevos ni cambiarlos."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'paid'
    and s.key = 'cases' and f.key = 'ended';
update public.stage_categories c set translations = '{"de":{"title":"Hardware","intro":"Mach aus den ersten Schätzungen aus Idea Zahlen, Lieferanten, Tests und eine Liste dessen, was den Bau noch blockiert."},"uk":{"title":"Hardware","intro":"Перетвори попередні оцінки з Idea на числа, постачальників, тести і список того, що ще блокує створення."},"es":{"title":"Hardware","intro":"Convierte las estimaciones iniciales de Idea en cifras, proveedores, pruebas y una lista de lo que aún bloquea la construcción."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'preparation' and t.version = 1 and c.key = 'hardware';
update public.stage_points p set translations = '{"de":{"title":"Formalisiere die Anforderungen der ersten Version","duration_hint":"Etwa 25 Minuten","guide_body":"Von der Schätzung zur Spezifikation\nPreparation bedeutet bei einem physischen Produkt den Schritt vom Wissen „Ist das machbar?“ zum Dokument „Wie genau bauen wir es?“. Idea hat die Fragen nach Machbarkeit, Kosten, Zeit, Nachfrage und Konformität beantwortet — als erste Schätzungen. Aufgabe dieser Etappe ist nicht, Tests zu wiederholen, sondern die Ergebnisse in eine messbare Spezifikation zu übersetzen, die sich ohne Rätselraten umsetzen lässt.\nJede Einschränkung aus früheren Tests — Haltbarkeit, Gewicht, Energieverbrauch, Genauigkeit — bekommt jetzt einen Zahlenwert und einen Status: verpflichtend oder wünschenswert.\nListet auf dieser Grundlage die wichtigsten Baugruppen auf, trennt kritische von Hilfskomponenten und ordnet jedes Modul einer Kategorie zu: muss, sollte, kann, nicht jetzt. Prüft zum Schluss, ob der Umfang alle verpflichtenden Anforderungen abdeckt. Wenn nicht, muss die Lücke geschlossen werden, bevor jemand mit dem Entwurf beginnt.\n§\nMessbare Anforderungen\nMach aus losen Ideen Zahlen. Statt zu schreiben, das Gerät solle „leicht sein und lange halten“, notiere konkrete Parameter: maximales Gewicht, Abmessungen und die erforderliche Akkulaufzeit.\nGenaue Zahlen vom ersten Tag an verringern Missverständnisse zwischen der Person, die für das Produkt verantwortlich ist, und der Person, die es baut, und erlauben es, den Fortschritt zu prüfen.\n§\nMinimum und Ziel\nLegt für jeden Parameter zwei Werte fest: die absolute Mindestschwelle, die für eine funktionierende erste Version nötig ist, und den Zielwert, den ihr später anstrebt.\nDie Trennung dieser Werte schützt davor, ständig Verbesserungen hinzuzufügen, und lässt euch eine stabile erste Version veröffentlichen, ohne den Start endlos zu verschieben.\n§\nVerpflichtend und wünschenswert\nTeilt die Funktionen in kritische und zusätzliche. Beschreibt den erwarteten Effekt, zum Beispiel „das Gerät überträgt alle 5 Sekunden drahtlos Daten“, und nicht eine konkrete Schaltungslösung wie „wir verwenden Modul X“.\nFasst das in einer Notiz zusammen, auf die das ganze Team Zugriff hat. Sonst entstehen leicht zwei widersprüchliche Versionen der Annahmen."},"uk":{"title":"Формалізуй вимоги першої версії","duration_hint":"Близько 25 хвилин","guide_body":"Від оцінки до специфікації\nPreparation для фізичного продукту — це перехід від знання «чи це здійсненно» до документа «як саме ми це збудуємо». Idea відповіла на запитання про здійсненність, витрати, час, попит і відповідність — у формі попередніх оцінок. Завдання цього етапу — не повторювати тести, а перекласти результати в вимірювану специфікацію, яку можна реалізувати без здогадок.\nКожне обмеження з попередніх тестів — довговічність, маса, енергоспоживання, точність — тепер отримує числове значення і статус: обов’язкове чи бажане.\nНа цій основі випишіть ключові вузли, відокремте критичні елементи від допоміжних і віднесіть кожен модуль до категорії: має бути, бажано, може бути, не зараз. Насамкінець перевірте, чи обсяг покриває всі обов’язкові вимоги. Якщо ні, прогалину треба закрити, перш ніж хтось почне проєктувати.\n§\nВимірювані вимоги\nПеретвори розмиті ідеї на числа. Замість писати, що пристрій має бути «легким і довго працювати», запиши конкретні параметри: максимальну масу, розміри і потрібний час роботи від батареї.\nТочні числа з першого дня зменшують непорозуміння між людиною, відповідальною за продукт, і людиною, яка його створює, і дають змогу перевіряти поступ.\n§\nМінімум і мета\nДля кожного параметра визначте два значення: абсолютно мінімальний поріг, потрібний для робочої першої версії, і цільове значення, до якого прагнете пізніше.\nРозділення цих значень захищає від постійного додавання поліпшень і дає змогу випустити стабільну першу версію, не відкладаючи старт без кінця.\n§\nОбов’язкове і бажане\nПоділіть функції на критичні й додаткові. Описуйте очікуваний ефект, наприклад «пристрій бездротово передає дані кожні 5 секунд», а не конкретне схемне рішення, наприклад «використовуємо модуль X».\nЗберіть це в одному записі, доступному всій команді. Інакше легко отримати дві суперечливі версії припущень."},"es":{"title":"Formaliza los requisitos de la primera versión","duration_hint":"Unos 25 minutos","guide_body":"De la estimación a la especificación\nPara un producto físico, Preparation supone pasar del saber «¿es viable?» al documento «¿cómo exactamente lo construiremos?». Idea respondió a las preguntas sobre viabilidad, costes, plazos, demanda y conformidad en forma de estimaciones iniciales. La tarea de esta etapa no es repetir pruebas, sino traducir los resultados a una especificación medible que se pueda llevar a cabo sin conjeturas.\nCada limitación de las pruebas anteriores —durabilidad, peso, consumo de energía, precisión— recibe ahora un valor numérico y un estado: obligatorio o deseable.\nA partir de ahí, enumerad los subconjuntos clave, separad los elementos críticos de los auxiliares y asignad cada módulo a una categoría: debe estar, debería estar, puede estar, ahora no. Al final, comprobad si el alcance cubre todos los requisitos obligatorios. Si no, hay que cerrar el hueco antes de que nadie empiece a diseñar.\n§\nRequisitos medibles\nConvierte las ideas vagas en cifras. En lugar de escribir que el dispositivo debe ser «ligero y durar mucho», anota parámetros concretos: peso máximo, dimensiones y autonomía de batería necesaria.\nTener cifras precisas desde el primer día reduce los malentendidos entre quien lleva el producto y quien lo construye, y permite comprobar el avance.\n§\nMínimo y objetivo\nPara cada parámetro fijad dos valores: el umbral mínimo imprescindible para tener una primera versión que funcione y el valor objetivo al que aspiráis después.\nSeparar estos valores protege de añadir mejoras sin parar y permite lanzar una primera versión estable sin aplazar el inicio indefinidamente.\n§\nObligatorio y deseable\nDividid las funciones en críticas y adicionales. Describid el efecto esperado, por ejemplo «el dispositivo envía datos de forma inalámbrica cada 5 segundos», y no una solución de circuito concreta, como «usamos el módulo X».\nReunidlo en un único registro accesible para todo el equipo. Si no, es fácil acabar con dos versiones contradictorias de los supuestos."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'spec';
update public.stage_subpoints s set translations = '{"de":{"title":"Messbare Parameter"},"uk":{"title":"Параметри, які можна виміряти"},"es":{"title":"Parámetros medibles"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'spec' and s.key = 'numbers';
update public.stage_fields f set translations = '{"de":{"question":"Notiere Funktionen und Einschränkungen als messbare Anforderungen.","help":"Eine Zeile ist ein Parameter. Das Minimum muss in der ersten Version erfüllt sein. Das Ziel hebt ihr euch für später auf. Priorität: verpflichtend oder wünschenswert.","example":"Laufzeit. Minimum 8 Stunden, Ziel 12 Stunden, verpflichtend. Gewicht. Minimum bis 300 g, Ziel bis 250 g, wünschenswert.","config":{"add_label":"Anforderung hinzufügen","columns":[{"key":"name","label":"Parameter oder Effekt","placeholder":"Z. B. Laufzeit mit einer Ladung"},{"key":"minimum","label":"Minimum der ersten Version","placeholder":"Z. B. 8 Stunden"},{"key":"target","label":"Ziel für später","placeholder":"Z. B. 12 Stunden"},{"key":"priority","label":"Verpflichtend oder wünschenswert","placeholder":"Verpflichtend oder wünschenswert"}]}},"uk":{"question":"Запиши функції й обмеження як вимірювані вимоги.","help":"Одна позиція — один параметр. Мінімум має бути виконано в першій версії. Мету залишаєте на потім. Пріоритет: обов’язкове чи бажане.","example":"Час роботи. Мінімум 8 годин, мета 12 годин, обов’язкове. Маса. Мінімум до 300 г, мета до 250 г, бажане.","config":{"add_label":"Додати вимогу","columns":[{"key":"name","label":"Параметр або ефект","placeholder":"Напр. час роботи на одному заряді"},{"key":"minimum","label":"Мінімум першої версії","placeholder":"Напр. 8 годин"},{"key":"target","label":"Мета на потім","placeholder":"Напр. 12 годин"},{"key":"priority","label":"Обов’язкове чи бажане","placeholder":"Обов’язкове або бажане"}]}},"es":{"question":"Anota las funciones y limitaciones como requisitos medibles.","help":"Una línea es un parámetro. El mínimo debe cumplirse en la primera versión. El objetivo queda para después. Prioridad: obligatorio o deseable.","example":"Autonomía. Mínimo 8 horas, objetivo 12 horas, obligatorio. Peso. Mínimo hasta 300 g, objetivo hasta 250 g, deseable.","config":{"add_label":"Añadir requisito","columns":[{"key":"name","label":"Parámetro o efecto","placeholder":"P. ej. autonomía con una carga"},{"key":"minimum","label":"Mínimo de la primera versión","placeholder":"P. ej. 8 horas"},{"key":"target","label":"Objetivo para después","placeholder":"P. ej. 12 horas"},{"key":"priority","label":"Obligatorio o deseable","placeholder":"Obligatorio o deseable"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'spec'
    and s.key = 'numbers' and f.key = 'requirements';
update public.stage_points p set translations = '{"de":{"title":"Formalisiere Lieferanten und Produktion","duration_hint":"Etwa 30 Minuten","guide_body":"Warum Lieferanten so viel wiegen wie die Spezifikation\nErgänze die ersten Preisangaben und Lieferantenlisten aus Idea um harte Daten: Mindestbestellmengen, Verfügbarkeit, Ersatzteile für kritische Komponenten, maximale Lieferzeit, nötige Werkzeuge und Maschinen sowie geografische, rechtliche und kommerzielle Einschränkungen.\nHier zeigen sich am häufigsten die Risiken, die später die Produktion am stärksten verzögern.\n§\nPreise, Mengen und Verfügbarkeit\nMach aus der ersten Stückliste eine Datei für die erste Serie. Sammle Stückpreise, Verfügbarkeit und Mindestbestellmengen.\nEine häufige Falle: Der Hersteller verlangt den Kauf von Tausenden Stück eines Bauteils, während ihr eine Kleinserie fertigt. Diese Zahlen früh zu prüfen schützt davor, Geld in überzähligen Teilen zu binden.\n§\nErsatzteile\nNenne die Baugruppen, die am stärksten von Preisschwankungen oder Engpässen bedroht sind, und finde für sie ein Ersatzteil oder einen zweiten Lieferanten.\nDas Fehlen eines kleinen Bauteils kann die Produktion lange stoppen. Ein freigegebenes Ersatzteil ist eine Absicherung, keine Zierde der Liste.\n§\nLieferzeit und Werkzeuge\nLege die maximale Wartezeit für Schlüsselteile fest sowie die Maschinen, Formen und Prüfwerkzeuge, die für die Produktion nötig sind.\nEine eigene Spritzgussform für das Gehäuse kann 8–12 Wochen dauern. Trag diesen Termin sofort in den Plan ein, damit die Montage der Serie nicht stockt.\n§\nZoll und Transport\nNimm Zoll, Einfuhr- und Ausfuhrvorschriften und die realistische Transportzeit in die Kalkulation auf.\nDie Kosten pro Stück sind nicht nur der Großhandelspreis. Fracht, Steuern und Zollabwicklung verändern die Endmarge und den Termin."},"uk":{"title":"Формалізуй постачальників і виробництво","duration_hint":"Близько 30 хвилин","guide_body":"Чому постачальники важать стільки ж, скільки специфікація\nДоповни попередні ціни й списки постачальників з Idea твердими даними: мінімальні обсяги замовлень, доступність, замінники для критичних елементів, максимальний час виконання, потрібні інструменти й машини, а також географічні, правові й торговельні обмеження.\nСаме тут найчастіше виходять ризики, які пізніше найбільше затримують виробництво.\n§\nЦіни, кількості й доступність\nПеретвори попередній список деталей на один файл першої серії. Збери ціни за одиницю, доступність і мінімальні обсяги замовлень.\nЧаста пастка: виробник вимагає купити тисячі штук мікросхеми, а ви складаєте коротку серію. Рання перевірка цих чисел захищає від заморожування грошей у надлишкових деталях.\n§\nЗамінники\nВкажи вузли, найбільше вразливі до коливань цін чи дефіциту, і знайди для них замінник або другого постачальника.\nВідсутність однієї дрібної мікросхеми може надовго зупинити виробництво. Затверджений замінник — це страховка, а не прикраса списку.\n§\nЧас доставки й інструменти\nВизнач максимальний час очікування на ключові деталі, а також машини, форми й тестові інструменти, потрібні для виробництва.\nСпеціальна ливарна форма для корпусу може зайняти 8–12 тижнів. Одразу впиши цей термін у план, щоб не зупинити складання серії.\n§\nМито й транспорт\nДо розрахунку впиши мито, вимоги ввезення й вивезення та реальний час транспортування.\nВартість одиниці — це не лише ціна з оптового складу. Фрахт, податки й митне оформлення змінюють кінцеву маржу й термін."},"es":{"title":"Formaliza proveedores y producción","duration_hint":"Unos 30 minutos","guide_body":"Por qué los proveedores pesan tanto como la especificación\nCompleta los precios y listas de proveedores iniciales de Idea con datos firmes: cantidades mínimas de pedido, disponibilidad, sustitutos para los elementos críticos, plazo máximo de entrega, herramientas y máquinas necesarias y limitaciones geográficas, legales y comerciales.\nAquí suelen aparecer los riesgos que más retrasan después la producción.\n§\nPrecios, cantidades y disponibilidad\nConvierte la lista inicial de piezas en un archivo de la primera serie. Reúne precios unitarios, disponibilidad y cantidades mínimas de pedido.\nUna trampa frecuente: el fabricante exige comprar miles de unidades de un chip y vosotros montáis una serie corta. Comprobar pronto estas cifras evita inmovilizar dinero en piezas sobrantes.\n§\nSustitutos\nSeñala los subconjuntos más expuestos a cambios de precio o escasez y busca para ellos un sustituto o un segundo proveedor.\nLa falta de un pequeño chip puede parar la producción mucho tiempo. Un sustituto aprobado es una protección, no un adorno de la lista.\n§\nPlazo de entrega y herramientas\nFija el plazo máximo de espera de las piezas clave y las máquinas, moldes y herramientas de prueba necesarios para producir.\nUn molde de inyección propio para la carcasa puede llevar 8–12 semanas. Mete ese plazo en el plan desde ya para no frenar el montaje de la serie.\n§\nAduanas y transporte\nIncluye en el cálculo los aranceles, los requisitos de importación y exportación y el tiempo real de transporte.\nEl coste por unidad no es solo el precio del distribuidor. El flete, los impuestos y los trámites aduaneros cambian el margen final y el plazo."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'supply';
update public.stage_subpoints s set translations = '{"de":{"title":"Teile der ersten Serie"},"uk":{"title":"Деталі першої серії"},"es":{"title":"Piezas de la primera serie"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'supply' and s.key = 'bom';
update public.stage_fields f set translations = '{"de":{"question":"Sammle Preise, Mindestbestellmenge und Verfügbarkeit der Teile.","help":"Eine Zeile ist ein Teil oder Material. Unbekannten Preis als „zu prüfen“ eintragen, nicht als null.","example":"Gehäuse. 4,50 € pro Stück bei einer Mindestbestellung von 200. Verfügbar, Lieferung 6 Wochen.","config":{"add_label":"Teil hinzufügen","columns":[{"key":"part","label":"Teil","placeholder":"Name und ggf. Lieferant"},{"key":"price","label":"Preis pro Stück","placeholder":"Z. B. 4,50 € oder zu prüfen"},{"key":"moq","label":"Mindestbestellung","placeholder":"Z. B. 200 Stück"},{"key":"lead","label":"Verfügbarkeit und Lieferzeit","placeholder":"Z. B. vorrätig, 6 Wochen"}]}},"uk":{"question":"Збери ціни, мінімальне замовлення й доступність деталей.","help":"Одна позиція — одна деталь або матеріал. Невідому ціну впиши як «перевірити», а не як нуль.","example":"Корпус. 180 грн за штуку при замовленні від 200. Доступний, доставка 6 тижнів.","config":{"add_label":"Додати деталь","columns":[{"key":"part","label":"Деталь","placeholder":"Назва й можливий постачальник"},{"key":"price","label":"Ціна за штуку","placeholder":"Напр. 180 грн або перевірити"},{"key":"moq","label":"Мінімальне замовлення","placeholder":"Напр. 200 штук"},{"key":"lead","label":"Доступність і час доставки","placeholder":"Напр. є, 6 тижнів"}]}},"es":{"question":"Reúne precios, pedido mínimo y disponibilidad de las piezas.","help":"Una línea es una pieza o material. Si no conoces el precio, escribe «por comprobar», no cero.","example":"Carcasa. 4,50 € la unidad con pedido mínimo de 200. Disponible, entrega en 6 semanas.","config":{"add_label":"Añadir pieza","columns":[{"key":"part","label":"Pieza","placeholder":"Nombre y, si lo hay, proveedor"},{"key":"price","label":"Precio por unidad","placeholder":"P. ej. 4,50 € o por comprobar"},{"key":"moq","label":"Pedido mínimo","placeholder":"P. ej. 200 unidades"},{"key":"lead","label":"Disponibilidad y plazo de entrega","placeholder":"P. ej. disponible, 6 semanas"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'supply'
    and s.key = 'bom' and f.key = 'parts';
update public.stage_subpoints s set translations = '{"de":{"title":"Ersatzteile und Werkzeuge"},"uk":{"title":"Замінники й інструменти"},"es":{"title":"Sustitutos y herramientas"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'supply' and s.key = 'backup';
update public.stage_fields f set translations = '{"de":{"question":"Welche Teile sind riskant und welchen Ersatz gibt es?","help":"Trag Teile ein, deren Fehlen oder Preissprung die Serie stoppen würde. Wenn es keine gibt, lass die Liste leer und speichere.","example":"Mikrocontroller A. Ersatz: Baustein B, schon an einem Muster getestet.","config":{"add_label":"Kritisches Teil hinzufügen","columns":[{"key":"part","label":"Kritisches Teil","placeholder":"Was die Produktion stoppen kann"},{"key":"alt","label":"Ersatz oder zweiter Lieferant","placeholder":"Name oder „suche noch“"}]}},"uk":{"question":"Які деталі ризиковані і який у них замінник?","help":"Впиши деталі, відсутність чи стрибок ціни яких зупинили б серію. Якщо таких немає, залиш список порожнім і збережи.","example":"Мікроконтролер A. Замінник: мікросхема B, уже перевірена на зразку.","config":{"add_label":"Додати критичну деталь","columns":[{"key":"part","label":"Критична деталь","placeholder":"Що може зупинити виробництво"},{"key":"alt","label":"Замінник або другий постачальник","placeholder":"Назва або «ще шукаю»"}]}},"es":{"question":"¿Qué piezas son arriesgadas y qué sustituto tienen?","help":"Escribe las piezas cuya falta o subida de precio pararía la serie. Si no hay, deja la lista vacía y guarda.","example":"Microcontrolador A. Sustituto: chip B, ya probado en una muestra.","config":{"add_label":"Añadir pieza crítica","columns":[{"key":"part","label":"Pieza crítica","placeholder":"Qué puede parar la producción"},{"key":"alt","label":"Sustituto o segundo proveedor","placeholder":"Nombre o «todavía buscando»"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'supply'
    and s.key = 'backup' and f.key = 'seconds';
update public.stage_fields f set translations = '{"de":{"question":"Welche Werkzeuge, Maschinen oder Formen braucht die erste Serie?","help":"Ergänze bei jeder Zeile die ungefähre Vorbereitungszeit, wenn du sie kennst.","example":"Spritzgussform für das Gehäuse. Vorbereitung etwa 10 Wochen.\nPrüfstand für die Dichtheit."},"uk":{"question":"Які інструменти, машини чи форми потрібні для першої серії?","help":"Біля кожної позиції допиши орієнтовний час її підготовки, якщо знаєш.","example":"Ливарна форма корпусу. Підготовка близько 10 тижнів.\nСтенд для перевірки герметичності."},"es":{"question":"¿Qué herramientas, máquinas o moldes hacen falta para la primera serie?","help":"En cada línea añade el tiempo aproximado de preparación, si lo conoces.","example":"Molde de inyección de la carcasa. Preparación unas 10 semanas.\nBanco de prueba de estanqueidad."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'supply'
    and s.key = 'backup' and f.key = 'tools';
update public.stage_fields f set translations = '{"de":{"question":"Welche Zölle, Ein- und Ausfuhrvorschriften und Transportzeiten fließen in Kosten und Termin ein?","help":"Wenn du in einem Land verkaufst und produzierst und keine solchen Kosten siehst, schreib das direkt.","example":"Teile aus Asien: Fracht und Zoll etwa 12 % des Werts. Transport 4 Wochen. Das fließt in den Stückpreis ein."},"uk":{"question":"Яке мито, правила ввезення й вивезення та час транспортування входять у вартість і термін?","help":"Якщо продаєш і виробляєш в одній країні й не бачиш таких витрат, напиши це прямо.","example":"Деталі з Азії: фрахт і мито близько 12% вартості. Транспорт 4 тижні. Це входить у ціну одиниці."},"es":{"question":"¿Qué aranceles, normas de importación y exportación y tiempos de transporte entran en el coste y el plazo?","help":"Si vendes y fabricas en un mismo país y no ves estos costes, dilo directamente.","example":"Piezas de Asia: flete y aranceles, en torno al 12 % del valor. Transporte de 4 semanas. Entra en el precio unitario."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'supply'
    and s.key = 'backup' and f.key = 'logistics';
update public.stage_points p set translations = '{"de":{"title":"Lege Qualität, Sicherheit und Zuverlässigkeit fest","duration_hint":"Etwa 20 Minuten","guide_body":"Qualität, bevor das Produkt auf den Markt kommt\nÜbersetze die Probleme aus den Prototyptests in Bedingungen, deren Erfüllung sich messen lässt. Sicherheitsanforderungen sind nicht verhandelbar, unabhängig von Zeit- oder Budgetdruck.\n§\nSichere Nutzung\nMach aus technologischen Risiken und Nutzungsszenarien Vorgaben, die einen Ausfall verhindern sollen.\nLege die Bedingungen für sicheren Betrieb bei normaler Nutzung und bei vorhersehbarer Fehlbedienung fest: Sturz, falsches Ladegerät, Feuchtigkeit. Wer Nutzerfehler mitdenkt, verringert spätere Rücksendungen.\n§\nHaltbarkeit und Fehlerschwelle\nLege die geplante Lebensdauer unter realen Bedingungen fest sowie den akzeptablen Anteil an Ausschuss in der Produktion und an Ausfällen bei Kunden.\nKein Gerät ist ausfallfrei. Ein Limit, zum Beispiel unter 1 % Ausfälle pro Jahr, erlaubt es, Austausch und Kontrolle zu planen, statt null anzunehmen.\n§\nEs lässt sich prüfen\nFormuliere jede Anforderung so, dass sie sich durch Messung, Test oder Verfahren prüfen lässt.\nStatt „das Gehäuse muss robust sein“ schreib: „Das Gehäuse übersteht einen Sturz aus 1,2 m Höhe auf Beton ohne Risse.“"},"uk":{"title":"Визнач якість, безпеку й надійність","duration_hint":"Близько 20 хвилин","guide_body":"Якість, перш ніж продукт вийде на ринок\nПерекладай проблеми з тестів прототипу в умови, виконання яких можна виміряти. Вимоги безпеки вважай такими, що не обговорюються, незалежно від тиску часу чи бюджету.\n§\nБезпечне використання\nПеретвори технологічні ризики й сценарії користування на настанови, які мають запобігти аварії.\nВизнач умови безпечної роботи за звичайного використання і за передбачувано неправильного: падіння, не той зарядний пристрій, вологість. Проєктування з урахуванням помилки користувача зменшує пізніші повернення.\n§\nДовговічність і поріг помилок\nВизнач запланований строк служби в реальних умовах і прийнятну частку браку на виробництві та відмов у клієнтів.\nЖоден пристрій не безвідмовний. Ліміт, наприклад менше 1% відмов на рік, дає змогу планувати заміни й контроль, а не закладати нуль.\n§\nЦе можна перевірити\nКожну вимогу сформулюй так, щоб її можна було перевірити вимірюванням, тестом чи процедурою.\nЗамість «корпус має бути міцним» запиши: «корпус витримує падіння з висоти 1,2 м на бетон без тріщин»."},"es":{"title":"Define calidad, seguridad y fiabilidad","duration_hint":"Unos 20 minutos","guide_body":"Calidad antes de que el producto llegue al mercado\nTraduce los problemas de las pruebas del prototipo a condiciones cuyo cumplimiento se pueda medir. Trata los requisitos de seguridad como innegociables, sea cual sea la presión de tiempo o de presupuesto.\n§\nUso seguro\nConvierte los riesgos tecnológicos y los escenarios de uso en pautas que eviten fallos.\nDefine las condiciones de funcionamiento seguro con un uso normal y con un mal uso previsible: caída, cargador equivocado, humedad. Diseñar pensando en el error del usuario reduce las devoluciones posteriores.\n§\nDurabilidad y umbral de fallos\nDefine la vida útil prevista en condiciones reales y el porcentaje aceptable de rechazos en producción y de averías en clientes.\nNingún dispositivo está libre de fallos. Un límite, por ejemplo menos del 1 % de averías al año, permite planificar sustituciones y controles en lugar de suponer cero.\n§\nSe puede comprobar\nFormula cada requisito de forma que pueda comprobarse con una medición, una prueba o un procedimiento.\nEn lugar de «la carcasa tiene que ser resistente», escribe: «la carcasa aguanta una caída de 1,2 m sobre hormigón sin agrietarse»."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'quality';
update public.stage_subpoints s set translations = '{"de":{"title":"Sichere Nutzung und Fehlerschwelle"},"uk":{"title":"Безпечне використання і поріг помилок"},"es":{"title":"Uso seguro y umbral de fallos"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'quality' and s.key = 'safe';
update public.stage_fields f set translations = '{"de":{"question":"Wie soll sich das Produkt bei normaler Nutzung und bei vorhersehbaren Nutzerfehlern verhalten?","help":"Sturz, falsche Stromversorgung, Feuchtigkeit, ein Kind in der Nähe — nur, was dieses Gerät wirklich betrifft.","example":"Bei einem Sturz vom Schreibtisch bricht das Gehäuse nicht. Ein falsches Ladegerät darf den Akku nicht beschädigen oder das Gehäuse erhitzen."},"uk":{"question":"Як продукт має поводитися за звичайного використання і за передбачуваної помилки користувача?","help":"Падіння, неправильне живлення, вологість, дитина поруч — лише те, що справді стосується цього пристрою.","example":"При падінні зі столу корпус не тріскає. Неправильний зарядний пристрій не може пошкодити батарею чи нагріти корпус."},"es":{"question":"¿Cómo debe comportarse el producto con un uso normal y ante un error previsible del usuario?","help":"Caída, alimentación incorrecta, humedad, un niño cerca: solo lo que de verdad afecta a este dispositivo.","example":"Si cae de la mesa, la carcasa no se rompe. Un cargador equivocado no puede dañar la batería ni calentar la carcasa."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'quality'
    and s.key = 'safe' and f.key = 'use';
update public.stage_fields f set translations = '{"de":{"question":"Wie lange soll es funktionieren und welchen Anteil an Defekten oder Ausschuss akzeptierst du?","help":"Nenne einen Zeitraum und eine Zahl. „Wenige Ausfälle“ lässt sich nicht prüfen.","example":"Ein Jahr tägliche Nutzung. Unter 2 % Ausschuss bei der Kontrolle und unter 1 % Ausfälle im ersten Jahr."},"uk":{"question":"Як довго має працювати і яку частку несправностей чи браку ти приймаєш?","help":"Вкажи період і число. «Мало відмов» перевірити неможливо.","example":"Рік щоденного використання. Менше 2% штук відбраковано на контролі й менше 1% відмов у перший рік."},"es":{"question":"¿Cuánto tiempo debe funcionar y qué porcentaje de defectos o rechazos aceptas?","help":"Indica un periodo y una cifra. «Pocas averías» no se puede comprobar.","example":"Un año de uso diario. Menos del 2 % de unidades rechazadas en control y menos del 1 % de averías el primer año."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'quality'
    and s.key = 'safe' and f.key = 'life';
update public.stage_subpoints s set translations = '{"de":{"title":"Wie ihr das prüft"},"uk":{"title":"Як ви це перевірите"},"es":{"title":"Cómo lo comprobaréis"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'quality' and s.key = 'tests';
update public.stage_fields f set translations = '{"de":{"question":"Formuliere die Anforderungen so, dass sie sich messen lassen.","help":"Eine Zeile ist ein Test oder eine Messung.","example":"Dichtheit. 30 Minuten in 1 m Tiefe eingetaucht, kein Wasser im Inneren.","config":{"add_label":"Test hinzufügen","columns":[{"key":"need","label":"Anforderung","placeholder":"Was zutreffen soll"},{"key":"test","label":"Test oder Messung","placeholder":"Wie ihr das prüft"}]}},"uk":{"question":"Запиши вимоги так, щоб їх можна було виміряти.","help":"Одна позиція — один тест або вимірювання.","example":"Герметичність. Занурення на 30 хвилин на глибину 1 м, без води всередині.","config":{"add_label":"Додати тест","columns":[{"key":"need","label":"Вимога","placeholder":"Що має бути правдою"},{"key":"test","label":"Тест або вимірювання","placeholder":"Як ви це перевірите"}]}},"es":{"question":"Escribe los requisitos de forma que se puedan medir.","help":"Una línea es una prueba o una medición.","example":"Estanqueidad. Inmersión de 30 minutos a 1 m de profundidad, sin agua en el interior.","config":{"add_label":"Añadir prueba","columns":[{"key":"need","label":"Requisito","placeholder":"Qué tiene que cumplirse"},{"key":"test","label":"Prueba o medición","placeholder":"Cómo lo comprobaréis"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'quality'
    and s.key = 'tests' and f.key = 'checks';
update public.stage_points p set translations = '{"de":{"title":"Übersetze Vorschriften in Produkteigenschaften","duration_hint":"Etwa 25 Minuten","guide_body":"Vorschriften als Eigenschaften, nicht als Schlagworte\nOrdne die Regulierungen und Zertifikate aus Idea konkreten Produkteigenschaften, nötiger Dokumentation, Prüfumfang und Kennzeichnungen zu. Prüfe, ob eine rechtliche Anforderung einer technischen Annahme widerspricht, solange noch Zeit für eine Änderung ist.\n§\nWas eine Vorschrift am Entwurf ändert\nVerknüpfe Anforderungen mit konkreten Lösungen: Materialwahl, Erdung, Platinenlayout.\nElektromagnetische Verträglichkeit und elektrische Sicherheit, die schon beim Schaltplan berücksichtigt werden, vermeiden teure Korrekturen nach nicht bestandenen Prüfungen.\n§\nDokumente und Prüfungen\nErstelle eine Liste von Dokumenten, Berichten und Normen auf den gewählten Märkten, zum Beispiel CE oder FCC, und ordne sie der Phase zu, in der sie gebraucht werden.\nEine Zertifizierung erfordert vollständige technische Unterlagen. Wer sie laufend sammelt, vermeidet Stillstand kurz vor dem Verkauf.\n§\nEtiketten und Anleitung\nLege Inhalt, Symbole und Format der Typenschilder, Warnaufkleber und Anleitungen fest, die auf dem Startmarkt vorgeschrieben sind.\nEin fehlendes Pflichtsymbol, zum Beispiel die durchgestrichene Mülltonne, kann eine Lieferung stoppen oder den Verkauf unmöglich machen.\n§\nWiderspricht eine Vorschrift dem Rest\nPrüfe, ob eine rechtliche Anforderung den Abmessungen, dem Gewicht oder der Nutzungsweise widerspricht. Löse das vor dem Bau.\nBeispiel: Ein dickeres isolierendes Gehäuse ändert die Abmessungen noch auf der Zeichnung, bevor ihr Formen bestellt."},"uk":{"title":"Перетвори правила на властивості продукту","duration_hint":"Близько 25 хвилин","guide_body":"Правила як властивості, а не гасла\nЗістав регуляції й сертифікати з Idea з конкретними властивостями продукту, потрібною документацією, обсягом випробувань і позначеннями. Перевір, чи правова вимога не суперечить технічному припущенню, поки ще є час на зміну.\n§\nЩо правило змінює в проєкті\nПов’яжи вимоги з конкретними рішеннями: вибір матеріалу, заземлення, розведення плати.\nЕлектромагнітна сумісність і електробезпека, враховані ще на схемі, зменшують дорогі виправлення після невдалих випробувань.\n§\nДокументи й випробування\nСклади перелік документів, звітів і норм на обраних ринках, наприклад CE чи FCC, і прив’яжи їх до етапу, на якому вони потрібні.\nСертифікація вимагає повної технічної документації. Збирання її поточно зменшує простій перед самим продажем.\n§\nЕтикетки й інструкція\nВизнач зміст, символи й формат табличок, попереджувальних наліпок та інструкцій, вимаганих на ринку, з якого починаєш.\nВідсутність обов’язкового символу, наприклад перекресленого кошика, може зупинити поставку або унеможливити продаж.\n§\nЧи правило суперечить решті\nПеревір, чи правова вимога не суперечить розмірам, масі чи способу використання. Розв’яжи це до створення.\nПриклад: товстіший ізоляційний корпус змінює розміри ще на кресленні, до того як ви замовите форми."},"es":{"title":"Traduce la normativa en características del producto","duration_hint":"Unos 25 minutos","guide_body":"La normativa como características, no como lemas\nRelaciona las normas y certificados de Idea con características concretas del producto, la documentación necesaria, el alcance de los ensayos y el marcado. Comprueba si algún requisito legal choca con un supuesto técnico mientras aún hay tiempo para cambiarlo.\n§\nQué cambia una norma en el diseño\nVincula los requisitos con soluciones concretas: elección de material, toma de tierra, diseño de la placa.\nTener en cuenta la compatibilidad electromagnética y la seguridad eléctrica ya en el esquema evita correcciones caras tras suspender los ensayos.\n§\nDocumentos y ensayos\nHaz una lista de documentos, informes y normas de los mercados elegidos, por ejemplo CE o FCC, y asígnalos a la fase en que se necesitan.\nLa certificación exige la documentación técnica completa. Reunirla sobre la marcha evita parones justo antes de vender.\n§\nEtiquetas e instrucciones\nDefine el contenido, los símbolos y el formato de placas, adhesivos de advertencia e instrucciones obligatorios en el mercado por el que empiezas.\nQue falte un símbolo obligatorio, como el contenedor tachado, puede frenar una entrega o impedir la venta.\n§\n¿Choca una norma con el resto?\nComprueba si algún requisito legal contradice las dimensiones, el peso o la forma de uso. Resuélvelo antes de construir.\nEjemplo: una carcasa aislante más gruesa cambia las dimensiones todavía en el plano, antes de encargar los moldes."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'rules';
update public.stage_subpoints s set translations = '{"de":{"title":"Vorschriften und Kennzeichnungen"},"uk":{"title":"Правила й позначення"},"es":{"title":"Normativa y marcado"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'rules' and s.key = 'map';
update public.stage_fields f set translations = '{"de":{"question":"Welche Vorschrift oder welches Zertifikat ändert eine konkrete Produkteigenschaft?","help":"Eine Zeile ist eine Norm, ein Zeichen oder eine Pflicht. Ergänze, welchen Teil des Produkts sie betrifft.","example":"Elektrische Sicherheit. Gehäuse aus einem Material, das keine Flammen unterhält. Prüfung vor dem Verkauf in der EU.","config":{"add_label":"Anforderung hinzufügen","columns":[{"key":"rule","label":"Vorschrift, Norm oder Zertifikat","placeholder":"Z. B. CE-Kennzeichnung, Batteriesicherheit"},{"key":"effect","label":"Was es am Produkt ändert","placeholder":"Material, Schaltung, Dokument"},{"key":"when","label":"Wann es nötig ist","placeholder":"Z. B. vor dem ersten Verkauf in der EU"}]}},"uk":{"question":"Яке правило чи сертифікат змінює конкретну властивість продукту?","help":"Одна позиція — одна норма, знак чи обов’язок. Допиши, якої частини продукту стосується.","example":"Електробезпека. Корпус із матеріалу, що не підтримує горіння. Випробування перед продажем у ЄС.","config":{"add_label":"Додати вимогу","columns":[{"key":"rule","label":"Правило, норма або сертифікат","placeholder":"Напр. маркування CE, безпека батарей"},{"key":"effect","label":"Що змінює в продукті","placeholder":"Матеріал, схема, документ"},{"key":"when","label":"Коли це потрібно","placeholder":"Напр. перед першим продажем у ЄС"}]}},"es":{"question":"¿Qué norma o certificado cambia una característica concreta del producto?","help":"Una línea es una norma, un marcado o una obligación. Añade a qué parte del producto afecta.","example":"Seguridad eléctrica. Carcasa de un material que no propaga la llama. Ensayo antes de vender en la UE.","config":{"add_label":"Añadir requisito","columns":[{"key":"rule","label":"Norma, estándar o certificado","placeholder":"P. ej. marcado CE, seguridad de baterías"},{"key":"effect","label":"Qué cambia en el producto","placeholder":"Material, circuito, documento"},{"key":"when","label":"Cuándo hace falta","placeholder":"P. ej. antes de la primera venta en la UE"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'rules'
    and s.key = 'map' and f.key = 'links';
update public.stage_fields f set translations = '{"de":{"question":"Was muss auf dem Startmarkt auf dem Etikett und in der Anleitung stehen?","help":"Inhalt, Zeichen und Sprache. Wenn du es noch nicht weißt, schreib „zu prüfen“ beim konkreten Zeichen, lass den Markt nicht weg.","example":"Produktname, Herstellerangaben, Symbol der durchgestrichenen Mülltonne und ein kurzer Warnhinweis auf Deutsch."},"uk":{"question":"Що має бути на етикетці й в інструкції на ринку, з якого починаєш?","help":"Зміст, знаки й мова. Якщо ще не знаєш, напиши «перевірити» біля конкретного знака, не пропускай ринку.","example":"Назва продукту, дані виробника, знак перекресленого кошика і коротке попередження українською."},"es":{"question":"¿Qué debe figurar en la etiqueta y en las instrucciones en el mercado por el que empiezas?","help":"Contenido, símbolos e idioma. Si aún no lo sabes, escribe «por comprobar» junto al símbolo concreto; no omitas el mercado.","example":"Nombre del producto, datos del fabricante, símbolo del contenedor tachado y una breve advertencia en español."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'rules'
    and s.key = 'map' and f.key = 'labels';
update public.stage_fields f set translations = '{"de":{"question":"Widerspricht eine Vorschrift früheren Anforderungen? Wie entscheidet ihr das?","help":"Wenn es keinen Widerspruch gibt, schreib „Kein Widerspruch“ und in einem Satz, was geprüft wurde.","example":"Die Isolierung erzwingt ein dickeres Gehäuse. Wir erhöhen das zulässige Maß von 80 mm auf 92 mm. Das Gewicht liegt weiter im Minimum."},"uk":{"question":"Чи якесь правило суперечить попереднім вимогам? Як ви це вирішуєте?","help":"Якщо суперечності немає, напиши «Суперечності немає» і одним реченням — що перевірено.","example":"Ізоляція вимагає товстішого корпусу. Підвищуємо допустимий розмір з 80 мм до 92 мм. Маса й далі в межах мінімуму."},"es":{"question":"¿Alguna norma contradice requisitos anteriores? ¿Cómo lo resolvéis?","help":"Si no hay contradicción, escribe «Sin contradicción» y, en una frase, qué se comprobó.","example":"El aislamiento obliga a una carcasa más gruesa. Subimos la medida admisible de 80 mm a 92 mm. El peso sigue dentro del mínimo."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'rules'
    and s.key = 'map' and f.key = 'clash';
update public.stage_points p set translations = '{"de":{"title":"Kläre Ressourcen und offene Probleme vor dem Bau","duration_hint":"Etwa 20 Minuten","guide_body":"Eine offene Liste dessen, was noch offen ist\nDas Ergebnis dieser Etappe ist kein fertiges Produkt. Das Ergebnis sind eine Spezifikation, Lieferantendaten, Qualitäts- und Vorschriftsanforderungen und eine Liste offener Risiken, mit der sich der Bau beginnen lässt, ohne zu raten, was entstehen soll.\nBeurteile bei jedem offenen Risiko aus Idea, ob ihr trotzdem starten könnt oder ob seine Lösung Bedingung für den Start ist. Nicht jedes Problem muss das Projekt stoppen. Jedes muss bewusst zurückgestellt sein, nicht übersehen.\n§\nWer und was fehlt\nListe Fachleute, Labore, Auftragnehmer und Maschinen auf, die für den Bau nötig sind. Markiere, was ihr schon habt und was beschafft werden muss.\nEin eigener Maschinenpark oder eine feste Stelle für eine Spezialistin ist in dieser Phase meist nicht nötig. Ein externes Labor oder ein Ingenieur für eine konkrete Prüfung ist oft schneller.\n§\nBudget mit Reserve\nReserviere einen Betrag für Werkzeuge, Prototypen, Prüfungen und Beratung auf Grundlage der vorigen Punkte.\nRechne etwa 15–20 % Reserve für eine Platinenkorrektur oder eine zusätzliche Laborsitzung ein. Bei Hardware klappt selten alles beim ersten Mal.\n§\nWas den Baustart blockiert\nNotiere die aktuellen technischen, kostenbezogenen, produktionsbezogenen und regulatorischen Risiken.\nTrenne die, die vor dem Bau gelöst werden müssen, von denen, die warten können. Die Kräfte gehen in das Risiko, das das Projekt stoppen kann, nicht in eine Kleinigkeit, die warten kann."},"uk":{"title":"Визнач ресурси й відкриті проблеми перед створенням","duration_hint":"Близько 20 хвилин","guide_body":"Відкритий список того, що ще не вирішено\nРезультатом цього етапу не є готовий продукт. Результат — специфікація, дані постачальників, вимоги якості й правил та список відкритих ризиків, з яким можна почати створення, не вгадуючи, що має з’явитися.\nДля кожного відкритого ризику з Idea оціни, чи можна рушати попри нього, чи його розв’язання — умова старту. Не кожна проблема мусить зупиняти проєкт. Кожна має бути свідомо відкладена, а не проґавлена.\n§\nКого й чого бракує\nВипиши фахівців, лабораторії, виконавців і машини, потрібні для створення. Познач, що вже маєте, а що треба здобути.\nВласний парк машин чи штатний вузький фахівець на цьому етапі зазвичай не потрібні. Зовнішня лабораторія чи інженер під конкретне випробування буває швидшим.\n§\nБюджет із запасом\nЗарезервуй суму на інструменти, прототипи, випробування й консультації на основі попередніх пунктів.\nДодай запас близько 15–20% на виправлення плати чи додаткову сесію в лабораторії. У залізі рідко все виходить з першого разу.\n§\nЩо блокує початок створення\nЗапиши поточні технічні, кошторисні, виробничі й регуляторні ризики.\nВідокрем ті, які треба розв’язати перед створенням, від тих, що можуть зачекати. Сили йдуть на ризик, що може зупинити проєкт, а не на дрібницю, яка може зачекати."},"es":{"title":"Define recursos y problemas abiertos antes de construir","duration_hint":"Unos 20 minutos","guide_body":"Una lista explícita de lo que sigue abierto\nEl resultado de esta etapa no es un producto terminado. Es una especificación, datos de proveedores, requisitos de calidad y normativa y una lista de riesgos abiertos con la que se puede empezar a construir sin adivinar qué hay que hacer.\nEn cada riesgo abierto de Idea, valora si podéis arrancar a pesar de él o si resolverlo es condición para empezar. No todos los problemas tienen que parar el proyecto. Todos tienen que aplazarse a conciencia, no pasarse por alto.\n§\nA quién y qué falta\nEnumera los especialistas, laboratorios, proveedores y máquinas necesarios para construir. Marca lo que ya tenéis y lo que hay que conseguir.\nEn esta fase no suele hacer falta un parque de máquinas propio ni contratar a un especialista muy concreto. Un laboratorio externo o un ingeniero para un ensayo concreto suele ser más rápido.\n§\nPresupuesto con margen\nReserva una cantidad para herramientas, prototipos, ensayos y consultas a partir de los puntos anteriores.\nAñade un margen del 15–20 % para corregir la placa o una sesión extra de laboratorio. En hardware rara vez sale todo a la primera.\n§\nQué bloquea el inicio de la construcción\nAnota los riesgos técnicos, de coste, de producción y normativos actuales.\nSepara los que hay que resolver antes de construir de los que pueden esperar. El esfuerzo va al riesgo que puede parar el proyecto, no a un detalle que puede esperar."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'readiness';
update public.stage_subpoints s set translations = '{"de":{"title":"Menschen, Werkzeuge und Budget"},"uk":{"title":"Люди, інструменти й бюджет"},"es":{"title":"Personas, herramientas y presupuesto"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'readiness' and s.key = 'resources';
update public.stage_fields f set translations = '{"de":{"question":"Was braucht ihr für den Bau und habt ihr es schon?","help":"Fachperson, Labor, Hersteller oder Maschine. Wenn es fehlt, schreib, woher ihr es bekommt.","example":"Dichtheitslabor. Haben wir nicht. Wir mieten eine Prüfung vor der Form.","config":{"add_label":"Ressource hinzufügen","columns":[{"key":"what","label":"Kompetenz oder Ressource","placeholder":"Wer oder was"},{"key":"status","label":"Haben wir oder müssen wir beschaffen","placeholder":"Haben wir, mieten wir, suchen wir"}]}},"uk":{"question":"Що вам потрібно для створення і чи вже це маєте?","help":"Фахівець, лабораторія, виробник або машина. За відсутності напиши, звідки візьмете.","example":"Лабораторія герметичності. Не маємо. Орендуємо одне випробування перед формою.","config":{"add_label":"Додати ресурс","columns":[{"key":"what","label":"Компетенція або ресурс","placeholder":"Хто або що"},{"key":"status","label":"Маємо чи треба здобути","placeholder":"Маємо, орендуємо, шукаємо"}]}},"es":{"question":"¿Qué necesitáis para construir y lo tenéis ya?","help":"Especialista, laboratorio, fabricante o máquina. Si falta, escribe de dónde lo sacaréis.","example":"Laboratorio de estanqueidad. No lo tenemos. Contrataremos un ensayo antes del molde.","config":{"add_label":"Añadir recurso","columns":[{"key":"what","label":"Competencia o recurso","placeholder":"Quién o qué"},{"key":"status","label":"Lo tenemos o hay que conseguirlo","placeholder":"Lo tenemos, lo alquilamos, lo buscamos"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'readiness'
    and s.key = 'resources' and f.key = 'needs';
update public.stage_fields f set translations = '{"de":{"question":"Welches Budget reservierst du für Werkzeuge, Prototypen, Tests und Beratung?","help":"Stütze den Betrag auf die vorigen Punkte und rechne etwa 15–20 % Reserve für die Korrektur ein, die beim ersten Anlauf auftaucht.","example":"Form, zwei Platineniterationen und eine Prüfung: 7.000 € plus 20 % Reserve, zusammen etwa 8.400 €."},"uk":{"question":"Який бюджет резервуєш на інструменти, прототипи, тести й консультації?","help":"Спирай суму на попередні пункти й додай запас близько 15–20% на виправлення, яке вийде з першої спроби.","example":"Форма, дві ітерації плати й одне випробування: 280 тис. грн плюс 20% запасу, разом близько 336 тис. грн."},"es":{"question":"¿Qué presupuesto reservas para herramientas, prototipos, pruebas y consultas?","help":"Basa la cifra en los puntos anteriores y añade un margen del 15–20 % para la corrección que saldrá en el primer intento.","example":"Molde, dos iteraciones de placa y un ensayo: 7.000 € más un 20 % de margen, unos 8.400 € en total."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'readiness'
    and s.key = 'resources' and f.key = 'budget';
update public.stage_subpoints s set translations = '{"de":{"title":"Was noch offen ist"},"uk":{"title":"Що ще відкрите"},"es":{"title":"Qué sigue abierto"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'readiness' and s.key = 'risks';
update public.stage_fields f set translations = '{"de":{"question":"Welche technischen, kostenbezogenen, produktionsbezogenen oder regulatorischen Risiken sind noch offen?","help":"Schreib bei jedem, ob es den Baustart blockiert oder warten kann. Wenn die Liste leer ist, lass sie leer und speichere — das heißt, du siehst kein offenes Risiko.","example":"Unbekannter Preis des Funkmoduls. Muss vor der Serienbestellung bekannt sein. Die Gehäusefarbe kann warten.","config":{"add_label":"Risiko hinzufügen","columns":[{"key":"risk","label":"Offenes Problem","placeholder":"Was noch nicht entschieden ist"},{"key":"gate","label":"Blockiert den Bau oder kann warten","placeholder":"Blockiert oder kann warten"}]}},"uk":{"question":"Які технічні, кошторисні, виробничі чи регуляторні ризики ще відкриті?","help":"Біля кожного напиши, чи блокує початок створення, чи може зачекати. Якщо список порожній, залиш його й збережи — це означає, що відкритого ризику ти не бачиш.","example":"Невідома ціна радіомодуля. Треба знати її перед замовленням серії. Колір корпусу може зачекати.","config":{"add_label":"Додати ризик","columns":[{"key":"risk","label":"Відкрита проблема","placeholder":"Що досі не вирішено"},{"key":"gate","label":"Блокує створення чи може зачекати","placeholder":"Блокує або може зачекати"}]}},"es":{"question":"¿Qué riesgos técnicos, de coste, de producción o normativos siguen abiertos?","help":"En cada uno escribe si bloquea el inicio de la construcción o puede esperar. Si la lista está vacía, déjala así y guarda: significa que no ves riesgos abiertos.","example":"Precio desconocido del módulo de radio. Hay que saberlo antes de encargar la serie. El color de la carcasa puede esperar.","config":{"add_label":"Añadir riesgo","columns":[{"key":"risk","label":"Problema abierto","placeholder":"Qué sigue sin resolver"},{"key":"gate","label":"Bloquea la construcción o puede esperar","placeholder":"Bloquea o puede esperar"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'readiness'
    and s.key = 'risks' and f.key = 'open';
update public.stage_categories c set translations = '{"de":{"title":"B2B","intro":"Bereite den Weg vom ersten Kontakt mit einer Firma bis zu dem Tag vor, an dem sie mit der Nutzung beginnen kann."},"uk":{"title":"B2B","intro":"Підготуй шлях від першого контакту з компанією до дня, коли вона зможе почати користуватися."},"es":{"title":"B2B","intro":"Prepara el camino desde el primer contacto con una empresa hasta el día en que puede empezar a usarlo."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'preparation' and t.version = 1 and c.key = 'b2b';
update public.stage_points p set translations = '{"de":{"title":"Bereite den Verkaufsprozess vor","duration_hint":"Etwa 20 Minuten","guide_body":"Ein kurzer Weg, kein langes Verfahren\nSchreib den Weg vom ersten Kontakt bis zum Beginn der Zusammenarbeit auf. Entferne Schritte, die die Entscheidung verlängern oder dein Gegenüber verwirren. Je einfacher der Weg, desto leichter kommt eine Firma zum Kauf.\nIm Verkauf an Firmen reichen meist drei oder vier Schritte: Gespräch und Bedarf verstehen, kurze Vorführung der passenden Lösung, Angebot, Abschluss.\n§\nWas eine Firma wirklich weiterbringt\nNotiere bei jeder Phase das Ereignis, nach dem die Firma weitergehen kann: Vorführung, Zustimmung der Person mit Budget, Bitte um ein Angebot.\nBring eine Sache nicht weiter, nur weil das Gespräch nett war. Stütze dich auf ein Signal: eine zurückgeschickte Bedarfsbeschreibung, die Anwesenheit der Person, die über das Budget verfügt.\n§\nEine Firmenliste statt eines eigenen Systems\nFührt die Firmen, mit denen ihr sprecht oder an die ihr euch wenden wollt: aktuelle Phase, nächster Schritt und die zuständige Person aus eurem Team.\nAnfangs reicht diese Liste. Ihr braucht kein eigenes Vertriebsprogramm. Wichtig ist, dass das ganze Team den nächsten Schritt sieht und weiß, wann er passieren soll."},"uk":{"title":"Підготуй процес продажу","duration_hint":"Близько 20 хвилин","guide_body":"Короткий шлях, а не довга процедура\nРозпиши шлях від першого контакту до початку співпраці. Прибери кроки, які подовжують рішення або плутають співрозмовника. Що простіший шлях, то легше компанії дійти до покупки.\nУ продажах компаніям зазвичай досить трьох-чотирьох кроків: розмова й пізнання потреби, короткий показ підібраного рішення, пропозиція, завершення.\n§\nЩо справді просуває компанію далі\nДля кожного етапу запиши подію, після якої компанія може перейти далі: демонстрація, згода людини з бюджетом, прохання про пропозицію.\nНе просувай справу лише тому, що розмова була приємною. Спирайся на сигнал: надісланий опис потреб, присутність людини, яка розпоряджається бюджетом.\n§\nСписок компаній замість окремої системи\nВедіть компанії, з якими розмовляєте або до яких хочете звернутися: поточний етап, наступний крок і людина з вашої команди.\nНа початку цього списку досить. Окрема програма для продажів не потрібна. Важливо, щоб уся команда бачила наступний крок і коли він має відбутися."},"es":{"title":"Prepara el proceso de venta","duration_hint":"Unos 20 minutos","guide_body":"Un camino corto, no un procedimiento largo\nDescribe el camino desde el primer contacto hasta el inicio de la colaboración. Quita los pasos que alargan la decisión o confunden a tu interlocutor. Cuanto más sencillo el camino, más fácil le resulta a la empresa llegar a comprar.\nEn la venta a empresas suelen bastar tres o cuatro pasos: conversación y conocer la necesidad, breve demostración de la solución ajustada, oferta y cierre.\n§\nQué hace avanzar de verdad a una empresa\nEn cada fase anota el hecho tras el cual la empresa puede avanzar: una demostración, el visto bueno de quien tiene el presupuesto, una petición de oferta.\nNo hagas avanzar el caso solo porque la conversación fue agradable. Básate en una señal: una descripción de necesidades devuelta, la presencia de quien maneja el presupuesto.\n§\nUna lista de empresas en lugar de un sistema aparte\nLlevad las empresas con las que habláis o a las que queréis dirigiros: fase actual, siguiente paso y persona de vuestro equipo.\nAl principio basta esta lista. No necesitáis un programa de ventas aparte. Lo importante es que todo el equipo vea el siguiente paso y cuándo debe ocurrir."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'sales';
update public.stage_subpoints s set translations = '{"de":{"title":"Der Weg vom Kontakt zur Zusammenarbeit"},"uk":{"title":"Шлях від контакту до співпраці"},"es":{"title":"Del contacto a la colaboración"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'sales' and s.key = 'steps';
update public.stage_fields f set translations = '{"de":{"question":"Ordne die Phasen und schreib, was die Firma weiterbringt.","help":"Eine Zeile ist eine Phase. Behalte nur Schritte, die es bei euch wirklich gibt.","example":"Gespräch. Weiter, wenn die andere Seite ein konkretes Problem beschreibt und einer Vorführung zustimmt. Vorführung. Weiter, wenn um ein Angebot gebeten wird.","config":{"add_label":"Phase hinzufügen","columns":[{"key":"stage","label":"Phase","placeholder":"Z. B. erstes Gespräch"},{"key":"forward","label":"Was passieren muss, um weiterzugehen","placeholder":"Ein konkretes Ereignis, nicht „gutes Gespräch“"}]}},"uk":{"question":"Розклади етапи й напиши, що просуває компанію далі.","help":"Одна позиція — один етап. Залиш лише кроки, які у вас справді є.","example":"Розмова. Далі, коли інша сторона опише конкретну проблему й погодиться на показ. Показ. Далі, коли попросять пропозицію.","config":{"add_label":"Додати етап","columns":[{"key":"stage","label":"Етап","placeholder":"Напр. перша розмова"},{"key":"forward","label":"Що має статися, щоб іти далі","placeholder":"Конкретна подія, а не «добра розмова»"}]}},"es":{"question":"Ordena las fases y escribe qué hace avanzar a la empresa.","help":"Una línea es una fase. Deja solo los pasos que de verdad tenéis.","example":"Conversación. Avanza cuando la otra parte describe un problema concreto y acepta una demostración. Demostración. Avanza cuando piden una oferta.","config":{"add_label":"Añadir fase","columns":[{"key":"stage","label":"Fase","placeholder":"P. ej. primera conversación"},{"key":"forward","label":"Qué tiene que pasar para avanzar","placeholder":"Un hecho concreto, no «buena conversación»"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'sales'
    and s.key = 'steps' and f.key = 'path';
update public.stage_subpoints s set translations = '{"de":{"title":"Firmen, mit denen ihr sprecht"},"uk":{"title":"Компанії, з якими ви розмовляєте"},"es":{"title":"Empresas con las que habláis"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'sales' and s.key = 'accounts';
update public.stage_fields f set translations = '{"de":{"question":"Trag Firmen ein, mit denen ihr schon sprecht oder an die ihr euch wenden wollt.","help":"Bei jeder: aktuelle Phase, nächste Aktion und wer in eurem Team dafür verantwortlich ist. Wenn du allein arbeitest, trag deinen Namen ein.","example":"Studio Nord. Nach dem ersten Gespräch. Angebot am Donnerstag schicken. Kuba.","config":{"add_label":"Firma hinzufügen","columns":[{"key":"company","label":"Firma","placeholder":"Name"},{"key":"stage","label":"Aktuelle Phase","placeholder":"Z. B. noch kein Kontakt"},{"key":"next","label":"Nächste Aktion","placeholder":"Was und wann"},{"key":"owner","label":"Wer aus eurem Team","placeholder":"Name"}]}},"uk":{"question":"Впиши компанії, з якими вже розмовляєте або до яких хочете звернутися.","help":"Для кожної: поточний етап, наступна дія і хто з вашої команди за це відповідає. Якщо працюєш сам, впиши своє ім’я.","example":"Studio Nord. Після першої розмови. Надіслати пропозицію в четвер. Kuba.","config":{"add_label":"Додати компанію","columns":[{"key":"company","label":"Компанія","placeholder":"Назва"},{"key":"stage","label":"Поточний етап","placeholder":"Напр. ще без контакту"},{"key":"next","label":"Наступна дія","placeholder":"Що й коли"},{"key":"owner","label":"Хто з вашої команди","placeholder":"Ім’я"}]}},"es":{"question":"Escribe las empresas con las que ya habláis o a las que queréis dirigiros.","help":"En cada una: fase actual, siguiente acción y quién de vuestro equipo se encarga. Si trabajas en solitario, escribe tu nombre.","example":"Studio Nord. Tras la primera conversación. Enviar la oferta el jueves. Kuba.","config":{"add_label":"Añadir empresa","columns":[{"key":"company","label":"Empresa","placeholder":"Nombre"},{"key":"stage","label":"Fase actual","placeholder":"P. ej. aún sin contacto"},{"key":"next","label":"Siguiente acción","placeholder":"Qué y cuándo"},{"key":"owner","label":"Quién de vuestro equipo","placeholder":"Nombre"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'sales'
    and s.key = 'accounts' and f.key = 'companies';
update public.stage_points p set translations = '{"de":{"title":"Bereite das erste Angebot vor","duration_hint":"Etwa 20 Minuten","guide_body":"Was genau ihr verkauft\nBeschreibe den Umfang der ersten Version in der Sprache des Nutzens, nicht als Technologieliste. Stütze dich auf das, was als erste Version entstehen soll.\nHaltet einen festen Kern des Angebots. Vermeidet es, für jeden Kunden alles von Grund auf zu entwerfen.\n§\nPreis und Zeit\nNenne den Preis oder die Art seiner Berechnung, wofür genau der Kunde zahlt und wie lange Zusammenarbeit oder Umsetzung dauern.\nEine kostenlose Testphase schafft selten Engagement bei einer Firma. Wenn ihr einen Test braucht, erwägt einen bezahlten Pilot zu niedrigeren Kosten oder eine klare Rückgabebedingung. Ein Kunde, der auch nur einen kleinen Betrag bezahlt, nimmt den Test ernster.\n§\nEin Pilot hat ein Ende\nWenn es einen Test gibt, legt vorher fest, was der Kunde bekommt und woran ihr ihn als abgeschlossen erkennt. Gibt es keinen Test, schreib „Entfällt“.\nEin Pilot ohne Ziel kann sich ohne Entscheidung hinziehen. Legt eine Kennzahl fest, zum Beispiel: „Wenn das Team in 14 Tagen 5 Stunden spart, gehen wir zum Vertrag über.“"},"uk":{"title":"Підготуй першу пропозицію","duration_hint":"Близько 20 хвилин","guide_body":"Що саме ви продаєте\nОпиши обсяг першої версії мовою користі, а не списком технологій. Спирайся на те, що має з’явитися як перша версія.\nТримайте сталий кістяк пропозиції. Уникайте проєктування всього з нуля для кожного клієнта.\n§\nЦіна й час\nВкажи ціну або спосіб її розрахунку, за що саме платить клієнт і як довго триває співпраця чи реалізація.\nБезплатний пробний період рідко будує залученість компанії. Якщо потрібна спроба, розгляньте платний пілот за нижчу ціну або чітку умову повернення коштів. Клієнт, який вкладає хоч невелику суму, ставиться до тесту серйозніше.\n§\nПілот має кінець\nЯкщо є тест, заздалегідь визнач, що клієнт отримує і за чим ви вважаєте його завершеним. Якщо тесту немає, напиши «Не стосується».\nПілот без мети може тягнутися без рішення. Визначте один показник, наприклад: «Якщо за 14 днів команда заощадить 5 годин, переходимо до договору»."},"es":{"title":"Prepara la primera oferta","duration_hint":"Unos 20 minutos","guide_body":"Qué vendéis exactamente\nDescribe el alcance de la primera versión en términos de beneficio, no como una lista de tecnologías. Básate en lo que va a ser la primera versión.\nMantened un núcleo fijo de la oferta. Evitad diseñarlo todo desde cero para cada cliente.\n§\nPrecio y plazo\nIndica el precio o cómo se calcula, por qué paga exactamente el cliente y cuánto dura la colaboración o la implantación.\nUn periodo de prueba gratuito rara vez genera compromiso en una empresa. Si necesitáis una prueba, plantead un piloto de pago a menor coste o una condición clara de devolución. Un cliente que pone aunque sea una cantidad pequeña se toma la prueba más en serio.\n§\nEl piloto tiene final\nSi hay prueba, fija de antemano qué recibe el cliente y cuándo la dais por terminada. Si no hay prueba, escribe «No aplica».\nUn piloto sin objetivo puede alargarse sin decisión. Fijad un indicador, por ejemplo: «Si en 14 días el equipo ahorra 5 horas, pasamos al contrato»."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'offer';
update public.stage_subpoints s set translations = '{"de":{"title":"Was ihr verkauft und zu welchem Preis"},"uk":{"title":"Що ви продаєте і за скільки"},"es":{"title":"Qué vendéis y a qué precio"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'offer' and s.key = 'scope';
update public.stage_fields f set translations = '{"de":{"question":"Welchen Umfang der ersten Version könnt ihr einer Firma anbieten?","help":"Stütze dich darauf, was im Allgemeinen Teil für die erste Version entstehen soll. Schreib, was Kunden bekommen, nicht wie es gebaut ist.","example":"Ein Meldeformular für den Empfang und eine wöchentliche Übersicht, wie viele Meldungen abgeschlossen wurden."},"uk":{"question":"Який обсяг першої версії можете запропонувати компанії?","help":"Спирайся на те, що має з’явитися до першої версії в Загальному. Напиши, що отримує клієнт, а не як це збудовано.","example":"Форма заявок для рецепції й щотижневий звіт, скільки заявок закрито."},"es":{"question":"¿Qué alcance de la primera versión podéis ofrecer a una empresa?","help":"Básate en lo que debe estar listo para la primera versión en General. Escribe qué recibe el cliente, no cómo está construido.","example":"Un formulario de incidencias para recepción y un resumen semanal de cuántas se han cerrado."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'offer'
    and s.key = 'scope' and f.key = 'what';
update public.stage_fields f set translations = '{"de":{"question":"Wie hoch ist der Preis oder wie berechnet ihr ihn, und wofür genau zahlen Kunden?","help":"Betrag, Satz oder Formel. Ergänze, ob es ein Abo, eine Einführung oder beides ist.","example":"600 € für die Einführung und 200 € pro Monat für die Nutzung durch bis zu 5 Personen."},"uk":{"question":"Яка ціна або як ви її рахуєте і за що саме платить клієнт?","help":"Сума, ставка чи формула. Допиши, чи це підписка, впровадження чи і те, і те.","example":"24 000 грн за впровадження й 8 000 грн на місяць за користування до 5 осіб."},"es":{"question":"¿Cuál es el precio o cómo lo calculáis, y por qué paga exactamente el cliente?","help":"Cantidad, tarifa o fórmula. Añade si es una suscripción, una implantación o ambas.","example":"600 € por la implantación y 200 € al mes por el uso de hasta 5 personas."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'offer'
    and s.key = 'scope' and f.key = 'price';
update public.stage_fields f set translations = '{"de":{"question":"Wie lange dauert die Zusammenarbeit oder Umsetzung?","help":"Wenn die Dauer keine Rolle spielt, schreib „Ohne festes Ende“ und was die Zusammenarbeit dann beendet.","example":"Einführung 3 Wochen. Unbefristetes Abo mit monatlicher Kündigung."},"uk":{"question":"Як довго триває співпраця чи реалізація?","help":"Якщо час не має значення, напиши «Без визначеного кінця» і що тоді завершує співпрацю.","example":"Впровадження 3 тижні. Підписка безстрокова, з місячним повідомленням про розірвання."},"es":{"question":"¿Cuánto dura la colaboración o la implantación?","help":"Si el plazo no importa, escribe «Sin fin definido» y qué pone fin entonces a la colaboración.","example":"Implantación de 3 semanas. Suscripción indefinida con preaviso de un mes."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'offer'
    and s.key = 'scope' and f.key = 'term';
update public.stage_subpoints s set translations = '{"de":{"title":"Test, falls nötig"},"uk":{"title":"Тест, якщо потрібен"},"es":{"title":"Prueba, si hace falta"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'offer' and s.key = 'pilot';
update public.stage_fields f set translations = '{"de":{"question":"Was bekommen Kunden im Test und woran erkennt ihr, dass er beendet ist?","help":"Wenn es keinen Test gibt, schreib „Entfällt“.","example":"14 Tage mit einem Team. Ende, wenn wir die gesparten Stunden gezählt haben und der Kunde über das Abo entscheidet."},"uk":{"question":"Що клієнт отримує в тесті і за чим ви вважаєте його завершеним?","help":"Якщо тесту немає, напиши «Не стосується».","example":"14 днів на одній команді. Кінець, коли порахуємо заощаджені години і клієнт вирішить, чи бере підписку."},"es":{"question":"¿Qué recibe el cliente en la prueba y cuándo la dais por terminada?","help":"Si no hay prueba, escribe «No aplica».","example":"14 días con un equipo. Termina cuando contemos las horas ahorradas y el cliente decida si contrata la suscripción."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'offer'
    and s.key = 'pilot' and f.key = 'deal';
update public.stage_points p set translations = '{"de":{"title":"Bereite den Beginn der Zusammenarbeit vor","duration_hint":"Etwa 20 Minuten","guide_body":"Den Umfang klären, bevor ihr für Kunden baut\nGeht zu den Vereinbarungen aus der Ideenphase zurück und listet die Funktionen auf, die für den versprochenen Nutzen unverzichtbar sind. Legt erst dann die Kontenstruktur, Rollen, Berechtigungen und Integrationen fest sowie das, was ihr auf später verschiebt.\nAuf dieser Grundlage lässt sich der Umfang der ersten Version abschließen und festhalten, woran ihr ein Element als fertig erkennt.\n§\nDaten einer Firma dürfen nicht zu einer anderen gelangen\nLegt fest, wie ihr die Daten einzelner Firmen trennt, welchen Zugriff Nutzer haben und welche Integrationen nötig sind.\nNotiert technische Einschränkungen, die den Bau beeinflussen. Vor allem die Situation, in der eine falsche Zugriffskonfiguration die Daten eines Kunden einem anderen zeigen würde.\n§\nSicherheit und Papiere\nLegt fest, welche Geschäfts- und personenbezogenen Daten ihr verarbeitet, wer Zugriff darauf hat, wie sie geschützt sind und wann sie gelöscht werden sollen.\nListet typische Anforderungen von Firmen auf, zum Beispiel Single Sign-On, sowie Dokumente: Nutzungsbedingungen, Datenschutzerklärung, Auftragsverarbeitungsvertrag, wenn ihr personenbezogene Daten verarbeitet.\nMacht daraus eine Checkliste und bestätigt sie, bevor ihr das Produkt einem Kunden zur Verfügung stellt.\n§\nTeam und Budget für den Umsetzungsstart\nLegt Rollen und Kompetenzen fest, verteilt Verantwortung und benennt Lücken: Macht ihr es selbst, vergebt ihr es extern oder sucht ihr jemanden?\nBereitet Werkzeuge, Budget und Zeitrahmen vor. Prüft, ob das für den vereinbarten Umfang reicht. Vor dem Bau soll das Team wissen, dass es Kompetenzen, Mittel und Zeit hat, statt den Mangel unterwegs zu entdecken.\n§\nVom Kauf zur ersten Nutzung\nBeschreibt den Weg der Kunden vom Kauf zur Nutzung: welche Informationen, Zugänge und Konfigurationen nötig sind und wer dafür verantwortlich ist.\nLegt fest, wie ihr Anfragen bearbeitet und wie ihr Kunden zwischen Vertrieb, Einführung und Support übergebt, damit keine Informationen verloren gehen.\n§\nWas ihr vom Kunden braucht\nListet Materialien, Daten, Zugänge und Zustimmungen auf, die Kunden vor dem Start übergeben müssen. Wenn ihr nichts braucht, schreibt das direkt.\nJe weniger Aufgaben ganz am Anfang, desto schneller kommen Kunden zur ersten Nutzung. Eine einfache Liste für sie reicht.\n§\nArbeitsteilung\nListet auf, was vor dem Start euer Team und was der Kunde erledigt. Benennt Personen auf beiden Seiten.\nDie häufigste Verzögerung ist eine fehlende verantwortliche Person auf Kundenseite. Stellt sicher, dass sie vom ersten Tag an benannt ist.\n§\nFormalitäten auf diesem Weg\nSchreibt die Schritte von der Kaufzusage bis zu dem Moment auf, in dem Kunden die Lösung selbstständig nutzen. Berücksichtigt Vertrag, NDA, Bestellung oder Rechnung, wenn es das bei euch gibt.\nEine Vorlage und eine elektronische Signatur verkürzen die Zeit von der Entscheidung bis zum ersten echten Nutzen. Das ist das Ziel dieses Punkts."},"uk":{"title":"Підготуй початок співпраці","duration_hint":"Близько 20 хвилин","guide_body":"Обсяг, перш ніж почнете будувати під клієнта\nПоверніться до домовленостей з етапу ідеї й випишіть функції, необхідні для обіцяної користі. Лише потім визначте структуру акаунтів, ролі, повноваження й інтеграції, а також те, що відкладаєте на потім.\nНа цій основі можна закрити обсяг першої версії й записати, за чим ви вважаєте елемент готовим.\n§\nДані однієї компанії не можуть потрапити до іншої\nВизначте, як відокремлюєте дані окремих компаній, який обсяг доступу користувачів і які інтеграції потрібні.\nЗапишіть технічні обмеження, що впливають на створення. Особливо ситуацію, у якій неправильне налаштування доступу показало б дані одного клієнта іншому.\n§\nБезпека й документи\nВизначте, які бізнесові та персональні дані ви оброблятимете, хто має до них доступ, як вони захищені і коли їх слід видалити.\nВипишіть вимоги, типові для компаній, наприклад єдиний вхід (SSO), а також документи: правила користування, політику, договір доручення обробки, якщо обробляєте персональні дані.\nЗробіть із цього чек-лист і підтвердьте його, перш ніж надати продукт клієнтові.\n§\nКоманда й бюджет на старт реалізації\nВизначте ролі й компетенції, призначте відповідальність і вкажіть прогалини: робите самі, замовите ззовні чи шукаєте людину.\nПідготуйте інструменти, бюджет і часові рамки. Перевірте, чи цього досить на погоджений обсяг. Перед створенням команда має знати, що в неї є компетенції, кошти й час, а не виявляти брак у процесі.\n§\nВід покупки до першого використання\nОпишіть шлях клієнта від покупки до користування: яка інформація, доступи й налаштування потрібні і хто за них відповідає.\nВизначте, як обробляєте звернення і як передаєте клієнта між продажами, впровадженням і підтримкою, щоб інформація не губилася дорогою.\n§\nЩо вам потрібно від клієнта\nВипишіть матеріали, дані, доступи й згоди, які клієнт має передати до старту. Якщо нічого не потрібно, напишіть це прямо.\nЩо менше завдань на самому початку, то швидше клієнт дійде до першого використання. Простого списку для нього досить.\n§\nРозподіл роботи\nВипишіть, що до старту робить ваша команда, а що клієнт. Призначте людей з обох боків.\nНайчастіша затримка — відсутність відповідальної людини з боку клієнта. Переконайтеся, що її визначено з першого дня.\n§\nФормальності на цьому шляху\nРозпишіть кроки від згоди на покупку до моменту, коли клієнт самостійно користується рішенням. Врахуйте договір, NDA, замовлення чи рахунок, якщо вони у вас є.\nШаблон і електронний підпис скорочують час від рішення до першої реальної користі. Це і є мета цього пункту."},"es":{"title":"Prepara el inicio de la colaboración","duration_hint":"Unos 20 minutos","guide_body":"El alcance, antes de construir para el cliente\nVolved a lo acordado en la fase de idea y enumerad las funciones imprescindibles para el beneficio prometido. Solo después definid la estructura de cuentas, los roles, los permisos y las integraciones, y lo que dejáis para más adelante.\nCon esto se puede cerrar el alcance de la primera versión y anotar cuándo dais un elemento por terminado.\n§\nLos datos de una empresa no pueden llegar a otra\nDefinid cómo separáis los datos de cada empresa, qué acceso tienen los usuarios y qué integraciones hacen falta.\nAnotad las limitaciones técnicas que afectan a la construcción. Sobre todo la situación en la que una mala configuración del acceso mostraría los datos de un cliente a otro.\n§\nSeguridad y documentación\nDefinid qué datos empresariales y personales vais a tratar, quién tiene acceso, cómo se protegen y cuándo deben borrarse.\nEnumerad requisitos habituales en empresas, como el inicio de sesión único, y los documentos: condiciones de uso, política de privacidad y contrato de encargado del tratamiento si tratáis datos personales.\nConvertidlo en una lista de comprobación y confirmadla antes de poner el producto a disposición del cliente.\n§\nEquipo y presupuesto para arrancar\nDefinid roles y competencias, asignad responsabilidades y señalad carencias: lo hacéis vosotros, lo externalizáis o buscáis a alguien.\nPreparad herramientas, presupuesto y plazos. Comprobad si bastan para el alcance acordado. Antes de construir, el equipo tiene que saber que tiene las competencias, los medios y el tiempo, y no descubrir la carencia por el camino.\n§\nDe la compra al primer uso\nDescribid el camino del cliente desde la compra hasta el uso: qué información, accesos y configuraciones hacen falta y quién se encarga.\nDefinid cómo gestionáis las solicitudes y cómo pasa el cliente de ventas a implantación y a soporte sin que se pierda información.\n§\nQué necesitáis del cliente\nEnumerad los materiales, datos, accesos y consentimientos que el cliente debe entregar antes de empezar. Si no necesitáis nada, decidlo claramente.\nCuantas menos tareas al principio, antes llegará el cliente al primer uso. Una lista sencilla para él es suficiente.\n§\nReparto del trabajo\nEnumerad qué hace vuestro equipo antes del inicio y qué hace el cliente. Asignad personas en ambos lados.\nEl retraso más habitual es que falte una persona responsable del lado del cliente. Aseguraos de que está designada desde el primer día.\n§\nTrámites en este camino\nDescribid los pasos desde la aprobación de la compra hasta que el cliente usa la solución por su cuenta. Incluid contrato, NDA, pedido o factura, si los tenéis.\nUna plantilla y la firma electrónica acortan el tiempo entre la decisión y el primer beneficio real. Ese es el objetivo de este punto."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'kickoff';
update public.stage_subpoints s set translations = '{"de":{"title":"Was vor dem Start passieren muss"},"uk":{"title":"Що має статися до старту"},"es":{"title":"Qué tiene que pasar antes de empezar"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'kickoff' and s.key = 'needs';
update public.stage_fields f set translations = '{"de":{"question":"Was braucht ihr vom Kunden, bevor er mit der Nutzung beginnt?","help":"Daten, Zugänge, Zustimmungen, Materialien. Wenn ihr nichts braucht, trag „Nichts“ ein.","example":"Liste der Personen, die Zugang bekommen.\nAnsprechperson beim Kunden, die Fragen entgegennimmt."},"uk":{"question":"Що вам потрібно від клієнта, перш ніж він почне користуватися?","help":"Дані, доступи, згоди, матеріали. Якщо нічого не потрібно, впиши «Нічого».","example":"Список людей, які отримають доступ.\nЛюдина з боку клієнта, яка приймає запитання."},"es":{"question":"¿Qué necesitáis del cliente antes de que empiece a usarlo?","help":"Datos, accesos, consentimientos, materiales. Si no necesitáis nada, escribe «Nada».","example":"Lista de personas que recibirán acceso.\nPersona del cliente que atiende las preguntas."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'kickoff'
    and s.key = 'needs' and f.key = 'from_client';
update public.stage_fields f set translations = '{"de":{"question":"Was muss euer Team vor dem Start erledigen?","help":"Eine Aktion pro Zeile.","example":"Den Bereich der Firma anlegen.\nDen Vertrag zur Unterschrift schicken."},"uk":{"question":"Що до старту має зробити ваша команда?","help":"Одна дія на позицію.","example":"Створити простір компанії.\nНадіслати договір на підпис."},"es":{"question":"¿Qué tiene que hacer vuestro equipo antes de empezar?","help":"Una acción por línea.","example":"Crear el espacio de la empresa.\nEnviar el contrato para firmar."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'kickoff'
    and s.key = 'needs' and f.key = 'ours';
update public.stage_fields f set translations = '{"de":{"question":"Was muss der Kunde vor dem Start erledigen?","help":"Eine Aktion pro Zeile. Wenn die Liste nur „Nichts“ enthält, trag es als einen Eintrag ein.","example":"Den Vertrag unterschreiben.\nEine verantwortliche Person auf eigener Seite benennen."},"uk":{"question":"Що до старту має зробити клієнт?","help":"Одна дія на позицію. Якщо список — лише «Нічого», впиши це одним записом.","example":"Підписати договір.\nВказати відповідальну людину зі свого боку."},"es":{"question":"¿Qué tiene que hacer el cliente antes de empezar?","help":"Una acción por línea. Si la lista es solo «Nada», escríbelo en una única entrada.","example":"Firmar el contrato.\nDesignar una persona responsable por su parte."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'kickoff'
    and s.key = 'needs' and f.key = 'theirs';
update public.stage_subpoints s set translations = '{"de":{"title":"Von der Zusage zur ersten Nutzung"},"uk":{"title":"Від згоди до першого використання"},"es":{"title":"De la aprobación al primer uso"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'kickoff' and s.key = 'start';
update public.stage_fields f set translations = '{"de":{"question":"Welche Schritte folgen von der Kaufbestätigung bis zu dem Moment, in dem Kunden die Lösung nutzen können?","help":"Ergänze die Formalitäten, die es bei euch gibt: Vertrag, NDA, Bestellung, Rechnung, Materialien.","example":"Wir unterschreiben den Vertrag.\nWir stellen die Rechnung für die Einführung.\nWir richten Zugänge ein und vereinbaren einen Termin für die erste Nutzung."},"uk":{"question":"Які наступні дії від підтвердження покупки до моменту, коли клієнт може користуватися?","help":"Допиши формальності, які у вас є: договір, NDA, замовлення, рахунок, матеріали.","example":"Підписуємо договір.\nВиставляємо рахунок за впровадження.\nСтворюємо доступи й домовляємося про час першого використання."},"es":{"question":"¿Qué pasos siguen desde la confirmación de la compra hasta que el cliente puede usarlo?","help":"Añade los trámites que tengáis: contrato, NDA, pedido, factura, materiales.","example":"Firmamos el contrato.\nEmitimos la factura de la implantación.\nCreamos los accesos y fijamos la hora del primer uso."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'kickoff'
    and s.key = 'start' and f.key = 'path';
update public.stage_fields f set translations = '{"de":{"question":"Welche Kundendaten werdet ihr haben und wer außerhalb dieser Firma kann sie sehen?","help":"Personenbezogene Daten, Firmendaten, Dateien. Wenn zwei Kunden die Materialien des anderen nicht sehen dürfen, schreib das direkt. Wenn ihr keine Kundendaten verarbeitet, schreib „Wir verarbeiten keine Kundendaten“.","example":"Wir haben Vornamen der Beschäftigten und den Inhalt der Meldungen. Sie sieht nur diese Firma und die Person aus unserem Team, die die Einführung leitet. Andere Kunden sehen sie nicht."},"uk":{"question":"Які дані клієнта ви матимете і хто поза цією компанією може їх бачити?","help":"Персональні дані, дані компанії, файли. Якщо два клієнти не можуть бачити матеріалів одне одного, напиши це прямо. Коли даних клієнта не обробляєте, напиши «Не обробляємо даних клієнта».","example":"Маємо імена працівників і зміст заявок. Їх бачить лише ця компанія і людина з нашої команди, яка веде впровадження. Інший клієнт цього не бачить."},"es":{"question":"¿Qué datos del cliente tendréis y quién fuera de esa empresa puede verlos?","help":"Datos personales, datos de la empresa, archivos. Si dos clientes no pueden ver los materiales del otro, dilo claramente. Si no tratáis datos del cliente, escribe «No tratamos datos del cliente».","example":"Tenemos los nombres de los empleados y el contenido de las incidencias. Solo los ve esa empresa y la persona de nuestro equipo que lleva la implantación. Otros clientes no los ven."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'kickoff'
    and s.key = 'start' and f.key = 'data';
update public.stage_categories c set translations = '{"de":{"title":"B2C","intro":"Lege fest, wie Käufer zurücktreten oder melden können, dass ein Kauf nicht funktioniert, und wie ihr das in der ersten Version bearbeitet."},"uk":{"title":"B2C","intro":"Визнач, як покупець може відмовитися або повідомити, що покупка не працює, і як ви це обробите в першій версії."},"es":{"title":"B2C","intro":"Define cómo puede desistir el comprador o avisar de que la compra no funciona, y cómo lo gestionaréis en la primera versión."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'preparation' and t.version = 1 and c.key = 'b2c';
update public.stage_points p set translations = '{"de":{"title":"Bereite Rückgaben und Reklamationen vor","duration_hint":"Etwa 20 Minuten","guide_body":"Wovon Rückgaben abhängen\nDie Regeln hängen vom Land ab, in dem du zu verkaufen beginnst, und davon, ob du online oder vor Ort verkaufst. Notiere zuerst Kanal, Zahlung und Übergabe. Ohne das lässt sich ein Rücktritt vom Kauf nicht sinnvoll beschreiben.\nNotiere, wann Kunden zurücktreten können und was du tun musst, wenn der Kauf nicht wie versprochen funktioniert. Wenn eine Frist noch nicht geprüft ist, schreib „zu prüfen“ bei der konkreten Regel. Rate keine Zahl.\n§\nWas das Produkt macht und was ihr von Hand erledigt\nNotiere für die Rückgabe und gesondert für die Reklamation, wie Kunden sich melden.\nAuf Seiten des Produkts oder Verkaufsorts reicht für den Start, was es erlaubt, einen Kontakt zu finden und anzugeben, welchen Kauf die Meldung betrifft.\nDen Rest könnt ihr von Hand erledigen: Meldung prüfen, antworten und die Rückerstattung veranlassen. Stimme diese Aufteilung mit der Person ab, die die erste Version baut.","guide_sources":["Regeln zu Widerruf und Reklamation für das Land und die Art des ersten Verkaufs."]},"uk":{"title":"Підготуй повернення й рекламації","duration_hint":"Близько 20 хвилин","guide_body":"Від чого залежать повернення\nПравила залежать від країни, де ти починаєш продажі, і від того, чи продаєш через інтернет, чи на місці. Спершу запиши канал, оплату й отримання. Без цього не вдасться осмислено описати відмову від покупки.\nЗапиши, коли клієнт може відмовитися і що ти маєш зробити, якщо покупка не працює так, як обіцяно. Якщо термін ще не перевірено, напиши «перевірити» біля конкретного правила. Не вгадуй числа.\n§\nЩо робить продукт, а що ви робите вручну\nДля повернення й окремо для рекламації запиши, як клієнт звертається.\nЗ боку продукту чи місця продажу на старт досить того, що дає змогу знайти контакт і вказати, якої покупки стосується звернення.\nРешту можна зробити вручну: перевірити звернення, відповісти й доручити повернення грошей. Узгодь цей розподіл із людиною, яка створює першу версію.","guide_sources":["Правила відмови й рекламації, властиві для країни та способу першого продажу."]},"es":{"title":"Prepara devoluciones y reclamaciones","duration_hint":"Unos 20 minutos","guide_body":"De qué dependen las devoluciones\nLas reglas dependen del país donde empiezas a vender y de si vendes por internet o en persona. Anota primero el canal, el pago y la entrega. Sin eso no se puede describir con sentido el desistimiento de la compra.\nAnota cuándo puede desistir el cliente y qué tienes que hacer si la compra no funciona como se prometió. Si un plazo aún no está comprobado, escribe «por comprobar» junto a la regla concreta. No adivines cifras.\n§\nQué hace el producto y qué hacéis a mano\nPara la devolución y, por separado, para la reclamación, anota cómo avisa el cliente.\nPor parte del producto o del punto de venta basta, para empezar, con que permita encontrar el contacto e indicar a qué compra se refiere el aviso.\nEl resto podéis hacerlo a mano: revisar el aviso, responder y ordenar el reembolso. Acuerda este reparto con quien construye la primera versión.","guide_sources":["Normas de desistimiento y reclamación propias del país y de la forma de la primera venta."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2c' and p.key = 'returns';
update public.stage_subpoints s set translations = '{"de":{"title":"Wie der erste Kauf aussieht"},"uk":{"title":"Як виглядає перша покупка"},"es":{"title":"Cómo es la primera compra"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2c' and p.key = 'returns' and s.key = 'channel';
update public.stage_fields f set translations = '{"de":{"question":"Wo findet der erste Verkauf statt und wie zahlen Käufer und erhalten den Kauf?","help":"Online oder stationär, Zahlungsart und Übergabeart. Davon hängen Rückgaben ab.","example":"Onlineshop. Zahlung bei der Bestellung. Paket per Kurier oder Selbstabholung."},"uk":{"question":"Де відбувається перший продаж і як покупець платить та отримує покупку?","help":"Інтернет чи стаціонарне місце, спосіб оплати й спосіб отримання. Від цього залежать повернення.","example":"Інтернет-магазин. Оплата при замовленні. Посилка кур’єром або самовивіз."},"es":{"question":"¿Dónde se hace la primera venta y cómo paga y recibe la compra el comprador?","help":"Online o en tienda física, forma de pago y forma de entrega. De esto dependen las devoluciones.","example":"Tienda online. Pago al hacer el pedido. Paquete por mensajería o recogida en persona."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2c' and p.key = 'returns'
    and s.key = 'channel' and f.key = 'where';
update public.stage_subpoints s set translations = '{"de":{"title":"Wann Käufer zurücktreten können"},"uk":{"title":"Коли покупець може відмовитися"},"es":{"title":"Cuándo puede desistir el comprador"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2c' and p.key = 'returns' and s.key = 'rights';
update public.stage_fields f set translations = '{"de":{"question":"Wann können Kunden vom Kauf zurücktreten und was musst du tun, wenn der Kauf nicht wie versprochen funktioniert?","help":"Berücksichtige das Land, in dem du beginnst, und die Verkaufsart. Wenn eine Frist noch nicht geprüft ist, schreib „zu prüfen“ bei der konkreten Regel, rate keine Zahl.","example":"Onlineverkauf in Deutschland: Kunden können innerhalb von 14 Tagen nach Erhalt widerrufen. Wenn das Produkt nicht funktioniert, nehmen wir die Reklamation an und erstatten das Geld oder tauschen das Stück aus."},"uk":{"question":"Коли клієнт може відмовитися від покупки і що ти маєш зробити, якщо покупка не працює так, як обіцяно?","help":"Врахуй країну, з якої починаєш, і спосіб продажу. Якщо термін ще не перевірено, напиши «перевірити» біля конкретного правила, не вгадуй числа.","example":"Продаж через інтернет в Україні: клієнт може відмовитися протягом 14 днів від отримання. Коли продукт не працює, приймаємо рекламацію й повертаємо гроші або замінюємо одиницю."},"es":{"question":"¿Cuándo puede el cliente desistir de la compra y qué tienes que hacer si no funciona como se prometió?","help":"Ten en cuenta el país por el que empiezas y la forma de venta. Si un plazo no está comprobado, escribe «por comprobar» junto a la regla concreta; no adivines cifras.","example":"Venta online en España: el cliente puede desistir en 14 días desde la recepción. Si el producto no funciona, aceptamos la reclamación y devolvemos el dinero o cambiamos la unidad."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2c' and p.key = 'returns'
    and s.key = 'rights' and f.key = 'rule';
update public.stage_subpoints s set translations = '{"de":{"title":"Wie ihr Rückgabe und Reklamation bearbeitet"},"uk":{"title":"Як ви обробите повернення й рекламацію"},"es":{"title":"Cómo gestionaréis devolución y reclamación"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2c' and p.key = 'returns' and s.key = 'handling';
update public.stage_fields f set translations = '{"de":{"question":"Notiere für Rückgabe und Reklamation, wie Kunden sich melden und was ihr tut.","help":"Rückgabe und Reklamation getrennt. Schreib, was das Produkt oder der Verkaufsort können muss und was ihr von Hand erledigt.","example":"Rückgabe. Kunden schreiben an die Adresse aus der Bestellbestätigung und nennen die Nummer. Wir prüfen die Frist, bestätigen den Paketeingang und veranlassen die Rückerstattung.","config":{"add_label":"Ablauf hinzufügen","columns":[{"key":"kind","label":"Rückgabe oder Reklamation","placeholder":"Rückgabe oder Reklamation"},{"key":"report","label":"Wie Kunden sich melden","placeholder":"E-Mail, Formular, im Laden"},{"key":"product","label":"Was Produkt oder Verkauf ermöglichen muss","placeholder":"Z. B. Kontakt und Kaufnummer finden"},{"key":"manual","label":"Was ihr von Hand erledigt","placeholder":"Prüfung, Antwort, Rückerstattung"}]}},"uk":{"question":"Для повернення й рекламації запиши, як клієнт звернеться і що ви зробите.","help":"Окремо повернення, окремо рекламація. Напиши, що має вміти продукт чи місце продажу, а що ви зробите вручну.","example":"Повернення. Клієнт пише на адресу з підтвердження замовлення й вказує номер. Ми перевіряємо термін, підтверджуємо отримання посилки й доручаємо повернення грошей.","config":{"add_label":"Додати шлях","columns":[{"key":"kind","label":"Повернення чи рекламація","placeholder":"Повернення або рекламація"},{"key":"report","label":"Як клієнт звертається","placeholder":"Пошта, форма, у магазині"},{"key":"product","label":"Що має уможливлювати продукт чи продаж","placeholder":"Напр. знайти контакт і номер покупки"},{"key":"manual","label":"Що ви зробите вручну","placeholder":"Перевірка, відповідь, повернення грошей"}]}},"es":{"question":"Para la devolución y la reclamación, anota cómo avisará el cliente y qué haréis.","help":"Devolución y reclamación por separado. Escribe qué debe permitir el producto o el punto de venta y qué haréis a mano.","example":"Devolución. El cliente escribe a la dirección de la confirmación del pedido e indica el número. Comprobamos el plazo, confirmamos la recepción del paquete y ordenamos el reembolso.","config":{"add_label":"Añadir proceso","columns":[{"key":"kind","label":"Devolución o reclamación","placeholder":"Devolución o reclamación"},{"key":"report","label":"Cómo avisa el cliente","placeholder":"Correo, formulario, en la tienda"},{"key":"product","label":"Qué debe permitir el producto o la venta","placeholder":"P. ej. encontrar el contacto y el número de compra"},{"key":"manual","label":"Qué haréis a mano","placeholder":"Revisión, respuesta, reembolso"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2c' and p.key = 'returns'
    and s.key = 'handling' and f.key = 'flow';

-- ═══ execution v1 ═══
update public.stage_templates t set translations = '{"de":{"title":"Execution","subtitle":"Baue die erste Version","intro":"Du steuerst den Bau im Ziel-Tracker. Die Punkte des Programms sagen, welches Ergebnis verlangt ist. Zusätzliche Ziele blockieren den Übergang nicht.","finish_label":"Ich gehe zum MVP über"},"uk":{"title":"Execution","subtitle":"Збудуй першу версію","intro":"Ти ведеш створення в трекері цілей. Пункти програми кажуть, який результат потрібен. Додаткові цілі не блокують переходу.","finish_label":"Переходжу до MVP"},"es":{"title":"Execution","subtitle":"Construye la primera versión","intro":"Llevas la construcción en el tracker de objetivos. Los puntos del programa dicen qué resultado se exige. Los objetivos adicionales no bloquean el paso.","finish_label":"Paso al MVP"}}'::jsonb
  where t.key = 'execution' and t.version = 1;
update public.stage_categories c set translations = '{"de":{"title":"Allgemein","intro":"Diese Punkte betreffen jeden Bau. Die Kategorien ergänzen eigene Ergebnisse."},"uk":{"title":"Загальне","intro":"Ці пункти стосуються кожного створення. Категорії додають власні результати."},"es":{"title":"General","intro":"Estos puntos se aplican a cualquier construcción. Las categorías añaden sus propios resultados."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'execution' and t.version = 1 and c.key = 'general';
update public.stage_points p set translations = '{"de":{"title":"Wähle das nächste Ergebnis und verteile die Arbeit","duration_hint":"Etwa 15 Minuten","guide_body":"1.1. Lege fest, was fertig sein soll\nBeginne mit der Arbeit, deren Ergebnis den nächsten Schritt im Bau ermöglicht. Greif auf frühere Vereinbarungen und die Anforderungen deiner Kategorie zurück. Wenn du schon ein passendes Goal hast, also ein notiertes Ziel, öffne seine Karte. Ergänze nur fehlende Informationen.\nBenenne das Ziel so, dass sich nach der Erledigung prüfen lässt, was entstanden ist. Ein bloßes „Am Produkt arbeiten“ sagt wenig. Hilfreich ist das Muster: „Fertiges [Element], mit dem man [eine konkrete Handlung ausführen] kann“. Wenn sich unter einem Namen mehrere unabhängige Ergebnisse verbergen, wähle das als Nächstes benötigte oder teile die Arbeit in kleinere Ziele.\nLege schon jetzt den Proof fest, also den Nachweis der Erledigung. Das kann eine konkrete Datei sein, ein Foto, eine Aufnahme der Funktion oder ein festgehaltenes Testergebnis. Passe ihn an das Ziel und die Anforderungen des Programmpunkts an. Ein Foto kann zeigen, wie ein Gegenstand aussieht, aber um seine Funktion zu bestätigen, braucht es vielleicht eine Aufnahme oder ein Prüfergebnis. Am Anfang legst du fest, was du zeigen wirst; den fertigen Nachweis fügst du nach der Arbeit hinzu.\n1.2. Verteile die Arbeit und lege einen Termin fest\nWähle eine Person, die dafür sorgt, dass das ganze Ziel erreicht wird. Sie kann sich von anderen helfen lassen, ist aber dafür verantwortlich, die nötigen Teile zusammenzubringen und die Arbeit abzuschließen. Nutze die in Preparation vereinbarte Aufteilung der Verantwortung. Wenn du allein arbeitest, bist du Eigentümerin oder Eigentümer des Ziels.\nVereinbare den Termin mit der ausführenden Person. Berücksichtige ihre Verfügbarkeit und ob sie zuerst das Ergebnis einer anderen Person braucht. Wenn das Ganze für den gewählten Termin zu groß ist, trenne ein kleineres Ergebnis ab, das sich in dieser Zeit erreichen lässt. Behalte die übrige Arbeit für später.\nFüge Aufgaben hinzu, wenn sie helfen, die Arbeit auf Personen zu verteilen oder ihre Reihenfolge festzulegen. Jede sollte klar sagen, was zu tun ist. Vermeide es, einzelne Klicks und offensichtliche Handgriffe aufzuschreiben. Wenn jemand auf das Ergebnis einer anderen Person wartet, legt einen Termin für die Übergabe dieses Teils fest.\nHänge Materialien an, ohne die die ausführende Person Informationen suchen oder nachfragen müsste. Wähle das aktuelle Dokument oder eine schon in Vairo gespeicherte Datei. Materialien zu anderen Arbeiten können an ihrem Ort bleiben.","guide_sources":["Geoff Ralston, YC’s Essential Startup Advice (2017): Konzentration auf die wichtigste Arbeit und Vereinfachung des Umfangs. Die Beschreibung von Goals und Proof ist eine Ausarbeitung für Vairo.","Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): Aufteilung der Verantwortung, Verfügbarkeit und Reihenfolge der Arbeiten. Die Zuweisungen in Goal- und Aufgabenkarten wenden diese Hinweise in Vairo an."]},"uk":{"title":"Обери найближчий результат і розподіли роботу","duration_hint":"Близько 15 хвилин","guide_body":"1.1. Визнач, що має бути готове\nПочни з роботи, результат якої дасть змогу зробити наступний крок у створенні. Звернися до попередніх домовленостей і вимог своєї категорії. Якщо вже маєш відповідний Goal, тобто записану ціль, відкрий її картку. Доповни лише відсутню інформацію.\nНазви ціль так, щоб після виконання можна було перевірити, що з’явилося. Саме «Попрацювати над продуктом» мало що каже. Корисний шаблон: «Готовий [елемент], який дає змогу [виконати конкретну дію]». Якщо під однією назвою ховається кілька незалежних результатів, обери найближче потрібний або поділи роботу на менші цілі.\nВже зараз визнач proof, тобто доказ виконання. Це може бути конкретний файл, фото, запис роботи або запис результату спроби. Добери його до цілі й вимог пункту програми. Фото може показати вигляд предмета, але для підтвердження його роботи може знадобитися запис чи результат перевірки. На початку ти визначаєш, що покажеш; готовий доказ додаси після виконання роботи.\n1.2. Розподіли роботу й визнач термін\nОбери одну людину, яка подбає про досягнення всієї цілі. Вона може користуватися допомогою інших, але відповідає за збирання потрібних частин і доведення роботи до кінця. Використай розподіл відповідальності, погоджений у Preparation. Коли працюєш сам, власник цілі — ти.\nПогодь термін із виконавцем. Врахуй його доступність і те, чи спершу йому потрібен результат роботи іншої людини. Якщо все разом завелике для обраного терміну, виокрем менший результат, якого можна досягти за цей час. Решту роботи збережи на потім.\nДодавай завдання тоді, коли вони допомагають розподілити роботу між людьми або визначити її порядок. Кожне має чітко вказувати, що треба зробити. Уникай розписування окремих кліків і очевидних дій. Якщо хтось чекає на результат іншої людини, домовтеся про термін передачі цієї частини.\nПрикріпи матеріали, без яких виконавцеві доведеться шукати інформацію чи перепитувати. Обери актуальний документ або файл, уже збережений у Vairo. Матеріали щодо інших робіт можуть залишитися на своїх місцях.","guide_sources":["Geoff Ralston, YC’s Essential Startup Advice (2017): зосередження на найважливішій роботі й спрощення обсягу. Опис Goals і proof — розробка для Vairo.","Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): розподіл відповідальності, доступність і визначення порядку робіт. Призначення в картках Goals і завдань — застосування цих порад у Vairo."]},"es":{"title":"Elige el próximo resultado y reparte el trabajo","duration_hint":"Unos 15 minutos","guide_body":"1.1. Define qué tiene que estar listo\nEmpieza por el trabajo cuyo resultado permita dar el siguiente paso en la construcción. Recurre a lo acordado antes y a los requisitos de tu categoría. Si ya tienes un Goal adecuado, es decir, un objetivo anotado, abre su tarjeta. Completa solo la información que falte.\nNombra el objetivo de forma que, al terminar, se pueda comprobar qué se ha hecho. Un simple «Trabajar en el producto» dice poco. Un patrón útil es: «[Elemento] listo que permite [hacer una acción concreta]». Si bajo un mismo nombre hay varios resultados independientes, elige el que hace falta antes o divide el trabajo en objetivos más pequeños.\nDefine ya el proof, es decir, la prueba de que está hecho. Puede ser un archivo concreto, una foto, una grabación del funcionamiento o el registro del resultado de una prueba. Ajústalo al objetivo y a los requisitos del punto del programa. Una foto puede mostrar el aspecto de un objeto, pero para confirmar que funciona quizá haga falta una grabación o el resultado de una comprobación. Al principio decides qué mostrarás; la prueba en sí la añadirás al terminar el trabajo.\n1.2. Reparte el trabajo y fija una fecha\nElige a una persona que se asegure de que se cumple todo el objetivo. Puede contar con ayuda de otros, pero es responsable de reunir las partes necesarias y terminar el trabajo. Usa el reparto de responsabilidades acordado en Preparation. Si trabajas en solitario, el responsable del objetivo eres tú.\nAcuerda la fecha con quien hace el trabajo. Ten en cuenta su disponibilidad y si antes necesita el resultado del trabajo de otra persona. Si el conjunto es demasiado grande para la fecha elegida, separa un resultado más pequeño que se pueda conseguir en ese tiempo. Guarda el resto del trabajo para después.\nAñade tareas cuando ayuden a repartir el trabajo entre personas o a fijar su orden. Cada una debe indicar claramente qué hay que hacer. Evita detallar clics sueltos y acciones obvias. Si alguien espera el resultado de otra persona, acordad la fecha de entrega de esa parte.\nAdjunta los materiales sin los cuales quien hace el trabajo tendría que buscar información o preguntar. Elige el documento actual o un archivo ya guardado en Vairo. Los materiales de otros trabajos pueden quedarse donde están.","guide_sources":["Geoff Ralston, YC’s Essential Startup Advice (2017): centrarse en el trabajo más importante y simplificar el alcance. La descripción de Goals y proof es una elaboración para Vairo.","Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): reparto de responsabilidades, disponibilidad y orden de los trabajos. Las asignaciones en las tarjetas de Goals y tareas aplican estas pautas en Vairo."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'general' and p.key = 'next';
update public.stage_subpoints s set translations = '{"de":{"title":"Lege Ergebnis, Eigentümer, Termin und Nachweis fest","description":"Das Ziel kann noch in Arbeit sein. Aufgaben und Materialien sind optional."},"uk":{"title":"Визнач результат, власника, термін і доказ","description":"Ціль може ще бути в процесі. Завдання й матеріали необов’язкові."},"es":{"title":"Define resultado, responsable, fecha y prueba","description":"El objetivo puede seguir en curso. Las tareas y los materiales son opcionales."}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'general' and p.key = 'next' and s.key = 'setup';
update public.stage_fields f set translations = '{"de":{"question":"Öffne ein bestehendes Ziel oder lege eines für die nächste Arbeit an.","help":"Ein Klick allein schließt den Punkt nicht ab. Es zählt ein Ziel mit benanntem Ergebnis, Eigentümer, Termin und festgelegtem Nachweis.","config":{"label":"Ziel aus der Preparation-Liste anlegen"}},"uk":{"question":"Відкрий наявну ціль або створи її для найближчої роботи.","help":"Саме клацання не зараховує пункт. Важить ціль із названим результатом, власником, терміном і визначеним доказом.","config":{"label":"Створити ціль зі списку Preparation"}},"es":{"question":"Abre un objetivo existente o crea uno para el próximo trabajo.","help":"Un clic no da el punto por hecho. Cuenta un objetivo con resultado nombrado, responsable, fecha y prueba definida.","config":{"label":"Crear objetivo de la lista de Preparation"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'general' and p.key = 'next'
    and s.key = 'setup' and f.key = 'open';
update public.stage_points p set translations = '{"de":{"title":"Führe die Arbeit bis zum fertigen Ergebnis","duration_hint":"Während des ganzen Baus","guide_body":"2.1. Halte den Fortschritt bei der Arbeit fest\nDu kannst in den Werkzeugen arbeiten, die du für diese Arbeit gewählt hast. Kehre zur Karte in Vairo zurück, wenn sich der Stand einer Aufgabe ändert, ein nützliches Ergebnis entstanden ist oder ein Hindernis auftaucht. Die Aktualisierung soll dir und dem Team schnell zeigen, was fertig ist und was als Nächstes zu tun ist.\nNotiere nur Informationen, die für die weitere Arbeit nötig sind. Beispiel: „Erste Variante fertig. Es fehlt noch [Element]. Aktuelle Datei: [Link].“ Wenn eine Statusänderung und eine angehängte Datei reichen, ist die Aktualisierung damit erledigt. Ein eigener Tagesbericht ist nicht nötig.\nNutze beim Wiedereinstieg dieselbe Karte. Ein gemeinsamer Eintrag verhindert, dass eine Person an einer alten Version arbeitet und eine andere das Ergebnis in Nachrichten sucht.\n2.2. Löse die Blockade, wenn du feststeckst\nSetze den Status „Blockiert“, wenn ein konkretes Hindernis die weitere Arbeit verhindert. Beschreibe es so, dass klar ist, was fehlt. „Ich warte auf die Entscheidung, welche der beiden Varianten wir vorbereiten“ gibt dem Team mehr Information als „Ich komme nicht weiter“. Ein überschrittener Termin allein bedeutet Verzug, nicht unbedingt eine Blockade.\nLege die nächste Handlung fest, die das Hindernis beseitigt, und weise sie einer konkreten Person zu. Zum Beispiel: „Anna wählt die Variante bis Donnerstag.“ Notiere das in der bestehenden Aufgabe oder füge unter dem Ziel eine Aufgabe hinzu. Wenn die Hilfe eine andere ausführende Person oder einen anderen Termin erfordert, korrigiere die bisherige Zuweisung.\nWenn das Hindernis die Art der Umsetzung betrifft, überlege einen einfacheren Weg zum selben benötigten Ergebnis. Anfangs lässt sich ein Teil der Arbeit von Hand oder mit Hilfe anderer erledigen. Eine solche Vereinfachung muss die Anforderungen des Ziels weiterhin erfüllen. Notiere die gewählte Lösung bei der Arbeit, damit die anderen wissen, wie es weitergeht.\n2.3. Schließe ein erreichtes Ziel ab\nVergleiche das Ergebnis mit dem, was entstehen sollte. Wenn das Ziel noch nicht erreicht ist, lass es offen und korrigiere die Aufgaben. Alle Tätigkeiten abzuhaken reicht nicht, wenn ihr erwartetes Ergebnis fehlt.\nUnterscheide ein Ziel, etwas zu prüfen, von einem Ziel, ein funktionierendes Element zu bauen. Wenn das Ziel ein Test war, ist auch ein negatives Ergebnis ein festzuhaltendes Ergebnis. Wenn das Ziel ein funktionierendes Element war, bedeutet ein misslungener Test, dass dieses Ziel weitere Arbeit braucht. So sieht das Team sowohl die erledigte Prüfung als auch das verbleibende Problem.\nWenn das Ziel erreicht ist, gib den verlangten Proof an und markiere es als erledigt. Du kannst schon in der Karte gespeichertes Material nutzen. Stelle sicher, dass du die richtige Version zeigst und dass der Nachweis dem entspricht, was bestätigt werden sollte.\nVairo berücksichtigt das Ergebnis in ausdrücklich verknüpften Programmpunkten. Das erste erledigte Goal schließt diesen General-Punkt ab. Die übrigen Bauanforderungen erfüllst du weiterhin in deinen Kategorien, mit denselben Karten und Arbeitsregeln.","guide_sources":["Michael Seibel, The Scientific Method for Startups (2016): Entscheidungen auf Grundlage beobachteter Ergebnisse treffen. Die Art, Fortschritt in Arbeitskarten festzuhalten, ist eine Anpassung dieses Prinzips für Vairo.","Paul Graham, Do Things that Don’t Scale (2013): anfangs einfache, auch manuelle Wege nutzen. Der Umgang mit Hindernissen und die Zuweisung von Handlungen folgen der Arbeitsweise in Vairo.","Michael Seibel, The Scientific Method for Startups (2016): Annahmen prüfen, Schlüsse ziehen und auf Grundlage der Ergebnisse weiterarbeiten. Die Regeln für das Abschließen von Goals und Programmpunkten stammen aus dem Vairo-Programm."]},"uk":{"title":"Веди роботу до готового результату","duration_hint":"Протягом усього створення","guide_body":"2.1. Записуй поступ під час роботи\nПрацювати можна в інструментах, обраних для цієї роботи. Повертайся до картки у Vairo, коли змінився стан завдання, з’явився корисний результат або виникла перешкода. Оновлення має дати тобі й команді змогу швидко побачити, що готове і що робити далі.\nЗаписуй лише інформацію, потрібну для подальшої роботи. Приклад: «Готовий перший варіант. Бракує ще [елемент]. Актуальний файл: [посилання]». Якщо досить змінити статус і прикріпити файл, на цьому оновлення завершено. Окремий звіт за весь день не потрібен.\nПовертаючись до роботи, користуйся тією самою карткою. Спільний запис допомагає уникнути ситуації, коли одна людина працює на старій версії, а інша шукає результат у повідомленнях.\n2.2. Розблокуй роботу, якщо застряг\nСтатус «Заблоковано» став тоді, коли конкретна перешкода унеможливлює подальшу роботу. Опиши її так, щоб було зрозуміло, чого бракує. «Чекаю на рішення, який із двох варіантів готуємо» дає команді більше інформації, ніж «Не можу зрушити». Саме перевищення терміну означає затримку; воно не обов’язково означає блокування.\nВизнач найближчу дію, яка усуне перешкоду, і признач її конкретній людині. Наприклад: «Оля обере варіант до четверга». Запиши це в наявному завданні або додай завдання під цією ціллю. Коли допомога вимагає зміни виконавця чи терміну, виправ дотеперішнє призначення.\nЯкщо перешкода стосується способу виконання, подумай про простіший шлях до того самого потрібного результату. На початку частину роботи можна виконати вручну або з чиєюсь допомогою. Таке спрощення має й далі відповідати вимогам цілі. Запиши обране рішення біля роботи, щоб інші знали, як продовжувати.\n2.3. Закрий досягнуту ціль\nПорівняй результат із тим, що мало з’явитися. Якщо ціль ще не досягнута, залиш її відкритою й виправ завдання. Відмітити всі дії недостатньо, коли бракує їхнього очікуваного ефекту.\nРозрізняй ціль перевірити щось і ціль збудувати робочий елемент. Якщо метою було провести спробу, її негативний результат теж є результатом, який треба записати. Якщо метою був робочий елемент, невдала спроба означає, що ця ціль потребує подальшої роботи. Так команда бачить і виконану перевірку, і проблему, що залишилася.\nКоли ціль досягнуто, вкажи потрібний proof і познач її як виконану. Можна використати матеріал, уже збережений у картці. Переконайся, що показуєш правильну версію і що доказ відповідає тому, що мало бути підтверджено.\nVairo врахує результат у явно пов’язаних пунктах програми. Перший виконаний Goal дає змогу зарахувати цей пункт General. Решту вимог до створення ти й далі виконуєш у своїх категоріях, користуючись тими самими картками й правилами роботи.","guide_sources":["Michael Seibel, The Scientific Method for Startups (2016): ухвалення рішень на основі спостережуваних результатів. Спосіб записувати поступ у робочих картках — адаптація цього принципу для Vairo.","Paul Graham, Do Things that Don’t Scale (2013): використання простих, зокрема ручних, способів на початку. Робота з перешкодами й призначення дій випливають із прийнятого в Vairo способу роботи.","Michael Seibel, The Scientific Method for Startups (2016): перевірка припущень, висновки й подальша робота на основі результатів. Правила виконання Goal і зарахування пунктів походять із програми Vairo."]},"es":{"title":"Lleva el trabajo hasta un resultado terminado","duration_hint":"Durante toda la construcción","guide_body":"2.1. Anota el avance mientras trabajas\nPuedes trabajar con las herramientas que hayas elegido para ese trabajo. Vuelve a la tarjeta en Vairo cuando cambie el estado de la tarea, haya un resultado útil o surja un obstáculo. La actualización debe permitirte a ti y al equipo ver rápido qué está listo y qué falta.\nAnota solo la información necesaria para seguir trabajando. Ejemplo: «Primera variante lista. Falta todavía [elemento]. Archivo actual: [enlace]». Si basta con cambiar el estado y adjuntar un archivo, la actualización termina ahí. No hace falta un informe del día entero.\nAl retomar el trabajo, usa la misma tarjeta. Un registro común evita que una persona trabaje sobre una versión antigua mientras otra busca el resultado en los mensajes.\n2.2. Desbloquea el trabajo si te atascas\nPon el estado «Bloqueado» cuando un obstáculo concreto impida seguir. Descríbelo de forma que se sepa qué falta. «Espero la decisión sobre cuál de las dos variantes preparamos» da al equipo más información que «No puedo avanzar». Pasarse de la fecha significa retraso; no tiene por qué significar bloqueo.\nDefine la próxima acción que eliminará el obstáculo y asígnala a una persona concreta. Por ejemplo: «Lucía elegirá la variante antes del jueves». Anótalo en la tarea existente o añade una tarea bajo ese objetivo. Si la ayuda requiere cambiar de responsable o de fecha, corrige la asignación.\nSi el obstáculo tiene que ver con la forma de hacerlo, plantéate un camino más sencillo hacia el mismo resultado. Al principio, parte del trabajo puede hacerse a mano o con ayuda de alguien. Esa simplificación debe seguir cumpliendo los requisitos del objetivo. Anota la solución elegida junto al trabajo para que los demás sepan cómo seguir.\n2.3. Cierra el objetivo conseguido\nCompara el resultado con lo que tenía que salir. Si el objetivo aún no se ha conseguido, déjalo abierto y corrige las tareas. Marcar todas las acciones no basta si falta el efecto esperado.\nDistingue un objetivo de comprobar algo de uno de construir un elemento que funcione. Si el objetivo era hacer una prueba, un resultado negativo también es un resultado que anotar. Si el objetivo era tener un elemento funcionando, una prueba fallida significa que ese objetivo necesita más trabajo. Así el equipo ve tanto la comprobación hecha como el problema pendiente.\nCuando hayas conseguido el objetivo, indica el proof requerido y márcalo como terminado. Puedes usar material ya guardado en la tarjeta. Asegúrate de mostrar la versión correcta y de que la prueba corresponde a lo que había que confirmar.\nVairo tendrá en cuenta el resultado en los puntos del programa vinculados explícitamente. El primer Goal terminado permite dar por hecho este punto General. Los demás requisitos de construcción los sigues cumpliendo en tus categorías, con las mismas tarjetas y normas de trabajo.","guide_sources":["Michael Seibel, The Scientific Method for Startups (2016): tomar decisiones a partir de resultados observados. La forma de anotar el avance en las tarjetas es una adaptación de este principio para Vairo.","Paul Graham, Do Things that Don’t Scale (2013): usar al principio formas sencillas, también manuales. La gestión de obstáculos y la asignación de acciones siguen la forma de trabajar de Vairo.","Michael Seibel, The Scientific Method for Startups (2016): comprobar suposiciones, sacar conclusiones y seguir trabajando a partir de los resultados. Las reglas para terminar un Goal y dar por hechos los puntos vienen del programa de Vairo."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'general' and p.key = 'work';
update public.stage_subpoints s set translations = '{"de":{"title":"Schließe ein erreichtes Ziel ab","description":"Ein ausdrücklich verknüpftes Ziel des aktuellen Baus, abgeschlossen und mit dem verlangten Nachweis."},"uk":{"title":"Закрий досягнуту ціль","description":"Одна явно прикріплена ціль поточного створення, виконана й із потрібним доказом."},"es":{"title":"Cierra el objetivo conseguido","description":"Un objetivo de la construcción actual vinculado explícitamente, terminado y con la prueba requerida."}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'general' and p.key = 'work' and s.key = 'done';
update public.stage_fields f set translations = '{"de":{"question":"Gib den Nachweis an und markiere das Ziel als erledigt.","help":"Wenn es noch kein Ergebnis gibt, lass das Ziel offen und korrigiere die Aufgaben.","config":{"label":"Ziele öffnen"}},"uk":{"question":"Вкажи доказ і познач ціль як виконану.","help":"Якщо результату ще немає, залиш ціль відкритою й виправ завдання.","config":{"label":"Відкрити цілі"}},"es":{"question":"Indica la prueba y marca el objetivo como terminado.","help":"Si todavía no hay resultado, deja el objetivo abierto y corrige las tareas.","config":{"label":"Abrir objetivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'general' and p.key = 'work'
    and s.key = 'done' and f.key = 'open';
update public.stage_points p set translations = '{"de":{"title":"Schließe Execution ab","duration_hint":"Wenn die übrigen Anforderungen erfüllt sind","guide_body":"3.1. Erledige die verlangten Arbeiten\nÖffne die Zusammenfassung der Etappe und prüfe die angezeigten Lücken. Wenn die Arbeit erledigt ist, aber kein Nachweis gespeichert ist, hänge das vorhandene Ergebnis an. Wenn das Ergebnis selbst fehlt, geh zum passenden Goal zurück und beende die Arbeit. Nutze die Anforderungen von General und den gewählten Kategorien.\nTrenne eine Lücke, die für die erste Version nötig ist, von einer Idee für ihren weiteren Ausbau. Hilfreich ist die Frage: „Leistet die erste Version ohne diese Änderung, was sie den Nutzern bieten soll?“ Extras können in offenen Goals bleiben. Anforderungen an Funktion und Sicherheit aus deinen Kategorien müssen vor dem Übergang erfüllt sein.\n3.2. Geh zur MVP Stage über\nWenn die übrigen Anforderungen erfüllt sind, bestätigt Founder oder Admin den Abschluss von Execution. Die Zusammenfassung nutzt die zuvor gespeicherten Ergebnisse. Du musst keine weitere Beschreibung der ganzen erledigten Arbeit vorbereiten.\nIn der MVP Stage stellst du die erste Version Zielpersonen zur Verfügung, sammelst ihre Reaktionen und machst weitere Verbesserungen. Tracker, Team, Materialien und offene Goals bleiben verfügbar. Der Abschluss des Baus entscheidet noch nicht, wie Zielpersonen das Produkt nutzen werden. Deshalb stützt du die weitere Arbeit auch darauf, was nach der Veröffentlichung passiert.","guide_sources":["Geoff Ralston, YC’s Essential Startup Advice (2017): unnötigen Ausbau der ersten Version begrenzen. Paul Graham, Do Things that Don’t Scale (2013): die erste Nutzung nicht aufschieben, um auf Perfektion zu warten — unter Berücksichtigung der Folgen von Fehlern. Die Liste der verlangten Arbeiten stammt aus dem Vairo-Programm.","Geoff Ralston, YC’s Essential Startup Advice (2017): eine nützliche erste Version veröffentlichen und auf Grundlage des Kontakts mit Nutzern weiter verbessern. Die Bedingungen für den Übergang zur MVP Stage und die Beibehaltung der Daten folgen den Vairo-Regeln."]},"uk":{"title":"Закрий Execution","duration_hint":"Коли решту вимог виконано","guide_body":"3.1. Доведи до кінця потрібні роботи\nВідкрий підсумок етапу й перевір зазначені прогалини. Якщо робота виконана, але доказу не збережено, прикріпи наявний результат. Якщо бракує самого результату, повернися до відповідного Goal і заверши роботу. Користуйся вимогами General і обраних категорій.\nВідокрем прогалину, потрібну для завершення першої версії, від ідеї її подальшого розширення. Допомагає запитання: «Чи без цієї зміни перша версія зробить те, що має дати користувачеві?». Доповнення можуть залишитися у відкритих Goals. Вимоги щодо роботи й безпеки з твоїх категорій мають бути виконані перед переходом далі.\n3.2. Перейди до MVP Stage\nКоли решту вимог виконано, Founder або Admin підтверджує завершення Execution. Підсумок використовує збережені раніше результати. Не треба готувати ще одного опису всієї виконаної роботи.\nУ MVP Stage ти займешся наданням першої версії адресатам, збиранням їхніх реакцій і подальшими виправленнями. Трекер, команда, матеріали й відкриті Goals залишаються доступними. Завершення створення ще не вирішує, як адресати користуватимуться продуктом. Тому подальшу роботу ти спиратимеш і на те, що станеться після його надання.","guide_sources":["Geoff Ralston, YC’s Essential Startup Advice (2017): обмеження зайвого розширення першої версії. Paul Graham, Do Things that Don’t Scale (2013): не відкладати першого використання в очікуванні досконалості, з урахуванням наслідків помилок. Список потрібних робіт випливає з програми Vairo.","Geoff Ralston, YC’s Essential Startup Advice (2017): надання корисної першої версії й подальші виправлення на основі контакту з користувачами. Умови переходу до MVP Stage і збереження даних випливають із правил Vairo."]},"es":{"title":"Cierra Execution","duration_hint":"Cuando se cumplan los demás requisitos","guide_body":"3.1. Termina los trabajos requeridos\nAbre el resumen de la etapa y revisa las carencias señaladas. Si el trabajo está hecho pero no hay prueba guardada, adjunta el resultado existente. Si falta el resultado en sí, vuelve al Goal correspondiente y termina el trabajo. Usa los requisitos de General y de las categorías elegidas.\nSepara lo que falta para terminar la primera versión de las ideas para ampliarla después. Ayuda la pregunta: «Sin este cambio, ¿hará la primera versión lo que debe ofrecer al usuario?». Los extras pueden quedarse en Goals abiertos. Los requisitos de funcionamiento y seguridad de tus categorías deben cumplirse antes de avanzar.\n3.2. Pasa a la MVP Stage\nCuando se cumplan los demás requisitos, el Founder o un Admin confirma el fin de Execution. El resumen usa los resultados guardados antes. No tienes que preparar otra descripción de todo el trabajo hecho.\nEn la MVP Stage pondrás la primera versión a disposición de los destinatarios, recogerás sus reacciones y harás nuevas mejoras. El tracker, el equipo, los materiales y los Goals abiertos siguen disponibles. Terminar la construcción no decide aún cómo usarán los destinatarios el producto. Por eso basarás el trabajo siguiente también en lo que pase tras ponerlo a su disposición.","guide_sources":["Geoff Ralston, YC’s Essential Startup Advice (2017): limitar la ampliación innecesaria de la primera versión. Paul Graham, Do Things that Don’t Scale (2013): no aplazar el primer uso esperando la perfección, teniendo en cuenta las consecuencias de los errores. La lista de trabajos requeridos viene del programa de Vairo.","Geoff Ralston, YC’s Essential Startup Advice (2017): poner a disposición una primera versión útil y seguir mejorándola a partir del contacto con usuarios. Las condiciones para pasar a la MVP Stage y la conservación de los datos siguen las reglas de Vairo."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'general' and p.key = 'close';
update public.stage_subpoints s set translations = '{"de":{"title":"Prüfe, was fehlt","description":"Dieser Punkt ist keine Bedingung dafür, dass der Abschluss-Button erscheint."},"uk":{"title":"Перевір, чого бракує","description":"Цей пункт не є умовою появи кнопки завершення."},"es":{"title":"Comprueba qué falta","description":"Este punto no es condición para que aparezca el botón de finalizar."}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'general' and p.key = 'close' and s.key = 'summary';
update public.stage_fields f set translations = '{"de":{"question":"Öffne die Zusammenfassung der Etappe und ergänze fehlende Ergebnisse.","help":"Der Abschluss-Button zählt die übrigen verlangten Punkte, nicht diesen Unterpunkt.","config":{"label":"Zusammenfassung"}},"uk":{"question":"Відкрий підсумок етапу й доповни відсутні результати.","help":"Кнопка завершення враховує решту потрібних пунктів, а не цей підпункт.","config":{"label":"Підсумок"}},"es":{"question":"Abre el resumen de la etapa y completa los resultados que falten.","help":"El botón de finalizar cuenta los demás puntos requeridos, no este subpunto.","config":{"label":"Resumen"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'general' and p.key = 'close'
    and s.key = 'summary' and f.key = 'open';
update public.stage_categories c set translations = '{"de":{"title":"SaaS","intro":"Die erste Version des Programms: Funktion, Zugang, Daten, Tests und Bereitschaft für Verbesserungen."},"uk":{"title":"SaaS","intro":"Перша версія програми: робота, доступ, дані, спроби й готовність до виправлень."},"es":{"title":"SaaS","intro":"La primera versión del programa: funcionamiento, acceso, datos, pruebas y disposición para mejorar."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'execution' and t.version = 1 and c.key = 'saas';
update public.stage_points p set translations = '{"de":{"title":"Baue die Hauptfunktion des Programms","guide_body":"1.1. Führe Nutzer zum ersten Ergebnis\nÖffne die zuvor vorbereitete Beschreibung der ersten Version. Wähle die Haupttätigkeit, die das Programm ermöglichen soll, und bring sie zu einem funktionierenden Ergebnis. Wenn du ein Werkzeug zur Erstellung von Berichten baust, sollten Nutzer Daten übergeben und den passenden Bericht erhalten können. Schon während des Baus kannst du diesen Weg an einem einfachen Beispiel zeigen. So merkst du früh, wenn die einzelnen Teile des Programms nicht wie geplant zusammenarbeiten.\nVerknüpfe ein bestehendes Goal oder lege ein Goal vom Typ „Bauergebnis“ an. Es kann lauten: „Nutzer fügen eine Datei mit Daten hinzu und laden den darauf basierenden Bericht herunter.“ Benenne eine verantwortliche Person, vereinbare einen Termin und gib den erwarteten Proof an, also den Nachweis der Erledigung. In diesem Beispiel kann das eine Aufnahme der ganzen Tätigkeit und der erhaltene Bericht sein. Das Ergebnis vor Arbeitsbeginn zu vereinbaren erleichtert später die Prüfung, ob die Aufgabe erledigt ist.\nTeile die Arbeit dort, wo sich ein konkretes Stück abnehmen lässt. Eine Person kann die Dateiannahme vorbereiten, eine zweite die Berechnungen und eine dritte die Ergebnisansicht. Vereinbart vorher, welche Daten diese Teile untereinander austauschen. Die für das Goal verantwortliche Person achtet auch auf ihr Zusammenspiel. Wenn eine ausführende Person sagt, ihr Teil sei fertig, prüft ihn mit dem Teil, der ihn nutzen soll. In Vairo reichen Aufgaben unter einem gemeinsamen Ziel. Passe die Größe einer Aufgabe daran an, dass sich ihr Ergebnis zeigen und prüfen lässt.\nWenn du eine fertige Plattform für Apps ohne Programmierung nutzt, kannst du dasselbe Ergebnis durch Konfiguration ihrer Funktionen erreichen. Wenn ein anderes Programm den Dienst nutzt, läuft die Verbindung über eine API, also eine festgelegte Art des Datenaustauschs zwischen Programmen. Zeig in diesem Fall das Senden der nötigen Daten und die erhaltene Antwort. Bei längerer Verarbeitung sollte das aufrufende Programm prüfen können, ob die Arbeit läuft, beendet ist oder wiederholt werden muss.\nFüge dem Proof das Ergebnis mit Beispieldaten und die Bezeichnung der geprüften Version bei. Die Version kann einen einfachen Namen haben, z. B. „0.1“, verknüpft mit einem Code-Stand oder dem Verlauf der fertigen Plattform. So weiß das Team auch nach weiteren Änderungen, worauf sich die Aufnahme bezieht. Nutze dasselbe Material in den nächsten Unterpunkten, wenn es auch deren Fragen beantwortet.","guide_sources":["Google Engineering Practices, Small CLs beschreibt die Arbeit in kleinen Änderungen, die sich einzeln prüfen lassen. Atlassian, Roles and Responsibilities erklärt das Abstimmen von Verantwortung und Beteiligung. Beispiel und Umgang mit dem Goal sind an Vairo angepasst."]},"uk":{"title":"Збудуй головну дію програми","guide_body":"1.1. Доведи користувача до першого результату\nВідкрий опис першої версії, підготовлений раніше. Обери головну дію, яку має уможливлювати програма, і доведи її до робочого результату. Якщо створюєш інструмент для підготовки звітів, користувач має могти передати дані й отримати потрібний звіт. Уже під час створення можна показати цей шлях на простому прикладі. Це дасть змогу рано помітити, що окремі частини програми не співпрацюють так, як ви припускали.\nПрикріпи наявний Goal або створи Goal типу «Результат створення». Він може звучати так: «Користувач додає файл із даними й завантажує підготовлений на їх основі звіт». Признач відповідальну людину, погодь термін і вкажи очікуваний proof, тобто доказ виконання. У цьому прикладі ним може бути запис усієї дії та отриманий звіт. Погодження результату до початку роботи полегшує пізнішу перевірку, чи завдання виконано.\nДіли роботу там, де можна прийняти конкретний фрагмент. Одна людина може підготувати приймання файла, друга — обчислення, а третя — перегляд результату. Заздалегідь домовтеся, які дані передають одна одній ці частини. Людина, відповідальна за Goal, пильнує також їхнє поєднання. Коли виконавець каже, що його частина готова, перевірте її з частиною, яка має нею користуватися. У Vairo досить завдань під спільною ціллю. Розмір завдання добирай до можливості показати й перевірити результат.\nЯкщо користуєшся готовою платформою для створення застосунків без написання коду, той самий результат можна отримати налаштуванням її функцій. Коли отримувачем послуги є інша програма, зв’язок відбувається через API, тобто встановлений спосіб обміну даними між програмами. У такому разі покажи надсилання потрібних даних і отриману відповідь. За довшої обробки отримувач має могти перевірити, чи робота триває, завершилася чи потребує повторення.\nДо proof додай результат, отриманий на прикладових даних, і позначення перевіреної версії. Версія може мати просту назву, напр. «0.1», пов’язану із записом коду або історією готової платформи. Так команда знатиме, чого стосується запис, і після наступних змін. Використай той самий матеріал у наступних підпунктах, якщо він відповідає й на їхні запитання.","guide_sources":["Google Engineering Practices, Small CLs описує роботу невеликими змінами, які можна окремо перевірити. Atlassian, Roles and Responsibilities пояснює узгодження відповідальності й участі співпрацівників. Приклад і спосіб ведення Goal адаптовано до Vairo."]},"es":{"title":"Construye la acción principal del programa","guide_body":"1.1. Lleva al usuario a su primer resultado\nAbre la descripción de la primera versión preparada antes. Elige la acción principal que debe permitir el programa y llévala hasta un resultado que funcione. Si creas una herramienta para preparar informes, el usuario debería poder aportar datos y recibir el informe correcto. Ya durante la construcción puedes mostrar este recorrido con un ejemplo sencillo. Así verás pronto si las partes del programa no colaboran como suponíais.\nVincula un Goal existente o crea un Goal del tipo «Resultado de construcción». Puede decir: «El usuario sube un archivo con datos y descarga el informe preparado a partir de él». Asigna un responsable, acuerda una fecha e indica el proof esperado, es decir, la prueba de que está hecho. En este ejemplo puede ser una grabación de toda la acción y el informe obtenido. Acordar el resultado antes de empezar facilita comprobar después si la tarea está hecha.\nDivide el trabajo donde se pueda recibir una parte concreta. Una persona puede preparar la carga del archivo; otra, los cálculos, y una tercera, la vista del resultado. Acordad antes qué datos se pasan esas partes. Quien es responsable del Goal vigila también que encajen. Cuando alguien diga que su parte está lista, comprobadla con la parte que la va a usar. En Vairo bastan tareas bajo un objetivo común. Ajusta el tamaño de cada tarea a que su resultado se pueda mostrar y comprobar.\nSi usas una plataforma para crear apps sin programar, puedes conseguir el mismo resultado configurando sus funciones. Cuando quien recibe el servicio es otro programa, la conexión se hace mediante una API, es decir, una forma acordada de intercambiar datos entre programas. En ese caso muestra el envío de los datos necesarios y la respuesta recibida. Si el procesamiento es largo, quien lo recibe debería poder comprobar si sigue en curso, ha terminado o hay que repetirlo.\nAñade al proof el resultado obtenido con datos de ejemplo y la versión comprobada. La versión puede tener un nombre sencillo, p. ej. «0.1», vinculado a un registro del código o al historial de la plataforma. Así el equipo sabrá a qué se refiere la grabación aunque haya más cambios. Usa el mismo material en los siguientes subpuntos si también responde a sus preguntas.","guide_sources":["Google Engineering Practices, Small CLs describe trabajar con cambios pequeños que se pueden revisar por separado. Atlassian, Roles and Responsibilities explica cómo acordar responsabilidades y la participación de colaboradores. El ejemplo y la forma de llevar el Goal están adaptados a Vairo."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'saas' and p.key = 'saas-core';
update public.stage_subpoints s set translations = '{"de":{"title":"Führe Nutzer zum ersten Ergebnis"},"uk":{"title":"Доведи користувача до першого результату"},"es":{"title":"Lleva al usuario a su primer resultado"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'saas' and p.key = 'saas-core' and s.key = 'result';
update public.stage_fields f set translations = '{"de":{"question":"Verknüpfe oder lege ein Ziel vom Typ „Bauergebnis“ an.","help":"Der Nachweis zeigt Version, Funktion und Ergebnis.","config":{"label":"Ziele öffnen"}},"uk":{"question":"Прикріпи або створи ціль типу «Результат створення».","help":"Доказ показує версію, дію і результат.","config":{"label":"Відкрити цілі"}},"es":{"question":"Vincula o crea un objetivo del tipo «Resultado de construcción».","help":"La prueba muestra la versión, el funcionamiento y el resultado.","config":{"label":"Abrir objetivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'saas' and p.key = 'saas-core'
    and s.key = 'result' and f.key = 'open';
update public.stage_points p set translations = '{"de":{"title":"Sorge für Zugang und Daten","guide_body":"2.1. Setze die Zugangsregeln für das Programm um\nNutze die Vereinbarungen aus Preparation und gib sie an die Person weiter, die den Zugang baut. Sie sollte wissen, wer das Programm betreten darf und welche Handlungen dieser Person offenstehen. Bei Nutzerkonten lohnt es sich, fertige Anmeldemechanismen zu nutzen. Prüft auch, wie Nutzer wieder Zugang bekommen, wenn sie ihr Passwort vergessen oder die gewählte Anmeldeart nicht mehr funktioniert. Bei einem öffentlichen Programm können bestimmte Handlungen ohne Konto möglich sein, die Verwaltung des Dienstes braucht aber weiterhin Schutz.\nDie Anmeldung bestätigt die Identität der Nutzer. Berechtigungen legen fest, was sie mit einem konkreten Material tun dürfen. Wer einen Bericht erstellt hat, darf ihn vielleicht ändern, während eine eingeladene Person ihn nur lesen darf. Wenn das Programm mehrere Firmen bedient, darf der Zugang zu einer nicht die Daten der anderen öffnen. Dasselbe Prinzip gilt für private Konten einzelner Personen.\nBereitet zwei Testkonten mit getrennten Materialien vor. Bitte eine technische Person zu prüfen, ob man vom zweiten Konto fremdes Material lesen oder ändern kann, auch durch das direkte Senden einer Anfrage an den Dienst. Ein versteckter Button schützt eine solche Anfrage nicht. Die Kontrolle muss in dem Teil des Programms greifen, der Anfragen bearbeitet und Daten herausgibt. Bei einer fertigen Plattform müssen ihre Zugriffseinstellungen in der genutzten Konfiguration geprüft werden.\nWenn der Zugang kostenpflichtig ist, setzt die zuvor gewählten Regeln um. Die Zahlungsbestätigung sollte aus einer verlässlichen Quelle kommen, z. B. dem System des Zahlungsanbieters. Wenn ihr Konten anfangs von Hand freischaltet, vereinbart, wer die Zahlung prüft und für wie lange der Zugang gilt. Das Ende des bezahlten Zeitraums und eine Kündigung der Verlängerung sollten zu dem in Preparation festgelegten Verhalten führen.\nWähle die Person für die technische Prüfung nach ihren Fähigkeiten. Als Founder kannst du die Regeln festlegen und das Ergebnis gemeinsam mit ihr abnehmen. Bewahre im Proof eine Beschreibung des funktionierenden Zugangs und das Ergebnis der Tests mit den Testkonten auf. Dieses Material hilft erneut bei der Prüfung des ganzen Programms in Unterpunkt 3.1.\n2.2. Behandle Daten im ganzen Ablauf des Programms\nVerfolge den Weg einer Information durch das Programm. Zum Beispiel fügt eine Nutzerin einem Projekt eine Datei hinzu, das Programm erstellt einen Bericht, und sie öffnet ihn später erneut. Prüfe, ob der Bericht die richtige Datei nutzt und dem richtigen Projekt zugeordnet bleibt. Ein paar leicht unterscheidbare Testdaten reichen. Sie helfen zu bemerken, wenn zwei Projekte verwechselt wurden oder ein Ergebnis nach erneutem Öffnen nicht erhalten blieb.\nVereinbare mit der ausführenden Person, welche Daten das Programm annehmen darf. Wenn es eine Bestellzahl erwartet, sollte es angemessen auf Text oder einen unzulässigen Wert reagieren. Wenn es Dateien annimmt, braucht es eine Prüfung von Art und zulässiger Größe. Die Kontrolle sollte vor der Verarbeitung auf Seiten des Dienstes stattfinden. Eine Meldung am Formular hilft Nutzern, einen Fehler zu korrigieren, aber eine Prüfung nur im Browser lässt sich umgehen.\nAchte auf Handlungen, die mehrere Dinge gleichzeitig ändern. Bei einer Platzreservierung kann das Programm die Anmeldung speichern und die Zahl freier Plätze verringern. Vereinbart, was passiert, wenn das Speichern der Anmeldung gelingt, der zweite Schritt aber abbricht. Zusammenhängende Änderungen in einer Datenbank lassen sich oft in einer Transaktion bündeln, also einem Vorgang, der ganz ausgeführt oder ganz zurückgenommen wird. Wenn die Arbeit mehrere Dienste umfasst, muss die ausführende Person einen Weg wählen, erledigte Schritte zu erkennen und die übrigen sicher abzuschließen oder zurückzunehmen.\nWendet die zuvor festgelegte Art an, Informationen aufzubewahren und zu löschen. Eine Datei und ein Verweis darauf können an verschiedenen Orten gespeichert sein. Einen Eintrag vom Bildschirm zu löschen, muss also nicht die Datei selbst löschen. Prüft, was mit Daten an den vom Programm genutzten Orten passiert, auch nach dem Ende des Zugangs. Wenn ein Ergebnis nur während einer einzelnen Verarbeitung gebraucht wird, sorgt dafür, dass diese Verarbeitung endet und die Daten nach den vereinbarten Regeln gelöscht werden.\nEin gemeinsames Goal kann den ganzen Datenweg umfassen, auch wenn verschiedene Personen seine Teile vorbereiten. Vereinbart einen Zeitpunkt für einen gemeinsamen Test, um Fehler bei der Übergabe von Informationen zu finden. Bewahre als Proof eine Beschreibung der Prüfung und ihr Ergebnis auf. Nutze Materialien, die bei der Arbeit entstehen, ohne technische Dokumentation in ein weiteres Formular abzuschreiben.","guide_sources":["OWASP, Authorization Cheat Sheet erklärt Berechtigungen und die Zugriffsprüfung auf Seiten des Dienstes. AWS, Tenant isolation beschreibt die Trennung der Ressourcen von Kunden. Stripe, Webhooks zeigt, wie man die Herkunft von Benachrichtigungen des Zahlungsanbieters prüft.","OWASP, Input Validation Cheat Sheet beschreibt die Prüfung von Eingabedaten und Dateien. PostgreSQL, Transactions erklärt das gemeinsame Bestätigen zusammenhängender Änderungen in der Datenbank. Der Umfang der Aufbewahrung und Löschung von Daten ergibt sich aus den Vereinbarungen zu deinem Produkt."]},"uk":{"title":"Подбай про доступ і дані","guide_body":"2.1. Запровадь правила доступу до програми\nСкористайся домовленостями з Preparation і передай їх людині, яка створює доступ. Вона має знати, хто може увійти до програми і які дії для цієї людини доступні. Для акаунтів користувачів варто скористатися готовими механізмами входу. Перевірте також, як користувач відновить доступ, коли загубить пароль або перестане працювати обраний спосіб входу. У публічній програмі певні дії можуть бути доступні без акаунта, а керування послугою все одно потребує захисту.\nВхід підтверджує особу користувача. Повноваження визначають, що йому дозволено робити з конкретним матеріалом. Людина, яка створила звіт, може мати право його змінювати, тоді як запрошений отримувач може лише його читати. Якщо програма обслуговує кілька компаній, доступ до однієї з них не має відкривати даних інших. Той самий принцип застосуй до приватних акаунтів окремих людей.\nПідготуйте два тестові акаунти з окремими матеріалами. Попроси технічну людину перевірити, чи з другого акаунта можна прочитати чи змінити чужий матеріал, зокрема через пряме надсилання запиту до послуги. Прихована кнопка не захищає від такого запиту. Контроль має працювати в тій частині програми, яка розглядає запити й видає дані. На готовій платформі треба перевірити її налаштування доступу у використаній конфігурації.\nЯкщо доступ платний, запровадьте обрані раніше правила. Підтвердження оплати має надходити з надійного джерела, напр. із системи платіжного оператора. Коли на початку розблоковуєте акаунти вручну, домовтеся, хто перевіряє оплату і на який час надає доступ. Кінець оплаченого періоду й відмова від наступного поновлення мають вести до поведінки, визначеної в Preparation.\nЛюдину, відповідальну за технічну перевірку, добирай за її вміннями. Як founder ти можеш визначити правила й прийняти результат разом із нею. У proof збережи опис робочого доступу й результат спроб на тестових акаунтах. Цей матеріал знову знадобиться під час перевірки всієї програми в підпункті 3.1.\n2.2. Обробляй дані в усій роботі програми\nПройди шлях однієї інформації через програму. Наприклад, користувач додає файл до проєкту, програма створює звіт, а користувач пізніше знову його відкриває. Перевір, чи звіт використовує правильний файл і залишається прив’язаним до правильного проєкту. Досить кількох легко розрізнюваних тестових даних. Вони допоможуть помітити, що два проєкти переплуталися або результат не зберігся після повторного входу.\nДомовся з виконавцем, які дані програма може приймати. Якщо вона очікує кількості замовлень, має відповідно реагувати на текст чи недопустиме значення. Якщо приймає файли, потрібна перевірка їхнього типу й допустимого розміру. Контроль має відбуватися перед обробкою на боці послуги. Повідомлення біля форми допомагає користувачеві виправити помилку, але перевірку лише в браузері можна обійти.\nЗверни увагу на дії, які змінюють кілька речей одночасно. Під час бронювання місця програма може зберегти заявку й зменшити кількість вільних місць. Домовтеся, що станеться, якщо збереження заявки вдасться, а другий крок перерветься. Пов’язані зміни в одній базі часто можна об’єднати в транзакцію, тобто операцію, яку виконують повністю або скасовують. Коли робота охоплює різні послуги, виконавець має добрати спосіб розпізнати виконані кроки й безпечно завершити чи скасувати решту.\nЗастосуйте раніше визначений спосіб зберігання й видалення інформації. Файл і посилання на нього можуть зберігатися в різних місцях. Тож видалення запису з екрана не обов’язково видаляє сам файл. Перевірте, що відбувається з даними в місцях, якими користується програма, також після завершення доступу. Якщо результат потрібен лише під час окремої обробки, подбайте про завершення цієї обробки й видалення даних згідно з прийнятими правилами.\nСпільний Goal може охоплювати весь шлях даних, навіть коли різні люди готують його фрагменти. Домовтеся про момент спільної спроби, щоб виявити помилки під час передачі інформації. Як proof збережи опис перевірки та її результат. Використай матеріали, що з’являються під час роботи, без переписування технічної документації в чергову форму.","guide_sources":["OWASP, Authorization Cheat Sheet пояснює повноваження й перевірку доступу на боці послуги. AWS, Tenant isolation описує відокремлення ресурсів клієнтів. Stripe, Webhooks показує перевірку походження сповіщень від платіжного оператора.","OWASP, Input Validation Cheat Sheet описує перевірку вхідних даних і файлів. PostgreSQL, Transactions пояснює принцип спільного затвердження пов’язаних змін у базі. Обсяг зберігання й видалення даних випливає з домовленостей щодо твого продукту."]},"es":{"title":"Ocúpate del acceso y los datos","guide_body":"2.1. Aplica las reglas de acceso al programa\nUsa lo acordado en Preparation y pásaselo a quien construye el acceso. Debe saber quién puede entrar en el programa y qué acciones tiene disponibles cada persona. Para las cuentas de usuario conviene usar mecanismos de inicio de sesión ya hechos. Comprobad también cómo recupera el acceso un usuario que pierde la contraseña o cuyo método de inicio de sesión deja de funcionar. En un programa público, algunas acciones pueden estar disponibles sin cuenta, pero la gestión del servicio sigue necesitando protección.\nIniciar sesión confirma la identidad del usuario. Los permisos definen qué puede hacer con un material concreto. Quien creó un informe puede tener derecho a cambiarlo, mientras que un destinatario invitado solo puede leerlo. Si el programa atiende a varias empresas, el acceso a una no debe abrir los datos de las demás. Aplica el mismo principio a las cuentas privadas de personas individuales.\nPreparad dos cuentas de prueba con materiales separados. Pide a alguien técnico que compruebe si desde la segunda cuenta se puede leer o cambiar material ajeno, también enviando directamente una petición al servicio. Un botón oculto no protege frente a esa petición. El control tiene que funcionar en la parte del programa que atiende las peticiones y entrega los datos. En una plataforma ya hecha, hay que revisar sus ajustes de acceso en la configuración usada.\nSi el acceso es de pago, aplicad las reglas elegidas antes. La confirmación del pago debe venir de una fuente fiable, p. ej. el sistema del proveedor de pagos. Si al principio desbloqueáis cuentas a mano, acordad quién comprueba el pago y por cuánto tiempo da acceso. El fin del periodo pagado y la cancelación de la renovación deben llevar al comportamiento definido en Preparation.\nElige a la persona responsable de la comprobación técnica según sus habilidades. Como founder puedes fijar las reglas y revisar el resultado con ella. Guarda en el proof una descripción del acceso funcionando y el resultado de las pruebas con las cuentas de prueba. Este material volverá a servir al comprobar todo el programa en el subpunto 3.1.\n2.2. Gestiona los datos en todo el funcionamiento del programa\nSigue el recorrido de una información a través del programa. Por ejemplo, un usuario añade un archivo a un proyecto, el programa crea un informe y el usuario lo vuelve a abrir más tarde. Comprueba que el informe usa el archivo correcto y sigue asignado al proyecto correcto. Bastan unos pocos datos de prueba fáciles de distinguir. Ayudarán a ver si se han confundido dos proyectos o si el resultado no se conservó al volver a entrar.\nAcuerda con quien lo construye qué datos puede aceptar el programa. Si espera un número de pedidos, debe reaccionar bien ante un texto o un valor no permitido. Si acepta archivos, necesita comprobar su tipo y su tamaño máximo. El control debe hacerse antes del procesamiento, del lado del servicio. Un mensaje junto al formulario ayuda al usuario a corregir el error, pero una comprobación solo en el navegador se puede saltar.\nFíjate en las acciones que cambian varias cosas a la vez. Al reservar una plaza, el programa puede guardar la solicitud y reducir el número de plazas libres. Acordad qué pasa si se guarda la solicitud pero el segundo paso se interrumpe. Los cambios relacionados en una misma base de datos a menudo se pueden agrupar en una transacción, es decir, una operación que se hace completa o se deshace. Si el trabajo abarca varios servicios, quien lo construye debe elegir cómo detectar los pasos hechos y terminar o deshacer el resto de forma segura.\nAplicad la forma de conservar y borrar información acordada antes. Un archivo y el enlace a él pueden guardarse en sitios distintos. Por eso, borrar una entrada de la pantalla no tiene por qué borrar el archivo. Comprobad qué pasa con los datos en los sitios que usa el programa, también tras terminar el acceso. Si un resultado solo hace falta durante un procesamiento concreto, aseguraos de que ese procesamiento termina y los datos se borran según las reglas acordadas.\nUn Goal común puede abarcar todo el recorrido de los datos, aunque distintas personas preparen sus partes. Acordad un momento para una prueba conjunta y detectar errores al pasar la información. Guarda como proof una descripción de la comprobación y su resultado. Usa los materiales que surjan durante el trabajo, sin copiar la documentación técnica en otro formulario.","guide_sources":["OWASP, Authorization Cheat Sheet explica los permisos y la comprobación del acceso del lado del servicio. AWS, Tenant isolation describe la separación de los recursos de los clientes. Stripe, Webhooks muestra cómo comprobar el origen de las notificaciones del proveedor de pagos.","OWASP, Input Validation Cheat Sheet describe la comprobación de datos de entrada y archivos. PostgreSQL, Transactions explica la confirmación conjunta de cambios relacionados en la base de datos. El alcance de conservación y borrado de datos sale de lo acordado para tu producto."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'saas' and p.key = 'saas-access';
update public.stage_subpoints s set translations = '{"de":{"title":"Setze die Zugangsregeln für das Programm um"},"uk":{"title":"Запровадь правила доступу до програми"},"es":{"title":"Aplica las reglas de acceso al programa"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'saas' and p.key = 'saas-access' and s.key = 'rules';
update public.stage_fields f set translations = '{"de":{"question":"Zeig, dass die gewählte Zugangsart funktioniert.","config":{"label":"Ziele öffnen"}},"uk":{"question":"Покажи, що обраний спосіб доступу працює.","config":{"label":"Відкрити цілі"}},"es":{"question":"Muestra que la forma de acceso elegida funciona.","config":{"label":"Abrir objetivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'saas' and p.key = 'saas-access'
    and s.key = 'rules' and f.key = 'open';
update public.stage_subpoints s set translations = '{"de":{"title":"Behandle Daten im ganzen Ablauf des Programms"},"uk":{"title":"Обробляй дані в усій роботі програми"},"es":{"title":"Gestiona los datos en todo el funcionamiento del programa"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'saas' and p.key = 'saas-access' and s.key = 'data';
update public.stage_fields f set translations = '{"de":{"question":"Beschreibe die funktionierende Datenverarbeitung und gib das Ergebnis ihrer Prüfung an.","config":{"label":"Ziele öffnen"}},"uk":{"question":"Опиши робочу обробку даних і вкажи результат її перевірки.","config":{"label":"Відкрити цілі"}},"es":{"question":"Describe la gestión de datos que funciona e indica el resultado de su comprobación.","config":{"label":"Abrir objetivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'saas' and p.key = 'saas-access'
    and s.key = 'data' and f.key = 'open';
update public.stage_points p set translations = '{"de":{"title":"Prüfe das Programm während der Nutzung","guide_body":"3.1. Prüfe das Ergebnis und die Reaktion auf Probleme\nBeginne den Test mit der Situation, in der sich eine neue Zielperson befindet. Bereite ein frisches Konto oder einen anderen für das Produkt passenden Zugang vor. Führe die Haupttätigkeit aus, ohne Materialien zu nutzen, die auf dem Konto der Entwickler liegen. Prüfe auch das Ergebnis selbst. Ein Bericht kann sich öffnen und trotzdem falsche Berechnungen enthalten. Ein Programm, das Text zusammenfasst, kann eine Antwort liefern, die die wichtigste Information auslässt.\nPrüfe dann das Verhalten bei einem Fehler oder einer Unterbrechung. Was sehen Nutzer, wenn sie eine falsche Datei hochladen? Wird klar, dass ein externer Dienst nicht geantwortet hat? Wo eine wiederholte Handlung eine zweite Reservierung anlegen oder erneut eine Gebühr abbuchen könnte, prüft auch das Wiederholen derselben Anfrage. Das Ergebnis eines Vorgangs sollte der Absicht der Nutzer entsprechen. Nutzt die Ergebnisse der Zugriffskontrolle aus Unterpunkt 2.1, wenn sie noch die geprüfte Version betreffen.\nBei Verbindungen zu externen Diensten bekommst du manchmal automatische Nachrichten über Ereignisse. Man nennt sie Webhooks. Eine solche Nachricht kann die Information über einen bezahlten Zugang sein. Die ausführende Person sollte ihre Herkunft mit der vom Anbieter genannten Methode prüfen und eine erneute Zustellung behandeln. Prüft auch Verzögerungen und eine andere Reihenfolge der Nachrichten, wenn die Integration so arbeiten kann. Nutzt bei Zahlungen die Testumgebung des Anbieters, damit Tests kein Geld abbuchen.\nTeilt die Prüfungen nach Fähigkeiten auf. Wer die Bedürfnisse der Nutzer kennt, kann die Verständlichkeit und die Richtigkeit des Berichts beurteilen. Eine technische Person prüft Anfragen an den Dienst und sein Verhalten bei Fehlern. Wenn du allein arbeitest, nutze die zuvor notierten Erwartungen und passende Hilfe bei Dingen, die du nicht beurteilen kannst. Wiederkehrende Prüfungen wichtiger Vorgänge lohnt es sich, mit der ausführenden Person als Tests zu erwägen, die nach Änderungen automatisch laufen.\nBewahre bei einem Goal vom Typ „Testergebnis“ die geprüfte Version und die Ergebnisse auf. Es reicht ein Eintrag, mit dem sich der Test wiederholen lässt, z. B. „Datei ohne Datum hinzugefügt. Erwartet: Hinweis auf fehlendes Datum. Das Programm hat einen leeren Bericht erstellt.“ So ein Ergebnis kann ein Goal abschließen, bei dem es um die Durchführung eines Tests geht. Das gefundene Problem muss trotzdem behoben werden, bevor die Funktion als bereit gilt. Die gesammelten Tests können in einem Dokument bleiben, das als Proof angehängt wird.\n3.2. Prüfe Last und Nutzungskosten\nGeh zur Zahl der ersten Nutzer und zur Nutzungsart aus Preparation zurück. Bilde die erwartete Arbeit an der vorbereiteten Programmversion nach. Wenn mehrere Personen gleichzeitig Berichte erstellen können, prüfe genau diese Situation. Miss die Wartezeit und sieh nach, ob alle Aufgaben korrekt abgeschlossen werden. Die Zahl der Konten allein zeigt keine Last. Es zählt, was Nutzer gleichzeitig tun und wie große Daten sie verarbeiten.\nBeginne mit einem kleinen Test und erhöhe die Last bis zum nötigen Umfang. Vereinbare mit der ausführenden Person einen sicheren Weg, ihn auf eurem Dienst durchzuführen. Berücksichtige bei Verbindungen zu externen Anbietern deren Testbedingungen und verfügbare Limits. Gib an, auf welcher Konfiguration der Test lief. Ein Ergebnis von einer stärkeren Maschine entspricht vielleicht nicht dem Verhalten des Programms im günstigeren Paket, das du Zielpersonen anbieten willst.\nSieh dir den Verbrauch der Dienste bei den ausgeführten Handlungen an. Die Monatskosten lassen sich grob als Fixgebühren plus Kosten der erwarteten Nutzung schätzen. Zum Beispiel würden bei einer Fixgebühr von 12 € und 5 Cent pro Bericht 50 Berichte insgesamt etwa 14,50 € kosten. Das ist nur ein Rechenbeispiel. Nutze die Preise deiner Anbieter und berücksichtige andere kostenpflichtige Vorgänge des Programms. Eine längere Datei oder das Wiederholen einer fehlgeschlagenen Verarbeitung kann die Kosten ändern.\nWenn die erwartete Nutzung das Budget übersteigt, begrenze, was Ausgaben verursacht. Das kann die Zahl der Berichte sein oder die Länge einer hochgeladenen Aufnahme. Prüfe mit der ausführenden Person, ob die Begrenzung auch bei einer direkten Anfrage an den Dienst greift. Nach Erreichen des Limits sollten Nutzer eine verständliche Information bekommen. Wenn der gewählte Anbieter die nötige Begrenzung selbst bietet, prüfe ihre Wirkung und die Folgen für die Zielperson.\nFüge dem Proof die Testbedingungen und die erzielten Ergebnisse hinzu. Notiere auch die Kostenschätzung für die erste Gruppe und die nötigen Limits. Trenne Messung von Vorhersage: „Wir haben 20 Berichte erstellt“ beschreibt den Test, „100 Berichte werden etwa … kosten“ beschreibt eine Berechnung. Die für dieses Goal verantwortliche Person sollte das technische Ergebnis mit der ausführenden Person abstimmen und die vertretbaren Kosten mit der Person, die das Budget im Blick hat.\n3.3. Behebe ein Problem und prüfe die Änderung\nNutze diesen Unterpunkt, wenn du bei der Arbeit einen Fehler findest. Beginne damit, ihn anhand des festgehaltenen Tests nachzustellen. Die Information „der Bericht funktioniert nicht“ lässt der ausführenden Person viel zu raten. Eine Beschreibung der Datei, der ausgeführten Handlung und des erhaltenen Ergebnisses führt schneller zur Ursache. Wenn der Fehler nur manchmal auftritt, notiere auch die Uhrzeit des Tests, damit sich der passende Eintrag im Programm finden lässt.\nFindet heraus, was das Problem verursacht. Eine Zeitüberschreitung kann aus einem Fehler in eurem Programm oder aus einer Verzögerung eines externen Dienstes stammen. Bitte die ausführende Person um eine Erklärung, die auf einer Prüfung beruht. Wenn die Ursache unbekannt bleibt, kann die nächste Aufgabe genau darin bestehen, sie herauszufinden. Das verhindert einen großen Umbau ohne Wissen, was repariert werden muss.\nFühre das Gespräch im Team so, dass Leute Probleme schnell melden. Frag, was passiert ist und welche Informationen sie bei der Arbeit hatten. Wenn eine unklare Regel oder verschiedene Versionen von Vereinbarungen die Ursache waren, verbessert auch die Art, wie sie weitergegeben werden. Vereinbart eine Person, die die Korrektur bis zu ihrer Prüfung im Blick behält. Eine Aufgabe nur an einen Programmierer weiterzugeben, beendet diese Arbeit nicht.\nWiederhole nach der Änderung den Test, der den Fehler gezeigt hat. Prüfe auch Teile des Programms, die die Korrektur beeinflusst haben könnte. Eine geänderte Speicherung von Daten im Bericht kann zum Beispiel die Reihenfolge der Dokumente im Verlauf ändern. Diese Art der Prüfung hilft, eine Situation zu erkennen, in der die Reparatur einer Funktion eine andere kaputt macht. Passt den Umfang der Tests an die Änderung an. Eine kleine Textkorrektur und eine Änderung der Zugriffsregeln erfordern einen anderen Prüfumfang.\nBewahre das frühere Ergebnis auf, kennzeichne die neue Version und füge das Ergebnis des erneuten Tests der zugehörigen Arbeit bei. Wenn du den bestätigten Proof eines abgeschlossenen Goals aktualisierst, öffne es entsprechend der Funktionsweise von Vairo erneut. Das Ziel „Berichterstellung reparieren“ endet, wenn korrektes Funktionieren gezeigt wurde. Wenn ihr keinen Fehler gefunden habt, verlangt dieser Unterpunkt keine ausgedachte zusätzliche Arbeit.","guide_sources":["Google SRE, Testing for Reliability beschreibt die Prüfung eines verbundenen Systems und die Auswahl von Tests. Stripe, Webhooks erklärt die Verifizierung von Nachrichten sowie den Umgang mit Wiederholungen und der Reihenfolge von Ereignissen. OWASP, Input Validation Cheat Sheet hilft bei der Auswahl von Tests mit fehlerhaften Daten. Das Festhalten der Ergebnisse in Goals folgt dem Vairo-Programm.","AWS, Load test your workload beschreibt die Wahl von Last, Bedingungen und Messungen. Google SRE, Reliable Product Launches at Scale berücksichtigt Nutzungsgrenzen bei der Vorbereitung eines Dienstes. Das Kostenbeispiel ist eine Hilfsrechnung für das Vairo-Programm.","Google SRE, Postmortem Culture: Learning from Failure beschreibt das Klären von Ursachen und Bedingungen, die das Melden von Fehlern fördern. Google SRE, Testing for Reliability erklärt das erneute Prüfen nach Änderungen. Der Umgang mit Proof und dem erneuten Öffnen eines Goals folgt den Vairo-Regeln."]},"uk":{"title":"Перевір програму під час користування","guide_body":"3.1. Перевір результат роботи й реакцію на проблеми\nПочни спробу з ситуації, у якій опиниться новий адресат. Підготуй свіжий акаунт або інший відповідний для продукту спосіб входу. Виконай головну дію, не користуючись матеріалами, залишеними в акаунті розробника. Перевір також сам результат. Звіт може відкритися, але водночас містити хибні обчислення. Програма, що підсумовує текст, може видати відповідь, яка пропускає найважливішу інформацію.\nДалі перевір поведінку при помилці чи перериванні роботи. Що побачить користувач, коли надішле неправильний файл? Чи буде зрозуміло, що зовнішня послуга не відповіла? Там, де повторення дії могло б створити друге бронювання або знову стягнути оплату, перевірте також повторення того самого запиту. Наслідок операції має відповідати наміру користувача. Скористайтеся результатами контролю доступу з підпункту 2.1, якщо вони й далі стосуються перевірюваної версії.\nПри зв’язках із зовнішніми послугами іноді отримуєш автоматичні повідомлення про події. Їх називають вебхуками. Таким повідомленням може бути інформація про оплату доступу. Виконавець має перевірити його походження способом, вказаним постачальником, і обробити повторну доставку. Перевірте також затримки й інший порядок повідомлень, якщо інтеграція може так працювати. Для платежів скористайтеся тестовим середовищем оператора, щоб спроби не списували грошей.\nРозподіліть перевірки за вміннями. Людина, яка знає потреби користувача, може оцінити зрозумілість роботи й правильність звіту. Технічна людина перевірить запити до послуги та її поведінку під час помилок. Якщо працюєш сам, користуйся раніше записаними очікуваннями й відповідною допомогою в питаннях, які не можеш оцінити. Повторювані перевірки ключових операцій варто обговорити з виконавцем як тести, що запускаються автоматично після змін.\nДля Goal типу «Результат тесту» збережи перевірену версію й результати. Досить запису, який дає змогу відтворити спробу, напр.: «Додано файл без дати. Очікувалося повідомлення про відсутню дату. Програма створила порожній звіт». Такий результат може завершити Goal щодо проведення тесту. Виявлена проблема все одно потребує виправлення перед підтвердженням готовності функції. Зібрані спроби можуть лишатися в одному документі, прикріпленому як proof.\n3.2. Перевір навантаження й вартість користування\nПовернися до кількості перших користувачів і способу користування, прийнятих у Preparation. Відтвори очікувану роботу на підготовленій версії програми. Якщо кілька людей можуть одночасно створювати звіти, перевір саме таку ситуацію. Виміряй час очікування й подивися, чи всі завдання завершуються правильно. Сама кількість акаунтів не показує навантаження. Важить те, що користувачі роблять одночасно і наскільки великі дані обробляють.\nПочни з малої спроби й збільшуй навантаження до потрібного обсягу. Домовся з виконавцем про безпечний спосіб провести її на вашій послузі. При зв’язках із зовнішніми постачальниками врахуй їхні умови тестування й доступні ліміти. Вкажи, на якій конфігурації проведено спробу. Результат на потужнішій машині може не відповідати роботі програми в дешевшому пакеті, який плануєш надати адресатам.\nПодивися на використання послуг під час виконаних дій. Вартість місяця можна попередньо оцінити як фіксовані оплати плюс вартість очікуваного використання. Наприклад, при фіксованій оплаті 500 грн і вартості 2 грн за звіт виконання 50 звітів коштувало б разом близько 600 грн. Це лише приклад розрахунку. Використай ціни своїх постачальників і врахуй інші платні дії програми. Довший файл або повторення невдалої обробки може змінити вартість.\nЯкщо очікуване використання перевищує бюджет, обмеж те, що породжує витрати. Це може бути кількість звітів або тривалість надісланого запису. Перевір із виконавцем, чи обмеження працює й за прямого запиту до послуги. Після досягнення ліміту користувач має отримати зрозуміле повідомлення. Якщо обраний постачальник сам забезпечує потрібне обмеження, перевір, як воно працює і які наслідки для адресата.\nДо proof додай умови спроби й отримані результати. Запиши також оцінку вартості для першої групи й потрібні ліміти. Відокремлюй вимірювання від прогнозу: «ми виконали 20 звітів» описує спробу, а «100 звітів коштуватимуть близько…» описує розрахунок. Людина, відповідальна за цей Goal, має погодити з виконавцем технічний результат, а з людиною, що пильнує бюджет, — допустиму вартість.\n3.3. Виправ проблему й перевір зміну\nСкористайся цим підпунктом, коли під час роботи знайдеш несправність. Почни з її відтворення на основі записаної спроби. Інформація «звіт не працює» залишає виконавцеві багато здогадок. Опис файла, виконаної дії й отриманого результату дає змогу швидше дістатися причини. Якщо помилка з’являється лише іноді, збережи також час спроби, щоб можна було знайти відповідний запис у програмі.\nЗ’ясуйте, що спричиняє проблему. Перевищення часу очікування може випливати як з помилки у вашій програмі, так і із затримки зовнішньої послуги. Попроси виконавця про пояснення, що спирається на перевірку. Коли причина лишається невідомою, найближчим завданням може бути саме її з’ясування. Це допомагає уникнути великої перебудови без знання, що треба виправити.\nВеди розмову з командою так, щоб люди швидко повідомляли про проблеми. Запитай, що сталося і яку інформацію вони мали під час роботи. Якщо причиною було незрозуміле правило чи різні версії домовленостей, виправте й спосіб їх передавання. Домовтеся про одну людину, яка пильнуватиме виправлення до його перевірки. Саме передання завдання програмістові не завершує цієї роботи.\nПісля зміни повтори спробу, яка раніше виявила помилку. Перевір також частини програми, на які могло вплинути виправлення. Зміна збереження дат у звіті може, наприклад, змінити порядок документів в історії. Такий вид перевірки допомагає вловити ситуацію, коли виправлення однієї функції ламає іншу. Обсяг спроб добирайте до зміни. Дрібне виправлення тексту й зміна правил доступу потребують різного обсягу перевірки.\nЗбережи попередній результат, познач нову версію й додай результат повторної спроби до пов’язаної роботи. Якщо оновлюєш затверджений proof виконаного Goal, відкрий його знову відповідно до роботи Vairo. Ціль «виправити створення звіту» завершується після показу правильної роботи. Коли ви не виявили несправності, цей підпункт не вимагає вигадувати додаткову роботу.","guide_sources":["Google SRE, Testing for Reliability описує перевірку пов’язаної системи й вибір тестів. Stripe, Webhooks пояснює верифікацію повідомлень і обробку повторів та порядку подій. OWASP, Input Validation Cheat Sheet допомагає дібрати спроби з некоректними даними. Запис результатів у Goals випливає з програми Vairo.","AWS, Load test your workload описує вибір навантаження, умов і вимірювань. Google SRE, Reliable Product Launches at Scale враховує обмеження використання під час підготовки послуги. Приклад вартості — допоміжний розрахунок для програми Vairo.","Google SRE, Postmortem Culture: Learning from Failure описує з’ясування причин і умови, що сприяють повідомленню про помилки. Google SRE, Testing for Reliability пояснює повторну перевірку роботи після змін. Обробка proof і повторного відкриття Goal випливає з правил Vairo."]},"es":{"title":"Comprueba el programa mientras se usa","guide_body":"3.1. Comprueba el resultado y la reacción ante problemas\nEmpieza la prueba desde la situación en la que estará un nuevo destinatario. Prepara una cuenta nueva u otra forma de entrada adecuada al producto. Haz la acción principal sin usar materiales que haya en la cuenta de quien lo creó. Comprueba también el resultado en sí. Un informe puede abrirse y aun así contener cálculos erróneos. Un programa que resume textos puede dar una respuesta que omite la información más importante.\nDespués comprueba el comportamiento ante un error o una interrupción. ¿Qué verá el usuario si sube un archivo equivocado? ¿Quedará claro que un servicio externo no respondió? Donde repetir una acción podría crear una segunda reserva o volver a cobrar, comprobad también la repetición de la misma petición. El efecto de la operación debe corresponder a la intención del usuario. Usad los resultados del control de acceso del subpunto 2.1 si siguen siendo válidos para la versión probada.\nAl conectar con servicios externos a veces recibes mensajes automáticos sobre eventos. Se llaman webhooks. Uno de esos mensajes puede ser el aviso de un acceso pagado. Quien lo construye debe comprobar su origen con el método que indica el proveedor y gestionar que llegue más de una vez. Comprobad también los retrasos y un orden distinto de los mensajes si la integración puede funcionar así. Con los pagos, usad el entorno de pruebas del proveedor para que las pruebas no cobren dinero.\nRepartid las comprobaciones según las habilidades. Quien conoce las necesidades del usuario puede valorar si el funcionamiento se entiende y si el informe es correcto. Alguien técnico comprobará las peticiones al servicio y su comportamiento ante errores. Si trabajas en solitario, usa las expectativas anotadas antes y la ayuda adecuada en lo que no sepas valorar. Conviene plantear con quien construye que las comprobaciones repetitivas de operaciones clave sean pruebas que se ejecuten automáticamente tras los cambios.\nEn un Goal del tipo «Resultado de prueba», guarda la versión probada y los resultados. Basta un registro que permita repetir la prueba, por ejemplo: «Se añadió un archivo sin fecha. Se esperaba un aviso de fecha ausente. El programa creó un informe vacío». Un resultado así puede cerrar un Goal que consistía en hacer una prueba. El problema detectado sigue necesitando arreglo antes de dar la función por lista. Las pruebas reunidas pueden quedar en un documento adjunto como proof.\n3.2. Comprueba la carga y el coste de uso\nVuelve al número de primeros usuarios y a la forma de uso que fijaste en Preparation. Reproduce el trabajo previsto en la versión preparada del programa. Si varias personas pueden crear informes a la vez, comprueba justo esa situación. Mide el tiempo de espera y mira si todas las tareas terminan bien. El número de cuentas por sí solo no muestra la carga. Lo que importa es qué hacen los usuarios a la vez y qué volumen de datos procesan.\nEmpieza con una prueba pequeña y aumenta la carga hasta el nivel necesario. Acuerda con quien lo construye una forma segura de hacerla en vuestro servicio. Con proveedores externos, ten en cuenta sus condiciones de prueba y sus límites. Indica con qué configuración se hizo la prueba. Un resultado en una máquina más potente puede no corresponder al funcionamiento en el plan más barato que piensas ofrecer.\nFíjate en el consumo de los servicios durante las acciones realizadas. El coste mensual se puede estimar como las tarifas fijas más el coste del uso previsto. Por ejemplo, con una tarifa fija de 12 € y 5 céntimos por informe, 50 informes costarían en total unos 14,50 €. Es solo un ejemplo de cálculo. Usa los precios de tus proveedores y ten en cuenta otras acciones de pago del programa. Un archivo más largo o repetir un procesamiento fallido puede cambiar el coste.\nSi el uso previsto supera el presupuesto, limita lo que genera gasto. Puede ser el número de informes o la duración de la grabación subida. Comprueba con quien lo construye que el límite funciona también ante una petición directa al servicio. Al llegar al límite, el usuario debe recibir un aviso comprensible. Si el proveedor elegido ya ofrece ese límite, comprueba cómo funciona y qué efecto tiene en el destinatario.\nAñade al proof las condiciones de la prueba y los resultados obtenidos. Anota también la estimación de coste para el primer grupo y los límites necesarios. Separa la medición de la previsión: «hicimos 20 informes» describe la prueba; «100 informes costarán unos…» describe un cálculo. Quien es responsable de este Goal debe acordar el resultado técnico con quien lo construye y el coste admisible con quien vigila el presupuesto.\n3.3. Corrige el problema y comprueba el cambio\nUsa este subpunto cuando encuentres un fallo durante el trabajo. Empieza por reproducirlo a partir de la prueba anotada. «El informe no funciona» deja mucho por adivinar a quien lo construye. Describir el archivo, la acción realizada y el resultado obtenido permite llegar antes a la causa. Si el error solo aparece a veces, guarda también la hora de la prueba para poder encontrar el registro correspondiente en el programa.\nAveriguad qué causa el problema. Que se agote el tiempo de espera puede deberse tanto a un error en vuestro programa como al retraso de un servicio externo. Pide a quien lo construye una explicación basada en una comprobación. Si la causa sigue sin conocerse, la próxima tarea puede ser precisamente averiguarla. Así se evita una gran reconstrucción sin saber qué hay que arreglar.\nHabla con el equipo de forma que la gente avise rápido de los problemas. Pregunta qué pasó y qué información tenían mientras trabajaban. Si la causa fue una norma poco clara o versiones distintas de lo acordado, mejorad también cómo se comunican. Acordad una persona que vigile la corrección hasta que se compruebe. Pasar la tarea a un programador no termina este trabajo.\nTras el cambio, repite la prueba que mostró el error. Comprueba también las partes del programa a las que pudo afectar la corrección. Cambiar cómo se guardan las fechas en el informe puede, por ejemplo, cambiar el orden de los documentos en el historial. Este tipo de comprobación ayuda a detectar cuándo arreglar una función estropea otra. Ajustad el alcance de las pruebas al cambio. Una pequeña corrección de texto y un cambio en las reglas de acceso requieren comprobaciones distintas.\nGuarda el resultado anterior, marca la nueva versión y adjunta el resultado de la nueva prueba al trabajo relacionado. Si actualizas el proof aprobado de un Goal terminado, vuelve a abrirlo según funciona Vairo. El objetivo «arreglar la creación del informe» termina al mostrar que funciona bien. Si no habéis detectado ningún fallo, este subpunto no exige inventarse trabajo adicional.","guide_sources":["Google SRE, Testing for Reliability describe cómo comprobar un sistema conectado y elegir las pruebas. Stripe, Webhooks explica la verificación de mensajes y la gestión de repeticiones y del orden de los eventos. OWASP, Input Validation Cheat Sheet ayuda a elegir pruebas con datos incorrectos. El registro de resultados en Goals sigue el programa de Vairo.","AWS, Load test your workload describe cómo elegir carga, condiciones y mediciones. Google SRE, Reliable Product Launches at Scale tiene en cuenta los límites de uso al preparar un servicio. El ejemplo de coste es un cálculo de apoyo para el programa de Vairo.","Google SRE, Postmortem Culture: Learning from Failure describe cómo aclarar causas y crear condiciones que favorezcan avisar de errores. Google SRE, Testing for Reliability explica la nueva comprobación tras los cambios. La gestión del proof y la reapertura de un Goal siguen las reglas de Vairo."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'saas' and p.key = 'saas-check';
update public.stage_subpoints s set translations = '{"de":{"title":"Prüfe das Ergebnis und die Reaktion auf Probleme"},"uk":{"title":"Перевір результат роботи й реакцію на проблеми"},"es":{"title":"Comprueba el resultado y la reacción ante problemas"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'saas' and p.key = 'saas-check' and s.key = 'behavior';
update public.stage_fields f set translations = '{"de":{"question":"Notiere Version, Testumfang, erwartete und erzielte Ergebnisse sowie gefundene Probleme.","config":{"label":"Ziele öffnen"}},"uk":{"question":"Запиши версію, обсяг спроб, очікувані й отримані результати та виявлені проблеми.","config":{"label":"Відкрити цілі"}},"es":{"question":"Anota la versión, el alcance de las pruebas, los resultados esperados y obtenidos y los problemas detectados.","config":{"label":"Abrir objetivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'saas' and p.key = 'saas-check'
    and s.key = 'behavior' and f.key = 'open';
update public.stage_subpoints s set translations = '{"de":{"title":"Prüfe Last und Nutzungskosten"},"uk":{"title":"Перевір навантаження й вартість користування"},"es":{"title":"Comprueba la carga y el coste de uso"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'saas' and p.key = 'saas-check' and s.key = 'load';
update public.stage_fields f set translations = '{"de":{"question":"Notiere die Nutzungsbedingungen, das Ergebnis des Lasttests und die Kostenschätzung.","config":{"label":"Ziele öffnen"}},"uk":{"question":"Запиши умови використання, результат спроби навантаження й оцінку вартості.","config":{"label":"Відкрити цілі"}},"es":{"question":"Anota las condiciones de uso, el resultado de la prueba de carga y la estimación de coste.","config":{"label":"Abrir objetivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'saas' and p.key = 'saas-check'
    and s.key = 'load' and f.key = 'open';
update public.stage_subpoints s set translations = '{"de":{"title":"Behebe das Problem und prüfe die Änderung","description":"Ohne Fehler gibt es keine Pflicht zur Korrektur."},"uk":{"title":"Виправ проблему й перевір зміну","description":"Без несправності немає обов’язку виправляти."},"es":{"title":"Corrige el problema y comprueba el cambio","description":"Si no hay fallo, no hay obligación de corregir."}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'saas' and p.key = 'saas-check' and s.key = 'fix';
update public.stage_fields f set translations = '{"de":{"question":"Wenn etwas die Nutzung blockiert, behebe es im Tracker und prüfe die Änderung.","config":{"label":"Ziele öffnen"}},"uk":{"question":"Якщо щось блокує використання, виправ це в трекері й перевір зміну.","config":{"label":"Відкрити цілі"}},"es":{"question":"Si algo bloquea el uso, corrígelo en el tracker y comprueba el cambio.","config":{"label":"Abrir objetivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'saas' and p.key = 'saas-check'
    and s.key = 'fix' and f.key = 'open';
update public.stage_points p set translations = '{"de":{"title":"Bereite das Programm auf Wartung und Updates vor","guide_body":"4.1. Setze eine Version auf, die sich teilen und verbessern lässt\nStarte die vorbereitete Version an dem Ort, von dem aus die ersten Zielpersonen sie nutzen können. Während der Vorbereitung kannst du den Zugang auf das Team beschränken. Prüfe die Haupttätigkeit genau dort, denn Einstellungen, die sich von denen auf dem Rechner der Entwickler unterscheiden, können das Verhalten des Programms ändern. Wenn du auf einer fertigen Plattform baust, nutze ihre Art der Veröffentlichung und prüfe die veröffentlichte Version.\nTrenne Testdaten von den Daten künftiger Zielpersonen. Trenne ebenso die Einstellungen von Test- und Live-Diensten, besonders bei Zahlungen. Die Verbindung zum Programm sollte verschlüsselt sein, meist über HTTPS. Bewahre private Schlüssel für Dienste in den dafür vorgesehenen Einstellungen des Anbieters oder an einem anderen gut geschützten Ort auf. Ein Schlüssel im Code, der an den Browser geschickt wird, kann von Nutzern ausgelesen werden. Notiere in Vairo, wo der Zugang verwaltet wird, ohne Geheimnisse zu kopieren.\nBewahre den Code und die Versionsangaben der nötigen Programmbestandteile auf. Ein Repository, z. B. bei GitHub, speichert den Code und den Verlauf seiner Änderungen. Der Code allein reicht aber womöglich nicht für einen Neustart, wenn passende Einstellungen oder Angaben zu genutzten Bibliotheken fehlen. Nutze bei einer fertigen Plattform ihren Versionsverlauf oder einen verfügbaren Export. Vereinbare mit der ausführenden Person, was eure Anwendung wiederherstellbar macht und welche Einschränkungen der gewählte Dienst hat.\nFührt ein Update der vorbereiteten Version durch und prüft danach die Hauptfunktion. Wenn mehrere Personen das Programm ändern, vereinbart, wer eine Version zusammenstellt und veröffentlicht. Die anderen sollten wissen, was in dieses Update eingeflossen ist und welche Tests wiederholt werden müssen. Ein aufbewahrter Änderungseintrag erleichtert auch die Rückkehr dazu, wenn später ein Fehler geklärt wird.\nPrüft, wie ihr von einem Fehler erfahrt und wo sich sein Eintrag findet. Ein solcher Eintrag, Log genannt, sollte helfen, die Handlung und den Zeitpunkt des Problems zu erkennen. Löst einen sicheren Testfehler aus und sucht ihn. Sorgt auch dafür, dass sich feststellen lässt, ob Nutzer die Haupttätigkeit abgeschlossen haben, z. B. einen Bericht erstellt. Diese Information wird in der MVP Stage gebraucht. Beschränkt die gespeicherten Informationen auf das Nötige; Passwörter und private Materialien der Nutzer gehören weder in Logs noch in Nachweise.\nNutze als Proof die Adresse und die Versionsbezeichnung, den Eintrag eines erfolgreichen Updates und vorhandene Materialien, die zu seiner Wiederherstellung nötig sind. Füge das Ergebnis der Fehlerprüfung und der Haupttätigkeit bei. Wer die Arbeit abnimmt, sollte wissen, wo das Programm läuft und wo man nach Informationen sucht, wenn es nicht mehr richtig funktioniert.\n4.2. Prüfe die Wiederherstellung von Betrieb und nötigen Daten\nÜbt die Situation, in der ein Update die Hauptfunktion des Programms verhindert. Wähle mit der ausführenden Person einen Weg, den Dienst wiederherzustellen. Das kann die Rückkehr zur vorigen Version sein oder das Einspielen einer vorbereiteten Korrektur. Wählt die Testbedingungen so, dass keine Daten der Zielpersonen beschädigt werden. Ihr könnt eine getrennte Testversion oder eine Probeanwendung beim gewählten Anbieter nutzen.\nFrag, ob das Update auch die Art der Datenspeicherung ändert. Eine ältere Programmversion versteht die neue Form vielleicht nicht. Deshalb stellt die Rückkehr zu früherem Code nicht immer den ganzen Dienst wieder her. Die technische Person sollte das im Verfahren berücksichtigen und es mit den Daten prüfen. Bewahre im Proof die Information auf, für welches Update und welche Konfiguration der Test gemacht wurde.\nWenn das Programm Materialien der Nutzer speichert, die für die weitere Arbeit nötig sind, prüft ihre Wiederherstellung aus einer Sicherung. Stellt Probedaten an einem getrennten Ort wieder her und öffnet sie im Programm. Seht nach, ob sich damit die nötige Handlung ausführen lässt. Eine Meldung des Anbieters über eine erfolgreiche Sicherung zeigt noch nicht, ob das Team daraus nutzbare Daten wiederherstellen kann. Wenn die Anwendung Informationen nur kurzzeitig verarbeitet, konzentriert euch auf die Wiederherstellung des Betriebs und der nötigen Einstellungen.\nNotiert, aus welchem Zeitpunkt die wiederhergestellten Daten stammen und wie lange der Test dauerte. Eine Sicherung vom Vorabend enthält zum Beispiel vielleicht nicht die heutige Arbeit. Klärt, ob dieser Wiederherstellungsumfang für die erste Nutzung des Produkts reicht. Wenn nicht, ändert die Art der Sicherung oder Wiederherstellung. Prüft bei einer fertigen Plattform die in eurem Paket verfügbaren Möglichkeiten und übt das passende Verfahren.\nBewahre eine kurze Beschreibung der ausgeführten Schritte und das Ergebnis auf. Du kannst die Anleitung des Anbieters anhängen und nur die für eure Anwendung nötigen Einstellungen ergänzen. Prüft im Team, ob die Person, die bei einem Ausfall reagieren soll, den nötigen Zugang hat und diese Anleitung versteht. Ein Test-Goal kann mit einem negativen Ergebnis enden, aber bevor ihr die Bereitschaft der Version bestätigt, braucht ihr einen erfolgreichen Wiederherstellungstest.","guide_sources":["The Twelve-Factor App, Codebase, Dependencies und Config beschreiben Versionierung, Abhängigkeiten und die Trennung der Konfiguration. OWASP, Logging Cheat Sheet erklärt das Protokollieren von Ereignissen und den Schutz von Informationen in Logs. Microsoft, Safe deployment practices beschreibt die Prüfung eingeführter Änderungen. Die Variante für eine fertige Plattform ist an die Bauweise des Produkts angepasst.","Microsoft, Safe deployment practices beschreibt die Wiederherstellung nach einem Update, auch bei Datenänderungen. AWS, Perform periodic recovery of the data to verify backup integrity and processes erklärt die Prüfung wiederhergestellter Daten, der Wiederherstellungszeit und des Zeitpunkts, zu dem man zurückkehren kann."]},"uk":{"title":"Підготуй програму до підтримки й оновлень","guide_body":"4.1. Запусти версію, яку можна надати й виправляти\nЗапусти підготовлену версію в місці, звідки зможуть користуватися перші адресати. Під час підготовки доступ можна обмежити командою. Перевір головну дію саме там, бо налаштування, що відрізняються від налаштувань на комп’ютері розробника, можуть змінити роботу програми. Якщо створюєш на готовій платформі, скористайся її способом публікації й перевір опубліковану версію.\nВідокрем дані для спроб від даних майбутніх адресатів. Так само розділи налаштування тестових і робочих послуг, особливо платежів. З’єднання з програмою має бути шифрованим, зазвичай через HTTPS. Приватні ключі до послуг зберігай у призначених для цього налаштуваннях постачальника або в іншому належно захищеному місці. Ключ, розміщений у коді, що надсилається до браузера, може прочитати користувач. До Vairo додай інформацію, де керують доступом, без копіювання секретів.\nЗбережи код та інформацію про версії потрібних складників програми. Репозиторій, напр. на GitHub, зберігає код та історію його змін. Однак самого коду може не вистачити для повторного запуску, якщо бракуватиме правильних налаштувань чи інформації про використані бібліотеки. На готовій платформі скористайся її історією версій або доступним експортом. З виконавцем домовся, що дасть змогу відтворити ваш застосунок і які обмеження має обрана послуга.\nПроведіть оновлення підготовленої версії, а потім перевірте головну дію. Якщо програму змінюють кілька людей, домовтеся, хто збирає й публікує версію. Решта має знати, що увійшло до цього оновлення і які спроби треба повторити. Збережений запис зміни полегшить також повернення до неї при з’ясуванні пізнішої несправності.\nПеревірте, як ви дізнаєтеся про помилку і де можна знайти її запис. Такий запис, званий логом, має допомагати розпізнати дію й момент проблеми. Спричиніть безпечну тестову помилку й знайдіть її. Забезпечте також можливість встановити, що користувач завершив головну дію, напр. створив звіт. Ця інформація знадобиться в MVP Stage. Обмежте записувану інформацію потрібною; паролі й приватні матеріали користувачів не мають потрапляти ні до логів, ні до доказів.\nЯк proof використай адресу й позначення версії, запис успішного оновлення та наявні матеріали, потрібні для його відтворення. Додай результат перевірки помилки й головної дії. Людина, яка приймає роботу, має знати, де працює програма і де шукати інформацію, коли вона перестане працювати правильно.\n4.2. Перевір відновлення роботи й потрібних даних\nВідпрацюйте ситуацію, коли оновлення унеможливлює головну дію програми. З виконавцем обери спосіб відновлення послуги. Це може бути повернення до попередньої версії або впровадження підготовленого виправлення. Доберіть умови спроби так, щоб не пошкодити даних адресатів. Можна використати окрему тестову версію або пробний застосунок в обраного постачальника.\nЗапитай, чи оновлення змінює також спосіб збереження даних. Старіша версія програми може не розуміти їхньої нової форми. Тому повернення до попереднього коду не завжди відновлює роботу всієї послуги. Технічна людина має врахувати це в процедурі й перевірити її разом із даними. У proof збережи інформацію, для якого оновлення й конфігурації виконано спробу.\nЯкщо програма зберігає матеріали користувача, потрібні для подальшої роботи, перевірте їх відновлення з копії. Відновіть пробні дані в окремому місці й відкрийте їх у програмі. Подивіться, чи можна виконати з ними потрібну дію. Повідомлення постачальника про успішну копію ще не показує, чи команда вміє відновити з неї корисні дані. Коли застосунок обробляє інформацію лише тимчасово, зосередьтеся на відновленні роботи й потрібних налаштувань.\nЗапишіть, з якого моменту походять відновлені дані і скільки тривала спроба. Наприклад, копія, зроблена попереднього вечора, може не містити сьогоднішньої роботи. З’ясуйте, чи такого обсягу відновлення досить для першого використання продукту. Якщо ні, змініть спосіб створення копій чи відновлення. Користуючись готовою платформою, перевірте можливості, доступні у вашому пакеті, і відпрацюйте відповідну процедуру.\nЗбережи короткий опис виконаних кроків і результат. Можна прикріпити інструкцію постачальника й дописати лише налаштування, потрібні для вашого застосунку. У команді перевірте, чи людина, яка має реагувати на аварію, має потрібний доступ і розуміє цю інструкцію. Тестовий Goal може завершитися негативним результатом, але перед підтвердженням готовності версії вам потрібна успішна спроба відновлення.","guide_sources":["The Twelve-Factor App, Codebase, Dependencies і Config описують версіонування, залежності й відокремлення конфігурації. OWASP, Logging Cheat Sheet пояснює запис подій і захист інформації в логах. Microsoft, Safe deployment practices описує перевірку впроваджуваних змін. Варіант для готової платформи адаптовано до способу створення продукту.","Microsoft, Safe deployment practices описує відновлення роботи після оновлення, також при змінах даних. AWS, Perform periodic recovery of the data to verify backup integrity and processes пояснює перевірку відновлених даних, часу відновлення й моменту, до якого можна повернутися."]},"es":{"title":"Prepara el programa para el mantenimiento y las actualizaciones","guide_body":"4.1. Pon en marcha una versión que se pueda compartir y mejorar\nPon en marcha la versión preparada en el lugar desde el que podrán usarla los primeros destinatarios. Durante la preparación puedes limitar el acceso al equipo. Comprueba la acción principal justo ahí, porque una configuración distinta de la del ordenador de quien lo desarrolló puede cambiar el funcionamiento. Si construyes sobre una plataforma ya hecha, usa su forma de publicar y comprueba la versión publicada.\nSepara los datos de prueba de los de los futuros destinatarios. Separa también la configuración de los servicios de prueba y de los reales, sobre todo los pagos. La conexión con el programa debe ir cifrada, normalmente con HTTPS. Guarda las claves privadas de los servicios en la configuración del proveedor pensada para ello o en otro lugar bien protegido. Una clave incluida en el código que se envía al navegador puede leerla el usuario. Añade en Vairo dónde se gestiona el acceso, sin copiar los secretos.\nGuarda el código y la información sobre las versiones de los componentes necesarios. Un repositorio, p. ej. en GitHub, guarda el código y el historial de cambios. Pero el código solo puede no bastar para volver a ponerlo en marcha si faltan la configuración correcta o los datos de las bibliotecas usadas. En una plataforma ya hecha, usa su historial de versiones o la exportación disponible. Acuerda con quien lo construye qué permitirá reconstruir vuestra aplicación y qué limitaciones tiene el servicio elegido.\nHaced una actualización de la versión preparada y después comprobad la acción principal. Si varias personas cambian el programa, acordad quién monta y publica cada versión. Los demás deben saber qué entra en esa actualización y qué pruebas hay que repetir. Guardar el registro del cambio también facilitará volver a él al aclarar un fallo posterior.\nComprobad cómo os enteraréis de un error y dónde encontrar su registro. Ese registro, llamado log, debe ayudar a identificar la acción y el momento del problema. Provocad un error de prueba seguro y buscadlo. Aseguraos también de poder saber si un usuario completó la acción principal, p. ej. creó un informe. Esa información servirá en la MVP Stage. Limitad la información registrada a lo necesario; las contraseñas y los materiales privados de los usuarios no deben ir a los logs ni a las pruebas.\nUsa como proof la dirección y la versión, el registro de una actualización correcta y los materiales existentes necesarios para reconstruirla. Añade el resultado de comprobar el error y la acción principal. Quien recibe el trabajo debe saber dónde funciona el programa y dónde buscar información cuando deje de funcionar bien.\n4.2. Comprueba la recuperación del servicio y de los datos necesarios\nEnsayad la situación en la que una actualización impide la acción principal del programa. Elige con quien lo construye la forma de restaurar el servicio. Puede ser volver a la versión anterior o aplicar una corrección preparada. Elegid las condiciones de la prueba para no dañar datos de los destinatarios. Podéis usar una versión de prueba aparte o una aplicación de prueba en el proveedor elegido.\nPregunta si la actualización cambia también la forma de guardar los datos. Una versión anterior del programa puede no entender su nueva forma. Por eso, volver al código anterior no siempre restaura todo el servicio. La persona técnica debe tenerlo en cuenta en el procedimiento y comprobarlo con los datos. Guarda en el proof para qué actualización y configuración se hizo la prueba.\nSi el programa guarda materiales del usuario necesarios para seguir trabajando, comprobad que se pueden restaurar desde una copia. Restaurad datos de prueba en un lugar aparte y abridlos en el programa. Mirad si se puede hacer con ellos la acción necesaria. Que el proveedor diga que la copia se hizo bien no demuestra que el equipo sepa recuperar de ella datos útiles. Si la aplicación solo trata la información de forma temporal, centraos en recuperar el funcionamiento y la configuración necesaria.\nAnotad de qué momento son los datos recuperados y cuánto duró la prueba. Por ejemplo, una copia de la noche anterior puede no incluir el trabajo de hoy. Decidid si ese alcance de recuperación basta para el primer uso del producto. Si no, cambiad la forma de hacer las copias o de recuperar. Con una plataforma ya hecha, comprobad las opciones de vuestro plan y ensayad el procedimiento correspondiente.\nGuarda una breve descripción de los pasos y el resultado. Puedes adjuntar las instrucciones del proveedor y añadir solo la configuración necesaria para vuestra aplicación. Comprobad en el equipo que quien debe reaccionar ante una caída tiene el acceso necesario y entiende esas instrucciones. Un Goal de prueba puede terminar con un resultado negativo, pero antes de confirmar que la versión está lista necesitáis una recuperación que funcione.","guide_sources":["The Twelve-Factor App, Codebase, Dependencies y Config describen el control de versiones, las dependencias y la separación de la configuración. OWASP, Logging Cheat Sheet explica el registro de eventos y la protección de la información en los logs. Microsoft, Safe deployment practices describe la comprobación de los cambios. La variante para plataformas ya hechas se ha adaptado a la forma de construir el producto.","Microsoft, Safe deployment practices describe cómo recuperar el servicio tras una actualización, también con cambios en los datos. AWS, Perform periodic recovery of the data to verify backup integrity and processes explica cómo comprobar los datos restaurados, el tiempo de recuperación y el momento al que se puede volver."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'saas' and p.key = 'saas-keep';
update public.stage_subpoints s set translations = '{"de":{"title":"Setze eine Version auf, die sich teilen und verbessern lässt"},"uk":{"title":"Запусти версію, яку можна надати й виправляти"},"es":{"title":"Pon en marcha una versión que se pueda compartir y mejorar"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'saas' and p.key = 'saas-keep' and s.key = 'release';
update public.stage_fields f set translations = '{"de":{"question":"Gib Adresse und Version, Materialien zur Wiederherstellung und ein erfolgreiches Update an.","config":{"label":"Ziele öffnen"}},"uk":{"question":"Вкажи адресу й версію, матеріали для відтворення та успішне оновлення.","config":{"label":"Відкрити цілі"}},"es":{"question":"Indica la dirección y la versión, los materiales para reconstruirla y una actualización correcta.","config":{"label":"Abrir objetivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'saas' and p.key = 'saas-keep'
    and s.key = 'release' and f.key = 'open';
update public.stage_subpoints s set translations = '{"de":{"title":"Prüfe die Wiederherstellung von Betrieb und nötigen Daten"},"uk":{"title":"Перевір відновлення роботи й потрібних даних"},"es":{"title":"Comprueba la recuperación del servicio y de los datos necesarios"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'saas' and p.key = 'saas-keep' and s.key = 'recover';
update public.stage_fields f set translations = '{"de":{"question":"Notiere die Art der Wiederherstellung und das Ergebnis des durchgeführten Tests.","config":{"label":"Ziele öffnen"}},"uk":{"question":"Запиши спосіб відновлення й результат проведеної спроби.","config":{"label":"Відкрити цілі"}},"es":{"question":"Anota la forma de recuperación y el resultado de la prueba realizada.","config":{"label":"Abrir objetivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'saas' and p.key = 'saas-keep'
    and s.key = 'recover' and f.key = 'open';
update public.stage_points p set translations = '{"de":{"title":"Bestätige die Bereitschaft der ersten Version","guide_body":"5.1. Bestätige die Bereitschaft der angegebenen Version\nNenne die konkrete Version, die ihr für die erste Nutzung vorbereitet habt. Hänge die Nachweise aus den vorigen Unterpunkten an und prüfe, ob sie noch für diese Version gelten. Wenn nach einem Test die Speicherung des Berichts geändert wurde, muss das frühere Ergebnis vielleicht ergänzt werden. Bitte die für die Änderung verantwortliche Person anzugeben, was erneut geprüft werden muss. Materialien, die gültig bleiben, können wiederverwendet werden.\nGeht die übrigen Probleme im Hinblick auf die geplante Nutzung durch. Eine fehlende zusätzliche Diagrammfarbe kann warten. Ein falsches Berichtsergebnis oder die Möglichkeit, fremde Daten zu lesen, verhindern, dass die betreffende Funktion als fertig gilt. Frag nach der Folge für die Zielperson und nach einem Nachweis korrekten Funktionierens. Die bloße Information, dass die ausführende Person mit dem Programmieren fertig ist, beantwortet diese Fragen nicht.\nBerücksichtigt die Bedingungen, unter denen die Tests gemacht wurden. Wenn ihr die Nutzung durch eine kleine Gruppe geprüft habt, gilt die Bestätigung genau für einen solchen Start. Die vorbereiteten Begrenzungen sollten helfen, diese Bedingungen einzuhalten. Das Team sollte auch wissen, wie es ein Problem bemerkt und wie es den Betrieb wiederherstellt. Nutzt die Ergebnisse der Unterpunkte 3.2, 4.1 und 4.2.\nDie Person, die die Nachweise sammelt, stützt sich auf die Einschätzungen der für die einzelnen Teile verantwortlichen Personen. Bei Fragen, die Fachwissen erfordern, stütze die Entscheidung auf eine passende Prüfung. Wenn ein Hindernis bleibt, nenne es bei der zugehörigen Arbeit und lass die Bereitschaftsbestätigung leer. Eine konkrete Information, z. B. „nach der Änderung des Dateizugriffs wurde kein erneuter Test gemacht“, erlaubt es, sofort die nächste Handlung festzulegen.\nWenn die angegebene Version die Bedingungen für die erste Nutzung erfüllt, wähle „Version bereit für die erste Nutzung“. Dieser Eintrag bestätigt das Ergebnis der SaaS-Kategorie. Die ganze Execution wird über den General-Teil abgeschlossen, nachdem die nötigen Kategorien erledigt sind. Die Bereitstellung des Produkts für Zielpersonen und das Sammeln der Nutzungsergebnisse führst du in der MVP Stage weiter, mit demselben Tracker und den gesammelten Materialien.","guide_sources":["Google SRE, Reliable Product Launches at Scale beschreibt, wie man die Bereitschaftsprüfung an den jeweiligen Dienst anpasst und sich auf das konzentriert, was den Start beeinflusst. Bestätigungsbedingungen, Wiederverwendung von Nachweisen und der Übergang zwischen Etappen folgen dem Programm und den CTO-Guidelines von Vairo."]},"uk":{"title":"Підтверди готовність першої версії","guide_body":"5.1. Підтверди готовність зазначеної версії\nВкажи конкретну версію, яку ви підготували до першого використання. Прикріпи докази з попередніх підпунктів і перевір, чи вони й далі її стосуються. Якщо після спроби змінили спосіб збереження звіту, попередній результат може потребувати доповнення. Попроси людину, відповідальну за зміну, вказати, що треба перевірити знову. Матеріали, що зберігають чинність, можна використати повторно.\nПерегляньте решту проблем з огляду на заплановане використання. Відсутність додаткового кольору діаграми може зачекати. Хибний результат звіту чи можливість прочитати чужі дані унеможливлюють визнання відповідної функції готовою. Питай про наслідки для адресата й про доказ правильної роботи. Сама інформація, що виконавець закінчив кодування, не вирішує цих питань.\nВрахуйте умови, для яких проводили спроби. Якщо ви перевірили використання малою групою, підтвердження стосується саме такого початку. Підготовлені обмеження мають допомагати втримати ці умови. Команда також має знати, як помітить проблему і як відновить роботу. Використайте результати підпунктів 3.2, 4.1 і 4.2.\nЛюдина, яка збирає докази, користується оцінками виконавців, відповідальних за окремі частини. У питаннях, що вимагають спеціальних знань, спирай рішення на відповідну перевірку. Якщо перешкода лишається, вкажи її біля пов’язаної роботи й залиш підтвердження готовності порожнім. Конкретна інформація, напр. «після зміни доступу до файлів повторної спроби не проведено», дає змогу одразу визначити наступну дію.\nКоли зазначена версія відповідає умовам першого використання, обери «Версія готова до першого використання». Цей запис підтверджує результат категорії SaaS. Закриття всього Execution відбувається через частину General після завершення потрібних категорій. Надання продукту адресатам і збирання результатів користування ти поведеш далі в MVP Stage, використовуючи той самий трекер і зібрані матеріали.","guide_sources":["Google SRE, Reliable Product Launches at Scale описує пристосування оцінки готовності до конкретної послуги й зосередження на питаннях, що впливають на її запуск. Умови підтвердження, повторне використання доказів і перехід між етапами випливають із програми та guidelines CTO Vairo."]},"es":{"title":"Confirma que la primera versión está lista","guide_body":"5.1. Confirma que la versión indicada está lista\nIndica la versión concreta que habéis preparado para el primer uso. Adjunta las pruebas de los subpuntos anteriores y comprueba si siguen siendo válidas para ella. Si después de una prueba se cambió cómo se guarda el informe, el resultado anterior puede necesitar completarse. Pide a quien hizo el cambio que indique qué hay que volver a comprobar. Los materiales que sigan siendo válidos se pueden reutilizar.\nRevisad los problemas pendientes pensando en el uso previsto. Que falte un color adicional en un gráfico puede esperar. Un resultado erróneo en el informe o la posibilidad de leer datos ajenos impiden dar por lista la función correspondiente. Pregunta por el efecto en el destinatario y por una prueba de que funciona bien. Que quien lo construye diga que ha terminado de programar no responde a estas preguntas.\nTened en cuenta las condiciones en que se hicieron las pruebas. Si comprobasteis el uso por un grupo pequeño, la confirmación vale justo para ese inicio. Los límites preparados deben ayudar a mantener esas condiciones. El equipo también debe saber cómo detectará un problema y cómo recuperará el servicio. Usad los resultados de los subpuntos 3.2, 4.1 y 4.2.\nQuien reúne las pruebas se apoya en la valoración de los responsables de cada parte. En asuntos que exigen conocimientos especializados, basa la decisión en una comprobación adecuada. Si queda un obstáculo, indícalo en el trabajo relacionado y deja vacía la confirmación. Una información concreta, como «no se repitió la prueba tras cambiar el acceso a los archivos», permite fijar de inmediato la siguiente acción.\nCuando la versión indicada cumpla las condiciones del primer uso, elige «Versión lista para el primer uso». Esta marca confirma el resultado de la categoría SaaS. El cierre de toda la Execution se hace en la parte General una vez terminadas las categorías necesarias. Poner el producto a disposición de los destinatarios y reunir los resultados de su uso lo seguirás haciendo en la MVP Stage, con el mismo tracker y los materiales reunidos.","guide_sources":["Google SRE, Reliable Product Launches at Scale describe cómo ajustar la evaluación de disponibilidad a cada servicio y centrarse en lo que afecta a su lanzamiento. Las condiciones de confirmación, la reutilización de pruebas y el paso entre etapas vienen del programa y de las guidelines del CTO de Vairo."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'saas' and p.key = 'saas-ready';
update public.stage_subpoints s set translations = '{"de":{"title":"Bestätige die Bereitschaft der angegebenen Version"},"uk":{"title":"Підтверди готовність зазначеної версії"},"es":{"title":"Confirma que la versión indicada está lista"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'saas' and p.key = 'saas-ready' and s.key = 'confirm';
update public.stage_fields f set translations = '{"de":{"question":"Welche Version bestätigst du?","help":"Trag die Bezeichnung der Version ein, auf die sich die früheren Nachweise beziehen."},"uk":{"question":"Яку версію ти підтверджуєш?","help":"Впиши позначення версії, якої стосуються попередні докази."},"es":{"question":"¿Qué versión confirmas?","help":"Escribe la versión a la que se refieren las pruebas anteriores."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'saas' and p.key = 'saas-ready'
    and s.key = 'confirm' and f.key = 'version';
update public.stage_fields f set translations = '{"de":{"question":"Ist diese Version bereit für die erste Nutzung?","help":"Lass es leer, solange die früheren Ergebnisse nicht fertig sind. Eine zweite Option gibt es nicht.","config":{"options":[{"value":"ready","label":"Version bereit für die erste Nutzung"}]}},"uk":{"question":"Чи ця версія готова до першого використання?","help":"Залиш порожнім, доки попередні результати не готові. Другого варіанта немає.","config":{"options":[{"value":"ready","label":"Версія готова до першого використання"}]}},"es":{"question":"¿Está lista esta versión para el primer uso?","help":"Déjalo vacío mientras los resultados anteriores no estén listos. No hay segunda opción.","config":{"options":[{"value":"ready","label":"Versión lista para el primer uso"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'saas' and p.key = 'saas-ready'
    and s.key = 'confirm' and f.key = 'ready';
update public.stage_categories c set translations = '{"de":{"title":"Hardware","intro":"Von Anforderungen und Sicherheit über das Exemplar bis zur Bereitschaft für die erste Nutzung."},"uk":{"title":"Hardware","intro":"Від вимог і безпеки через екземпляр до готовності до першого використання."},"es":{"title":"Hardware","intro":"De los requisitos y la seguridad, pasando por la unidad, hasta estar listo para el primer uso."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'execution' and t.version = 1 and c.key = 'hardware';
update public.stage_points p set translations = '{"de":{"title":"Lege die Anforderungen der ersten Version fest","guide_body":"1.1. Lege fest, was du vor der ersten Nutzung prüfst\nÖffne die Produktbeschreibung aus der vorigen Etappe. Stell dir die erste Nutzung vor: Wer nimmt es in die Hand, was will die Person tun und unter welchen Bedingungen wird sie arbeiten. Aus dieser Beschreibung sollte sich ergeben, was die Konstruktion ermöglichen muss. Eine Halterung für ruhiges Arbeiten am Schreibtisch braucht vielleicht andere Lösungen als eine Halterung an einem fahrenden Fahrzeug. Verknüpfe die vorhandene Beschreibung und ergänze fehlende Informationen an derselben Stelle.\nNotiere jede wichtige Anforderung so, dass sich entscheiden lässt, ob sie erfüllt ist. „Die Halterung ist stabil“ lässt zu viel Raum für Vermutungen. „Die Halterung hält 5 kg 30 Minuten lang ohne zu rutschen“ nennt ein prüfbares Ergebnis. Das ist ein Beispiel für die Schreibweise. Passende Last, Dauer und Testbedingungen müssen sich aus dem Zweck deines Produkts und seinen Sicherheitsanforderungen ergeben.\nErgänze bei jeder Anforderung, wie du sie prüfst. Manchmal reicht das Messen eines Maßes, manchmal braucht es einen Funktionstest oder eine Prüfung durch eine Fachperson. Wer die Konstruktion vorbereitet und wer die Prüfung durchführt, sollte das erwartete Ergebnis gleich verstehen. Wenn ihr Unterschiede jetzt klärt, vermeidet ihr ein Teil, das später neu bestellt werden muss.\nBerücksichtige Tests schon bei der Planung der ersten Exemplare. Wenn eine Prüfung ein Teil beschädigen kann, klär vorher, ob du ein eigenes Muster brauchst. Wenn mehrere Personen dasselbe Exemplar nutzen, vereinbart die Reihenfolge. So umfasst die erste Bestellung, was du für die Antworten brauchst, und die Vorbereitung eines Tests hält die übrigen Arbeiten nicht auf.\n1.2. Prüfe, was nötig ist, damit das Produkt sicher ist und Vorschriften erfüllt\nKläre, welche Anforderungen für genau dein Produkt und das Land gelten, in dem du es anbieten willst. Auch der Zweck zählt. Ein ähnlich aussehender Gegenstand kann anderen Anforderungen unterliegen, wenn er zum Spielen, für die Arbeit oder medizinisch genutzt wird. Beginne mit offiziellen Informationen für die betreffende Produktgruppe. In der Europäischen Union kann das Portal Your Europe ein Ausgangspunkt sein.\nDie CE-Kennzeichnung betrifft nur bestimmte Produktgruppen. Wenn sie verlangt ist, muss die passende Konformitätsbewertung durchlaufen werden, also das Prüfen und Dokumentieren, dass die einschlägigen Anforderungen erfüllt sind. Der Kauf eines Teils mit CE bestätigt nicht automatisch die Konformität des ganzen Produkts, das du daraus baust. Dass keine CE-Pflicht besteht, bedeutet auch nicht, dass das Produkt keinen Sicherheitsanforderungen unterliegt.\nWenn du Hilfe brauchst, gib einer Fachperson die Beschreibung der Nutzung und die vorhandenen Konstruktionsunterlagen. Bitte sie anzugeben, was im Entwurf berücksichtigt werden muss und welche Prüfungen vor der geplanten Nutzung nötig sind. Eine so konkrete Frage liefert eine nützlichere Antwort als die allgemeine Bitte, „das Produkt zu prüfen“.\nLegt im Team fest, wer diese Antwort einholt und dafür sorgt, dass nötige Änderungen umgesetzt werden. Diese Person kann die Arbeit koordinieren und auf das Wissen einer passenden Fachperson zurückgreifen. Wenn du allein arbeitest, kannst du eine solche Beratung extern beauftragen. Weise die Bewertung einer Frage einer Person zu, die sie beurteilen kann; ein freier Termin allein reicht nicht.\nErgänze das Dokument aus Unterpunkt 1.1 um die Erkenntnisse und ihre Quelle. Beschreibe eine ungeklärte Frage konkret, z. B. „Es muss bestätigt werden, ob das gewählte Material für diese Nutzung geeignet ist.“ Wenn die Antwort eine Änderung der Konstruktion erzwingen kann, kläre sie vor einer teuren Bestellung. Der Abschluss dieses Unterpunkts bedeutet, dass die Anforderungen erkannt sind; ihre Erfüllung wird in der weiteren Arbeit bestätigt.","guide_sources":["NASA, Technical Requirements Definition beschreibt die Übersetzung der Nutzungsweise in prüfbare Anforderungen. NASA, Product Verification erklärt die Wahl der Methoden und Mittel zu ihrer Prüfung.","Your Europe, CE marking erklärt den Umfang der Kennzeichnung und die Verantwortung für das ganze Produkt. NASA, Technical Planning beschreibt die Abstimmung von Kompetenzen und Verantwortung auf technische Arbeit."]},"uk":{"title":"Визнач вимоги першої версії","guide_body":"1.1. Визнач, що перевіриш перед першим використанням\nВідкрий опис продукту з попереднього етапу. Уяви його перше використання: хто бере його до рук, що хоче зробити і в яких умовах працюватиме. З цього опису має випливати, що конструкція мусить уможливлювати. Тримач для спокійної роботи за столом може вимагати інших рішень, ніж тримач на транспорті, що рухається. Прикріпи наявний опис і доповни відсутню інформацію в тому самому місці.\nКожну важливу вимогу запиши так, щоб можна було вирішити, чи її виконано. «Тримач міцний» залишає забагато місця для здогадок. «Тримач утримує 5 кг протягом 30 хвилин без зсування» вказує результат, який можна перевірити. Це приклад способу запису. Відповідне навантаження, час і умови спроби мають випливати з призначення твого продукту та вимог його безпеки.\nБіля вимоги допиши, як її перевіриш. Іноді досить виміряти розмір, а іноді знадобиться спроба роботи чи дослідження, виконане фахівцем. Людина, що готує конструкцію, і людина, що виконує перевірку, мають однаково розуміти очікуваний результат. Пояснення розбіжностей зараз допоможе уникнути виготовлення деталі, яку пізніше доведеться замовляти знову.\nВрахуй спроби вже під час планування перших екземплярів. Якщо дослідження може пошкодити деталь, заздалегідь визнач, чи потрібен окремий зразок. Якщо кілька людей користуватимуться тим самим екземпляром, домовтеся про черговість. Так перше замовлення охопить те, що потрібно для отримання відповідей, а підготовка однієї спроби не зупинить решти робіт.\n1.2. Перевір, що потрібно, щоб продукт був безпечним і відповідав правилам\nВизнач, які вимоги стосуються саме твого продукту й країни, де ти збираєшся його надавати. Важить також призначення. Схожий на вигляд предмет може підлягати іншим вимогам, коли служить для гри, роботи чи медичного застосування. Почни з офіційної інформації для відповідної групи продуктів. У Європейському Союзі відправною точкою може бути портал Your Europe.\nМаркування CE стосується лише певних груп продуктів. Коли воно потрібне, треба пройти відповідну оцінку відповідності, тобто перевірку й документування виконання відповідних вимог. Купівля деталі з CE не підтверджує автоматично відповідності всього продукту, який ти з неї збудуєш. Відсутність обов’язку маркування CE теж не означає, що продукт не підлягає вимогам безпеки.\nЯкщо потрібна допомога, передай фахівцеві опис застосування й наявні конструкторські матеріали. Попроси вказати, що треба врахувати в проєкті і які перевірки знадобляться перед запланованим використанням. Таке конкретне запитання дає кориснішу відповідь, ніж загальне прохання «перевірити продукт».\nУ команді визначте, хто збере цю відповідь і подбає про впровадження потрібних змін. Ця людина може координувати роботу, спираючись на знання відповідного фахівця. Якщо працюєш сам, можеш замовити таку консультацію ззовні. Доручай оцінку питання людині, яка вміє його оцінити; самого вільного часу недостатньо.\nДоповни документ із підпункту 1.1 висновками та їхнім джерелом. Нез’ясоване питання опиши конкретно, напр. «Треба підтвердити, чи обраний матеріал придатний для такого застосування». Якщо відповідь може змусити змінити конструкцію, з’ясуй її перед дорогим замовленням. Завершення цього підпункту означає розпізнання вимог; підтвердження їх виконання відбувається під час подальшої роботи.","guide_sources":["NASA, Technical Requirements Definition описує перетворення способу використання на перевірювані вимоги. NASA, Product Verification пояснює вибір методів і ресурсів, потрібних для їх перевірки.","Your Europe, CE marking пояснює обсяг маркування й відповідальність за весь продукт. NASA, Technical Planning описує узгодження компетенцій і відповідальності з технічною роботою."]},"es":{"title":"Define los requisitos de la primera versión","guide_body":"1.1. Define qué comprobarás antes del primer uso\nAbre la descripción del producto de la etapa anterior. Imagina su primer uso: quién lo coge, qué quiere hacer y en qué condiciones va a trabajar. De esa descripción debe salir qué tiene que permitir la construcción. Un soporte para trabajar tranquilo en un escritorio puede necesitar soluciones distintas que uno usado en un vehículo en marcha. Vincula la descripción existente y completa ahí mismo lo que falte.\nEscribe cada requisito importante de forma que se pueda decidir si se cumple. «El soporte es resistente» deja demasiado margen a la interpretación. «El soporte aguanta 5 kg durante 30 minutos sin deslizarse» señala un resultado comprobable. Es un ejemplo de cómo escribirlo. La carga, el tiempo y las condiciones de prueba adecuados deben salir del uso de tu producto y de sus requisitos de seguridad.\nEn cada requisito añade cómo lo comprobarás. A veces basta medir una dimensión; otras hará falta una prueba de funcionamiento o un ensayo de un especialista. Quien prepara la construcción y quien hace la comprobación deben entender igual el resultado esperado. Aclarar ahora las diferencias evita fabricar una pieza que luego haya que volver a encargar.\nTen en cuenta las pruebas ya al planificar las primeras unidades. Si un ensayo puede dañar la pieza, decide antes si necesitas una muestra aparte. Si varias personas van a usar la misma unidad, acordad el orden. Así el primer pedido incluirá lo necesario para obtener las respuestas, y preparar una prueba no frenará el resto del trabajo.\n1.2. Comprueba qué hace falta para que el producto sea seguro y cumpla la normativa\nAveriga qué requisitos se aplican a tu producto concreto y al país donde piensas ofrecerlo. También importa su uso. Un objeto de aspecto parecido puede tener requisitos distintos si es para jugar, para trabajar o de uso sanitario. Empieza por la información oficial para ese grupo de productos. En la Unión Europea, el portal Your Europe puede ser el punto de partida.\nEl marcado CE solo afecta a determinados grupos de productos. Cuando es obligatorio, hay que pasar la evaluación de conformidad correspondiente, es decir, comprobar y documentar que se cumplen los requisitos aplicables. Comprar una pieza con CE no confirma automáticamente la conformidad del producto completo que construyas con ella. Que no sea obligatorio el marcado CE tampoco significa que el producto no tenga requisitos de seguridad.\nSi necesitas ayuda, da a un especialista la descripción del uso y los materiales de diseño disponibles. Pídele que indique qué hay que tener en cuenta en el diseño y qué comprobaciones harán falta antes del uso previsto. Una pregunta así de concreta da una respuesta más útil que una petición genérica de «revisar el producto».\nAcordad en el equipo quién recogerá esa respuesta y se ocupará de aplicar los cambios necesarios. Esa persona puede coordinar el trabajo apoyándose en el conocimiento del especialista adecuado. Si trabajas en solitario, puedes contratar esa consulta fuera. Encarga la valoración de cada cuestión a quien sepa valorarla; tener la agenda libre no basta.\nCompleta el documento del subpunto 1.1 con lo averiguado y su fuente. Describe con precisión lo que quede sin aclarar, p. ej. «Hay que confirmar si el material elegido sirve para este uso». Si la respuesta puede obligar a cambiar la construcción, aclárala antes de un pedido caro. Terminar este subpunto significa haber identificado los requisitos; su cumplimiento se confirma en el trabajo posterior.","guide_sources":["NASA, Technical Requirements Definition describe cómo traducir la forma de uso en requisitos comprobables. NASA, Product Verification explica cómo elegir los métodos y recursos para comprobarlos.","Your Europe, CE marking explica el alcance del marcado y la responsabilidad sobre el producto completo. NASA, Technical Planning describe cómo ajustar competencias y responsabilidades al trabajo técnico."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'hardware' and p.key = 'hw-spec';
update public.stage_subpoints s set translations = '{"de":{"title":"Lege fest, was du vor der ersten Nutzung prüfst"},"uk":{"title":"Визнач, що перевіриш перед першим використанням"},"es":{"title":"Define qué comprobarás antes del primer uso"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'hardware' and p.key = 'hw-spec' and s.key = 'checks';
update public.stage_fields f set translations = '{"de":{"question":"Wofür ist die erste Version, wer nutzt sie und unter welchen Bedingungen?","help":"Wenn du schon eine solche Beschreibung hast, füge sie ein oder gib die Datei an."},"uk":{"question":"Для чого перша версія, хто нею користується і в яких умовах?","help":"Якщо вже маєш такий опис, встав його або вкажи файл."},"es":{"question":"¿Para qué sirve la primera versión, quién la usa y en qué condiciones?","help":"Si ya tienes esa descripción, pégala o indica el archivo."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'hardware' and p.key = 'hw-spec'
    and s.key = 'checks' and f.key = 'use';
update public.stage_fields f set translations = '{"de":{"question":"Dokument: was das Produkt leisten muss, welches Ergebnis reicht und wie du es prüfst.","help":"Berücksichtige bei einer Anforderung, die ein Exemplar verbrauchen kann, zusätzliche Stücke."},"uk":{"question":"Документ: що продукт має робити, який результат достатній і як ти це перевіриш.","help":"Для вимоги, яка може зужити екземпляр, врахуй додаткові штуки."},"es":{"question":"Documento: qué debe hacer el producto, qué resultado basta y cómo lo comprobarás.","help":"En los requisitos que pueden gastar una unidad, cuenta con unidades adicionales."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'hardware' and p.key = 'hw-spec'
    and s.key = 'checks' and f.key = 'requirements';
update public.stage_subpoints s set translations = '{"de":{"title":"Prüfe, was nötig ist, damit das Produkt sicher ist und Vorschriften erfüllt"},"uk":{"title":"Перевір, що потрібно, щоб продукт був безпечним і відповідав правилам"},"es":{"title":"Comprueba qué hace falta para que el producto sea seguro y cumpla la normativa"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'hardware' and p.key = 'hw-spec' and s.key = 'safety';
update public.stage_fields f set translations = '{"de":{"question":"Welche Vorschriften, Schutzmaßnahmen, Prüfungen und Dokumente betreffen diese Nutzung?","help":"Nenne die Quelle. Wenn du etwas nicht weißt, notiere, was geklärt werden muss. Das ist eine Erhebung der Anforderungen, kein Zertifikat."},"uk":{"question":"Які правила, запобіжники, дослідження й документи стосуються такого використання?","help":"Вкажи джерело. Якщо чогось не знаєш, запиши, що треба з’ясувати. Це розпізнання вимог, а не сертифікат."},"es":{"question":"¿Qué normas, protecciones, ensayos y documentos afectan a este uso?","help":"Indica la fuente. Si no sabes algo, anota qué hay que aclarar. Es identificar requisitos, no un certificado."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'hardware' and p.key = 'hw-spec'
    and s.key = 'safety' and f.key = 'rules';
update public.stage_points p set translations = '{"de":{"title":"Prüfe ein unsicheres Element, bevor du das Ganze baust","guide_body":"2.1. Mach einen früheren Test, wenn sein Ergebnis die Konstruktion ändern kann\nSieh dir den Entwurf an und wähle die Unbekannte, durch die du später am meisten Arbeit verlieren kannst. Das kann eine Verbindung von Teilen sein, deren Festigkeit du noch nicht kennst. Es kann auch um ein Material gehen, das unter den erwarteten Bedingungen seine Eigenschaften behalten muss. Ein früherer Test ergibt Sinn, wenn sein Ergebnis hilft, die weitere Konstruktion zu wählen. Wenn du schon passende Ergebnisse für diese Nutzung hast, verwende sie.\nBereite nur den Teil des Produkts vor, mit dem sich die gewählte Frage beantworten lässt. Für die Prüfung einer Verbindung können zwei Muster reichen. Ein Formmodell kann helfen, die Passung zu prüfen, aber Schlüsse zur Festigkeit erfordern passendes Material und passende Fertigung. Wähle das Muster nach dem, was du herausfinden willst.\nEin Goal vom Typ „Testergebnis“ kann lauten: „Prüfen, ob die gewählte Verbindung die Lastanforderung aus Unterpunkt 1.1 erfüllt.“ Lege eine verantwortliche Person und einen Termin für die Antwort fest. Gib als erwarteten Proof den Testeintrag mit Ergebnis und Schlussfolgerung an. So ist schon vor Arbeitsbeginn klar, womit sie enden soll.\nWenn mehrere Personen daran arbeiten, teile Mustervorbereitung, Prüfung und Bewertung des Ergebnisses in Aufgaben unter diesem Goal auf. Erkläre in einer Notiz, was fertig sein muss, bevor die nächste Aufgabe beginnt. Bei einem kleinen Test, den du allein machst, kannst du alles in einem Goal führen. Die Feinheit der Aufteilung sollte helfen, die Arbeit zu erledigen.\nNotiere nach dem Test, was geprüft wurde, unter welchen Bedingungen und was passiert ist. Ein negatives Ergebnis kann ein Goal zur Durchführung eines Tests abschließen, wenn ihr die nötige Antwort bekommen habt. Die nächste Entscheidung kann dann darin bestehen, die Verbindung oder das Material zu ändern. Beginne einen weiteren Test mit einer konkreten Frage, die das vorige Ergebnis noch nicht beantwortet hat.","guide_sources":["TWI, What is Prototyping? beschreibt die Wahl des Prototyps passend zur Frage und die schrittweise Prüfung einer Konstruktion. Michael Seibel, The Scientific Method for Startups stellt Arbeit durch Prüfen von Annahmen und Schlussfolgern vor. Das Goal-Beispiel wendet diese Prinzipien in Vairo an."]},"uk":{"title":"Перевір непевний елемент перед створенням цілого","guide_body":"2.1. Проведи попередню спробу, якщо її результат може змінити конструкцію\nПоглянь на проєкт і обери невідому, через яку пізніше можеш втратити найбільше роботи. Це може бути спосіб з’єднання деталей, міцності якого ти ще не знаєш. Може йтися й про матеріал, що має зберігати свої властивості в передбачуваних умовах. Попередня спроба має сенс тоді, коли її результат допоможе обрати подальшу конструкцію. Якщо вже маєш відповідні результати для такого застосування, використай їх.\nПідготуй лише такий фрагмент продукту, який дасть змогу відповісти на обране запитання. Для перевірки з’єднання можуть вистачити два зразки. Модель, що показує форму, може допомогти перевірити припасування, але висновки про міцність потребують відповідного матеріалу й способу виготовлення. Добирай зразок до того, що хочеш дізнатися.\nGoal типу «Результат тесту» може звучати так: «Перевірити, чи обране з’єднання відповідає вимозі навантаження з підпункту 1.1». Признач відповідальну людину й термін отримання відповіді. Як очікуваний proof вкажи запис спроби з результатом і висновком. Так ще до початку роботи відомо, чим вона має завершитися.\nЯкщо над цим працюють кілька людей, розподіли підготовку зразка, проведення дослідження й оцінку результату на завдання в цьому Goal. У нотатці поясни, що має бути готове до початку наступного завдання. За малої спроби, яку виконуєш сам, можеш вести все в одному Goal. Детальність поділу має допомагати виконати роботу.\nПісля спроби запиши, що досліджували, в яких умовах і що сталося. Негативний результат може завершити Goal щодо проведення спроби, якщо ви отримали потрібну відповідь. Наступним рішенням тоді може бути зміна з’єднання чи матеріалу. Наступну спробу починай із конкретним запитанням, на яке попередній результат ще не відповів.","guide_sources":["TWI, What is Prototyping? описує вибір прототипу під запитання й поетапну перевірку конструкції. Michael Seibel, The Scientific Method for Startups представляє роботу через перевірку припущень і висновки. Приклад Goal — застосування цих принципів у Vairo."]},"es":{"title":"Comprueba el elemento incierto antes de construir el conjunto","guide_body":"2.1. Haz una prueba previa si su resultado puede cambiar la construcción\nMira el diseño y elige la incógnita por la que más trabajo puedes perder después. Puede ser una forma de unir piezas cuya resistencia aún no conoces. O un material que tiene que mantener sus propiedades en las condiciones previstas. Una prueba previa tiene sentido si su resultado ayuda a elegir la construcción siguiente. Si ya tienes resultados adecuados para este uso, aprovéchalos.\nPrepara solo la parte del producto que permita responder a la pregunta elegida. Para comprobar una unión pueden bastar dos muestras. Una maqueta de forma puede ayudar a comprobar el encaje, pero las conclusiones sobre resistencia requieren el material y la fabricación adecuados. Elige la muestra según lo que quieras averiguar.\nUn Goal del tipo «Resultado de prueba» puede decir: «Comprobar si la unión elegida cumple el requisito de carga del subpunto 1.1». Asigna un responsable y una fecha para la respuesta. Como proof esperado, indica el registro de la prueba con su resultado y su conclusión. Así, antes de empezar, ya se sabe cómo debe terminar el trabajo.\nSi trabajan varias personas, reparte en tareas de ese Goal la preparación de la muestra, el ensayo y la valoración del resultado. Explica en una nota qué debe estar listo antes de empezar la siguiente tarea. En una prueba pequeña que haces tú solo, puedes llevarlo todo en un Goal. El nivel de detalle del reparto debe ayudar a hacer el trabajo.\nTras la prueba, anota qué se ensayó, en qué condiciones y qué pasó. Un resultado negativo puede cerrar un Goal de hacer una prueba si habéis obtenido la respuesta necesaria. La siguiente decisión puede ser entonces cambiar la unión o el material. Empieza la siguiente prueba con una pregunta concreta que el resultado anterior aún no haya respondido.","guide_sources":["TWI, What is Prototyping? describe cómo elegir el prototipo según la pregunta y comprobar la construcción por fases. Michael Seibel, The Scientific Method for Startups presenta el trabajo como comprobación de suposiciones y extracción de conclusiones. El ejemplo de Goal aplica estos principios en Vairo."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'hardware' and p.key = 'hw-try';
update public.stage_subpoints s set translations = '{"de":{"title":"Mach einen früheren Test, wenn sein Ergebnis die Konstruktion ändern kann"},"uk":{"title":"Проведи попередню спробу, якщо її результат може змінити конструкцію"},"es":{"title":"Haz una prueba previa si su resultado puede cambiar la construcción"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'hardware' and p.key = 'hw-try' and s.key = 'probe';
update public.stage_fields f set translations = '{"de":{"question":"Ziel vom Typ „Testergebnis“: Version, Bedingungen, Ergebnis und Entscheidung.","config":{"label":"Ziele öffnen"}},"uk":{"question":"Ціль типу «Результат тесту»: версія, умови, результат і рішення.","config":{"label":"Відкрити цілі"}},"es":{"question":"Objetivo del tipo «Resultado de prueba»: versión, condiciones, resultado y decisión.","config":{"label":"Abrir objetivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'hardware' and p.key = 'hw-try'
    and s.key = 'probe' and f.key = 'open';
update public.stage_points p set translations = '{"de":{"title":"Fertige die erste Produktversion oder gib sie in Auftrag","guide_body":"3.1. Fertige ein Exemplar, das sich prüfen lässt\nVerknüpfe die Anforderungen und die nötigen Dateien mit einem Goal vom Typ „Bauergebnis“, das das zu bauende Exemplar beschreibt. Nenne die Version, auf die sich die Arbeit bezieht. Lege auch fest, was die Erledigung dieses Goals zeigen wird. Ein Foto kann bestätigen, dass der Gegenstand entstanden ist, und ein Video oder ein Abnahmeprotokoll kann zusätzlich seine Grundfunktion zeigen. Die genaue Prüfung der Anforderungen machst du in Unterpunkt 4.1.\nTeile den Bau in Ergebnisse, die sich an die nächste Person übergeben lassen. Bei einer einfachen Halterung kann eine Aufgabe eine Zeichnung mit den Befestigungsmaßen sein. Die nächste ist die Fertigung des Teils nach dieser Zeichnung. Die folgende umfasst das Zusammenbauen der Halterung und die Prüfung der Passung. Eine solche Aufteilung zeigt, was entstehen soll und worauf die nächste Person wartet.\nEine Aufgabe ist klein genug, wenn die verantwortliche Person ihren Umfang versteht und den Abschluss benennen kann. Teile sie weiter, wenn sie mehrere Übergaben verbirgt oder das Ergebnis lange unsichtbar bleibt. Kleine Montageschritte können in einer Anleitung bei der Aufgabe bleiben. Ein eigener Eintrag lohnt sich, wenn er hilft, Verantwortung zuzuweisen oder ein wichtiges Ergebnis zu verfolgen.\nVereinbare die Zuteilung mit der ausführenden Person und berücksichtige ihre Fähigkeiten und verfügbare Zeit. Der Eigentümer des Goals sorgt dafür, dass das ganze Exemplar entsteht, und die einzelnen Aufgaben können verschiedene Personen übernehmen. Bei einem externen Auftrag achtet eine Person aus deinem Team auf die Vereinbarungen und nimmt das Ergebnis ab. Kläre vor der Bestellung mit dem Auftragnehmer, nach welchen Dateien gearbeitet wird und was genau übergeben werden soll.\nWenn Teile parallel entstehen, vereinbart vorher die Stellen, an denen sie zusammenpassen müssen. Wenn eine Person das Gehäuse entwirft und eine andere das darin eingebaute Element, brauchen beide übereinstimmende Maße und Befestigungspositionen. Gib Änderungen dieser Vereinbarungen vor der weiteren Arbeit an die andere Person weiter.\nBerücksichtige beim Termin die Wartezeit auf Auftragnehmer oder Lieferungen. Wenn sich das Produkt ohne ein bestelltes Teil nicht zusammenbauen lässt, beeinflusst dessen Termin die weitere Arbeit. Führe die übrigen Aufgaben parallel, wo sie die nötigen Daten schon haben. Wenn mehrere Arbeiten auf eine Fachperson oder einen Arbeitsplatz warten, lege eine Reihenfolge fest, statt allen denselben Termin zu geben.\n3.2. Bewahre die Informationen auf, die für den Bau dieser Version nötig sind\nSammle die Dokumentation während des Baus. Nach Fertigstellung des Exemplars sollte sie zeigen, wie genau diese Version entstanden ist. Wenn ihr in der Werkstatt ein Maß geändert oder ein Teil ausgetauscht habt, berücksichtige das in den Dateien. Die Zeichnung einer früheren Idee reicht nicht, um die fertige Konstruktion zu wiederholen.\nBewahre Informationen auf, mit denen sich das Material erneut wählen und die richtigen Teile bestellen lassen. Der Eintrag „kleiner Motor“ kann zum Kauf eines ganz anderen Teils führen. Die Bezeichnung des konkreten Modells und die Stückzahl erlauben es, die Wahl nachzuvollziehen. Eine solche Liste von Teilen und Materialien heißt oft BOM. Du kannst sie in einem normalen Dokument führen, das du beim Bau schon nutzt.\nKennzeichne die Dateiversion und verknüpfe sie mit dem Exemplar. Wenn du einem Auftragnehmer eine neue Zeichnung gibst, sag klar, dass sie die vorige ersetzt, und bestätige, ob das frühere Teil schon gefertigt wurde. So vermeidest du einfach, dass zwei Personen nach unterschiedlichen Maßen arbeiten. Setze im Goal einen Link auf die richtigen Materialien, statt weitere Kopien davon zu erstellen.\nSprich schon vor der Bestellung mit dem Auftragnehmer darüber, wie die nötige Zahl an Exemplaren entsteht. Frag, ob die gewählte Form und das Material zu seiner Fertigungsweise passen. Manchmal vereinfacht eine kleine Änderung der Konstruktion die Montage oder vermeidet ein teures Werkzeug. Das ist die Grundlage des fertigungsgerechten Entwurfs, abgekürzt DFM. In dieser Etappe passt du die Fertigung an die erste nötige Nutzung an.\nPrüfe die Verfügbarkeit von Teilen, von denen der weitere Bau abhängt, und bewahre das Angebot des Auftragnehmers auf. Wenn du allein baust, nutze Kosten und Erfahrungen aus dem ersten Exemplar. Trenne die Kosten der einmaligen Vorbereitung von den Kosten des nächsten Stücks, wenn es einen solchen Unterschied gibt. Wenn die Montage eine unbeschriebene Korrektur oder langes Anpassen erfordert, notiere das bei der Konstruktion. So lässt sich der Entwurf verbessern oder der Auftragnehmer vor der nächsten Bestellung vorbereiten.","guide_sources":["NASA, Technical Planning beschreibt Arbeitsergebnisse, ihre Reihenfolge und nötige Ressourcen. NASA, Interface Management erklärt die Koordination von Teilen, die verschiedene Personen erstellen. Atlassian, Roles and Responsibilities unterstützt die Unterscheidung zwischen verantwortlicher und mitarbeitenden Personen. Die Aufteilung des Beispiel-Goals in Aufgaben ist an Vairo angepasst.","NASA, Configuration Management beschreibt die Identifizierung von Versionen und die Kontrolle von Dokumentationsänderungen. TWI, What is Design for Manufacturing? erklärt, wie Konstruktionsentscheidungen Fertigung und Montage beeinflussen."]},"uk":{"title":"Виготов або замов першу версію продукту","guide_body":"3.1. Виготов екземпляр, який можна перевірити\nПрикріпи вимоги й потрібні файли до Goal типу «Результат створення», що описує екземпляр, який має з’явитися. Вкажи версію, якої стосується робота. Визнач також, що покаже виконання цього Goal. Фото може підтвердити появу предмета, а відео чи запис приймання може додатково показати його базову роботу. Детальну перевірку вимог виконаєш у підпункті 4.1.\nПоділи створення на результати, які можна передати наступній людині. Для простого тримача одним завданням може бути підготовка креслення з розмірами кріплення. Наступним — виготовлення деталі за цим кресленням. Ще наступне охопить складання тримача й перевірку припасування. Такий поділ показує, що має з’явитися і на що чекає наступна людина.\nЗавдання досить мале, коли відповідальна людина розуміє його обсяг і вміє вказати момент завершення. Поділи його далі, якщо воно ховає кілька передач роботи або результат довго буде невидимим. Дрібні монтажні дії можуть залишитися в інструкції при завданні. Окремий запис корисний тоді, коли допомагає призначити відповідальність або стежити за важливим результатом.\nРозподіл погодь із виконавцем, враховуючи його вміння й доступний час. Власник Goal пильнує появи всього екземпляра, а окремі завдання можуть виконувати різні люди. За зовнішнього замовлення людина з твоєї команди стежить за домовленостями й приймає результат. Перед замовленням домовся з виконавцем, за якими файлами він працює і що саме має передати.\nЯкщо деталі з’являються паралельно, заздалегідь домовтеся про місця, де вони мають з’єднатися. Коли одна людина проєктує корпус, а друга — елемент, що в ньому розміщується, обом потрібні узгоджені розміри й положення кріплень. Зміну цих домовленостей передай другій людині до подальшої роботи.\nУ терміні врахуй очікування на виконавця чи доставку. Якщо без замовленої деталі не можна скласти продукт, її термін впливає на подальшу роботу. Решту завдань веди паралельно там, де вже є потрібні дані. Коли кілька робіт чекають на одного фахівця чи одне робоче місце, визнач черговість замість призначати всім той самий термін.\n3.2. Збережи інформацію, потрібну для виготовлення цієї версії\nЗбирай документацію під час створення. Після виготовлення екземпляра вона має показувати, як з’явилася саме ця версія. Якщо в майстерні ви змінили розмір або замінили деталь, врахуй це у файлах. Креслення попередньої ідеї недостатньо, щоб повторити готову конструкцію.\nЗбережи інформацію, яка дасть змогу знову дібрати матеріал і замовити правильні деталі. Запис «малий двигун» може призвести до купівлі зовсім іншого елемента. Позначення конкретної моделі й кількість штук дадуть змогу відтворити вибір. Такий перелік елементів і матеріалів часто називають BOM. Можна вести його у звичайному документі, яким уже користуєшся при створенні.\nПознач версію файлів і пов’яжи її з екземпляром. Коли передаєш виконавцеві нове креслення, чітко вкажи, що воно замінює попереднє, і підтвердь, чи попередню деталь уже виготовлено. Це простий спосіб уникнути ситуації, коли двоє людей працюють за різними розмірами. У Goal розмісти посилання на правильні матеріали замість створювати їхні нові копії.\nЩе до замовлення поговори з виконавцем про те, як з’явиться потрібна кількість екземплярів. Запитай, чи обрана форма й матеріал підходять для його способу виробництва. Іноді дрібна зміна конструкції дає змогу спростити складання або уникнути дорогого інструмента. Це основа проєктування з думкою про виготовлення, яке позначають скороченням DFM. На цьому етапі ти пристосовуєш виготовлення до першого потрібного використання.\nПеревір доступність деталей, від яких залежить подальше створення, і збережи пропозицію виконавця. Якщо будуєш сам, використай витрати й досвід із першого екземпляра. Відокрем вартість одноразової підготовки від вартості наступної штуки, якщо така різниця є. Коли складання вимагає неописаного виправлення чи довгого припасовування, допиши цю інформацію біля конструкції. Це дасть змогу виправити проєкт або підготувати виконавця перед наступним замовленням.","guide_sources":["NASA, Technical Planning описує результати робіт, їхній порядок і потрібні ресурси. NASA, Interface Management пояснює координацію частин, які створюють різні люди. Atlassian, Roles and Responsibilities допомагає розрізнити відповідальну людину й співпрацівників. Поділ прикладового Goal на завдання адаптовано до Vairo.","NASA, Configuration Management описує ідентифікацію версій і контроль змін документації. TWI, What is Design for Manufacturing? пояснює, як конструкторські рішення впливають на виготовлення й складання."]},"es":{"title":"Fabrica o encarga la primera versión del producto","guide_body":"3.1. Fabrica una unidad que se pueda comprobar\nVincula los requisitos y los archivos necesarios a un Goal del tipo «Resultado de construcción» que describa la unidad que se va a hacer. Indica a qué versión se refiere el trabajo. Define también qué demostrará que el Goal está hecho. Una foto puede confirmar que el objeto existe, y un vídeo o un acta de recepción puede mostrar además su funcionamiento básico. La comprobación detallada de los requisitos la harás en el subpunto 4.1.\nDivide la construcción en resultados que se puedan pasar a la siguiente persona. En un soporte sencillo, una tarea puede ser preparar un plano con las medidas del anclaje. La siguiente, fabricar la pieza según ese plano. La siguiente, montar el soporte y comprobar el encaje. Un reparto así muestra qué hay que hacer y qué espera la siguiente persona.\nUna tarea es lo bastante pequeña cuando su responsable entiende su alcance y sabe decir cuándo termina. Divídela más si esconde varias entregas de trabajo o si su resultado va a estar mucho tiempo sin verse. Los pequeños pasos de montaje pueden quedarse en unas instrucciones dentro de la tarea. Una entrada aparte sirve cuando ayuda a asignar responsabilidad o a seguir un resultado importante.\nAcuerda el reparto con quien hace el trabajo, teniendo en cuenta sus habilidades y su tiempo. El responsable del Goal vela por que se complete toda la unidad, y cada tarea puede hacerla una persona distinta. Si se encarga fuera, alguien de tu equipo vigila lo acordado y recibe el resultado. Antes de encargarlo, acuerda con el proveedor con qué archivos trabaja y qué tiene que entregar exactamente.\nSi las piezas se hacen en paralelo, acordad antes los puntos donde tienen que encajar. Si una persona diseña la carcasa y otra el elemento que va dentro, ambas necesitan medidas y posiciones de anclaje coincidentes. Comunica a la otra persona cualquier cambio de lo acordado antes de seguir.\nEn la fecha, ten en cuenta la espera del proveedor o de la entrega. Si sin la pieza encargada no se puede montar el producto, su plazo afecta al resto del trabajo. Avanza en paralelo las demás tareas que ya tengan los datos necesarios. Si varios trabajos esperan a un mismo especialista o un mismo puesto, fija un orden en lugar de poner a todos la misma fecha.\n3.2. Guarda la información necesaria para fabricar esta versión\nReúne la documentación durante la construcción. Una vez hecha la unidad, debe mostrar cómo se hizo exactamente esta versión. Si en el taller cambiasteis una medida o sustituisteis una pieza, refléjalo en los archivos. El plano de una idea anterior no basta para repetir la construcción final.\nGuarda la información que permita volver a elegir el material y pedir las piezas correctas. Anotar «motor pequeño» puede llevar a comprar un elemento totalmente distinto. La referencia del modelo concreto y el número de unidades permiten reproducir la elección. Esa lista de piezas y materiales suele llamarse BOM. Puedes llevarla en un documento normal que ya uses en la construcción.\nMarca la versión de los archivos y vincúlala a la unidad. Cuando pases un plano nuevo a un proveedor, indica claramente que sustituye al anterior y confirma si la pieza anterior ya se ha fabricado. Es una forma sencilla de evitar que dos personas trabajen con medidas distintas. En el Goal pon un enlace a los materiales correctos en lugar de crear más copias.\nAntes de hacer el pedido, habla con el proveedor sobre cómo se harán las unidades necesarias. Pregunta si la forma y el material elegidos encajan con su forma de fabricar. A veces un pequeño cambio de diseño simplifica el montaje o evita una herramienta cara. Es la base del diseño pensado para la fabricación, conocido como DFM. En esta etapa ajustas la fabricación al primer uso necesario.\nComprueba la disponibilidad de las piezas de las que depende la construcción y guarda la oferta del proveedor. Si construyes solo, aprovecha los costes y la experiencia de la primera unidad. Separa el coste de preparación único del coste de la siguiente unidad, si hay esa diferencia. Si el montaje exige un ajuste no descrito o mucho tiempo de encaje, anótalo junto a la construcción. Así podrás mejorar el diseño o preparar al proveedor antes del siguiente pedido.","guide_sources":["NASA, Technical Planning describe los resultados del trabajo, su orden y los recursos necesarios. NASA, Interface Management explica cómo coordinar piezas hechas por distintas personas. Atlassian, Roles and Responsibilities ayuda a distinguir al responsable de los colaboradores. La división del Goal de ejemplo en tareas está adaptada a Vairo.","NASA, Configuration Management describe cómo identificar versiones y controlar los cambios de documentación. TWI, What is Design for Manufacturing? explica cómo influyen las decisiones de diseño en la fabricación y el montaje."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'hardware' and p.key = 'hw-build';
update public.stage_subpoints s set translations = '{"de":{"title":"Fertige ein Exemplar, das sich prüfen lässt"},"uk":{"title":"Виготов екземпляр, який можна перевірити"},"es":{"title":"Fabrica una unidad que se pueda comprobar"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'hardware' and p.key = 'hw-build' and s.key = 'unit';
update public.stage_fields f set translations = '{"de":{"question":"Verknüpfe ein Ziel mit Versionsbezeichnung und einem Nachweis, dass das Exemplar entstanden ist.","config":{"label":"Ziele öffnen"}},"uk":{"question":"Прикріпи ціль із позначенням версії й доказом, що екземпляр з’явився.","config":{"label":"Відкрити цілі"}},"es":{"question":"Vincula un objetivo con la versión y una prueba de que la unidad existe.","config":{"label":"Abrir objetivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'hardware' and p.key = 'hw-build'
    and s.key = 'unit' and f.key = 'open';
update public.stage_subpoints s set translations = '{"de":{"title":"Bewahre die Informationen auf, die für den Bau dieser Version nötig sind"},"uk":{"title":"Збережи інформацію, потрібну для виготовлення цієї версії"},"es":{"title":"Guarda la información necesaria para fabricar esta versión"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'hardware' and p.key = 'hw-build' and s.key = 'repeat';
update public.stage_fields f set translations = '{"de":{"question":"Wie entsteht diese Version: Verfügbarkeit, Fertigungsweise und Kosten der ersten Exemplare?","help":"Füge Zeichnungen oder Entwürfe bei, wenn sie zum Wiederholen nötig sind."},"uk":{"question":"Як виготовляється ця версія: доступність, спосіб і вартість перших екземплярів?","help":"Додай креслення чи проєкти, якщо вони потрібні для повторення."},"es":{"question":"¿Cómo se hace esta versión: disponibilidad, forma de fabricación y coste de las primeras unidades?","help":"Adjunta planos o diseños si hacen falta para repetirla."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'hardware' and p.key = 'hw-build'
    and s.key = 'repeat' and f.key = 'how';
update public.stage_fields f set translations = '{"de":{"question":"Dateien dieser Version."},"uk":{"question":"Файли цієї версії."},"es":{"question":"Archivos de esta versión."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'hardware' and p.key = 'hw-build'
    and s.key = 'repeat' and f.key = 'files';
update public.stage_points p set translations = '{"de":{"title":"Prüfe das Produkt und behebe gefundene Probleme","guide_body":"4.1. Prüfe die erste Version anhand der festgelegten Anforderungen\nÖffne die Anforderungen aus Punkt 1 und nutze sie als Grundlage der Tests. Ein Goal kann die ganze nötige Prüfreihe umfassen. Du kannst eigene Aufgaben abtrennen, wenn verschiedene Personen prüfen oder die Prüfungen eine eigene Vorbereitung brauchen. Das gemeinsame Ergebnis soll die Antwort sein, welche Anforderungen die angegebene Version erfüllt und was noch Arbeit braucht.\nStelle vor dem Test sicher, dass die durchführende Person das richtige Exemplar und die aktuellen Anforderungen hat. Unterscheide bei mehreren Stücken die Exemplarnummer von der Konstruktionsversion. Zwei Stücke nach demselben Entwurf können eine unterschiedliche Testgeschichte haben. Der Eintrag „v2, Exemplar 3“ lässt später verstehen, auf welchen Gegenstand sich das Ergebnis bezieht.\nStelle bei jeder Prüfung das erwartete dem erzielten Ergebnis gegenüber. Ergänze Bedingungen, die es beeinflusst haben könnten. Wenn der Test die Laufzeit eines Geräts betraf, gib auch an, wie es genutzt wurde. Wähle das Nachweismaterial passend zur Frage: Ein Foto kann einen Riss zeigen, eine Zeitmessung braucht aber einen Eintrag des erzielten Ergebnisses. Halte die Daten direkt beim Test fest.\nVereinbart im Team die Nutzung eines gemeinsamen Exemplars. Wer es weitergibt, sollte sagen, welche Tests es durchlaufen hat und ob Schäden aufgefallen sind. Passt Reihenfolge und Einsatz eigener Muster an die gewählte Prüfmethode an. Prüfungen, die passende Ausrüstung oder Qualifikationen erfordern, überlasst einer Person oder Einrichtung, die sie hat.\nWenn jemand anderes die Ergebnisse durchsehen kann, bitte darum, ihre Übereinstimmung mit den Anforderungen zu prüfen. Wenn du allein arbeitest, geh zu den notierten Kriterien zurück, bevor du einen Test als erfolgreich ansiehst. Ein abgeschlossenes Goal vom Typ „Testergebnis“ bestätigt, dass die Prüfung gemacht und die Antwort festgehalten wurde. Eine nicht erfüllte Anforderung braucht trotzdem eine Entscheidung und passendes Handeln, bevor die Bereitschaft des Produkts bestätigt wird.\n4.2. Behebe das Problem und prüfe die Korrektur\nKläre zuerst, was genau passiert ist. Nutze den Testeintrag und prüfe, an welcher Stelle das Problem auftrat. Ein gerissenes Teil ist eine Beobachtung. Die Aussage, falsches Material sei die Ursache, muss geprüft werden, denn auch Fertigung oder Montage können eine Rolle gespielt haben. Wenn die Ursache unbekannt bleibt, ist ihre Klärung die nächste Aufgabe.\nStütze das Gespräch mit dem Team auf das, was sich prüfen lässt. Frag, nach welcher Zeichnung gearbeitet wurde und welche Informationen bei der Arbeit verfügbar waren. Bedanke dich für die schnelle Fehlermeldung. Wer die Reaktion des Teams fürchtet, zögert vielleicht, ein Problem weiterzugeben, und die anderen arbeiten so lange mit einer falschen Annahme. Vereinbare nach dem Finden der Ursache eine konkrete Änderung. Wenn eine alte Zeichnung den Fehler verursacht hat, verbessere auch die Weitergabe aktueller Dateien.\nBeschreibe im zugehörigen Goal, was ihr ändert und welches Ergebnis die Wirksamkeit der Korrektur bestätigen soll. Die Aufgabe, die Zeichnung zu ändern, kann früher erledigt sein, aber das Goal zur Fehlerbehebung braucht noch die Prüfung der neuen Konstruktion. Verteile diese Tätigkeiten nach den Fähigkeiten der Ausführenden. Die Person, die die Korrektur koordiniert, sorgt dafür, dass die Arbeit bis zu dieser abschließenden Prüfung kommt.\nPrüfe, wenn möglich, die Wirkung einer Änderung nach der anderen. Wenn ihr mehrere Dinge gleichzeitig ändert, halte alle Änderungen fest, damit sich das Ergebnis später erklären lässt. Kennzeichne die neue Version und lass den Zugang zu früheren Ergebnissen bestehen.\nBeurteile auch, was die Korrektur sonst beeinflusst hat. Ein dickeres Teil trägt vielleicht die Last besser, passt aber nicht mehr an den Montageort. Wiederhole die Prüfungen zum geänderten Element und zu den Produktteilen, auf die die Änderung wirkt. Vereinbare den Umfang der erneuten Prüfungen mit einer Person, die diese Zusammenhänge beurteilen kann. Füge das Ergebnis der Korrektur der bestehenden Arbeit in Vairo bei.","guide_sources":["NASA, Product Verification beschreibt die Prüfung von Anforderungen und die Vorbereitung von Prüfungen. NASA, Configuration Management erklärt die Identifizierung der geprüften Version. Die Art, das Ergebnis im Goal festzuhalten, folgt den Vairo-Regeln.","John Lunney und Sue Lueder, Postmortem Culture: Learning from Failure beschreibt die Analyse von Ursachen und das Schaffen von Bedingungen für das Melden von Problemen; diese Teamregeln werden hier auf den Hardwarebau angewendet. NASA, Configuration Management beschreibt die Bewertung der Auswirkung von Änderungen und ihre Prüfung."]},"uk":{"title":"Перевір продукт і виправ виявлені проблеми","guide_body":"4.1. Перевір першу версію за визначеними вимогами\nВідкрий вимоги з пункту 1 і використай їх як основу спроб. Один Goal може охоплювати весь потрібний набір перевірок. Можна виокремити окремі завдання, коли дослідження виконують різні люди або вони потребують окремої підготовки. Спільним результатом має бути відповідь, які вимоги виконує зазначена версія і що ще потребує роботи.\nПеред спробою переконайся, що людина, яка її виконує, має правильний екземпляр і актуальні вимоги. При кількох штуках розрізняй номер екземпляра й версію конструкції. Дві штуки, виготовлені за тим самим проєктом, можуть мати різну історію спроб. Запис «v2, екземпляр 3» дасть змогу пізніше зрозуміти, якого предмета стосується результат.\nДля кожної перевірки зістав очікуваний результат з отриманим. Допиши умови, які могли на нього вплинути. Якщо тест стосувався часу роботи пристрою, вкажи також, як ним користувалися. Доказовий матеріал добирай до запитання: фото може показати тріщину, але вимірювання часу потребує запису отриманого результату. Зберігай дані одразу під час спроби.\nУ команді домовтеся про користування спільним екземпляром. Людина, яка передає його далі, має сказати, які спроби він пройшов і чи помічено пошкодження. Черговість і використання окремих зразків добирайте до прийнятого методу дослідження. Дослідження, що вимагають відповідного обладнання чи кваліфікації, доручіть людині чи установі, яка їх має.\nЯкщо хтось інший може переглянути результати, попроси його перевірити їх відповідність вимогам. За самостійної роботи повернися до записаних критеріїв, перш ніж визнаєш спробу вдалою. Виконаний Goal типу «Результат тесту» підтверджує проведення дослідження й запис відповіді. Невиконана вимога все одно потребує рішення й відповідної дії перед підтвердженням готовності продукту.\n4.2. Усунь проблему й перевір виправлення\nПочни з з’ясування, що саме сталося. Скористайся записом спроби й перевір, у який момент з’явилася проблема. Тріщина деталі — це спостереження. Твердження, що причиною був неправильний матеріал, потребує перевірки, бо значення міг мати також спосіб виготовлення чи складання. Якщо причина лишається невідомою, найближчим завданням буде її з’ясування.\nРозмову з командою спирай на те, що можна перевірити. Запитай, яким кресленням користувалися і яка інформація була доступна під час роботи. Подякуй за швидке повідомлення про помилку. Людина, яка побоюється реакції команди, може зволікати з передачею проблеми, а решта тим часом працюватиме на хибному припущенні. Після знаходження причини погодь конкретну зміну. Якщо помилку спричинило старе креслення, виправ також спосіб передавання актуальних файлів.\nОпиши в пов’язаному Goal, що ви змінюєте і який результат має підтвердити ефективність виправлення. Завдання зі зміни креслення може бути виконане раніше, але Goal щодо усунення несправності ще потребує перевірки нової конструкції. Признач ці дії відповідно до вмінь виконавців. Людина, що координує виправлення, пильнує, щоб робота дійшла до цієї кінцевої перевірки.\nКоли можливо, перевіряй вплив однієї зміни за раз. Якщо змінюєте кілька речей одночасно, збережи інформацію про всі зміни, щоб пізніше можна було пояснити отриманий результат. Познач нову версію й залиш доступ до попередніх результатів.\nОціни також, на що ще вплинуло виправлення. Товстіша деталь може краще тримати навантаження, але перестати вміщатися в місці монтажу. Повтори перевірки щодо зміненого елемента й тих частин продукту, на які впливає зміна. Обсяг повторних досліджень погодь із людиною, яка вміє оцінити ці залежності. Додай результат виправлення до наявної роботи у Vairo.","guide_sources":["NASA, Product Verification описує перевірку вимог і підготовку досліджень. NASA, Configuration Management пояснює ідентифікацію досліджуваної версії. Спосіб запису результату в Goal випливає з правил Vairo.","John Lunney і Sue Lueder, Postmortem Culture: Learning from Failure описує аналіз причин і створення умов для повідомлення про проблеми; ці принципи командної роботи застосовано тут до створення заліза. NASA, Configuration Management описує оцінку впливу змін та їх перевірку."]},"es":{"title":"Comprueba el producto y corrige los problemas detectados","guide_body":"4.1. Comprueba la primera versión según los requisitos fijados\nAbre los requisitos del punto 1 y úsalos como base de las pruebas. Un Goal puede abarcar todo el conjunto de comprobaciones necesarias. Puedes separar tareas cuando los ensayos los hacen personas distintas o requieren una preparación propia. El resultado común debe ser saber qué requisitos cumple la versión indicada y qué sigue necesitando trabajo.\nAntes de la prueba, asegúrate de que quien la hace tiene la unidad correcta y los requisitos actuales. Si hay varias unidades, distingue el número de unidad de la versión del diseño. Dos unidades hechas con el mismo diseño pueden tener un historial de pruebas distinto. Anotar «v2, unidad 3» permitirá saber después a qué objeto se refiere el resultado.\nEn cada comprobación, compara el resultado esperado con el obtenido. Añade las condiciones que pudieron influir. Si la prueba era de autonomía, indica también cómo se usó el dispositivo. Elige la prueba documental según la pregunta: una foto puede mostrar una grieta, pero medir un tiempo exige anotar el resultado. Guarda los datos en el momento de hacer la prueba.\nAcordad en el equipo cómo usar una unidad compartida. Quien la pasa a otra persona debe decir qué pruebas ha pasado y si ha notado daños. Ajustad el orden y el uso de muestras separadas al método de ensayo elegido. Los ensayos que requieren equipo o cualificación específicos, encargádselos a quien los tenga.\nSi otra persona puede revisar los resultados, pídele que compruebe si cumplen los requisitos. Si trabajas solo, vuelve a los criterios anotados antes de dar una prueba por buena. Un Goal terminado del tipo «Resultado de prueba» confirma que se hizo el ensayo y se anotó la respuesta. Un requisito no cumplido sigue necesitando una decisión y la acción correspondiente antes de confirmar que el producto está listo.\n4.2. Elimina el problema y comprueba la corrección\nEmpieza por aclarar qué pasó exactamente. Usa el registro de la prueba y mira en qué momento apareció el problema. Que una pieza se agriete es una observación. Afirmar que la causa fue un material inadecuado requiere comprobación, porque también pudo influir la fabricación o el montaje. Si la causa sigue sin conocerse, la próxima tarea será aclararla.\nBasa la conversación con el equipo en lo que se puede comprobar. Pregunta qué plano se usó y qué información había mientras se trabajaba. Agradece que se avisara rápido del error. Quien teme la reacción del equipo puede tardar en comunicar un problema, y mientras tanto los demás trabajarán con una suposición errónea. Cuando encuentres la causa, acordad un cambio concreto. Si el error vino de un plano antiguo, mejorad también cómo se comparten los archivos actuales.\nDescribe en el Goal relacionado qué cambiáis y qué resultado debe confirmar que la corrección funciona. La tarea de cambiar el plano puede hacerse antes, pero el Goal de eliminar el fallo necesita además comprobar el nuevo diseño. Reparte estas tareas según las habilidades de cada persona. Quien coordina la corrección se asegura de que el trabajo llegue a esa comprobación final.\nCuando sea posible, comprueba el efecto de un cambio cada vez. Si cambiáis varias cosas a la vez, guarda la información de todos los cambios para poder explicar después el resultado. Marca la nueva versión y conserva el acceso a los resultados anteriores.\nValora también a qué más afectó la corrección. Una pieza más gruesa puede soportar mejor la carga, pero dejar de caber en su sitio. Repite las comprobaciones del elemento cambiado y de las partes del producto a las que afecta el cambio. Acuerda el alcance de los nuevos ensayos con quien sepa valorar esas relaciones. Añade el resultado de la corrección al trabajo existente en Vairo.","guide_sources":["NASA, Product Verification describe la comprobación de requisitos y la preparación de ensayos. NASA, Configuration Management explica la identificación de la versión ensayada. La forma de anotar el resultado en el Goal sigue las reglas de Vairo.","John Lunney y Sue Lueder, Postmortem Culture: Learning from Failure describe cómo analizar causas y crear condiciones para avisar de problemas; estas pautas de trabajo en equipo se aplican aquí a la construcción de hardware. NASA, Configuration Management describe cómo valorar el efecto de los cambios y comprobarlos."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'hardware' and p.key = 'hw-test';
update public.stage_subpoints s set translations = '{"de":{"title":"Prüfe die erste Version anhand der festgelegten Anforderungen"},"uk":{"title":"Перевір першу версію за визначеними вимогами"},"es":{"title":"Comprueba la primera versión según los requisitos fijados"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'hardware' and p.key = 'hw-test' and s.key = 'trial';
update public.stage_fields f set translations = '{"de":{"question":"Der Nachweis enthält die Ergebnisse der für die erste Nutzung verlangten Prüfungen.","config":{"label":"Ziele öffnen"}},"uk":{"question":"Доказ містить результати перевірок, потрібних для першого використання.","config":{"label":"Відкрити цілі"}},"es":{"question":"La prueba incluye los resultados de las comprobaciones exigidas para el primer uso.","config":{"label":"Abrir objetivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'hardware' and p.key = 'hw-test'
    and s.key = 'trial' and f.key = 'open';
update public.stage_subpoints s set translations = '{"de":{"title":"Behebe das Problem und prüfe die Korrektur"},"uk":{"title":"Усунь проблему й перевір виправлення"},"es":{"title":"Elimina el problema y comprueba la corrección"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'hardware' and p.key = 'hw-test' and s.key = 'fix';
update public.stage_fields f set translations = '{"de":{"question":"Wenn ein Test ein Problem gezeigt hat, behebe es und halte die neue Prüfung fest.","config":{"label":"Ziele öffnen"}},"uk":{"question":"Якщо спроба виявила проблему, виправ її й запиши нову перевірку.","config":{"label":"Відкрити цілі"}},"es":{"question":"Si una prueba detectó un problema, corrígelo y anota la nueva comprobación.","config":{"label":"Abrir objetivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'hardware' and p.key = 'hw-test'
    and s.key = 'fix' and f.key = 'open';
update public.stage_points p set translations = '{"de":{"title":"Bereite das Produkt für die erste Nutzung vor","guide_body":"5.1. Bereite das nötige Exemplar und die Materialien zur Nutzung vor\nBereite so viele Exemplare vor, wie die erste geplante Nutzung erfordert. Das kann eine Installation sein oder mehrere Stücke, die an Zielpersonen gehen. Nutze die Dokumentation der geprüften Version. Achte bei weiteren Exemplaren darauf, ob der Auftragnehmer das vereinbarte Material und die vereinbarte Fertigungsweise eingehalten hat. Ein bei der Montage vorgeschlagenes Ersatzteil kann eine erneute Prüfung der Konstruktion erfordern.\nTrenne Ergebnisse zum Entwurf von der Kontrolle des vorbereiteten Stücks. Die Prüfung der Konstruktion hilft festzustellen, ob der Entwurf die Anforderungen erfüllt. Die Abnahme eines konkreten Exemplars hilft, einen Fertigungsfehler zu finden, z. B. ein fehlendes Teil oder eine falsche Montage. Der Umfang dieser Kontrolle sollte zu deinem Produkt und den Anforderungen aus Punkt 1 passen. Bewahre das Ergebnis beim jeweiligen Exemplar auf.\nWähle für die erste Nutzung ein Stück in passendem Zustand. Prüfe seine Testgeschichte, besonders wenn Tests es geschwächt oder beschädigt haben könnten. Wenn verschiedene Personen montieren und kontrollieren, gib ihnen dieselben aktuellen Materialien. Wenn du allein arbeitest, kannst du beides selbst erledigen, gestützt auf die notierten Anforderungen und nötige Hilfe von Fachleuten.\nErstelle eine Anleitung auf Grundlage dessen, was Nutzer tun werden. Erkläre, wie man das Produkt vorbereitet und richtig nutzt. Beschreibe Einschränkungen und Warnhinweise, die sich aus der Konstruktion ergeben. Wenn sich die Bedienung schwer in Worten zeigen lässt, füge ein Foto oder eine Zeichnung hinzu. Wenn das Produkt installiert werden muss, gib die passenden Informationen auch an die Person, die das übernimmt.\nFüge die Dokumente und Kennzeichnungen bei, die für dieses Produkt und die geplante Nutzung nötig sind, gemäß den Erkenntnissen aus Unterpunkt 1.2. Die Materialien sollten zur vorbereiteten Version passen. Nutze vorhandene Ergebnisse und Dateien. Wenn das Produkt transportiert wird, sichere es auch für diesen Weg, damit es in einem Zustand ankommt, der die vorgesehene Nutzung erlaubt.\n5.2. Bestätige die Bereitschaft der angegebenen Version\nNenne genau, welche Version für die festgelegte Nutzung bereit ist. Verknüpfe ihre Prüfergebnisse und die in Unterpunkt 5.1 vorbereiteten Materialien. Wer diesen Eintrag ansieht, sollte das fertige Exemplar mit der Dokumentation verbinden können und verstehen, auf welcher Grundlage ihr es als bereit angesehen habt.\nGeh zu den Anforderungen aus Punkt 1 zurück. Prüfe, ob ihr für jede eine Antwort habt und ob ein Problem bleibt, das die vorgesehene Nutzung verhindert. Bei Teamarbeit stützt sich die Person, die die Ergebnisse sammelt, auf die Einschätzungen der für einzelne Bereiche Verantwortlichen. Stütze die Entscheidung in Fragen, die Fachwissen erfordern, auf eine passende Bewertung oder Prüfung.\nWenn jemand einen Zweifel äußert, kläre, welche Anforderung er betrifft und was zu seiner Klärung fehlt. Die Information „Es fehlt das Prüfergebnis nach dem Materialwechsel“ zeigt zum Beispiel eine konkrete weitere Arbeit. Solange Anforderungen für die geplante Nutzung nicht erfüllt sind, lass die Bestätigung leer und notiere das Hindernis bei der passenden Arbeit.\nIdeen für zusätzliche Funktionen können für später in Notizen bleiben. Die Bereitschaft beurteilst du gemessen an der festgelegten Nutzung und ihren Anforderungen. Wenn du die Nutzung selbst ändern willst, prüfe zuerst, welche Anforderungen und Prüfungen sich aus dieser Änderung ergeben. Eine umgeschriebene Beschreibung löst kein Konstruktionsproblem.\nWenn ihr die nötigen Bestätigungen habt und keine Hindernisse die angegebene Nutzung blockieren, markiere die Bereitschaft der Version. Vairo sammelt den Eintrag dieser Entscheidung und die verknüpften Nachweise. Die technische Bewertung und die Verantwortung für die Freigabe des Produkts zur Nutzung bleiben bei den zuständigen Personen. Behalte die Verknüpfung mit dieser Version, damit du später weißt, welches Produkt in die erste Nutzung ging und worauf sich erhaltene Rückmeldungen beziehen.","guide_sources":["NASA, Product Transition beschreibt die Übergabe eines geprüften Produkts mit Dokumentation und die Vorbereitung auf seine Nutzung. Your Europe, CE marking erklärt die Pflichten zu passender Dokumentation und Kennzeichnung bei Produkten, die unter CE fallen.","NASA, Product Transition beschreibt die Übergabe eines Produkts auf Grundlage seines Zustands und seiner Dokumentation. NASA, Product Verification erklärt die Prüfung, ob Anforderungen erfüllt sind. Die Art, Bereitschaft zu bestätigen und Nachweise zu verknüpfen, folgt der festgelegten Funktionsweise von Vairo."]},"uk":{"title":"Підготуй продукт до першого використання","guide_body":"5.1. Підготуй потрібний екземпляр і матеріали до використання\nПідготуй кількість екземплярів, що випливає з першого запланованого використання. Це може бути одна інсталяція або кілька штук, які передають адресатам. Використай документацію перевіреної версії. На наступних екземплярах звертай увагу, чи виконавець зберіг погоджений матеріал і спосіб виготовлення. Замінник, запропонований під час складання, може вимагати повторної перевірки конструкції.\nВідокрем результати щодо проєкту від контролю підготовленої штуки. Перевірка конструкції допомагає встановити, чи проєкт відповідає вимогам. Приймання конкретного екземпляра дає змогу вловити помилку його виготовлення, напр. відсутність елемента чи неправильне складання. Обсяг такого контролю має відповідати твоєму продуктові й вимогам із пункту 1. Збережи результат біля екземпляра, якого він стосується.\nДля першого використання обери штуку у відповідному стані. Перевір її історію спроб, особливо коли тести могли її послабити чи пошкодити. Якщо складання й контроль виконують різні люди, передай їм ті самі актуальні матеріали. За самостійної роботи можеш виконати обидві дії, спираючись на записані вимоги й потрібну допомогу фахівця.\nПідготуй інструкцію на основі того, що робитиме користувач. Поясни, як підготувати продукт і як правильно ним користуватися. Опиши обмеження й попередження, що випливають з його конструкції. Якщо спосіб обслуговування важко показати словами, додай фото чи малюнок. Якщо продукт вимагає встановлення, передай відповідну інформацію також людині, яка його виконає.\nДодай документи й позначення, потрібні для цього продукту й запланованого використання, згідно з висновками з підпункту 1.2. Матеріали мають відповідати підготовленій версії. Використай наявні результати й файли. Якщо продукт транспортуватимуть, подбай також про його захист у дорозі, щоб він дістався у стані, що уможливлює передбачене використання.\n5.2. Підтверди готовність зазначеної версії\nТочно вкажи, яка версія готова до визначеного використання. Прикріпи результати її перевірок і матеріали, підготовлені в підпункті 5.1. Людина, яка переглядає цей запис, має могти пов’язати готовий екземпляр із документацією і зрозуміти, на якій підставі ви визнали його готовим.\nПовернися до вимог із пункту 1. Перевір, чи маєте відповідь для кожної з них і чи лишилася проблема, яка унеможливлює передбачене використання. За командної роботи людина, що збирає результати, користується оцінками людей, відповідальних за окремі ділянки. У питаннях, що вимагають спеціальних знань, спирай рішення на відповідну оцінку чи дослідження.\nЯкщо хтось висловлює сумнів, поясни, якої вимоги він стосується і чого бракує для його розв’язання. Наприклад, інформація «бракує результату дослідження після зміни матеріалу» вказує конкретну подальшу роботу. Доки вимоги для запланованого використання лишаються невиконаними, залиш підтвердження порожнім і запиши перешкоду біля відповідної роботи.\nІдеї додаткових функцій можуть залишитися в нотатках на потім. Готовність ти оцінюєш щодо визначеного застосування та його вимог. Якщо хочеш змінити саме застосування, спершу перевір, які вимоги й дослідження випливають із цієї зміни. Саме переписування опису не розв’язує проблеми конструкції.\nКоли маєте потрібні підтвердження і немає перешкод, що блокують зазначене використання, познач готовність версії. Vairo збирає запис цього рішення й пов’язані докази. Технічна оцінка й відповідальність за допуск продукту до використання лишаються за відповідними людьми. Збережи зв’язок із цією версією, щоб пізніше знати, який продукт пішов у перше використання і чого стосуються отримані зауваження.","guide_sources":["NASA, Product Transition описує передачу перевіреного продукту разом із документацією й підготовку до його використання. Your Europe, CE marking пояснює обов’язки щодо належної документації й маркування продуктів, на які поширюється CE.","NASA, Product Transition описує передачу продукту на основі його стану й документації. NASA, Product Verification пояснює перевірку виконання вимог. Спосіб підтвердження готовності й прикріплення доказів випливає з усталеної роботи Vairo."]},"es":{"title":"Prepara el producto para el primer uso","guide_body":"5.1. Prepara la unidad y los materiales necesarios para el uso\nPrepara el número de unidades que exige el primer uso previsto. Puede ser una instalación o varias unidades que se entregan a los destinatarios. Usa la documentación de la versión comprobada. En las unidades siguientes, fíjate en si el proveedor ha mantenido el material y la forma de fabricación acordados. Un sustituto propuesto durante el montaje puede exigir volver a comprobar el diseño.\nSepara los resultados del diseño del control de la unidad preparada. Comprobar el diseño ayuda a saber si cumple los requisitos. Revisar una unidad concreta permite detectar un error de fabricación, como una pieza que falta o un montaje incorrecto. El alcance de ese control debe corresponder a tu producto y a los requisitos del punto 1. Guarda el resultado junto a la unidad a la que se refiere.\nPara el primer uso, elige una unidad en buen estado. Revisa su historial de pruebas, sobre todo si los ensayos pudieron debilitarla o dañarla. Si el montaje y el control los hacen personas distintas, dales los mismos materiales actuales. Si trabajas solo, puedes hacer ambas cosas, apoyándote en los requisitos anotados y en la ayuda especializada necesaria.\nPrepara unas instrucciones a partir de lo que hará el usuario. Explica cómo preparar el producto y cómo usarlo correctamente. Describe las limitaciones y advertencias que se derivan de su diseño. Si el manejo es difícil de explicar con palabras, añade una foto o un dibujo. Si el producto requiere instalación, pasa también la información adecuada a quien la vaya a hacer.\nAñade los documentos y marcados necesarios para este producto y el uso previsto, según lo averiguado en el subpunto 1.2. Los materiales deben corresponder a la versión preparada. Usa los resultados y archivos existentes. Si el producto se va a transportar, protégelo también para el trayecto, de modo que llegue en un estado que permita el uso previsto.\n5.2. Confirma que la versión indicada está lista\nIndica exactamente qué versión está lista para el uso fijado. Vincula los resultados de sus comprobaciones y los materiales preparados en el subpunto 5.1. Quien vea este registro debe poder relacionar la unidad terminada con la documentación y entender en qué os basasteis para darla por lista.\nVuelve a los requisitos del punto 1. Comprueba si tenéis respuesta para cada uno y si queda algún problema que impida el uso previsto. En equipo, quien reúne los resultados se apoya en la valoración de los responsables de cada área. En cuestiones que requieren conocimiento especializado, basa la decisión en una evaluación o un ensayo adecuados.\nSi alguien plantea una duda, aclara a qué requisito se refiere y qué falta para resolverla. Por ejemplo, «falta el resultado del ensayo tras cambiar el material» señala un trabajo concreto. Mientras no se cumplan los requisitos del uso previsto, deja vacía la confirmación y anota el obstáculo en el trabajo correspondiente.\nLas ideas de funciones adicionales pueden quedarse en notas para después. La disponibilidad se valora respecto al uso fijado y sus requisitos. Si quieres cambiar el uso en sí, comprueba primero qué requisitos y ensayos se derivan de ese cambio. Reescribir la descripción no resuelve un problema de diseño.\nCuando tengáis las confirmaciones necesarias y no haya obstáculos que bloqueen el uso indicado, marca que la versión está lista. Vairo recoge el registro de esa decisión y las pruebas vinculadas. La evaluación técnica y la responsabilidad de autorizar el uso del producto siguen correspondiendo a las personas adecuadas. Mantén el vínculo con esta versión para saber después qué producto pasó al primer uso y a qué se refieren los comentarios recibidos.","guide_sources":["NASA, Product Transition describe la entrega de un producto comprobado con su documentación y la preparación para su uso. Your Europe, CE marking explica las obligaciones de documentación y marcado de los productos sujetos a CE.","NASA, Product Transition describe la entrega de un producto según su estado y su documentación. NASA, Product Verification explica cómo comprobar el cumplimiento de los requisitos. La forma de confirmar que está listo y vincular pruebas sigue el funcionamiento acordado de Vairo."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'hardware' and p.key = 'hw-ready';
update public.stage_subpoints s set translations = '{"de":{"title":"Bereite das nötige Exemplar und die Materialien zur Nutzung vor"},"uk":{"title":"Підготуй потрібний екземпляр і матеріали до використання"},"es":{"title":"Prepara la unidad y los materiales necesarios para el uso"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'hardware' and p.key = 'hw-ready' and s.key = 'pack';
update public.stage_fields f set translations = '{"de":{"question":"Welche Exemplare gehen in die Nutzung und welche Anleitungen und Dokumente begleiten sie?","help":"Du kannst Materialien angeben, die beim Bau und beim Test schon genutzt wurden, wenn sie diese Version betreffen."},"uk":{"question":"Які екземпляри йдуть у використання і які інструкції та документи їх супроводжують?","help":"Можеш вказати матеріали, вже використані під час створення й спроби, якщо вони стосуються цієї версії."},"es":{"question":"¿Qué unidades pasan al uso y qué instrucciones y documentos las acompañan?","help":"Puedes indicar materiales ya usados en la construcción y la prueba si se refieren a esta versión."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'hardware' and p.key = 'hw-ready'
    and s.key = 'pack' and f.key = 'control';
update public.stage_subpoints s set translations = '{"de":{"title":"Bestätige die Bereitschaft der angegebenen Version"},"uk":{"title":"Підтверди готовність зазначеної версії"},"es":{"title":"Confirma que la versión indicada está lista"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'hardware' and p.key = 'hw-ready' and s.key = 'confirm';
update public.stage_fields f set translations = '{"de":{"question":"Welche Version bestätigst du?"},"uk":{"question":"Яку версію ти підтверджуєш?"},"es":{"question":"¿Qué versión confirmas?"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'hardware' and p.key = 'hw-ready'
    and s.key = 'confirm' and f.key = 'version';
update public.stage_fields f set translations = '{"de":{"question":"Ist diese Version bereit für die festgelegte Nutzung?","help":"Das Feld bleibt leer, bis du es bestätigst.","config":{"options":[{"value":"ready","label":"Version bereit für die festgelegte Nutzung"}]}},"uk":{"question":"Чи ця версія готова до визначеного використання?","help":"Поле порожнє, доки ти його не підтвердиш.","config":{"options":[{"value":"ready","label":"Версія готова до визначеного використання"}]}},"es":{"question":"¿Está lista esta versión para el uso fijado?","help":"El campo queda vacío hasta que lo confirmes.","config":{"options":[{"value":"ready","label":"Versión lista para el uso fijado"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'hardware' and p.key = 'hw-ready'
    and s.key = 'confirm' and f.key = 'ready';
update public.stage_categories c set translations = '{"de":{"title":"B2B","intro":"Bereite die Übergabe an die Firma vor und übe den Weg vom Start bis zum abgenommenen Ergebnis."},"uk":{"title":"B2B","intro":"Підготуй передачу компанії й відпрацюй шлях від старту до прийнятого результату."},"es":{"title":"B2B","intro":"Prepara la entrega a la empresa y ensaya el camino desde el inicio hasta el resultado recibido."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'execution' and t.version = 1 and c.key = 'b2b';
update public.stage_points p set translations = '{"de":{"title":"Bereite die Lösung für die Nutzung in der Firma vor","guide_body":"1.1. Bereite die erste Übergabe an die Firma vor\nÖffne die Vereinbarungen aus Preparation und wähle die erste Nutzungsweise, für die du das Produkt vorbereitest. Greif auf die notierten Rollen und Anforderungen für den Arbeitsbeginn zurück. Bereite auf dieser Grundlage vor, was du der Firma tatsächlich übergibst. Vielleicht reicht eine kurze Nachricht mit der Adresse des Programms und dem Weg der Datenübergabe. Bei einem Gerät braucht es vielleicht eine Anleitung für die Person, die es am Arbeitsplatz montiert.\nTrenne in dieser Nachricht die Tätigkeiten deines Teams von denen des Kunden. Wenn die Firma eine Datei liefern soll, zeig, wie man sie vorbereitet und wohin man sie schickt. Wenn jemand einen Arbeitsplatz vorbereiten muss, gib ihm die nötigen Informationen vor der Lieferung. Eine fertige Anleitung sollte helfen, die Tätigkeit ohne Raten und ohne Suche in alten Nachrichten zu erledigen.\nAchte auf die Übergabe des Ergebnisses. Zum Beispiel sammelt ein Mitarbeiter Daten und erstellt eine Übersicht, die später die Leitung bekommt. Prüfe, in welcher Form die Leitung diese Übersicht braucht. Bereite das nötige Dokument oder die Freigabe vor und nutze dafür schon in SaaS gebaute Funktionen oder Hardware-Materialien. In einer kleinen Firma kann eine Person diese Aufgaben übernehmen.\nWenn die Firma vorher ein Dokument oder eine Zustimmung genannt hat, die für den Start nötig sind, bereite deinen Teil vor. Nenne, was noch eine Entscheidung des Kunden braucht. Deine eigene Beschreibung ersetzt keine Zustimmung der Firma. Bei einem internen Test kann man eine solche Übergabe nachbilden, die Prüfung der Bedingungen des konkreten Kunden bleibt vor Beginn der Zusammenarbeit trotzdem nötig.\nNenne im Goal ein Ergebnis, z. B. „Vorbereitete Übergabe der Übersicht vom Mitarbeiter an die Leitung“. Der Eigentümer achtet darauf, dass die Materialien zur selben Produktversion passen. Zusätzliche Aufgaben helfen, wenn verschiedene Personen die Anleitung und das Produktelement vorbereiten. Nachweis sind fertige Materialien, die bei der ersten Zusammenarbeit genutzt werden können.","guide_sources":["GOV.UK, Solve a whole problem for users (den ganzen Ablauf an die Arbeit der Zielperson anpassen); Paul Graham, Do Things that Don’t Scale (persönliche Hilfe für die ersten Firmen und ein einfacher Start)."]},"uk":{"title":"Підготуй рішення до використання в компанії","guide_body":"1.1. Підготуй першу передачу компанії\nВідкрий домовленості з Preparation і обери перший спосіб використання, до якого готуєш продукт. Звернися до записаних ролей і вимог початку роботи. На їх основі підготуй те, що справді передаси компанії. Може вистачити короткого повідомлення з адресою програми й способом передачі даних. Для пристрою може знадобитися інструкція для людини, яка монтуватиме його на робочому місці.\nУ цьому повідомленні відокрем дії своєї команди від дій клієнта. Якщо компанія має надати файл, покажи, як його підготувати і куди передати. Якщо хтось має підготувати робоче місце, дай йому потрібну інформацію до доставки. Готова інструкція має допомогти виконати дію без здогадок і пошуку відповідей у давніх повідомленнях.\nЗверни увагу на передачу результату. Наприклад, працівник може зібрати дані й підготувати звіт, який пізніше отримає керівник. Перевір, у якій формі керівникові потрібен цей звіт. Підготуй потрібний документ чи спосіб надання, користуючись функціями, уже створеними в SaaS, або матеріалами Hardware. У малій компанії ці завдання може виконувати одна людина.\nЯкщо компанія раніше вказала документ чи згоду, потрібні для початку, підготуй свою частину. Вкажи, що ще потребує рішення клієнта. Власний опис не замінює згоди компанії. Під час внутрішньої спроби можна відтворити таку передачу, але перевірка умов конкретного клієнта лишається потрібною перед початком співпраці.\nУ Goal вкажи один результат, напр. «Підготовлена передача звіту від працівника до керівника». Власник пильнує, щоб матеріали відповідали тій самій версії продукту. Додаткові завдання корисні, коли інструкцію й елемент продукту готують різні люди. Доказом є готові матеріали, які можна використати під час першої співпраці.","guide_sources":["GOV.UK, Solve a whole problem for users (пристосування всього перебігу до роботи адресата); Paul Graham, Do Things that Don’t Scale (особиста допомога першим компаніям і простий спосіб початку)."]},"es":{"title":"Prepara la solución para su uso en la empresa","guide_body":"1.1. Prepara la primera entrega a la empresa\nAbre lo acordado en Preparation y elige el primer uso para el que preparas el producto. Recurre a los roles anotados y a los requisitos para empezar. Con eso, prepara lo que de verdad entregarás a la empresa. Puede bastar un mensaje breve con la dirección del programa y la forma de pasar los datos. Con un dispositivo puede hacer falta una instrucción para quien lo instale en el puesto de trabajo.\nEn ese mensaje, separa las tareas de tu equipo de las del cliente. Si la empresa tiene que aportar un archivo, muestra cómo prepararlo y dónde enviarlo. Si alguien tiene que preparar un puesto, dale la información necesaria antes de la entrega. Unas instrucciones listas deben ayudar a hacer la tarea sin adivinar ni buscar respuestas en mensajes antiguos.\nFíjate en la entrega del resultado. Por ejemplo, un empleado puede reunir datos y preparar un resumen que luego recibe su responsable. Comprueba en qué formato necesita el responsable ese resumen. Prepara el documento o la forma de compartirlo, usando funciones ya construidas en SaaS o materiales de Hardware. En una empresa pequeña, estas tareas puede hacerlas una sola persona.\nSi la empresa indicó antes un documento o un permiso necesario para empezar, prepara tu parte. Señala qué sigue necesitando una decisión del cliente. Tu propia descripción no sustituye el visto bueno de la empresa. En una prueba interna se puede simular esa entrega, pero comprobar las condiciones del cliente concreto sigue siendo necesario antes de empezar a colaborar.\nEn el Goal indica un resultado, p. ej. «Entrega preparada del resumen del empleado al responsable». El responsable del Goal vela por que los materiales correspondan a la misma versión del producto. Las tareas adicionales sirven cuando las instrucciones y el elemento del producto los preparan personas distintas. La prueba son los materiales listos para usar en la primera colaboración.","guide_sources":["GOV.UK, Solve a whole problem for users (ajustar todo el recorrido al trabajo del destinatario); Paul Graham, Do Things that Don’t Scale (ayuda personal a las primeras empresas y una forma sencilla de empezar)."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'b2b' and p.key = 'b2b-hand';
update public.stage_subpoints s set translations = '{"de":{"title":"Bereite die erste Übergabe an die Firma vor"},"uk":{"title":"Підготуй першу передачу компанії"},"es":{"title":"Prepara la primera entrega a la empresa"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'b2b' and p.key = 'b2b-hand' and s.key = 'pack';
update public.stage_fields f set translations = '{"de":{"question":"Ziel mit fertigen Materialien für den Start und die Übergabe des Ergebnisses.","config":{"label":"Ziele öffnen"}},"uk":{"question":"Ціль із готовими матеріалами для початку й передачі результату.","config":{"label":"Відкрити цілі"}},"es":{"question":"Objetivo con los materiales listos para empezar y entregar el resultado.","config":{"label":"Abrir objetivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'b2b' and p.key = 'b2b-hand'
    and s.key = 'pack' and f.key = 'open';
update public.stage_points p set translations = '{"de":{"title":"Prüfe die Nutzung der Lösung in der Arbeit der Firma","guide_body":"2.1. Übe den Ablauf vom Start bis zum abgenommenen Ergebnis\nNimm ein konkretes Beispiel aus früheren Gesprächen. Bei einem Berichtswerkzeug kann das die Erstellung einer Wochenübersicht durch einen Mitarbeiter und ihre Abnahme durch die Leitung sein. Bei einer Dienstleistung führe einen Probeumfang der Arbeit aus und bereite das Ergebnis vor, das die Firma abnehmen würde. Verlangt ist eine funktionierende Version; die bloße Beschreibung eines künftigen Ablaufs zeigt nicht, ob man ihn durchlaufen kann.\nTeile den Test danach auf, wer den nächsten Schritt macht. Eine Person kann mehrere Rollen spielen, wenn du allein arbeitest. Halte bei jeder Übergabe an und prüfe, ob die nächste Person das nötige Material hat und versteht, was sie damit tun soll. Ein häufiges Problem ist ein Ergebnis, das entstanden ist, aber bei der falschen Person landet oder sich nicht weiterverwenden lässt.\nDu kannst eine Vertreterin der Firma einladen. Gib ihr eine Aufgabe, die ihrer Arbeit entspricht, und beobachte, wo sie eine Erklärung braucht. Wenn die Beteiligung des Kunden jetzt nicht möglich ist, mach einen internen Test und beschreibe ihn so. Ein solcher Eintrag zeigt die Prüfung des vorbereiteten Ablaufs. Die Passung zu den Bedingungen einer konkreten Firma bestätigst du während der Zusammenarbeit.\nBerücksichtige die Hilfe, die du am Anfang leisten willst. Wenn du die Lösung für jede Firma persönlich einrichtest, führe auch diesen Teil des Tests aus. Bewahre nützliche Einstellungen oder eine Anleitung auf. Wenn die Arbeit zwischen deinen Mitarbeitenden wechselt, vereinbart, wer welchen Teil übernimmt und wo das Ergebnis liegt. Eine Person ist dafür verantwortlich, das ganze Goal abzuschließen.\nNotiere im Proof Beispiel, Version und Ergebnis. Der Satz „Der Mitarbeiter hat die Übersicht erstellt, aber die Leitung konnte die Datei nicht öffnen“ zeigt eine konkrete Korrektur. Wiederhole nach der Änderung den nötigen Teil. Ein negatives Ergebnis erlaubt es, ein Goal zur Durchführung eines Tests abzuschließen; die Bereitschaft in 2.2 verlangt, dass Hindernisse im festgelegten Ablauf beseitigt sind.\n2.2. Bestätige die Bereitschaft für die erste Nutzung in der Firma\nGeh die fertigen Materialien und das Testergebnis für die angegebene Version durch. Prüfe, ob die Firma die nötigen Vorbereitungen treffen kann, ob der Mitarbeiter das Ergebnis bekommt und ob es weiter dorthin gelangt, wo es gebraucht wird. Nutze vorhandene Dateien. Diese Bestätigung verlangt keine weitere Zusammenfassung des ganzen Projekts.\nVereinbare mit der Person, die den Test geleitet hat, ob Hindernisse bleiben, die eine solche Nutzung verhindern. Fehlende Startmaterialien oder eine nicht erfolgte Übergabe des Ergebnisses müssen nachgeholt werden. Die Idee, eine weitere Abteilung zu bedienen, kann warten, wenn die aktuelle Version einem Team dienen soll. Beurteile den Umfang nach den früheren Vereinbarungen.\nWenn sich nach dem Test die Produktversion oder die Art der Übergabe geändert hat, kläre, was erneut geprüft werden muss. Verknüpfe das neue Ergebnis mit derselben Arbeit und bewahre den früheren Eintrag auf. Nutze bei Fragen, die eine technische Bewertung erfordern, eine passende ausführende Person. Produktspezifische Anforderungen gelten weiterhin in den übrigen gewählten Kategorien.\nDie Bestätigung betrifft die Bereitschaft für die erste festgelegte Nutzung. Sie verlangt keinen unterschriebenen Vertrag, keinen zahlenden Kunden und keinen Nachweis steigender Verkäufe. Ein interner Test bleibt als intern gekennzeichnet. In der MVP Stage lässt sich prüfen, wie die Lösung unter weiteren Bedingungen bei Zielpersonen funktioniert und was verbessert werden muss.","guide_sources":["GOV.UK, Using moderated usability testing (Test an einer konkreten Aufgabe und Beobachtung der Schwierigkeiten der teilnehmenden Person); GOV.UK, Provide a joined up experience across all channels (Prüfung der Arbeitsübergabe zwischen Personen und Kontaktwegen).","GOV.UK, How the beta phase works (schrittweise Bereitstellung des vorbereiteten Dienstes und weitere Verbesserungen)."]},"uk":{"title":"Перевір використання рішення в роботі компанії","guide_body":"2.1. Відпрацюй перебіг від початку до отримання результату\nВізьми один конкретний приклад із попередніх розмов. Для інструмента звітів це може бути підготовка тижневого звіту працівником і його отримання керівником. Для послуги виконай пробний обсяг роботи й підготуй результат, який компанія мала б прийняти. Потрібна робоча версія; сам опис майбутнього перебігу не показує, чи можна через нього пройти.\nПоділи спробу за тим, хто робить наступну річ. Одна людина може грати кілька ролей, якщо працюєш сам. Зупиняйся на кожній передачі й перевіряй, чи наступний отримувач має потрібний матеріал і розуміє, що з ним робити. Часта проблема — результат, який з’явився, але потрапив не до тієї людини або не придатний для подальшого використання.\nМожеш запросити представника компанії. Дай йому завдання, що відповідає його роботі, і спостерігай, де йому потрібне пояснення. Коли участь клієнта зараз неможлива, проведи внутрішню спробу й так її і опиши. Такий запис показує перевірку підготовленого перебігу. Відповідність умовам конкретної компанії підтвердиш під час співпраці.\nВрахуй допомогу, яку збираєшся надавати на початку. Якщо кожній компанії особисто налаштовуєш рішення, виконай і цей фрагмент спроби. Збережи корисні налаштування чи інструкцію. Якщо робота переходить між твоїми співпрацівниками, домовтеся, хто приймає який фрагмент і де знайде результат. Одна людина відповідає за доведення всього Goal до кінця.\nУ proof запиши приклад, версію й результат. Речення «Працівник підготував звіт, але керівник не зміг відкрити файл» вказує конкретне виправлення. Після зміни повтори потрібний фрагмент. Негативний результат дає змогу завершити Goal щодо проведення спроби; готовність у 2.2 вимагає усунення перешкод у визначеному перебігу.\n2.2. Підтверди готовність до першого використання в компанії\nПерегляньте готові матеріали й результат спроби для зазначеної версії. Перевір, чи компанія може виконати потрібну підготовку, чи працівник отримає результат і чи потрапить він далі туди, де потрібен. Користуйся наявними файлами. Це підтвердження не вимагає писати ще один підсумок усього проєкту.\nДомовся з людиною, що проводила спробу, чи лишилися перешкоди, які унеможливлюють таке використання. Відсутність стартових матеріалів чи невиконана передача результату потребують завершення. Ідея обслуговування наступного відділу може зачекати, якщо поточна версія має служити одній команді. Оцінюй обсяг відповідно до попередніх домовленостей.\nЯкщо після спроби змінилася версія продукту чи спосіб передачі, визнач, що треба перевірити знову. Прикріпи новий результат до тієї самої роботи й збережи попередній запис. У питаннях, що вимагають технічної оцінки, скористайся відповідним виконавцем. Вимоги, властиві продуктові, і далі діють в інших обраних категоріях.\nПідтвердження стосується готовності до першого визначеного використання. Воно не вимагає підписаного договору, клієнта, що платить, чи доказу зростання продажів. Внутрішня спроба лишається позначеною як внутрішня. У MVP Stage можна буде перевірити, як рішення працює в інших умовах у адресатів і що треба виправити.","guide_sources":["GOV.UK, Using moderated usability testing (спроба на конкретному завданні й спостереження труднощів учасника); GOV.UK, Provide a joined up experience across all channels (перевірка передачі роботи між людьми й способами контакту).","GOV.UK, How the beta phase works (поступове надання підготовленої послуги й подальші виправлення)."]},"es":{"title":"Comprueba el uso de la solución en el trabajo de la empresa","guide_body":"2.1. Ensaya el recorrido desde el inicio hasta recibir el resultado\nUsa un ejemplo concreto de conversaciones anteriores. En una herramienta de informes puede ser que un empleado prepare el resumen semanal y su responsable lo reciba. En un servicio, haz un trabajo de prueba y prepara el resultado que la empresa debería recibir. Hace falta una versión que funcione; describir el recorrido futuro no demuestra que se pueda completar.\nDivide la prueba según quién hace el siguiente paso. Si trabajas solo, una persona puede hacer varios papeles. Detente en cada entrega y comprueba que el siguiente destinatario tiene el material necesario y entiende qué hacer con él. Un problema frecuente es un resultado que se ha hecho pero llega a la persona equivocada o no sirve para seguir.\nPuedes invitar a alguien de la empresa. Dale una tarea propia de su trabajo y observa dónde necesita explicaciones. Si ahora no es posible que participe el cliente, haz una prueba interna y descríbela como tal. Ese registro muestra la comprobación del recorrido preparado. El encaje con las condiciones de una empresa concreta lo confirmarás durante la colaboración.\nTen en cuenta la ayuda que piensas dar al principio. Si configuras la solución en persona para cada empresa, haz también esa parte de la prueba. Guarda los ajustes o las instrucciones útiles. Si el trabajo pasa entre tus colaboradores, acordad quién recibe cada parte y dónde encontrará el resultado. Una persona es responsable de llevar todo el Goal hasta el final.\nAnota en el proof el ejemplo, la versión y el resultado. La frase «El empleado preparó el resumen, pero el responsable no pudo abrir el archivo» señala una corrección concreta. Tras el cambio, repite la parte necesaria. Un resultado negativo permite cerrar un Goal de hacer una prueba; estar listo en 2.2 exige eliminar los obstáculos del recorrido fijado.\n2.2. Confirma que está listo para el primer uso en la empresa\nRevisa los materiales preparados y el resultado de la prueba para la versión indicada. Comprueba si la empresa puede hacer los preparativos necesarios, si el empleado recibirá el resultado y si este llegará después a donde hace falta. Usa los archivos existentes. Esta confirmación no exige escribir otro resumen de todo el proyecto.\nAcuerda con quien llevó la prueba si quedan obstáculos que impidan ese uso. Si faltan materiales de inicio o no se hizo la entrega del resultado, hay que completarlo. La idea de atender a otro departamento puede esperar si la versión actual es para un solo equipo. Valora el alcance según lo acordado antes.\nSi tras la prueba cambió la versión del producto o la forma de entrega, determina qué hay que volver a comprobar. Vincula el nuevo resultado al mismo trabajo y guarda el registro anterior. En asuntos que requieran valoración técnica, recurre a la persona adecuada. Los requisitos propios del producto siguen vigentes en las demás categorías elegidas.\nLa confirmación se refiere a estar listo para el primer uso fijado. No exige un contrato firmado, un cliente que pague ni una prueba de aumento de ventas. Una prueba interna sigue marcada como interna. En la MVP Stage se podrá comprobar cómo funciona la solución en otras condiciones con los destinatarios y qué hay que mejorar.","guide_sources":["GOV.UK, Using moderated usability testing (prueba con una tarea concreta y observación de las dificultades del participante); GOV.UK, Provide a joined up experience across all channels (comprobación de la entrega del trabajo entre personas y canales de contacto).","GOV.UK, How the beta phase works (puesta a disposición gradual del servicio preparado y mejoras posteriores)."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'b2b' and p.key = 'b2b-try';
update public.stage_subpoints s set translations = '{"de":{"title":"Übe den Ablauf vom Start bis zum abgenommenen Ergebnis"},"uk":{"title":"Відпрацюй перебіг від початку до отримання результату"},"es":{"title":"Ensaya el recorrido desde el inicio hasta recibir el resultado"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'b2b' and p.key = 'b2b-try' and s.key = 'trial';
update public.stage_fields f set translations = '{"de":{"question":"Testnachweis: vom Arbeitsstart der Firma bis zum abgenommenen Ergebnis.","config":{"label":"Ziele öffnen"}},"uk":{"question":"Доказ спроби: від початку роботи компанії до отриманого результату.","config":{"label":"Відкрити цілі"}},"es":{"question":"Prueba del ensayo: desde que la empresa empieza hasta que recibe el resultado.","config":{"label":"Abrir objetivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'b2b' and p.key = 'b2b-try'
    and s.key = 'trial' and f.key = 'open';
update public.stage_subpoints s set translations = '{"de":{"title":"Bestätige die Bereitschaft für die erste Nutzung in der Firma"},"uk":{"title":"Підтверди готовність до першого використання в компанії"},"es":{"title":"Confirma que está listo para el primer uso en la empresa"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'b2b' and p.key = 'b2b-try' and s.key = 'ready';
update public.stage_fields f set translations = '{"de":{"question":"Welche Version bestätigst du?"},"uk":{"question":"Яку версію ти підтверджуєш?"},"es":{"question":"¿Qué versión confirmas?"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'b2b' and p.key = 'b2b-try'
    and s.key = 'ready' and f.key = 'version';
update public.stage_fields f set translations = '{"de":{"question":"Ist diese Version bereit für die erste Nutzung in der Firma?","help":"Das Feld bleibt leer, bis du es bestätigst.","config":{"options":[{"value":"ready","label":"Bereit für die erste Nutzung in der Firma"}]}},"uk":{"question":"Чи ця версія готова до першого використання в компанії?","help":"Поле порожнє, доки ти його не підтвердиш.","config":{"options":[{"value":"ready","label":"Готово до першого використання в компанії"}]}},"es":{"question":"¿Está lista esta versión para el primer uso en la empresa?","help":"El campo queda vacío hasta que lo confirmes.","config":{"options":[{"value":"ready","label":"Listo para el primer uso en la empresa"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'b2b' and p.key = 'b2b-try'
    and s.key = 'ready' and f.key = 'ready';
update public.stage_categories c set translations = '{"de":{"title":"B2C","intro":"Bereite das Angebot für Verbraucher vor und übe den Weg vom Erhalt des Produkts bis zur Meldung eines Problems."},"uk":{"title":"B2C","intro":"Підготуй пропозицію для споживача й відпрацюй шлях від отримання продукту до повідомлення про проблему."},"es":{"title":"B2C","intro":"Prepara la oferta para el consumidor y ensaya el camino desde que recibe el producto hasta que avisa de un problema."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'execution' and t.version = 1 and c.key = 'b2c';
update public.stage_points p set translations = '{"de":{"title":"Bereite das Angebot für Verbraucher vor","guide_body":"1.1. Stelle die nötigen Informationen dort bereit, wo gewählt wird\nBereite das Material vor, das du bei der ersten Bestellung oder Anmeldung nutzt. Beginne damit, was Kunden bekommen und wann sie es nutzen können. Beschreibe die aktuelle Version entsprechend ihren Möglichkeiten. Wenn das Produkt erst später fertig wird, sag das klar. Es reicht der Ort, der für Kontakt oder Verkauf schon gewählt ist, z. B. ein Angebot auf einer bestehenden Plattform oder eine Nachricht an Kunden.\nNutze den früheren Preis und ergänze die nötigen Bedingungen. Bei einer konkreten Bestellung sollten Kunden wissen, wie viel sie insgesamt zahlen, einschließlich verpflichtender Versandkosten. Wenn sich der Preis vorab nicht vernünftig berechnen lässt, prüfe die einschlägigen Informationspflichten und gib an, wie er berechnet wird. Zeig bei einer wiederkehrenden Gebühr den Abrechnungszeitraum, die Kündigungsbedingungen und eine etwaige Mindestlaufzeit.\nPasse die Informationen an die Art des Vertragsschlusses an. Ein Onlineverkauf kann andere Informationen erfordern als ein Verkauf vor Ort. Für Polen nutze die unten genannten Seiten des UOKiK; in anderen Ländern die Informationen der zuständigen Verbraucherschutzbehörde. Ergänze die passenden Verkäuferangaben, den Kontakt und die Regeln für Reklamationen. Prüfe auch das Widerrufsrecht, also die Möglichkeit, in bestimmten Situationen vom Vertrag zurückzutreten. Umfang und Ausnahmen dieses Rechts hängen vom Angebot ab. Vermeide es, die AGB eines Shops zu kopieren, der ein ganz anderes Produkt verkauft.\nPrüfe bei einer elektronischen Bestellung mit Zahlungspflicht auch, ob Kunden eindeutig sehen, dass sie zahlungspflichtig bestellen. Die nötigen Informationen müssen im richtigen Moment erscheinen. Ein Dokument, das bei dir liegt, bedeutet nicht, dass Kunden es erhalten haben. Eine fertige Verkaufsplattform bietet vielleicht einen Teil der nötigen Funktionen; prüfe deine Konfiguration und den eingetragenen Text.\nWeise das Goal einer Person zu, die das fertige Angebot zusammenstellt. Den Text kann eine Person vorbereiten, das Einbinden bei der Bestellung eine andere. Rechtsfragen, die geklärt werden müssen, gib an eine passende Fachperson. Bewahre als Proof den verwendeten Text und seinen Ort auf. So löscht eine spätere Änderung der Seite nicht die Information darüber, was geprüft wurde.","guide_sources":["UOKiK, Prawo do informacji (klare Informationen passend zur Art des Vertragsschlusses); UOKiK, Sprzedaż poza lokalem i na odległość (Preis, Angebotsbedingungen und Informationen beim Fernabsatz); UOKiK, Odstąpienie od umowy (Widerruf vom Vertrag und Situationen, in denen die passenden Regeln geprüft werden müssen)."]},"uk":{"title":"Підготуй пропозицію для споживача","guide_body":"1.1. Розмісти потрібну інформацію в місці вибору\nПідготуй матеріал, який використаєш при першому замовленні чи записі. Почни з того, що отримає клієнт і коли зможе цим скористатися. Опиши поточну версію відповідно до її можливостей. Якщо продукт буде готовий пізніше, скажи це чітко. Досить місця, вже обраного для контакту чи продажу, напр. пропозиції на наявній платформі або повідомлення клієнтові.\nВикористай попередню ціну й допиши потрібні умови. Для конкретного замовлення клієнт має знати, скільки заплатить разом, зокрема які обов’язкові витрати на доставку понесе. Якщо ціну неможливо розумно обчислити заздалегідь, перевір відповідні інформаційні обов’язки й вкажи спосіб її обчислення. За поновлюваної оплати покажи період розрахунку, умови припинення й можливий мінімальний строк зобов’язання.\nДобери інформацію до способу укладення договору. Продаж через інтернет може вимагати передачі іншої інформації, ніж продаж на місці. Для Польщі скористайся вказаними нижче сторінками UOKiK; в інших країнах — інформацією відповідного органу захисту прав споживачів. Доповни відповідні дані продавця, контакт і правила щодо рекламацій. Перевір також право відмови, тобто можливість відмовитися від договору в певних ситуаціях. Обсяг цього права й винятки залежать від пропозиції. Уникай копіювання правил магазину, що продає зовсім інший продукт.\nДля електронного замовлення з обов’язком оплати перевір також, чи клієнт однозначно бачить, що замовляє з обов’язком оплати. Потрібна інформація має з’являтися в потрібний момент. Документ, що зберігається в тебе, не означає, що клієнт його отримав. Готова платформа продажів може забезпечувати частину потрібних функцій; перевір свою конфігурацію й вписаний текст.\nПризнач Goal людині, яка збере готову пропозицію. Текст може підготувати одна людина, а розмістити його при замовленні — інша. Правові питання, що потребують з’ясування, передай відповідному фахівцеві. Як proof збережи використаний текст і місце його розміщення. Так пізніша зміна сторінки не видалить інформації про те, що перевірено.","guide_sources":["UOKiK, Prawo do informacji (чітка інформація, пристосована до способу укладення договору); UOKiK, Sprzedaż poza lokalem i na odległość (ціна, умови пропозиції та інформація при дистанційному продажу); UOKiK, Odstąpienie od umowy (відмова від договору та ситуації, що вимагають перевірки відповідних правил)."]},"es":{"title":"Prepara la oferta para el consumidor","guide_body":"1.1. Pon la información necesaria donde se elige\nPrepara el material que usarás en el primer pedido o registro. Empieza por lo que recibirá el cliente y cuándo podrá usarlo. Describe la versión actual según lo que permite hacer. Si el producto estará listo más tarde, dilo con claridad. Basta con el lugar ya elegido para el contacto o la venta, por ejemplo una oferta en una plataforma existente o un mensaje al cliente.\nUsa el precio anterior y añade las condiciones necesarias. En un pedido concreto, el cliente debe saber cuánto pagará en total, incluidos los gastos de envío obligatorios. Si el precio no puede calcularse razonablemente de antemano, revisa las obligaciones de información aplicables e indica cómo se calcula. Con un pago recurrente, muestra el periodo de facturación, las condiciones de baja y, si existe, la permanencia mínima.\nAjusta la información a la forma de celebrar el contrato. La venta por internet puede exigir dar información distinta que la venta en persona. Para Polonia, usa las páginas de la UOKiK indicadas abajo; en otros países, la información de la autoridad de consumo competente. Completa los datos del vendedor, el contacto y las normas sobre reclamaciones. Comprueba también el derecho de desistimiento, es decir, la posibilidad de retirarse del contrato en determinadas situaciones. Su alcance y sus excepciones dependen de la oferta. Evita copiar las condiciones de una tienda que vende un producto totalmente distinto.\nEn un pedido electrónico con obligación de pago, comprueba también que el cliente ve claramente que el pedido implica pagar. La información necesaria debe aparecer en el momento adecuado. Que tú guardes un documento no significa que el cliente lo haya recibido. Una plataforma de venta ya hecha puede cubrir parte de las funciones necesarias; revisa tu configuración y el texto introducido.\nAsigna el Goal a quien vaya a reunir la oferta final. Una persona puede preparar el texto y otra colocarlo en el pedido. Las cuestiones legales que haya que aclarar, pásaselas al especialista adecuado. Guarda como proof el texto usado y dónde está. Así, un cambio posterior de la página no borrará la información de lo que se comprobó.","guide_sources":["UOKiK, Prawo do informacji (información clara ajustada a la forma de celebrar el contrato); UOKiK, Sprzedaż poza lokalem i na odległość (precio, condiciones de la oferta e información en la venta a distancia); UOKiK, Odstąpienie od umowy (desistimiento del contrato y situaciones que exigen comprobar las normas aplicables)."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'b2c' and p.key = 'b2c-offer';
update public.stage_subpoints s set translations = '{"de":{"title":"Stelle die nötigen Informationen dort bereit, wo gewählt wird"},"uk":{"title":"Розмісти потрібну інформацію в місці вибору"},"es":{"title":"Pon la información necesaria donde se elige"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'b2c' and p.key = 'b2c-offer' and s.key = 'place';
update public.stage_fields f set translations = '{"de":{"question":"Ziel mit fertigem Angebot am Ort der Wahl.","config":{"label":"Ziele öffnen"}},"uk":{"question":"Ціль із готовою пропозицією в місці вибору.","config":{"label":"Відкрити цілі"}},"es":{"question":"Objetivo con la oferta lista donde se elige.","config":{"label":"Abrir objetivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'b2c' and p.key = 'b2c-offer'
    and s.key = 'place' and f.key = 'open';
update public.stage_points p set translations = '{"de":{"title":"Prüfe den ganzen Weg der Kunden","guide_body":"2.1. Übe den Erhalt des Produkts und die Meldung eines Problems\nWähle ein Angebot, das du am Anfang bereitstellen willst. Geh es so durch wie ein neuer Kunde: vom Lesen der Beschreibung bis zum Erhalt des versprochenen Ergebnisses. Prüfe bei einer digitalen Datei, ob sie ankommt und sich öffnen lässt. Bereite bei einem physischen Produkt eine Testbestellung vor und prüfe, ob das richtige Exemplar übergeben wird. Führe bei einer Dienstleistung einen Test im versprochenen Umfang durch.\nBeobachte auch die Arbeit auf deiner Seite. Wenn eine Bestellung bei einer Person eingeht und eine andere das Produkt übergibt, prüfe, ob die zweite die nötigen Informationen bekommt. Bei wenigen Kunden kannst du einen Teil der Abwicklung von Hand erledigen. Übe den gewählten Weg und berücksichtige die Arbeit, die Kunden nicht sehen.\nNutze bei einem Zahlungsanbieter den vom Anbieter beschriebenen Testmodus. Bei Stripe dienen dazu die Testumgebung und Testzahlungsdaten. Wenn eine passende Prüfung schon im SaaS-Teil gemacht wurde, verknüpfe dieses Ergebnis und ergänze hier nur fehlende Teile des Verbraucherwegs. Achte darauf, ob Kunden die richtige Bestätigung erhalten und ob die Bestellung bei der Abwicklung ankommt.\nSchick dann eine Beispielmeldung über den angegebenen Kontakt. Prüfe, wer sie erhält und wie daraus eine Antwort oder die nötige Handlung wird. Eine Reklamation betrifft ein Problem mit der gekauften Leistung; ein Widerruf kann eine andere Grundlage und einen anderen Ablauf haben. Wähle für den Test eine Situation, die dein Produkt betrifft, und wende die passenden Regeln an. Ein normales Kontaktpostfach kann für die erste Abwicklung reichen, wenn jemand es prüft und sich um die Sache kümmern kann.\nDu kannst eine Person außerhalb des Teams bitten, den vorbereiteten Weg durchzugehen. Beobachte, wo sie eine zusätzliche Erklärung braucht. Notiere bei einem eigenen Test, wer ihn gemacht hat; schließ daraus nicht, dass jeder das Angebot versteht. Bewahre in einem Goal das Ergebnis des Produkterhalts, den Meldetest und gefundene Probleme auf. Ein negatives Ergebnis ist eine abgeschlossene Prüfung, braucht aber vor 2.2 eine passende Korrektur.\n2.2. Bestätige die Bereitschaft, den ersten Kunden zu bedienen\nVergleiche das Angebot mit dem Testergebnis. Das Versprechen, eine Datei sofort nach der Bestellung zu liefern, sollte dem entsprechen, was Kunden bekommen. Wenn du menschliche Hilfe und mehr Zeit brauchst, sollte das Angebot das berücksichtigen. Prüfe ebenso Preis, Umfang der ersten Version und den Nutzungsbeginn.\nGeh die gefundenen Probleme durch. Ein falscher Betrag bei der Bestellung, fehlendes versprochenes Material oder ein nicht funktionierender Kontakt müssen vor der Bestätigung behoben werden. Eine zusätzliche Produktvariante oder ein Empfehlungsprogramm können warten. Du beurteilst die Bereitschaft des gewählten Starts, also nutze den festgelegten Umfang.\nWiederhole nach einer Korrektur den Teil, den die Änderung betraf, und füge das Ergebnis derselben Arbeit bei. Wenn das Angebot nach dem Test geändert wurde, prüfe, ob das Ergebnis noch zu seinem Inhalt passt. Eine Person, die die Materialien sammelt, kann Abweichungen zwischen dem Versprechen der Beschreibung und dem Vorbereiteten finden.\nBestätige die Bereitschaft, wenn du die nötigen Nachweise hast und Hindernisse gelöst sind. Dieser Eintrag bestätigt weder Nachfrage noch die Wirksamkeit von Werbung. In der MVP Stage stellst du die erste Version Zielpersonen bereit und prüfst ihre Nutzung. Materialien und Goals bleiben am selben Ort, sodass sich Rückmeldungen nach dem Start einer konkreten Version zuordnen lassen.","guide_sources":["GOV.UK, Make the service simple to use (prüfen, ob die Zielperson die nötige Aufgabe erledigen kann); Stripe, Testing (Zahlungen in der dafür vorgesehenen Umgebung testen); UOKiK, Reklamacja (eine Meldung zu einem Problem mit dem Kauf erkennen).","UOKiK, Prawo do informacji (Richtigkeit und Verständlichkeit der Informationen für Verbraucher); GOV.UK, How the beta phase works (begrenzter Start der Bereitstellung eines Dienstes und weitere Verbesserungen)."]},"uk":{"title":"Перевір увесь шлях клієнта","guide_body":"2.1. Відпрацюй отримання продукту й повідомлення про проблему\nОбери одну пропозицію, яку хочеш надати на початку. Пройди її так, як зробить новий клієнт: від прочитання опису до отримання обіцяного результату. Для цифрового файла перевір його отримання й відкриття. Для фізичного продукту підготуй пробне замовлення й перевір передачу правильного екземпляра. Для послуги виконай спробу в обіцяному обсязі.\nСпостерігай також за роботою на своєму боці. Якщо замовлення надходить до однієї людини, а продукт передає інша, перевір, чи друга отримує потрібну інформацію. За невеликої кількості клієнтів частину обслуговування можна виконувати вручну. Відпрацюй обраний спосіб, враховуючи роботу, якої клієнт не бачить.\nДля платіжного шлюзу користуйся тестовим режимом, описаним постачальником. У Stripe для цього є тестове середовище й тестові платіжні дані. Якщо відповідну перевірку виконано в SaaS, прикріпи цей результат, а тут доповни лише відсутні елементи шляху споживача. Зверни увагу, чи клієнт отримує правильне підтвердження і чи замовлення потрапляє до обробки.\nДалі надішли прикладове звернення через вказаний контакт. Перевір, хто його отримує і як доводить до відповіді чи потрібної дії. Рекламація стосується проблеми з купленою послугою; відмова від договору може мати іншу підставу й перебіг. Обери для спроби ситуацію, що стосується твого продукту, і застосуй відповідні правила. Звичайна контактна скринька може вистачити для першого обслуговування, якщо хтось її перевіряє й уміє зайнятися справою.\nМожеш попросити людину поза командою пройти підготовлений шлях. Спостерігай, де їй потрібне додаткове пояснення. За самостійної спроби запиши, хто її виконав; не роби з неї висновку, що кожен зрозуміє пропозицію. В одному Goal збережи результат отримання продукту, спробу звернення й виявлені проблеми. Негативний результат — це завершена перевірка, але перед 2.2 він потребує відповідного виправлення.\n2.2. Підтверди готовність обслужити першого клієнта\nПорівняй пропозицію з результатом спроби. Обіцянка надати файл одразу після замовлення має відповідати тому, що клієнт отримає. Якщо потрібна допомога людини й більше часу, пропозиція має це враховувати. Так само перевір ціну, обсяг першої версії й спосіб початку користування.\nПереглянь знайдені проблеми. Неправильна сума при замовленні, відсутність обіцяного матеріалу чи непрацюючий контакт потребують виправлення перед підтвердженням. Додатковий варіант продукту чи програма рекомендацій можуть зачекати. Ти оцінюєш готовність обраного початку, тож користуйся визначеним обсягом.\nПісля виправлення повтори фрагмент, якого стосувалася зміна, і додай результат до тієї самої роботи. Якщо пропозицію змінили після спроби, перевір, чи результат і далі відповідає її змісту. Призначення однієї людини для збирання матеріалів дає змогу вловити розбіжність між тим, що обіцяє опис, і тим, що підготував виконавець.\nПідтверди готовність, коли маєш потрібні докази й розв’язані перешкоди. Цей запис не підтверджує ні попиту, ні ефективності реклами. У MVP Stage ти надаси першу версію адресатам і перевіриш, як вони нею користуються. Матеріали й Goals залишаться в тому самому місці, тож зауваження після старту можна буде пов’язати з конкретною версією.","guide_sources":["GOV.UK, Make the service simple to use (перевірка, чи адресат уміє виконати потрібне завдання); Stripe, Testing (тестування платежів у призначеному для цього середовищі); UOKiK, Reklamacja (розпізнання звернення щодо проблеми з покупкою).","UOKiK, Prawo do informacji (відповідність і зрозумілість інформації, переданої споживачеві); GOV.UK, How the beta phase works (обмежений початок надання послуги й подальші виправлення)."]},"es":{"title":"Comprueba todo el recorrido del cliente","guide_body":"2.1. Ensaya la recepción del producto y el aviso de un problema\nElige una oferta que quieras poner a disposición al principio. Recórrela como lo haría un cliente nuevo: desde leer la descripción hasta recibir el resultado prometido. Con un archivo digital, comprueba que llega y se abre. Con un producto físico, prepara un pedido de prueba y comprueba que se entrega la unidad correcta. Con un servicio, haz una prueba con el alcance prometido.\nObserva también el trabajo de tu lado. Si el pedido llega a una persona y otra entrega el producto, comprueba que la segunda recibe la información necesaria. Con pocos clientes, parte de la gestión puedes hacerla a mano. Ensaya la forma elegida teniendo en cuenta el trabajo que el cliente no ve.\nCon una pasarela de pago, usa el modo de pruebas que describe el proveedor. En Stripe sirven para ello el entorno de pruebas y los datos de pago de prueba. Si la comprobación correspondiente ya se hizo en SaaS, vincula ese resultado y aquí completa solo lo que falte del recorrido del consumidor. Fíjate en si el cliente recibe la confirmación correcta y si el pedido llega a quien lo gestiona.\nDespués envía un aviso de ejemplo por el contacto indicado. Comprueba quién lo recibe y cómo llega a una respuesta o a la acción necesaria. Una reclamación se refiere a un problema con lo comprado; el desistimiento puede tener otra base y otro proceso. Elige para la prueba una situación relativa a tu producto y aplica las normas correspondientes. Un buzón de contacto normal puede bastar para la primera atención si alguien lo revisa y sabe ocuparse del asunto.\nPuedes pedir a alguien de fuera del equipo que recorra el camino preparado. Observa dónde necesita más explicaciones. Si haces la prueba tú solo, anota quién la hizo; no concluyas de ella que cualquiera entenderá la oferta. Guarda en un Goal el resultado de la recepción del producto, la prueba del aviso y los problemas detectados. Un resultado negativo es una comprobación terminada, pero exige la corrección correspondiente antes de 2.2.\n2.2. Confirma que estás listo para atender al primer cliente\nCompara la oferta con el resultado de la prueba. La promesa de entregar un archivo nada más hacer el pedido debe corresponder a lo que recibirá el cliente. Si necesitas ayuda humana y más tiempo, la oferta debe reflejarlo. Comprueba igualmente el precio, el alcance de la primera versión y la forma de empezar a usarlo.\nRevisa los problemas encontrados. Un importe erróneo en el pedido, que falte el material prometido o un contacto que no funciona deben corregirse antes de confirmar. Una variante adicional del producto o un programa de recomendaciones pueden esperar. Valoras si está listo el inicio elegido, así que usa el alcance fijado.\nTras corregir, repite la parte afectada por el cambio y añade el resultado al mismo trabajo. Si la oferta cambió después de la prueba, comprueba que el resultado sigue correspondiendo a su contenido. Asignar a una persona para reunir los materiales permite detectar diferencias entre lo que promete la descripción y lo que se ha preparado.\nConfirma que está listo cuando tengas las pruebas necesarias y los obstáculos resueltos. Esta marca no confirma la demanda ni la eficacia de la publicidad. En la MVP Stage pondrás la primera versión a disposición de los destinatarios y comprobarás cómo la usan. Los materiales y los Goals seguirán en el mismo sitio, así que los comentarios tras el lanzamiento podrán vincularse a una versión concreta.","guide_sources":["GOV.UK, Make the service simple to use (comprobar si el destinatario sabe hacer la tarea necesaria); Stripe, Testing (probar pagos en el entorno destinado a ello); UOKiK, Reklamacja (identificar un aviso sobre un problema con la compra).","UOKiK, Prawo do informacji (coherencia y claridad de la información dada al consumidor); GOV.UK, How the beta phase works (inicio limitado de la puesta a disposición del servicio y mejoras posteriores)."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'b2c' and p.key = 'b2c-path';
update public.stage_subpoints s set translations = '{"de":{"title":"Übe den Erhalt des Produkts und die Meldung eines Problems"},"uk":{"title":"Відпрацюй отримання продукту й повідомлення про проблему"},"es":{"title":"Ensaya la recepción del producto y el aviso de un problema"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'b2c' and p.key = 'b2c-path' and s.key = 'trial';
update public.stage_fields f set translations = '{"de":{"question":"Testnachweis für Erhalt und Bearbeitung einer Meldung.","config":{"label":"Ziele öffnen"}},"uk":{"question":"Доказ спроби отримання й обробки звернення.","config":{"label":"Відкрити цілі"}},"es":{"question":"Prueba del ensayo de recepción y gestión de un aviso.","config":{"label":"Abrir objetivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'b2c' and p.key = 'b2c-path'
    and s.key = 'trial' and f.key = 'open';
update public.stage_subpoints s set translations = '{"de":{"title":"Bestätige die Bereitschaft, den ersten Kunden zu bedienen"},"uk":{"title":"Підтверди готовність обслужити першого клієнта"},"es":{"title":"Confirma que estás listo para atender al primer cliente"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'b2c' and p.key = 'b2c-path' and s.key = 'ready';
update public.stage_fields f set translations = '{"de":{"question":"Welche Version bestätigst du?"},"uk":{"question":"Яку версію ти підтверджуєш?"},"es":{"question":"¿Qué versión confirmas?"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'b2c' and p.key = 'b2c-path'
    and s.key = 'ready' and f.key = 'version';
update public.stage_fields f set translations = '{"de":{"question":"Ist diese Version bereit, den ersten Kunden zu bedienen?","help":"Das Feld bleibt leer, bis du es bestätigst.","config":{"options":[{"value":"ready","label":"Bereit, den ersten Kunden zu bedienen"}]}},"uk":{"question":"Чи ця версія готова до обслуговування першого клієнта?","help":"Поле порожнє, доки ти його не підтвердиш.","config":{"options":[{"value":"ready","label":"Готово до обслуговування першого клієнта"}]}},"es":{"question":"¿Está lista esta versión para atender al primer cliente?","help":"El campo queda vacío hasta que lo confirmes.","config":{"options":[{"value":"ready","label":"Listo para atender al primer cliente"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'b2c' and p.key = 'b2c-path'
    and s.key = 'ready' and f.key = 'ready';

-- ═══ mvp v1 ═══
update public.stage_templates t set translations = '{"de":{"title":"MVP Stage","subtitle":"Veröffentlichen und prüfen","intro":"Du stellst die erste Version Zielpersonen bereit, sammelst Reaktionen und verbesserst das Produkt. Tracker, Team und Materialien aus Execution bleiben verfügbar.","finish_label":"Ich schließe das Programm ab"},"uk":{"title":"MVP Stage","subtitle":"Випусти й перевір","intro":"Ти надаєш першу версію адресатам, збираєш реакції й покращуєш продукт. Трекер, команда й матеріали з Execution залишаються доступними.","finish_label":"Завершую програму"},"es":{"title":"MVP Stage","subtitle":"Lanza y comprueba","intro":"Pones la primera versión a disposición de los destinatarios, recoges reacciones y mejoras el producto. El tracker, el equipo y los materiales de Execution siguen disponibles.","finish_label":"Termino el programa"}}'::jsonb
  where t.key = 'mvp' and t.version = 1;
update public.stage_categories c set translations = '{"de":{"title":"Allgemeine Validierung","intro":"Gemeinsame Grundlage für jedes Produkt — unabhängig von der Kategorie."},"uk":{"title":"Загальна валідація","intro":"Спільна основа для кожного продукту — незалежно від категорії."},"es":{"title":"Validación general","intro":"Base común para cualquier producto, sea cual sea su categoría."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'mvp' and t.version = 1 and c.key = 'general';
update public.stage_points p set translations = '{"de":{"title":"Baue eine minimale Version der Lösung","guide_body":"Die allgemeine MVP-Validierung besteht darin, eine minimale Version der Lösung zu bauen: nur die Funktionen umzusetzen, die für die Hauptannahme nötig sind, die Schlüsselelemente so zu verbinden, dass Nutzer die Haupthandlung ausführen können, und das MVP in einen Zustand zu bringen, in dem die ersten Zielpersonen es nutzen können. Der nächste Schritt ist der Beginn der Tests mit Nutzern — eine passende Testgruppe festlegen, den Testzeitraum bestimmen, das MVP der gewählten Gruppe bereitstellen und beobachten, wie sie das Produkt nutzen und auf welche Probleme sie stoßen."},"uk":{"title":"Збудуй мінімальну версію рішення","guide_body":"Загальна валідація MVP полягає у створенні мінімальної версії рішення: реалізації лише функцій, потрібних для головного припущення, поєднанні ключових елементів так, щоб користувач міг виконати головну дію, і підготовці MVP до стану, що уможливлює його використання першими адресатами. Наступний крок — початок тестування з користувачами: визначення дослідницької групи, придатної для тестування рішення, встановлення періоду дослідження, надання MVP обраній групі й спостереження, як вони користуються продуктом і з якими проблемами стикаються."},"es":{"title":"Construye una versión mínima de la solución","guide_body":"La validación general del MVP consiste en construir una versión mínima de la solución: hacer solo las funciones necesarias para la suposición principal, conectar los elementos clave para que el usuario pueda realizar la acción principal y llevar el MVP a un estado en que puedan usarlo los primeros destinatarios. El siguiente paso es empezar las pruebas con usuarios: definir un grupo de prueba adecuado, fijar el periodo de estudio, dar acceso al MVP al grupo elegido y observar cómo usan el producto y con qué problemas se encuentran."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'mvp' and t.version = 1
    and c.key = 'general' and p.key = 'general-zbuduj-minimalna-wersje-rozwiazania';
update public.stage_subpoints s set translations = '{"de":{"title":"Setze die Grundfunktionen des MVP um"},"uk":{"title":"Реалізуй базові функції MVP"},"es":{"title":"Haz las funciones básicas del MVP"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'mvp' and t.version = 1
    and c.key = 'general' and p.key = 'general-zbuduj-minimalna-wersje-rozwiazania' and s.key = 'zrealizuj-podstawowe-funkcje-mvp';
update public.stage_fields f set translations = '{"de":{"question":"Baue nur die Funktionen, die zum Prüfen der Hauptannahme nötig sind.","help":"Baue nur die Funktionen, die zum Prüfen der Hauptannahme nötig sind. Verknüpfe das in diesem Punkt verlangte Ziel und füge den Nachweis in der Zielkarte hinzu."},"uk":{"question":"Створи лише функції, потрібні для перевірки головного припущення.","help":"Створи лише функції, потрібні для перевірки головного припущення. Прикріпи ціль, потрібну в цьому пункті, і додай доказ у картці цілі."},"es":{"question":"Construye solo las funciones necesarias para comprobar la suposición principal.","help":"Construye solo las funciones necesarias para comprobar la suposición principal. Vincula el objetivo requerido en este punto y añade la prueba en la tarjeta del objetivo."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'mvp' and t.version = 1 and c.key = 'general' and p.key = 'general-zbuduj-minimalna-wersje-rozwiazania'
    and s.key = 'zrealizuj-podstawowe-funkcje-mvp' and f.key = 'note';
update public.stage_subpoints s set translations = '{"de":{"title":"Verbinde die Schlüsselelemente der Lösung"},"uk":{"title":"Поєднай ключові елементи рішення"},"es":{"title":"Conecta los elementos clave de la solución"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'mvp' and t.version = 1
    and c.key = 'general' and p.key = 'general-zbuduj-minimalna-wersje-rozwiazania' and s.key = 'polacz-kluczowe-elementy-rozwiazania';
update public.stage_fields f set translations = '{"de":{"question":"Sorge dafür, dass Nutzer die Haupthandlung in der Lösung ausführen können.","help":"Sorge dafür, dass Nutzer die Haupthandlung in der Lösung ausführen können. Verknüpfe das in diesem Punkt verlangte Ziel und füge den Nachweis in der Zielkarte hinzu."},"uk":{"question":"Зроби так, щоб користувач міг виконати головну дію в рішенні.","help":"Зроби так, щоб користувач міг виконати головну дію в рішенні. Прикріпи ціль, потрібну в цьому пункті, і додай доказ у картці цілі."},"es":{"question":"Haz que el usuario pueda realizar la acción principal en la solución.","help":"Haz que el usuario pueda realizar la acción principal en la solución. Vincula el objetivo requerido en este punto y añade la prueba en la tarjeta del objetivo."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'mvp' and t.version = 1 and c.key = 'general' and p.key = 'general-zbuduj-minimalna-wersje-rozwiazania'
    and s.key = 'polacz-kluczowe-elementy-rozwiazania' and f.key = 'note';
update public.stage_subpoints s set translations = '{"de":{"title":"Bereite das MVP für Tests vor"},"uk":{"title":"Підготуй MVP до тестування"},"es":{"title":"Prepara el MVP para las pruebas"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
