update public.stage_fields f set translations = '{"de":{"question":"Bring das MVP in einen Zustand, in dem die ersten Zielpersonen es nutzen können.","help":"Bring das MVP in einen Zustand, in dem die ersten Zielpersonen es nutzen können. Verknüpfe das in diesem Punkt verlangte Ziel und füge den Nachweis in der Zielkarte hinzu."},"uk":{"question":"Доведи MVP до стану, готового до використання першими адресатами.","help":"Доведи MVP до стану, готового до використання першими адресатами. Прикріпи ціль, потрібну в цьому пункті, і додай доказ у картці цілі."},"es":{"question":"Lleva el MVP a un estado en que puedan usarlo los primeros destinatarios.","help":"Lleva el MVP a un estado en que puedan usarlo los primeros destinatarios. Vincula el objetivo requerido en este punto y añade la prueba en la tarjeta del objetivo."}}'::jsonb
