    and t.key = 'mvp' and t.version = 1 and c.key = 'general' and p.key = 'general-zbuduj-minimalna-wersje-rozwiazania'
    and s.key = 'przygotuj-mvp-do-testowania' and f.key = 'note';
update public.stage_points p set translations = '{"de":{"title":"Beginne die Tests mit Nutzern","guide_body":"Der nächste Schritt ist der Beginn der Tests mit Nutzern — eine passende Testgruppe festlegen, den Testzeitraum bestimmen, das MVP der gewählten Gruppe bereitstellen und beobachten, wie sie das Produkt nutzen und auf welche Probleme sie stoßen."},"uk":{"title":"Почни тестування з користувачами","guide_body":"Наступний крок — початок тестування з користувачами: визначення дослідницької групи, придатної для тестування рішення, встановлення періоду дослідження, надання MVP обраній групі й спостереження, як вони користуються продуктом і з якими проблемами стикаються."},"es":{"title":"Empieza las pruebas con usuarios","guide_body":"El siguiente paso es empezar las pruebas con usuarios: definir un grupo de prueba adecuado, fijar el periodo de estudio, dar acceso al MVP al grupo elegido y observar cómo usan el producto y con qué problemas se encuentran."}}'::jsonb
