    and s.key = 'okresl-grupe-badawcza' and f.key = 'note';
update public.stage_subpoints s set translations = '{"de":{"title":"Lege den Testzeitraum fest"},"uk":{"title":"Встанови період дослідження"},"es":{"title":"Fija el periodo de estudio"}}'::jsonb
