update public.stage_subpoints s set translations = '{"de":{"title":"Beobachte die Reaktionen der Nutzer"},"uk":{"title":"Спостерігай за реакціями користувачів"},"es":{"title":"Observa las reacciones de los usuarios"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
