update public.stage_fields f set translations = '{"de":{"question":"Verfolge, wie Nutzer das Produkt verwenden und welche Probleme sie haben.","help":"Verfolge, wie Nutzer das Produkt verwenden und welche Probleme sie haben. Verknüpfe das in diesem Punkt verlangte Ziel und füge den Nachweis in der Zielkarte hinzu."},"uk":{"question":"Стеж, як користувачі користуються продуктом і які мають проблеми.","help":"Стеж, як користувачі користуються продуктом і які мають проблеми. Прикріпи ціль, потрібну в цьому пункті, і додай доказ у картці цілі."},"es":{"question":"Sigue cómo usan el producto los usuarios y qué problemas tienen.","help":"Sigue cómo usan el producto los usuarios y qué problemas tienen. Vincula el objetivo requerido en este punto y añade la prueba en la tarjeta del objetivo."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
