    and s.key = 'obserwuj-reakcje-uzytkownikow' and f.key = 'note';
update public.stage_points p set translations = '{"de":{"title":"Sammle Feedback","guide_body":"Danach wird Feedback gesammelt: direkte Meinungen der Nutzer zu ihren Erfahrungen mit dem MVP einholen, die Lösung mit Fachleuten und anderen erfahrenen Personen besprechen, Fehler, Schwierigkeiten und unverständliche Elemente festhalten sowie die Erwartungen der Nutzer an Haupt- und Zusatzfunktionen notieren. Das gesammelte Feedback wird analysiert — die Zufriedenheit der Nutzer bewertet, gemeldete Probleme untersucht, um die am häufigsten wiederkehrenden Fehler und Hürden zu finden, geprüft, welche Funktionen Nutzer wirklich brauchen, und die wichtigsten Schlüsse gezogen, was geändert und was weiter geprüft werden muss."},"uk":{"title":"Збери фідбек","guide_body":"Далі збирають фідбек: отримують прямі думки користувачів про досвід із MVP, консультують рішення з фахівцями та іншими досвідченими людьми, фіксують несправності, труднощі й незрозумілі елементи, а також записують очікування користувачів щодо головних і додаткових функцій. Зібраний фідбек аналізують: оцінюють рівень задоволення користувачів, розглядають повідомлені проблеми, щоб знайти несправності й бар’єри, що повторюються найчастіше, перевіряють, які функції користувачам справді потрібні, і роблять найважливіші висновки щодо того, що потребує зміни, а що подальшої перевірки."},"es":{"title":"Recoge feedback","guide_body":"Después se recoge feedback: obtener opiniones directas de los usuarios sobre su experiencia con el MVP, consultar la solución con especialistas y otras personas con experiencia, registrar fallos, dificultades y elementos poco claros, y anotar las expectativas de los usuarios sobre funciones principales y adicionales. El feedback reunido se analiza: valorar el nivel de satisfacción de los usuarios, estudiar los problemas comunicados para encontrar los fallos y barreras más repetidos, comprobar qué funciones necesitan de verdad los usuarios y sacar las conclusiones más importantes sobre qué hay que cambiar y qué seguir comprobando."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'mvp' and t.version = 1
    and c.key = 'general' and p.key = 'general-zbierz-feedback';
update public.stage_subpoints s set translations = '{"de":{"title":"Sammle Meinungen der Nutzer"},"uk":{"title":"Збирай думки користувачів"},"es":{"title":"Recoge opiniones de los usuarios"}}'::jsonb
