update public.stage_points p set translations = '{"de":{"title":"Erarbeite die Richtung der weiteren Entwicklung","guide_body":"Das gesammelte Feedback wird analysiert — die Zufriedenheit der Nutzer bewertet, gemeldete Probleme untersucht, um die am häufigsten wiederkehrenden Fehler und Hürden zu finden, geprüft, welche Funktionen Nutzer wirklich brauchen, und die wichtigsten Schlüsse gezogen, was geändert und was weiter geprüft werden muss. Auf Grundlage dieser Schlüsse wird die Richtung der weiteren Entwicklung erarbeitet: die wichtigsten Korrekturen mit dem größten Einfluss auf den Wert des Produkts festlegen, die Verbesserung des MVP gemäß dem Feedback planen, eine teilweise oder vollständige Änderung der Idee erwägen und die nächste Handlungsrichtung bestimmen."},"uk":{"title":"Опрацюй напрям подальшого розвитку","guide_body":"Зібраний фідбек аналізують: оцінюють рівень задоволення користувачів, розглядають повідомлені проблеми, щоб знайти несправності й бар’єри, що повторюються найчастіше, перевіряють, які функції користувачам справді потрібні, і роблять найважливіші висновки щодо того, що потребує зміни, а що подальшої перевірки. На основі цих висновків опрацьовують напрям подальшого розвитку: визначають найважливіші виправлення з найбільшим впливом на цінність продукту, планують покращення MVP відповідно до фідбеку, розглядають часткову чи повну зміну ідеї й визначають наступний напрям дій."},"es":{"title":"Define la dirección del desarrollo futuro","guide_body":"El feedback reunido se analiza: valorar el nivel de satisfacción de los usuarios, estudiar los problemas comunicados para encontrar los fallos y barreras más repetidos, comprobar qué funciones necesitan de verdad los usuarios y sacar las conclusiones más importantes sobre qué hay que cambiar y qué seguir comprobando. A partir de esas conclusiones se define la dirección del desarrollo futuro: fijar las correcciones más importantes, con más impacto en el valor del producto, planificar la mejora del MVP según el feedback, plantearse un cambio parcial o total de la idea y decidir la siguiente dirección de trabajo."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'mvp' and t.version = 1
    and c.key = 'general' and p.key = 'general-opracuj-kierunek-dalszego-rozwoju';
