update public.stage_points p set translations = '{"de":{"title":"Besprich die Lösung erneut","guide_body":"Zum Schluss wird die Lösung erneut besprochen: die wichtigsten Änderungen ins MVP einbauen, es den Nutzern erneut bereitstellen, die Reaktionen vor und nach den Änderungen vergleichen und den ganzen Prozess — Testen, Feedback sammeln und Verbessern — als Validierungszyklus wiederholen."},"uk":{"title":"Знову проконсультуй рішення","guide_body":"Насамкінець рішення знову консультують: вносять найважливіші зміни в MVP, знову надають його користувачам, порівнюють реакції до й після змін і повторюють увесь процес — тестування, збирання фідбеку й покращення — як цикл валідації."},"es":{"title":"Vuelve a consultar la solución","guide_body":"Por último, la solución se vuelve a consultar: aplicar al MVP los cambios más importantes, ponerlo de nuevo a disposición de los usuarios, comparar las reacciones antes y después de los cambios y repetir todo el proceso —pruebas, feedback y mejoras— como un ciclo de validación."}}'::jsonb
